INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TheMystic07/OpenWalc/nostr', 'community', 'TheMystic07', 'OpenWalc', 'TheMystic07/OpenWalc', 'nostr', 0, 1, 30, '2026-03-03T01:46:00Z', '2026-03-07T04:12:25.009Z', '1916e20ad165717e7ab21867e45a9f279acb9df33c4abb5c9872365962f4967f', '{"id":"TheMystic07/OpenWalc/nostr","name":"nostr","description":{"en":"The nostr skill enables developers to build censorship-resistant social networks using cryptographic keys and signatures. It benefits developers seeking to create global, open social networks.","zh":"Nostr 协议是一个简单的开源协议，使用加密密钥和签名实现真正的抗审查和全球社交网络","ja":"Nostr プロトコルは、暗号鍵と署名を使用して真正の検閲耐性とグローバルなソーシャルネットワークを実現するシンプルなオープンプロトコル","ko":"Nostr 프로토콜은 암호 키와 서명을 사용하여真正의 검열 저항성과 글로벌 소셜 네트워크를实现하는 단순한 오픈 프로토콜","es":"Nostr es un protocolo abierto que permite crear redes sociales resistentes a la censura utilizando claves y firmas criptográficas. Accede a la documentación oficial en el repositorio NIPs","fr":"Nostr est un protocole ouvert qui permet de créer des réseaux sociaux résistants à la censure en utilisant des clés et des signatures cryptographiques. Accédez à la documentation officielle dans le référentiel NIPs","de":"Nostr ist ein offenes Protokoll, das die Erstellung zensurresistenter sozialer Netzwerke mithilfe kryptographischer Schlüssel und Signaturen ermöglicht. Greifen Sie auf die offizielle Dokumentation im NIPs-Repository zu","pt":"O Nostr é um protocolo simples e aberto que permite redes sociais verdadeiramente resistentes à censura, utilizando chaves e assinaturas criptográficas.","ru":"Nostr - простой и открытый протокол, позволяющий создавать真正 резистентные к цензуре социальные сети, используя криптографические ключи и подписи.","ar":"Nostr هو بروتوكول بسيط ومفتوح يسمح بشبكات اجتماعية مقاومة للرقابة، باستخدام المفاتيح والتوقيعات المعمّاة"},"seo":{"title":{"en":"nostr: Setup Guide for Censorship-Resistant Social Networ...","zh":"Nostr 协议开发指南","ja":"Nostr プロトコル開発ガイド","ko":"Nostr 프로토콜 개발 가이드","es":"Guía de configuración de Nostr: redes sociales resistente...","fr":"Configurer Nostr: le protocole de réseaux sociaux résista...","de":"Nostr-Setup-Anleitung: zensurresistente soziale Netzwerke","pt":"Guia de Configuração do Nostr: Rede Social Resistente à C...","ru":"Настройка Nostr: Протокол для ИИ Агентов Социальных Сетей","ar":"دليل إعداد Nostr: بروتوكول شبكات اجتماعية مقاوم للرقابة"},"description":{"en":"Unlock the power of nostr protocol for global social networks. Learn how to access NIPs and implement censorship-resistant solutions. Get started now!","zh":"了解 Nostr 协议的技术细节，包括 NIPs 文档和加密密钥签名","ja":"Nostr プロトコルの技術的詳細を学び、NIPs ドキュメントと暗号鍵署名について","ko":"Nostr 프로토콜의 기술적 세부 사항을 학습하고 NIPs 문서 및 암호 키 서명에 대해","es":"Aprende a configurar Nostr, un protocolo abierto para redes sociales resistentes a la censura, y descubre sus características clave","fr":"Découvrez comment configurer Nostr, un protocole ouvert pour les réseaux sociaux résistants à la censure, et explorez ses fonctionnalités","de":"Erfahren Sie, wie Sie Nostr konfigurieren, ein offenes Protokoll für zensurresistente soziale Netzwerke, und entdecken Sie seine wichtigsten Funktionen","pt":"Aprenda como configurar o Nostr, um protocolo simples e aberto para redes sociais resistentes à censura, utilizando chaves e assinaturas criptográficas.","ru":"Узнайте, как настроить Nostr, простой и открытый протокол для ИИ Агентов социальных сетей, устойчивых к цензуре, с помощью криптографических ключей и подписей.","ar":"تعرف على كيفية إعداد Nostr، بروتوكول بسيط ومفتوح لشبكات اجتماعية مقاومة للرقابة، باستخدام المفاتيح والتوقيعات المعمّاة"},"definition":{"en":"nostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.","zh":"Nostr 协议是一种使用加密密钥和签名的开源协议","ja":"Nostr プロトコルは、暗号鍵と署名を使用するオープンプロトコル","ko":"Nostr 프로토콜은 암호 키와 서명을 사용하는 오픈 프로토콜","es":"Nostr es un protocolo de redes sociales abierto y resistente a la censura que utiliza claves y firmas criptográficas","fr":"Nostr est un protocole de réseaux sociaux ouvert et résistant à la censure qui utilise des clés et des signatures cryptographiques","de":"Nostr ist ein offenes und zensurresistentes soziales Netzwerkprotokoll, das kryptographische Schlüssel und Signaturen verwendet","pt":"O que é Nostr? Um protocolo de rede social resistente à censura que utiliza chaves e assinaturas criptográficas.","ru":"Что такое Nostr? Протокол социальной сети, устойчивой к цензуре, использующий криптографические ключи и подписи.","ar":"ما هو Nostr؟ بروتوكول شبكة اجتماعية مقاوم للرقابة، يستخدم المفاتيح والتوقيعات المعمّاة"},"features":{"en":["Uses cryptographic keys and signatures for secure communication","Enables access to NIPs (Nostr Implementation Possibilities) repository","Supports fetching individual NIPs from GitHub repository","Allows for implementation of censorship-resistant social networks","Provides a simple, open protocol for global social network development","Utilizes GitHub repository for Nostr protocol documentation"],"zh":["使用加密密钥和签名","实现抗审查和全球社交网络","NIPs 文档维护","支持 Individual NIPs","使用 HTTPS 访问 NIPs 文档"],"ja":["暗号鍵と署名を使用","検閲耐性とグローバルなソーシャルネットワークを実現","NIPs ドキュメントの維持","Individual NIPs をサポート","HTTPS を使用して NIPs ドキュメントにアクセス"],"ko":["암호 키와 서명을 사용","검열 저항성과 글로벌 소셜 네트워크를实现","NIPs 문서 유지","Individual NIPs 지원","HTTPS를 사용하여 NIPs 문서에 액세스"],"es":["Utiliza claves y firmas criptográficas para garantizar la seguridad","Permite la creación de redes sociales resistentes a la censura","Documentación oficial disponible en el repositorio NIPs","Acceso a individual NIPs a través de GitHub","Soporte para la implementación de redes sociales globales"],"fr":["Utilise des clés et des signatures cryptographiques pour assurer la sécurité","Permet la création de réseaux sociaux résistants à la censure","Documentation officielle disponible dans le référentiel NIPs","Accès à des NIPs individuels via GitHub","Prise en charge de la mise en œuvre de réseaux sociaux mondiaux"],"de":["Verwendet kryptographische Schlüssel und Signaturen für die Sicherheit","Ermöglicht die Erstellung zensurresistenter sozialer Netzwerke","Offizielle Dokumentation im NIPs-Repository verfügbar","Zugriff auf einzelne NIPs über GitHub","Unterstützung für die Implementierung globaler sozialer Netzwerke"],"pt":["Utiliza chaves e assinaturas criptográficas para garantir a segurança","Permite redes sociais verdadeiramente resistentes à censura","Protocolo simples e aberto para implementação fácil","Documentação disponível em NIPs (Nostr Implementation Possibilities)","Suporte a NIP-01 (basic proto) e outros padrões"],"ru":["Использует криптографические ключи и подписи для обеспечения безопасности","Позволяет создавать真正 резистентные к цензуре социальные сети","Простой и открытый протокол для легкой реализации","Документация доступна в NIPs (Nostr Implementation Possibilities)","Поддержка NIP-01 (basic proto) и других стандартов"],"ar":["يستخدم المفاتيح والتوقيعات المعمّاة لضمان الأمان","يسمح بإنشاء شبكات اجتماعية مقاومة للرقابة","بروتوكول بسيط ومفتوح للتنفيذ السهل","توثيق متاح في NIPs (Nostr Implementation Possibilities)","دعم NIP-01 (basic proto) ومعايير أخرى"]},"keywords":{"en":["how to use nostr","what is nostr protocol","nostr alternative","nostr vs activitypub","nostr install guide","nostr setup for social networks","censorship-resistant social networks","nostr implementation possibilities","nostr github repository"],"zh":["Nostr 协议","NIPs 文档","加密密钥","签名","抗审查","全球社交网络","Individual NIPs","HTTPS"],"ja":["Nostr プロトコル","NIPs ドキュメント","暗号鍵","署名","検閲耐性","グローバルなソーシャルネットワーク","Individual NIPs","HTTPS"],"ko":["Nostr 프로토콜","NIPs 문서","암호 키","서명","검열 저항성","글로벌 소셜 네트워크","Individual NIPs","HTTPS"],"es":["Nostr protocolo","redes sociales resistentes a la censura","claves criptográficas","firmas criptográficas","NIPs","GitHub","seguridad en redes sociales","implementación de redes sociales globales"],"fr":["Protocole Nostr","réseaux sociaux résistants à la censure","clés cryptographiques","signatures cryptographiques","NIPs","GitHub","sécurité des réseaux sociaux","mise en œuvre de réseaux sociaux mondiaux"],"de":["Nostr-Protokoll","zensurresistente soziale Netzwerke","kryptographische Schlüssel","kryptographische Signaturen","NIPs","GitHub","Sicherheit in sozialen Netzwerken","Implementierung globaler sozialer Netzwerke"],"pt":["Nostr protocolo","rede social resistente à censura","chaves criptográficas","assinaturas criptográficas","NIPs","NIP-01","protocolo de rede social"],"ru":["Протокол Nostr","социальная сеть, устойчивая к цензуре","криптографические ключи","криптографические подписи","NIPs","NIP-01","протокол социальной сети"],"ar":["بروتوكول Nostr","شبكة اجتماعية مقاومة للرقابة","مفاتيح معمّاة","توقيعات معمّاة","NIPs","NIP-01","بروتوكول شبكة اجتماعية"]}},"owner":"TheMystic07","repo":"OpenWalc","repoPath":"TheMystic07/OpenWalc","stars":0,"forks":1,"updatedAt":"2026-03-03T01:46:00Z","topics":[],"category":"community","skillMd":{"name":"nostr","description":"Knowledge about the Nostr protocol. Use to view up-to-date NIPs, discover capabilities of the Nostr protocol, and to implement Nostr functionality correctly.","bodyPreview":"# Nostr Protocol\n\nNostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.\n\n## Finding Nostr Documentation\n\nAll Nostr protocol documentation is maintained in the NIPs (Nostr Implementation Possibilities) repository. To access this information:\n\n### Reading Individual NIPs\n\nIndividual NIPs can be fetched from:\n```\nhttps://github.com/nostr-protocol/nips/blob/master/{NIP}.md\n```\n\nFor example, NIP-01 (the basic proto","body":"# Nostr Protocol\n\nNostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.\n\n## Finding Nostr Documentation\n\nAll Nostr protocol documentation is maintained in the NIPs (Nostr Implementation Possibilities) repository. To access this information:\n\n### Reading Individual NIPs\n\nIndividual NIPs can be fetched from:\n```\nhttps://github.com/nostr-protocol/nips/blob/master/{NIP}.md\n```\n\nFor example, NIP-01 (the basic protocol specification) is available at:\n```\nhttps://github.com/nostr-protocol/nips/blob/master/01.md\n```\n\n### Finding Event Kinds\n\nDocumentation for Nostr event kinds is spread across one or more NIPs. **There is no direct relationship between the NIP number and the kind number.**\n\nTo find which NIPs document a specific event kind:\n\n1. First, fetch the README:\n   ```\n   https://github.com/nostr-protocol/nips/blob/master/README.md\n   ```\n\n2. Reference the \"Event Kinds\" table in the README to find which NIP(s) document the kind you''re looking for\n\n### Discovering Existing Capabilities\n\nThe README should be consulted to:\n\n- **View the list of NIPs** - Use this to discover what capabilities already exist on the Nostr network\n- **Review client and relay messages** - Understand the communication protocol\n- **Check the list of tags** - See what standardized tags are available\n- **Decide on using existing NIPs** - Before implementing a feature, check if an existing NIP already covers it\n\n### Best Practices\n\nAlways start by fetching and reviewing the README to understand the current state of the protocol and avoid reinventing existing functionality.\n"},"lastSynced":"2026-03-07T04:12:25.009Z","agentAnalysis":{"suitability":{"en":"Ideal for Decentralized Social Network Agents seeking to leverage censorship-resistant protocols like nostr.","zh":"适用于寻求利用类似nostr的抗审查协议的去中心化社交网络代理的理想选择","ja":"nostrのような検閲耐性のあるプロトコルを利用した分散型ソーシャルネットワークエージェントに最適","ko":"노스트르와 같은 검열에 강한 프로토콜을 활용하는 분산 소셜 네트워크 에이전트에게 이상적","es":"Ideal para Agentes de Redes Sociales Descentralizadas que buscan aprovechar protocolos resistentes a la censura como nostr.","fr":"Idéal pour les Agents de Réseaux Sociaux Décentralisés qui cherchent à exploiter des protocoles résistants à la censure comme nostr.","de":"Ideal für dezentrale soziale Netzwerkagenten, die zensurresistente Protokolle wie nostr nutzen möchten.","pt":"Ideal para Agentes de Rede Social Descentralizada que buscam aproveitar protocolos resistentes à censura como o nostr.","ru":"Идеально для децентрализованных социальных сетевых агентов, стремящихся использовать протоколы, устойчивые к цензуре, такие как nostr.","ar":"مثالي لعميل الشبكة الاجتماعية اللامركزية الذين يسعون إلى الاستفادة من بروتوكولات مقاومة للرقابة مثل nostr."},"recommendation":{"en":"Empowers agents to build global, open social networks using cryptographic keys and signatures, enabling truly censorship-resistant communication via the nostr protocol and accessing documentation through NIPs (Nostr Implementation Possibilities).","zh":"赋予代理构建全球、开放的社交网络的能力，使用加密密钥和签名，实现真正的抗审查通信，通过nostr协议，并通过NIPs（Nostr实现可能性）访问文档","ja":"nostrプロトコルと加密鍵および署名を使用して、グローバルでオープンなソーシャルネットワークを構築し、真正に検閲耐性のあるコミュニケーションを可能にし、NIPs（Nostr実装の可能性）を介して文書にアクセスするエージェントの構築を可能にする","ko":"노스트르 프로토콜과 암호화 키 및 서명을 사용하여 글로벌하고 개방적인 소셜 네트워크를 구축하며, 진정한 검열에 강한 통신을 가능하게 하며, NIPs(노스트르 구현 가능성)를 통해 문서에 액세스 할 수 있는 에이전트의 구축을 가능하게 함","es":"Habilita a los agentes a crear redes sociales globales y abiertas utilizando claves y firmas criptográficas, lo que permite una comunicación verdaderamente resistente a la censura a través del protocolo nostr y acceder a la documentación a través de NIPs (Posibilidades de Implementación de Nostr).","fr":"Permet aux agents de créer des réseaux sociaux mondiaux et ouverts en utilisant des clés et des signatures cryptographiques, ce qui permet une communication véritablement résistante à la censure via le protocole nostr et accéder à la documentation via les NIP (Possibilités d''Implémentation de Nostr).","de":"Ermöglicht es den Agenten, globale, offene soziale Netzwerke mithilfe von kryptografischen Schlüsseln und Signaturen zu erstellen, was eine wirklich zensurresistente Kommunikation über das nostr-Protokoll ermöglicht und den Zugriff auf die Dokumentation über NIPs (Nostr-Implementierungsmöglichkeiten) ermöglicht.","pt":"Habilita os agentes a construir redes sociais globais e abertas usando chaves e assinaturas criptográficas, permitindo comunicação verdadeiramente resistente à censura via o protocolo nostr e acessando documentação por meio de NIPs (Possibilidades de Implementação do Nostr).","ru":"Наделяет агентов возможностью создавать глобальные, открытые социальные сети с использованием криптографических ключей и подписей, обеспечивая真正 устойчивую к цензуре связь через протокол nostr и доступ к документации через NIPs (Возможности реализации Nostr).","ar":"يمنح العملاء بناء شبكات اجتماعية مفتوحة وعالمية باستخدام المفاتيح والتوقيعات المعمارية، وتمكين التواصل المقاوم للرقابة بشكل حقيقي عبر بروتوكول nostr والوصول إلى المستندات من خلال NIPs (إمكانيات تنفيذ nostr)."},"useCases":{"en":["Building censorship-resistant social networks","Implementing cryptographic key management for secure communication","Fetching and parsing NIPs for protocol implementation"],"zh":["构建抗审查的社交网络","实现加密密钥管理以实现安全通信","获取和解析NIPs以实现协议实现"],"ja":["検閲耐性のあるソーシャルネットワークの構築","安全なコミュニケーションのための加密鍵管理の実装","NIPsの取得および解析によるプロトコル実装"],"ko":["검열에 강한 소셜 네트워크 구축","보안 통신을 위한 암호화 키 관리 구현","프로토콜 구현을 위한 NIPs 가져오기 및 구문 분석"],"es":["Construir redes sociales resistentes a la censura","Implementar gestión de claves criptográficas para comunicación segura","Recuperar y analizar NIPs para la implementación del protocolo"],"fr":["Construire des réseaux sociaux résistants à la censure","Mettre en œuvre une gestion de clés cryptographiques pour une communication sécurisée","Récupérer et analyser les NIP pour la mise en œuvre du protocole"],"de":["Zensurresistente soziale Netzwerke erstellen","Kryptografische Schlüsselverwaltung für sichere Kommunikation implementieren","NIPs abrufen und analysieren, um das Protokoll zu implementieren"],"pt":["Construção de redes sociais resistentes à censura","Implementação de gerenciamento de chaves criptográficas para comunicação segura","Recuperação e análise de NIPs para implementação do protocolo"],"ru":["Создание сетей, устойчивых к цензуре","Реализация управления криптографическими ключами для безопасной связи","Получение и разбор NIPs для реализации протокола"],"ar":["بناء شبكات اجتماعية مقاومة للرقابة","تنفيذ إدارة المفاتيح المعمارية للأتصال الآمن","استرجاع وتحليل NIPs لتنفيذ البروتوكول"]},"limitations":{"en":["Requires understanding of cryptographic keys and signatures","Nostr protocol specific","Documentation access via GitHub repository"],"zh":["需要理解加密密钥和签名","特定于nostr协议","文档访问通过GitHub仓库"],"ja":["加密鍵および署名の理解が必要","nostrプロトコルに特有","文書へのアクセスはGitHubリポジトリ経由"],"ko":["암호화 키 및 서명의 이해가 필요","노스트르 프로토콜에 특정","문서 액세스는 깃허브 저장소 통해"],"es":["Requiere comprensión de claves y firmas criptográficas","Específico del protocolo nostr","Acceso a la documentación a través del repositorio de GitHub"],"fr":["Nécessite une compréhension des clés et des signatures cryptographiques","Spécifique du protocole nostr","Accès à la documentation via le référentiel GitHub"],"de":["Erfordert das Verständnis von kryptografischen Schlüsseln und Signaturen","Spezifisch für das nostr-Protokoll","Zugriff auf die Dokumentation über das GitHub-Repository"],"pt":["Exige compreensão de chaves e assinaturas criptográficas","Específico do protocolo nostr","Acesso à documentação via repositório do GitHub"],"ru":["Требует понимания криптографических ключей и подписей","Специфичен для протокола nostr","Доступ к документации через репозиторий GitHub"],"ar":["يتطلب فهم المفاتيح والتوقيعات المعمارية","محدد لبروتوكول nostr","دخول المستندات من خلال مستودع GitHub"]},"version":4},"contentHash":"1916e20ad165717e7ab21867e45a9f279acb9df33c4abb5c9872365962f4967f","qualityScore":30}');
