INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TheMystic07/OpenWalc/nostr', 'nostr', 'TheMystic07', 'OpenWalc', 'community', 'nostr TheMystic07 OpenWalc community The nostr skill enables developers to build censorship-resistant social networks using cryptographic keys and signatures. It benefits developers seeking to create global, open social networks. Nostr 协议是一个简单的开源协议，使用加密密钥和签名实现真正的抗审查和全球社交网络 Nostr プロトコルは、暗号鍵と署名を使用して真正の検閲耐性とグローバルなソーシャルネットワークを実現するシンプルなオープンプロトコル Nostr 프로토콜은 암호 키와 서명을 사용하여真正의 검열 저항성과 글로벌 소셜 네트워크를实现하는 단순한 오픈 프로토콜 Nostr es un protocolo abierto que permite crear redes sociales resistentes a la censura utilizando claves y firmas criptográficas. Accede a la documentación oficial en el repositorio NIPs Nostr est un protocole ouvert qui permet de créer des réseaux sociaux résistants à la censure en utilisant des clés et des signatures cryptographiques. Accédez à la documentation officielle dans le référentiel NIPs Nostr ist ein offenes Protokoll, das die Erstellung zensurresistenter sozialer Netzwerke mithilfe kryptographischer Schlüssel und Signaturen ermöglicht. Greifen Sie auf die offizielle Dokumentation im NIPs-Repository zu O Nostr é um protocolo simples e aberto que permite redes sociais verdadeiramente resistentes à censura, utilizando chaves e assinaturas criptográficas. Nostr - простой и открытый протокол, позволяющий создавать真正 резистентные к цензуре социальные сети, используя криптографические ключи и подписи. Nostr هو بروتوكول بسيط ومفتوح يسمح بشبكات اجتماعية مقاومة للرقابة، باستخدام المفاتيح والتوقيعات المعمّاة how to use nostr what is nostr protocol nostr alternative nostr vs activitypub nostr install guide nostr setup for social networks censorship-resistant social networks nostr implementation possibilities nostr github repository Nostr 协议 NIPs 文档 加密密钥 签名 抗审查 全球社交网络 Individual NIPs HTTPS Uses cryptographic keys and signatures for secure communication Enables access to NIPs (Nostr Implementation Possibilities) repository Supports fetching individual NIPs from GitHub repository Allows for implementation of censorship-resistant social networks Provides a simple, open protocol for global social network development Utilizes GitHub repository for Nostr protocol documentation nostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('carlosnetto/x9.150-py/x9-jws', 'community', 'carlosnetto', 'x9.150-py', 'carlosnetto/x9.150-py', 'x9-jws', 0, 0, 30, '2026-02-27T21:09:34Z', '2026-03-07T04:12:41.461Z', 'e76d3f64a16160224f13438c53dea08fc5acfdd7f02e93b10d2aa4e9ff12be3a', '{"id":"carlosnetto/x9.150-py/x9-jws","name":"x9-jws","description":{"en":"The x9-jws skill helps developers implement the JWS security layer of X9.150, enabling secure payment processing. It provides guidance on signing, verification, and non-repudiation.","zh":"X9-JWS 是一个 JSON Web Signature 安全层的专家指南，帮助开发者理解签名、验证和证书发现等","ja":"X9-JWS は JSON Web Signature セキュリティ層の専門家ガイドで、開発者が署名、検証、証明書発見などを理解するのに役立ちます","ko":"X9-JWS는 JSON Web Signature 보안 레이어의 전문가 가이드로 개발자가 서명, 검증 및 인증서 발견 등을 이해하는 데 도움이 됩니다","es":"x9-jws es una herramienta de seguridad de pagos que implementa la capa de seguridad JWS de x9.150. Ofrece signing, verificación y validación de frescura.","fr":"x9-jws est un outil de sécurité des paiements qui met en œuvre la couche de sécurité JWS de x9.150. Il propose la signature, la vérification et la validation de fraîcheur.","de":"x9-jws ist ein Zahlungssicherheitstool, das die JWS-Sicherheitsschicht von x9.150 implementiert. Es bietet Signierung, Verifizierung und Frischvalidierung.","pt":"O x9-jws é uma ferramenta de segurança para implementar a camada JWS do x9.150, garantindo a autenticidade e integridade de pagamentos.","ru":"x9-jws - это инструмент безопасности для реализации слоя JWS в x9.150, обеспечивающий аутентичность и целостность платежей для ИИ Агентов","ar":"x9-jws هو أداة أمان لتنفيذ طبقة JWS من x9.150، مما يضمن صحة وسلامة المعاملات المالية"},"seo":{"title":{"en":"x9-jws: JWS Security Implementation Guide for AI Agents","zh":"X9-JWS 安全指南：JSON Web Signature 实现最佳实践","ja":"X9-JWS セキュリティガイド：JSON Web Signature の実装","ko":"X9-JWS 보안 가이드: JSON Web Signature 구현 모범 사례","