INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('carlosnetto/x9.150-py/x9-jws', 'x9-jws', 'carlosnetto', 'x9.150-py', 'community', 'x9-jws carlosnetto x9.150-py community The x9-jws skill helps developers implement the JWS security layer of X9.150, enabling secure payment processing. It provides guidance on signing, verification, and non-repudiation. X9-JWS 是一个 JSON Web Signature 安全层的专家指南，帮助开发者理解签名、验证和证书发现等 X9-JWS は JSON Web Signature セキュリティ層の専門家ガイドで、開発者が署名、検証、証明書発見などを理解するのに役立ちます X9-JWS는 JSON Web Signature 보안 레이어의 전문가 가이드로 개발자가 서명, 검증 및 인증서 발견 등을 이해하는 데 도움이 됩니다 x9-jws es una herramienta de seguridad de pagos que implementa la capa de seguridad JWS de x9.150. Ofrece signing, verificación y validación de frescura. x9-jws est un outil de sécurité des paiements qui met en œuvre la couche de sécurité JWS de x9.150. Il propose la signature, la vérification et la validation de fraîcheur. x9-jws ist ein Zahlungssicherheitstool, das die JWS-Sicherheitsschicht von x9.150 implementiert. Es bietet Signierung, Verifizierung und Frischvalidierung. O x9-jws é uma ferramenta de segurança para implementar a camada JWS do x9.150, garantindo a autenticidade e integridade de pagamentos. x9-jws - это инструмент безопасности для реализации слоя JWS в x9.150, обеспечивающий аутентичность и целостность платежей для ИИ Агентов x9-jws هو أداة أمان لتنفيذ طبقة JWS من x9.150، مما يضمن صحة وسلامة المعاملات المالية x9-jws setup guide JWS security implementation X9.150 payment security JSON Web Signature tutorial how to use x9-jws x9-jws alternative x9-jws vs JSON Web Token x9-jws install secure payment processing with x9-jws X9-JWS JSON Web Signature 安全层 签名和验证 证书发现 AIエージェント JSON Web Signature 实现 Explains JWS concept in the context of payment security Provides reference implementations in the codebase Offers code snippets for signing, verification, and protected header construction Supports certificate discovery and freshness validation Ensures non-repudiation for secure payment processing x9-jws is a security implementation guide for JSON Web Signature (JWS) in X9.150, facilitating secure payment transactions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('arbilinskiy-dev/vk_all/author-feedback', 'community', 'arbilinskiy-dev', 'vk_all', 'arbilinskiy-dev/vk_all', 'author-feedback', 0, 0, 30, '2026-03-04T15:06:23Z', '2026-03-07T04:16:20.605Z', '7dfea20081c2618043e4e91494df9f6a3a5a851c459cf3c5168683ec28615df1', '{"id":"arbilinskiy-dev/vk_all/author-feedback","name":"author-feedback","description":{"en":"The author-feedback skill enables analysts to refine AI-generated text by providing corrected text feedback, ensuring subsequent outputs align with the author''s style. This skill benefits developers and writers seeking to perfect their AI-driven content creation.","zh":"作者反馈技能是一种分析式技能，用于接收作者的反馈并修改AI生成文本以匹配作者风格","ja":"著者フィードバックスキルは、著者のフィードバックを受け取り、AI生成テキストを著者スタイルに合わせるための分析スキルです","ko":"저자 피드백 스킬은 저자의 피드백을 받고 AI 생성 텍스트를 저자 스타일에 맞추기 위한 분석 스킬입니다","es":"Author Feedback es un skill que permite a los agentes de IA aprender de la retroalimentación del autor para mejorar la generación de texto.","fr":"La réaction de l''auteur est une compétence qui permet aux outils d''IA d''apprendre de la rétroaction de l''auteur pour améliorer la génération de texte.","de":"Author-Feedback ist ein Skill, der es KI-Agents ermöglicht, von der Rückmeldung des Autors zu lernen, um die Textgenerierung zu verbessern.","pt":"O Author Feedback é um skill que permite a otimização da retroalimentação de autores em ferramentas de IA. Ele recebe a correção do texto original e modifica os arquivos do skill para melhorar a qualidade do texto gerado.","ru":"Автор-скилл — это скилл, который позволяет оптимизировать обратную связь от авторов в ИИ инструментах. Он получает исправленный текст и модифицирует файлы скилла для улучшения качества сгенерированного текста.","ar":"مخرجات مديري التغذية الراجعة للمؤلف هو مهارة يسمح بتحسين التغذية الراجعة للمؤلف في أدوات الذكاء الاصطناعي. وهو يستلم النص الأصلي المصحح ويعمل على تعديل ملفات المهارة لتحسين جودة النص الذي يولد."},"seo":{"title":{"en":"author-feedback: AI Text Optimization Setup Guide | AI Ag...","zh":"作者反馈设置指南 - AI工具","ja":"著者フィードバックのセットアップガイド - AIエージェント","ko":"저자 피드백 설정 가이드 - AI 에이전트","es":"Guía de Configuración de Author Feedback para Agentes de IA","fr":"Guide de Mise en Place de la Réaction de l''Auteur pour le...","de":"Einrichtungsleitfaden für Author-Feedback in KI-Agents","pt":"Guia de Configuração do Author Feedback - Otimizando a Re...","ru":"Руководство по настройке автор-скилла - Обратная связь дл...","ar":"دليل الضبط لمخرجات مديري التغذية الراجعة للمؤلف - أدوات ذ..."},"description":{"en":"Unlock the full potential of AI text generation with author-feedback. Learn how to fine-tune your AI agent''s style and get started with our setup guide today!","zh":"了解作者反馈技能的技术细节，并学习如何优化AI生成文本以匹配作者风格","ja":"著者フィードバックスキルの技術的詳細を学び、AI生成テキストを著者スタイルに最適化する方法を知る","ko":"저자 피드백 스킬의 기술적 세부 사항을 배우고 AI 생성 텍스트를 저자 스타일에 최적화하는 방법을 알아보세요","es":"Aprende a configurar Author Feedback para mejorar la generación de texto en tus agentes de IA. Mejora la calidad del contenido con retroalimentación del autor.","fr":"Découvrez comment configurer la réaction de l''auteur pour améliorer la génération de texte dans vos outils d''IA. Améliorez la qualité du contenu avec la rétr...","de":"Erfahren Sie, wie Sie Author-Feedback einrichten, um die Textgenerierung in Ihren KI-Agents zu verbessern. Verbessern Sie die Qualität des Inhalts mit Feedba...","pt":"Aprenda a configurar o Author Feedback para melhorar a qualidade do texto gerado por IA. Descubra como otimizar a retroalimentação de autores em ferramentas ...","ru":"Узнайте, как настроить автор-скилл для улучшения качества сгенерированного текста ИИ Агентами. Откройте для себя, как оптимизировать обратную связь от авторо...","ar":"تعلم كيفية ضبط مخرجات مديري التغذية الراجعة للمؤلف لتحسين جودة النص الذي يولد بواسطة أدوات الذكاء الاصطناعي. اكتشف كيفية تحسين التغذية الراجعة للمؤلف في أدوا..."},"definition":{"en":"author-feedback is a skill that modifies AI agent files based on user-provided corrections to generate text closer to the author''s intended style","zh":"作者反馈是一种AI技能，通过分析作者的反馈来优化AI生成文本","ja":"著者フィードバックは、著者のフィードバックを分析してAI生成テキストを最適化するAIスキルです","ko":"저자 피드백은 저자의 피드백을 분석하여 AI 생성 텍스트를 최적화하는 AI 스킬입니다","es":"Author Feedback es una función de aprendizaje que utiliza la retroalimentación del autor para mejorar la generación de texto en agentes de IA.","fr":"La réaction de l''auteur est une fonction d''apprentissage qui utilise la rétroaction de l''auteur pour améliorer la génération de texte dans les outils d''IA.","de":"Author-Feedback ist eine Lernfunktion, die die Rückmeldung des Autors verwendet, um die Textgenerierung in KI-Agents zu verbessern.","pt":"O Author Feedback é um skill de IA que otimiza a retroalimentação de autores para melhorar a qualidade do texto gerado.","ru":"Автор-скилл — это скилл ИИ, который оптимизирует обратную связь от авторов для улучшения качества сгенерированного текста.","ar":"مخرجات مديري التغذية الراجعة للمؤلف هو مهارة ذكاء اصطناعي يتحسين التغذية الراجعة للمؤلف لتحسين جودة النص الذي يولد."},"features":{"en":["Processes ''было/стало'' input for comparative text analysis","Accepts ''только исправленный текст'' for contextual chat corrections","Handles ''текстовые замечания'' for nuanced feedback incorporation","Modifies all files in the author-skill to reflect user feedback","Enables next-generation text output in the author''s style","Supports iterative refinement through repeated feedback loops"],"zh":["接收作者的反馈（原始AI文本+修改后的文本）","支持单独的修改后的文本输入","支持文本备注的输入","使用CLI进行配置","集成React和Python技术","优化AI生成文本以匹配作者风格"],"ja":["著者のフィードバック（オリジナルのAIテキスト+修正されたテキスト）を受け取る","修正されたテキストのみの入力をサポート","テキストの注釈の入力をサポート","CLIを使用して設定","ReactとPythonの技術を統合","AI生成テキストを著者スタイルに最適化"],"ko":["저자의 피드백（원본 AI 텍스트+수정된 텍스트）を受け取음","수정된 텍스트만의 입력을 지원","텍스트备注의 입력을 지원","CLI를 사용하여 설정","React와 Python 기술을 통합","AI 생성 텍스트를 저자 스타일에 최적화"],"es":["Procesamiento de texto original y corregido","Análisis de retroalimentación del autor","Actualización de archivos de skill para mejorar la generación de texto","Compatibilidad con diferentes formatos de entrada","Integración con tecnologías de IA para mejorar la generación de texto"],"fr":["Traitement du texte original et corrigé","Analyse de la rétroaction de l''auteur","Mise à jour des fichiers de compétence pour améliorer la génération de texte","Compatibilité avec différents formats d''entrée","Intégration avec les technologies d''IA pour améliorer la génération de texte"],"de":["Verarbeitung von Original- und korrigiertem Text","Analyse der Rückmeldung des Autors","Aktualisierung von Skill-Dateien zur Verbesserung der Textgenerierung","Kompatibilität mit verschiedenen Eingabeformaten","Integration mit KI-Technologien zur Verbesserung der Textgenerierung"],"pt":["Recebe a correção do texto original e modifica os arquivos do skill","Otimiza a retroalimentação de autores em ferramentas de IA","Melhora a qualidade do texto gerado por IA","Permite a customização do estilo de texto","Integração com ferramentas de IA para melhorar a eficiência"],"ru":["Получает исправленный текст и модифицирует файлы скилла","Оптимизирует обратную связь от авторов в ИИ инструментах","Улучшает качество сгенерированного текста ИИ","Позволяет настраивать стиль текста","Интегрируется с ИИ инструментами для улучшения эффективности"],"ar":["يستلم النص الأصلي المصحح ويعمل على تعديل ملفات المهارة","يحسن التغذية الراجعة للمؤلف في أدوات الذكاء الاصطناعي","يحسن جودة النص الذي يولد بواسطة أدوات الذكاء الاصطناعي","يسمح بتعديل أسلوب النص","يتكامل مع أدوات الذكاء الاصطناعي لتحسين الكفاءة"]},"keywords":{"en":["how to use author-feedback","author-feedback setup guide","what is author-feedback","author-feedback alternative","author-feedback vs human editing","install author-feedback","author-feedback for AI agents","text optimization with author-feedback","author-feedback for content creation"],"zh":["AI工具","作者反馈","AI生成文本","分析式技能","CLI配置","React集成","Python集成","文本优化","作者风格"],"ja":["AIエージェント","著者フィードバック","AI生成テキスト","分析スキル","CLI設定","React統合","Python統合","テキスト最適化","著者スタイル"],"ko":["AI 에이전트","저자 피드백","AI 생성 텍스트","분석 스킬","CLI 설정","React 통합","Python 통합","텍스트 최적화","저자 스타일"],"es":["agentes de IA","author feedback","retroalimentación del autor","generación de texto","aprendizaje automático","procesamiento de lenguaje natural","desarrollo de skills de IA","mejora de la generación de texto","configuración de author feedback"],"fr":["outils d''IA","réaction de l''auteur","rétroaction de l''auteur","génération de texte","apprentissage automatique","traitement du langage naturel","développement de compétences d''IA","amélioration de la génération de texte","configuration de la réaction de l''auteur"],"de":["KI-Agents","author feedback","Rückmeldung des Autors","Textgenerierung","maschinelles Lernen","natürliche Sprachverarbeitung","Entwicklung von KI-Skills","Verbesserung der Textgenerierung","Einrichtung von Author-Feedback"],"pt":["Author Feedback","Retroalimentação de autores","Ferramentas de IA","Otimização de texto","Customização de estilo","Integração com IA","Melhoria da qualidade do texto","Desenvolvimento de skills de IA"],"ru":["Автор-скилл","Обратная связь от авторов","ИИ инструменты","Оптимизация текста","Настройка стиля","Интеграция с ИИ","Улучшение качества текста","Разработка скиллов ИИ"],"ar":["مخرجات مديري التغذية الراجعة للمؤلف","التغذية الراجعة للمؤلف","أدوات الذكاء الاصطناعي","تحسين النص","تعديل أسلوب النص","التكامل مع أدوات الذكاء الاصطناعي","تحسين جودة النص","تطوير مهارات الذكاء الاصطناعي"]}},"owner":"arbilinskiy-dev","repo":"vk_all","repoPath":"arbilinskiy-dev/vk_all","stars":0,"forks":0,"updatedAt":"2026-03-04T15:06:23Z","topics":[],"category":"community","skillMd":{"name":"author-feedback","description":"Обратная связь для автор-скилла. Принимает исправленный текст (было/стало или только исправленный вариант) — анализирует дельту изменений, выявляет паттерны правок и автоматически обновляет файлы автор-скилла (SKILL.md + JSON-анализы). По сути обучает автор-скилл на основе обратной связи. Триггеры — «вот исправленный текст», «я поправил пост», «обнови автор скилл», «фитбек автор скилл», «author feedback», «вот как я исправил», «было/стало», «автор скилл не так написал», «скорректируй стиль автора», «обнови стиль на основе правок», «я поправил — обнови скилл», «вот мои правки к посту».","bodyPreview":"# Скилл: Author Feedback — Обучение автор-скилла на обратной связи\n\n## Роль\n\nТы — аналитик стиля, который получает обратную связь от автора (исправленный текст) и модернизирует все файлы автор-скилла, чтобы следующий сгенерированный текст был ближе к авторскому стилю.\n\n## Входные данные\n\nПользователь даёт ОДНО из:\n- **Было/стало** — оригинальный AI-текст + исправленный автором текст\n- **Только исправленный текст** — если оригинал AI-текста доступен в контексте чата\n- **Текстовые замечания** — \"в","body":"# Скилл: Author Feedback — Обучение автор-скилла на обратной связи\n\n## Роль\n\nТы — аналитик стиля, который получает обратную связь от автора (исправленный текст) и модернизирует все файлы автор-скилла, чтобы следующий сгенерированный текст был ближе к авторскому стилю.\n\n## Входные данные\n\nПользователь даёт ОДНО из:\n- **Было/стало** — оригинальный AI-текст + исправленный автором текст\n- **Только исправленный текст** — если оригинал AI-текста доступен в контексте чата\n- **Текстовые замечания** — \"вот тут слишком пафосно\", \"убери телесность\", \"добавь больше опечаток\"\n\n## Процедура\n\n### Шаг 1: Собрать пару \"AI-текст ↔ исправленный текст\"\n\nЕсли пользователь дал только исправленный вариант — найти оригинальный AI-текст в контексте чата (он был сгенерирован ранее в этом диалоге).\n\nЕсли оригинал недоступен — попросить пользователя предоставить оба варианта.\n\n### Шаг 2: Глубокий анализ дельты\n\nЗапустить **саб-агент** для проведения детального сравнения текстов. Промпт:\n\n```\nТы — лингвистический аналитик. Тебе даны два текста:\n\nТЕКСТ A (сгенерированный AI):\n{ai_text}\n\nТЕКСТ B (исправленный автором):\n{corrected_text}\n\nПроведи ГЛУБОКИЙ анализ дельты изменений по 12 категориям:\n\n1. ДОБАВЛЕНО — что автор дописал (целые блоки, предложения, слова)\n2. УДАЛЕНО — что автор убрал\n3. ПЕРЕФРАЗИРОВАНО — что переписано другими словами (найди пары)\n4. СТРУКТУРА — изменения в порядке блоков, абзацев\n5. ЛЕКСИКА — замены слов: какие слова AI использовал → какие автор предпочёл\n6. ТОНАЛЬНОСТЬ — стал ли текст жёстче/мягче/ироничнее/серьёзнее\n7. ТЕХНИЧЕСКИЕ ТЕРМИНЫ — как автор обращается с терминами (объясняет, упрощает, убирает)\n8. МЕТАФОРЫ — какие метафоры добавлены/убраны/заменены\n9. ОПЕЧАТКИ — добавил ли автор натуральные опечатки, какого типа\n10. CTA/ФИНАЛ — как изменился финал поста\n11. P.S. БЛОКИ — добавлены/убраны/изменены постскриптумы\n12. КОНТЕКСТ/ОБЪЯСНЕНИЯ — добавил ли автор контекст \"зачем\", \"как было раньше\", пояснения терминов\n\nДля каждой категории приведи:\n- Конкретные примеры (цитаты из обоих текстов)\n- Паттерн (если виден повторяющийся принцип)\n- Рекомендацию для обновления инструкции ghostwriter-скилла\n\nВерни результат как JSON:\n{\n  \"categories\": [\n    {\n      \"name\": \"ДОБАВЛЕНО\",\n      \"examples\": [...],\n      \"pattern\": \"описание паттерна\",\n      \"recommendation\": \"что добавить/изменить в скилле\"\n    },\n    ...\n  ],\n  \"summary\": \"3-5 ключевых выводов о том, что скилл делает неправильно\",\n  \"severity\": \"minor|moderate|major\" // насколько критичны изменения\n}\n```\n\n### Шаг 3: Прочитать текущие файлы автор-скилла\n\n⚡ ПАРАЛЛЕЛЬНО запустить 2 саб-агента:\n\n**Саб-агент A** — прочитать SKILL.md:\n```\nПрочитай файл .agents/skills/author-writer/SKILL.md полностью.\nВерни его содержимое целиком. Это нужно для обновления на основе обратной связи.\n```\n\n**Саб-агент B** — прочитать JSON-файлы анализа:\n```\nПрочитай ВСЕ 6 JSON-файлов из backend_python/data/author_analysis/:\n- writing_style.json\n- rhetoric.json\n- structure.json\n- influence.json\n- psychology.json\n- values.json\n\nДля каждого файла верни:\n1. Путь к файлу\n2. Полное содержимое (без сокращений)\n```\n\n### Шаг 4: Сформировать план правок\n\nНа основе анализа дельты (Шаг 2) и текущего содержимого файлов (Шаг 3) — определить:\n\n#### Какие файлы затронуты\n\n| Тип изменения | Какой файл обновлять |\n|---|---|\n| Лексика, опечатки, синтаксис, термины | `writing_style.json` + SKILL.md (раздел II) |\n| Метафоры, ирония, приёмы, P.S. | `rhetoric.json` + SKILL.md (раздел III) |\n| Структура поста, формат, длина | `structure.json` + SKILL.md (раздел VI) |\n| CTA, крючки, финал поста | `influence.json` + SKILL.md (раздел IV) |\n| Тональность, эмоции, уязвимость | `psychology.json` + SKILL.md (раздел I) |\n| Ценности, позиция, мировоззрение | `values.json` + SKILL.md (раздел V) |\n| Быстрые правила, чеклист, процедура | SKILL.md (разделы \"Быстрый старт\", \"Чеклист\", \"Процедура\") |\n\n#### Типы правок\n\nДля каждого выявленного паттерна — определить тип правки:\n- **ДОБАВИТЬ** — нового правила/паттерна не было → добавить\n- **УСИЛИТЬ** — правило есть, но работает слабо → усилить формулировку, добавить примеры\n- **ОСЛАБИТЬ** — правило слишком агрессивное → смягчить, добавить оговорку \"ДОЗИРОВАННО\"\n- **УДАЛИТЬ** — правило мешает → убрать или пометить как deprecated\n- **ПЕРЕФОРМУЛИРОВАТЬ** — правило есть, но сбивает с толку → переписать яснее\n\n### Шаг 5: Применить правки\n\nПрименить изменения к файлам. Приоритет:\n\n1. **SKILL.md** — главный файл инструкций, всегда обновляется первым\n2. **JSON-файлы** — дополнительные данные, обновляются если затронуты\n\nПри внесении правок:\n- **НЕ удалять** существующие правила без явного конфликта с обратной связью\n- **НЕ переписывать** разделы целиком — точечные правки\n- **Добавлять примеры** из реальной дельты (цитаты из исправленного автором текста)\n- **Обновлять \"Быстрый старт\"** если добавлено новое ключевое правило\n- **Обновлять \"Чеклист\"** если добавлен новый пункт проверки\n\n### Шаг 6: Отчёт пользователю\n\nВернуть пользователю краткий отчёт:\n\n```\n## Обновление автор-скилла на основе обратной связи\n\n### Выявленные паттерны:\n1. [паттерн] — [что было не так] → [что исправлено]\n2. ...\n\n### Обновлённые файлы:\n- ✅ SKILL.md — [какие разделы затронуты]\n- ✅ writing_style.json — [что добавлено/изменено]\n- ...\n\n### Ключевые изменения:\n- [самое важное изменение]\n- [второе по важности]\n- ...\n```\n\n## Делегирование саб-агентам\n\nСледующие шаги рекомендуется выполнять через `runSubagent`:\n\n| Шаг | Что делегировать | Параллельность |\n|---|---|---|\n| Шаг 2 | Анализ дельты (лингвистический разбор) | Один агент |\n| Шаг 3A | Чтение SKILL.md | ⚡ ПАРАЛЛЕЛЬНО с 3B |\n| Шаг 3B | Чтение 6 JSON-файлов | ⚡ ПАРАЛЛЕЛЬНО с 3A |\n\n## Примеры использования\n\n### Пример 1: Пользователь дал исправленный текст\n```\nПользователь: \"Вот я поправил пост, смотри:\n[исправленный текст]\"\n\n→ Скилл находит AI-текст в контексте чата\n→ Анализирует дельту\n→ Обновляет файлы\n```\n\n### Пример 2: Пользователь дал было/стало\n```\nПользователь: \"Обнови автор скилл. Было:\n[AI текст]\nСтало:\n[исправленный текст]\"\n\n→ Скилл анализирует дельту\n→ Обновляет файлы\n```\n\n### Пример 3: Пользователь дал текстовые замечания\n```\nПользователь: \"Автор скилл пишет слишком пафосно,\nдобавь больше опечаток и убери философию из экшн-постов\"\n\n→ Скилл читает текущие файлы\n→ Корректирует правила в указанном направлении\n```\n\n## Красные линии\n\n- **НЕ удалять** массово существующие правила — только точечные правки\n- **НЕ менять** структуру JSON-файлов (ключи, вложенность) — только значения\n- **НЕ добавлять** правила, противоречащие ядру стиля автора (ценности, красные линии из раздела V)\n- **НЕ делать** выводы на основе одного исправления — если паттерн виден в 1 месте, формулировать как \"тенденция\", а не как \"жёсткое правило\"\n- **Спрашивать** пользователя если правка может конфликтовать с существующим правилом\n"},"lastSynced":"2026-03-07T04:16:20.605Z","agentAnalysis":{"suitability":{"en":"Ideal for Language Agents like Claude Code, AutoGPT, and LangChain needing refined text generation through author feedback","zh":"适用于 Claude Code、AutoGPT 和 LangChain 等语言代理，需要通过作者反馈来实现精细的文本生成","ja":"Claude Code、AutoGPT、LangChain などの言語エージェントに適しており、著者からのフィードバックを通じて洗練されたテキスト生成が必要","ko":"Claude Code, AutoGPT, LangChain 등의 언어 에이전트에 적합하며, 저자 피드백을 통해 세련된 텍스트 생성이 필요한 경우","es":"Ideal para Agentes de Lenguaje como Claude Code, AutoGPT y LangChain que necesitan generación de texto refinada a través de la retroalimentación del autor","fr":"Idéal pour les agents de langage comme Claude Code, AutoGPT et LangChain qui nécessitent une génération de texte raffinée via les commentaires de l''auteur","de":"Ideal für Sprachagenten wie Claude Code, AutoGPT und LangChain, die eine verfeinerte Textgenerierung durch Autorenfeedback benötigen","pt":"Ideal para Agentes de Linguagem como Claude Code, AutoGPT e LangChain que necessitam de geração de texto refinada por meio de feedback do autor","ru":"Идеально подходит для языковых агентов, таких как Claude Code, AutoGPT и LangChain, требующих усовершенствованной генерации текста посредством обратной связи автора","ar":"مثالي لعميل لغة مثل Claude Code و AutoGPT و LangChain الذين يحتاجون إلى توليد نص متطور من خلال ملاحظات الكاتب"},"recommendation":{"en":"Empowers agents to refine AI-generated text by incorporating corrected text feedback, ensuring subsequent outputs align with the author''s style through comprehensive content analysis, utilizing text feedback protocols and natural language processing techniques","zh":"赋予代理人通过整合更正的文本反馈来完善 AI 生成的文本的能力，确保后续输出与作者的风格一致，通过全面内容分析，利用文本反馈协议和自然语言处理技术","ja":"エージェントに、訂正されたテキストのフィードバックを組み込むことで、AI によって生成されたテキストを洗練させる能力を与え、後の出力を著者のスタイルと一致させることを保証する。包括的なコンテンツ分析を使用し、テキストのフィードバックプロトコルと自然言語処理技術を利用する","ko":"에이전트에게 수정된 텍스트 피드백을 통합하여 AI가 생성한 텍스트를 세련되게 만드는 능력을 부여하여, 이후의 출력이 저자의 스타일과 일치하도록 보장한다. 포괄적인 콘텐츠 분석을 사용하고, 텍스트 피드백 프로토콜 및 자연어 처리 기술을 활용한다","es":"Habilita a los agentes a perfeccionar el texto generado por IA incorporando la retroalimentación de texto corregida, asegurando que las salidas posteriores se alineen con el estilo del autor a través del análisis de contenido integral, utilizando protocolos de retroalimentación de texto y técnicas de procesamiento de lenguaje natural","fr":"Permet aux agents de raffiner le texte généré par IA en intégrant les commentaires de texte corrigés, en garantissant que les sorties ultérieures s''alignent sur le style de l''auteur via une analyse de contenu complète, en utilisant des protocoles de commentaires de texte et des techniques de traitement du langage naturel","de":"Ermächtigt die Agenten, den von künstlicher Intelligenz generierten Text durch die Einbeziehung von korrigiertem Textfeedback zu verfeinern, sodass die nachfolgenden Ausgaben mit dem Stil des Autors übereinstimmen, durch umfassende Inhaltsanalyse, unter Verwendung von Text-Feedback-Protokollen und Techniken des natürlichen Sprachverarbeitung","pt":"Habilita os agentes a refinar o texto gerado por IA incorporando feedback de texto corrigido, garantindo que as saídas subsequentes estejam alinhadas com o estilo do autor por meio de análise de conteúdo abrangente, utilizando protocolos de feedback de texto e técnicas de processamento de linguagem natural","ru":"Наделяет агентов возможностью усовершенствовать текст, сгенерированный ИИ, включая исправленный текстовый фидбэк, гарантируя, что последующие выводы соответствуют стилю автора посредством всестороннего анализа контента, используя протоколы текстового фидбэка и техники обработки естественного языка","ar":"يتمكّن الوكيل من تعديل النص الذي تمّ توليده بواسطة الذكاء الاصطناعي عن طريق دمج ملاحظات النص المصحّح، مما يضمن أنّ الإخراجات اللاحقة تتماشى مع أسلوب الكاتب من خلال تحليل المحتوى الشامل، واستخدام بروتوكولات ملاحظات النص و تقنيات معالجة اللغة الطبيعية"},"useCases":{"en":["Refining AI-generated content for publishing","Aligning AI outputs with specific author styles","Improving text coherence through iterative feedback"],"zh":["为出版而改进 AI 生成的内容","使 AI 输出与特定的作者风格一致","通过迭代反馈来提高文本的连贯性"],"ja":["出版のために AI によって生成されたコンテンツを改良する","AI の出力を特定の著者のスタイルと一致させる","イテレーティブなフィードバックを通じてテキストの連貫性を改善する"],"ko":["발행을 위해 AI가 생성한 콘텐츠를 개선하는 것","AI 출력을 특정 저자의 스타일과 일치시키는 것","반복적인 피드백을 통해 텍스트의 일관성을 개선하는 것"],"es":["Perfeccionar el contenido generado por IA para su publicación","Alinear las salidas de IA con estilos de autor específicos","Mejorar la coherencia del texto a través de la retroalimentación iterativa"],"fr":["Perfectionner le contenu généré par IA pour la publication","Aligner les sorties de l''IA sur des styles d''auteur spécifiques","Améliorer la cohérence du texte via une rétroaction itérative"],"de":["Vervollkommnen des von künstlicher Intelligenz generierten Inhalts für die Veröffentlichung","Ausrichten der künstlichen Intelligenz-Ausgaben an spezifischen Autorenstilen","Verbesserung der Textkohärenz durch iterative Rückmeldung"],"pt":["Refinamento de conteúdo gerado por IA para publicação","Alinhamento de saídas de IA com estilos de autor específicos","Melhoria da coerência do texto por meio de feedback iterativo"],"ru":["Усовершенствование контента, сгенерированного ИИ, для публикации","Совмещение выводов ИИ с конкретными стилями автора","Улучшение связности текста посредством итеративного фидбэка"],"ar":["تعديل المحتوى الذي تمّ توليده بواسطة الذكاء الاصطناعي للنشر","مواءمة إخراجات الذكاء الاصطناعي مع أساليب الكتّاب المحدّدة","تحسين تماسك النص من خلال ملاحظات متكررة"]},"limitations":{"en":["Requires user-provided corrected text feedback","Limited to text-based feedback formats"],"zh":["需要用户提供更正的文本反馈","仅限于基于文本的反馈格式"],"ja":["ユーザーが訂正されたテキストのフィードバックを提供する必要がある","テキストベースのフィードバック形式のみに限定される"],"ko":["사용자가 수정된 텍스트 피드백을 제공해야 함","텍스트 기반 피드백 형식만으로 제한됨"],"es":["Requiere retroalimentación de texto corregida proporcionada por el usuario","Limitado a formatos de retroalimentación basados en texto"],"fr":["Nécessite des commentaires de texte corrigés fournis par l''utilisateur","Limité aux formats de commentaires basés sur le texte"],"de":["Benötigt vom Benutzer bereitgestelltes korrigiertes Text-Feedback","Begrenzt auf textbasierte Feedback-Formate"],"pt":["Exige feedback de texto corrigido fornecido pelo usuário","Limitado a formatos de feedback baseados em texto"],"ru":["Требует исправленного текстового фидбэка, предоставленного пользователем","Ограничен форматами фидбэка на основе текста"],"ar":["يتطلب ملاحظات نصية محسّنة من قبل المستخدم","محدود بالتنسيقات القائمة على ملاحظات النص"]},"version":4},"contentHash":"7dfea20081c2618043e4e91494df9f6a3a5a851c459cf3c5168683ec28615df1","qualityScore":30}');
