INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arbilinskiy-dev/vk_all/author-feedback', 'author-feedback', 'arbilinskiy-dev', 'vk_all', 'community', 'author-feedback arbilinskiy-dev vk_all community The author-feedback skill enables analysts to refine AI-generated text by providing corrected text feedback, ensuring subsequent outputs align with the author''s style. This skill benefits developers and writers seeking to perfect their AI-driven content creation. 作者反馈技能是一种分析式技能，用于接收作者的反馈并修改AI生成文本以匹配作者风格 著者フィードバックスキルは、著者のフィードバックを受け取り、AI生成テキストを著者スタイルに合わせるための分析スキルです 저자 피드백 스킬은 저자의 피드백을 받고 AI 생성 텍스트를 저자 스타일에 맞추기 위한 분석 스킬입니다 Author Feedback es un skill que permite a los agentes de IA aprender de la retroalimentación del autor para mejorar la generación de texto. La réaction de l''auteur est une compétence qui permet aux outils d''IA d''apprendre de la rétroaction de l''auteur pour améliorer la génération de texte. Author-Feedback ist ein Skill, der es KI-Agents ermöglicht, von der Rückmeldung des Autors zu lernen, um die Textgenerierung zu verbessern. O Author Feedback é um skill que permite a otimização da retroalimentação de autores em ferramentas de IA. Ele recebe a correção do texto original e modifica os arquivos do skill para melhorar a qualidade do texto gerado. Автор-скилл — это скилл, который позволяет оптимизировать обратную связь от авторов в ИИ инструментах. Он получает исправленный текст и модифицирует файлы скилла для улучшения качества сгенерированного текста. مخرجات مديري التغذية الراجعة للمؤلف هو مهارة يسمح بتحسين التغذية الراجعة للمؤلف في أدوات الذكاء الاصطناعي. وهو يستلم النص الأصلي المصحح ويعمل على تعديل ملفات المهارة لتحسين جودة النص الذي يولد. how to use author-feedback author-feedback setup guide what is author-feedback author-feedback alternative author-feedback vs human editing install author-feedback author-feedback for AI agents text optimization with author-feedback author-feedback for content creation AI工具 作者反馈 AI生成文本 分析式技能 CLI配置 React集成 Python集成 文本优化 作者风格 Processes ''было/стало'' input for comparative text analysis Accepts ''только исправленный текст'' for contextual chat corrections Handles ''текстовые замечания'' for nuanced feedback incorporation Modifies all files in the author-skill to reflect user feedback Enables next-generation text output in the author''s style Supports iterative refinement through repeated feedback loops author-feedback is a skill that modifies AI agent files based on user-provided corrections to generate text closer to the author''s intended style');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chen893/--skill/novel-indexing-and-searching', 'community', 'chen893', '--skill', 'chen893/--skill', 'novel-indexing-and-searching', 0, 0, 30, '2026-03-01T14:13:15Z', '2026-03-07T04:17:02.306Z', '620435182f869462557367ff0ab1f3fad85b69f8f6aa67dea70ef80c80a1b95b', '{"id":"chen893/--skill/novel-indexing-and-searching","name":"novel-indexing-and-searching","description":{"en":"novel-indexing-and-searching enables developers to efficiently search and retrieve files using stable IDs and indexed caches. It benefits developers working with large projects.","zh":"novel-indexing-and-searching是一种高效的索引与检索技术，使用Python和CLI脚本生成和更新索引。它能够实现精准定位到行，减少回读整书的时间。","ja":"novel-indexing-and-searchingは効率的なインデックスと検索技術であり、PythonとCLIスクリプトを使用してインデックスを生成および更新します。行への精密な位置付けを実現し、全書の再読み込み時間を短縮します。","ko":"novel-indexing-and-searching는 효율적인 색인 및 검색 기술입니다. Python 및 CLI 스크립트를 사용하여 색인을 생성하고 업데이트합니다. 행으로의 精密한 위치 지정이 가능하며, 전체 책의 다시 읽기 시간을 단축합니다.","es":"Novel-indexing-and-searching es una habilidad que permite la indexación y búsqueda de entidades en un proyecto, utilizando tecnologías como Python y CLI.","fr":"Novel-indexing-and-searching est une compétence qui permet l''indexation et la recherche d''entités dans un projet, en utilisant des technologies telles que Python et CLI.","de":"Novel-indexing-and-searching ist eine Fähigkeit, die die Indizierung und Suche nach Entitäten in einem Projekt ermöglicht, unter Verwendung von Technologien wie Python und CLI.","pt":"O skill de novel-indexing-and-searching permite a indexação e busca eficiente de novelas. Utilize essa ferramenta para melhorar a experiência do usuário.","ru":"Навык novel-indexing-and-searching позволяет индексировать и искать романы эффективно. Используйте эту инструменту, чтобы улучшить опыт пользователя.","ar":"المهارة novel-indexing-and-searching تسمح بفهرسة و بحث الروايات بكفاءة. استخدم هذه الأداة لتحسين تجربة المستخدم."},"seo":{"title":{"en":"novel-indexing-and-searching: Efficient File Search Setup...","zh":"AI工具：novel-indexing-and-searching 索引与检索设置指南","ja":"AIエージェント：novel-indexing-and-searching インデックスと検索のベストプラクティス","ko":"AI 도구: novel-indexing-and-searching 색인 및 검색 설정 가이드","es":"Guía de configuración para novel-indexing-and-searching c...","fr":"Guide de configuration pour novel-indexing-and-searching ...","de":"Konfigurationsleitfaden für novel-indexing-and-searching ...","pt":"Guia de Configuração de Indexação e Busca de Novelas","ru":"Настройка Индексации и Поиска Романов ИИ Агентов","ar":"دليل إعداد فهرسة و بحث الروايات لعمليات الإستخبارات الاصط..."},"description":{"en":"Unlock rapid file search with novel-indexing-and-searching. Discover how to generate indexes, use stable IDs, and optimize your workflow. Get started now!","zh":"了解novel-indexing-and-searching的技术细节，实现高效的索引与检索。使用Python和CLI脚本，轻松生成和更新索引。","ja":"novel-indexing-and-searchingの技術的詳細を学び、効率的なインデックスと検索を実現しましょう。PythonとCLIスクリプトを使用して、インデックスを生成および更新します。","ko":"novel-indexing-and-searching의 기술적 세부 사항을 알아보고 효율적인 색인 및 검색을 구현하세요. Python 및 CLI 스크립트를 사용하여 색인을 생성하고 업데이트합니다.","es":"Aprende a configurar y utilizar novel-indexing-and-searching con nuestra guía paso a paso y mejora tu experiencia de desarrollo con herramientas de AI","fr":"Découvrez comment configurer et utiliser novel-indexing-and-searching avec notre guide étape par étape et améliorez votre expérience de développement avec de...","de":"Erfahren Sie, wie Sie novel-indexing-and-searching konfigurieren und verwenden können, mit unserem Schritt-für-Schritt-Leitfaden und verbessern Sie Ihre Entw...","pt":"Aprenda a configurar a indexação e busca de novelas com o skill de novel-indexing-and-searching. Melhore a eficiência da sua aplicação com essa ferramenta de...","ru":"Узнайте, как настроить индексацию и поиск романов с помощью навыка novel-indexing-and-searching. Улучшите эффективность вашего приложения с этой передовой ин...","ar":"تعلم كيفية إعداد فهرسة و بحث الروايات مع مهارة novel-indexing-and-searching. تحسين كفاءة تطبيقك مع هذه الأداة البحث المتقدمة."},"definition":{"en":"novel-indexing-and-searching is a skill that enables efficient file search and retrieval through indexing and caching, using stable IDs and table structures.","zh":"novel-indexing-and-searching是一种使用Python和CLI脚本的索引与检索技术","ja":"novel-indexing-and-searchingはPythonとCLIスクリプトを使用したインデックスと検索技術です","ko":"novel-indexing-and-searching는 Python 및 CLI 스크립트를 사용한 색인 및 검색 기술입니다","es":"Novel-indexing-and-searching es una herramienta de AI que permite la indexación y búsqueda de entidades en un proyecto","fr":"Novel-indexing-and-searching est un outil d''IA qui permet l''indexation et la recherche d''entités dans un projet","de":"Novel-indexing-and-searching ist ein KI-Tool, das die Indizierung und Suche nach Entitäten in einem Projekt ermöglicht","pt":"O novel-indexing-and-searching é uma ferramenta de busca avançada que indexa e busca novelas de forma eficiente.","ru":"Навык novel-indexing-and-searching - это передовая инструментой поиска, которая индексирует и ищет романы эффективно.","ar":"المهارة novel-indexing-and-searching هي أداة بحث متقدمة تفهرس و تبحث الروايات بكفاءة."},"features":{"en":["Generates indexes using Python scripts in the `.codex/skills/novel-indexing-and-searching/scripts` directory","Utilizes stable IDs for entities, such as `char-中文名` and `loc-中文名`, for reliable referencing","Supports table structures in `open-threads.md` and `timeline.md` for easy parsing","Creates derived caches in the `WORKDIR/_data` directory for fast access","Allows for rebuilding indexes at any time, prohibiting manual modifications"],"zh":["使用Python和CLI脚本生成和更新索引","实现精准定位到行，减少回读整书的时间","支持多种实体类型，包括角色、地点、组织等","使用稳定ID，禁止使用拼音做ID"],"ja":["PythonとCLIスクリプトを使用してインデックスを生成および更新","行への精密な位置付けを実現し、全書の再読み込み時間を短縮","多種のエンティティタイプをサポート、キャラクター、場所、組織など","安定したIDを使用し、拼音をIDとして使用することを禁止"],"ko":["Python 및 CLI 스크립트를 사용하여 색인을 생성하고 업데이트합니다","행으로의 精密한 위치 지정이 가능하며, 전체 책의 다시 읽기 시간을 단축합니다","다양한 엔티티 유형을 지원합니다. 캐릭터, 장소, 조직 등","안정된 ID를 사용하며,拼音을 ID로 사용하는 것을 금지합니다"],"es":["Generación de índices con Python","Búsqueda de entidades con CLI","Soporte para archivos Markdown","Indexación de entidades como personajes, lugares y objetos","Integración con herramientas de desarrollo como Git"],"fr":["Génération d''indexes avec Python","Recherche d''entités avec CLI","Prise en charge des fichiers Markdown","Indexation d''entités telles que des personnages, des lieux et des objets","Intégration avec des outils de développement comme Git"],"de":["Erstellung von Indizes mit Python","Suche nach Entitäten mit CLI","Unterstützung für Markdown-Dateien","Indizierung von Entitäten wie Charakteren, Orten und Objekten","Integration mit Entwicklungstools wie Git"],"pt":["Indexação de novelas em tempo real","Busca avançada com filtro por entidades","Suporte a estruturas de dados personalizadas","Integração com o CLI para execução de comandos","Geração de índices em formato de arquivo"],"ru":["Индексация романов в реальном времени","Расширенный поиск с фильтром по сущностям","Поддержка пользовательских структур данных","Интеграция с CLI для выполнения команд","Генерация индексов в формате файла"],"ar":["فهرسة الروايات في الوقت الحقيقي","بحث متقدم مع مرشح الكيانات","دعم الهياكل البيانية المخصصة","التكامل مع CLI لتنفيذ الأوامر","توليد الفهارس في شكل ملف"]},"keywords":{"en":["how to use novel-indexing-and-searching","novel-indexing-and-searching setup guide","novel-indexing-and-searching vs traditional search methods","novel-indexing-and-searching install","what is novel-indexing-and-searching","novel-indexing-and-searching alternative solutions","novel-indexing-and-searching for AI agents","novel-indexing-and-searching workflow optimization","novel-indexing-and-searching file search efficiency"],"zh":["novel-indexing-and-searching","AI工具","索引与检索","Python","CLI脚本","精准定位","实体类型","稳定ID"],"ja":["novel-indexing-and-searching","AIエージェント","インデックスと検索","Python","CLIスクリプト","精密な位置付け","エンティティタイプ","安定したID"],"ko":["novel-indexing-and-searching","AI 도구","색인 및 검색","Python","CLI 스크립트","정밀한 위치 지정","엔티티 유형","안정된 ID"],"es":["novel-indexing-and-searching","herramientas de AI","desarrollo de software","indexación de entidades","búsqueda de entidades","Python","CLI","Markdown","Git"],"fr":["novel-indexing-and-searching","outils d''IA","développement de logiciels","indexation d''entités","recherche d''entités","Python","CLI","Markdown","Git"],"de":["novel-indexing-and-searching","KI-Tools","Software-Entwicklung","Indizierung von Entitäten","Suche nach Entitäten","Python","CLI","Markdown","Git"],"pt":["indexação de novelas","busca avançada de novelas","ferramenta de busca de novelas","índices de novelas","CLI para novelas","entidades de novelas","estruturas de dados de novelas"],"ru":["индексация романов","расширенный поиск романов","инструмент поиска романов","индексы романов","CLI для романов","сущности романов","структуры данных романов"],"ar":["فهرسة الروايات","بحث متقدم للروايات","أداة بحث الروايات","فهارس الروايات","CLI للروايات","كيانات الروايات","هياكل البيانية للروايات"]}},"owner":"chen893","repo":"--skill","repoPath":"chen893/--skill","stars":0,"forks":0,"updatedAt":"2026-03-01T14:13:15Z","topics":[],"category":"community","skillMd":{"name":"novel-indexing-and-searching","description":"索引与检索：为长篇生成可重建的本地索引（entities/chapters/threads/timeline），并提供按 ID/专名/关键词快速定位“在哪章哪段”的检索工具。用于“找某段原文、查某角色/线索首次出现、定位冲突来源、避免回读整章整卷”等需求。","bodyPreview":"# 索引与检索（novel-indexing-and-searching）\n\n## 目标\n\n- 先检索、再打开文件：把“回读整书”变成“精准定位到行”。\n- 索引是派生缓存：写到 `WORKDIR/_data/**`，可随时重建，禁止手改（WORKDIR 为工作区目录名，默认 `novel`）。\n\n## 核心约定（让索引靠谱）\n\n- 关键实体使用稳定 ID（禁止用拼音做 ID）：\n  - 实体：`char-中文名`/`loc-中文名`/`fac-中文名`/`item-中文名`/`sys-中文名`\n  - 线索/事件：`thr-####`/`evt-####`\n  - bible 文件名通常为：`char-林瑶.md`/`loc-旧镇.md`/`fac-青竹会.md` 等\n- `open-threads.md` 与 `timeline.md` 尽量保持表格结构（便于解析）\n\n## 最短路径工作流\n\n### 1) 生成/更新索引\n\n在项目根目录执行：\n\n```bash\npython .codex/skills/novel-indexing-and-searching/scripts/bui","body":"# 索引与检索（novel-indexing-and-searching）\n\n## 目标\n\n- 先检索、再打开文件：把“回读整书”变成“精准定位到行”。\n- 索引是派生缓存：写到 `WORKDIR/_data/**`，可随时重建，禁止手改（WORKDIR 为工作区目录名，默认 `novel`）。\n\n## 核心约定（让索引靠谱）\n\n- 关键实体使用稳定 ID（禁止用拼音做 ID）：\n  - 实体：`char-中文名`/`loc-中文名`/`fac-中文名`/`item-中文名`/`sys-中文名`\n  - 线索/事件：`thr-####`/`evt-####`\n  - bible 文件名通常为：`char-林瑶.md`/`loc-旧镇.md`/`fac-青竹会.md` 等\n- `open-threads.md` 与 `timeline.md` 尽量保持表格结构（便于解析）\n\n## 最短路径工作流\n\n### 1) 生成/更新索引\n\n在项目根目录执行：\n\n```bash\npython .codex/skills/novel-indexing-and-searching/scripts/build_index.py --root .\n```\n\n输出写入：\n- `WORKDIR/_data/entities.json`\n- `WORKDIR/_data/chapter_index.json`\n- `WORKDIR/_data/threads.json`\n- `WORKDIR/_data/timeline.json`\n\n### 2) 执行检索\n\n在项目根目录执行：\n\n```bash\npython .codex/skills/novel-indexing-and-searching/scripts/search.py --root . --query \"thr-0007\"\n```\n\n常用技巧：\n- 优先搜 ID（最稳定），其次搜专名（次稳定），最后才搜泛关键词\n- 先在 `summaries/` 与 `continuity/` 搜，再回到 `draft/` 精准回读正文\n- 若工作区目录名不是 `novel`：两条命令都加 `--novel-dir WORKDIR`。\n"},"lastSynced":"2026-03-07T04:17:02.306Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing efficient file retrieval and indexing capabilities in large projects.","zh":"非常适合需要在大型项目中高效文件检索和索引功能的开发代理。","ja":"大規模なプロジェクトで効率的なファイルの取得および索引機能が必要な開発エージェントに最適です。","ko":"대규모 프로젝트에서 효율적인 파일 검색 및 색인 기능이 필요한 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan capacidades de recuperación y indexación de archivos eficientes en proyectos grandes.","fr":"Parfait pour les agents de développement qui ont besoin de capacités de récupération et d''indexation de fichiers efficaces dans les grands projets.","de":"Perfekt für Entwicklungssagenten, die effiziente Dateiabruf- und Indexierungsfunktionen in großen Projekten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de capacidades de recuperação e indexação de arquivos eficientes em projetos grandes.","ru":"Идеально подходит для агентов разработки, которым требуются эффективные возможности поиска и индексации файлов в крупных проектах.","ar":"مثالي لعمليات تطوير العوامل التي تحتاج إلى إمكانيات استرجاع وتصنيف الملفات بكفاءة في المشاريع الكبيرة."},"recommendation":{"en":"Empowers agents to precisely locate and retrieve files using stable IDs and indexed caches, leveraging Python scripts for seamless integration with project workflows, particularly in managing entities and events through `char-`, `loc-`, `fac-`, `item-`, and `sys-` prefixed IDs.","zh":"赋予代理以精确定位和检索文件的能力，使用稳定的ID和索引缓存，利用Python脚本实现与项目工作流的无缝集成，特别是在通过`char-`、`loc-`、`fac-`、`item-`和`sys-`前缀的ID管理实体和事件时。","ja":"エージェントにファイルを正確に位置付けおよび取得する機能を提供し、安定したIDと索引キャッシュを使用し、Pythonスクリプトを使用してプロジェクトのワークフローとのシームレスな統合を実現し、特に`char-`、`loc-`、`fac-`、`item-`、`sys-`接頭辞のIDを使用してエンティティとイベントを管理する場合。","ko":"에이전트에 파일을 정확하게 위치시키고 검색할 수 있는 능력을 부여하며, 안정적인 ID와 색인 캐시를 사용하여 Python 스크립트를 통해 프로젝트 워크플로와의 무縫한 통합을 구현하며, 특히 `char-`, `loc-`, `fac-`, `item-`, `sys-` 접두사 ID를 사용하여 엔티티와 이벤트를 관리하는 경우에 적합합니다.","es":"Habilita a los agentes a localizar y recuperar archivos de manera precisa utilizando IDs estables y cachés indexados, aprovechando scripts de Python para una integración sin problemas con los flujos de trabajo del proyecto, particularmente en la gestión de entidades y eventos a través de IDs con prefijos `char-`, `loc-`, `fac-`, `item-` y `sys-`.","fr":"Permet aux agents de localiser et de récupérer des fichiers de manière précise en utilisant des IDs stables et des caches indexés, en exploitant les scripts Python pour une intégration transparente avec les flux de travail du projet, en particulier dans la gestion d''entités et d''événements via des IDs préfixés `char-`, `loc-`, `fac-`, `item-` et `sys-`.","de":"Ermächtigt Agenten, Dateien präzise zu lokalisieren und abzurufen, indem sie stabile IDs und indizierte Caches verwenden, und nutzt Python-Skripte für eine nahtlose Integration in die Projektworkflows, insbesondere bei der Verwaltung von Entitäten und Ereignissen über `char-`, `loc-`, `fac-`, `item-` und `sys-` vorangestellte IDs.","pt":"Habilita os agentes a localizar e recuperar arquivos com precisão usando IDs estáveis e caches indexados, aproveitando scripts Python para integração transparente com fluxos de trabalho de projeto, particularmente na gestão de entidades e eventos por meio de IDs prefixados por `char-`, `loc-`, `fac-`, `item-` e `sys-`.","ru":"Позволяет агентам точно находить и извлекать файлы, используя стабильные идентификаторы и индексированные кэши, используя скрипты Python для бесшовной интеграции с рабочими процессами проекта, особенно при управлении сущностями и событиями через идентификаторы с префиксами `char-`, `loc-`, `fac-`, `item-` и `sys-`.","ar":"تمكّن العوامل من تحديد موقع الملفات واسترجاعها بدقة باستخدام معرفات مستقرة ومخازن مؤشرة، مستفيدة من سكريبتات Python لتكامل عديم الفجوات مع سير عمل المشروع، لا سيما في إدارة الكيانات والأحداث من خلال معرفات مسبوقة بـ `char-`، `loc-`، `fac-`، `item-` و `sys-`."},"useCases":{"en":["Indexing and searching large project files using stable IDs","Automating the generation and update of indexed caches for efficient file retrieval","Streamlining development workflows by quickly locating specific lines within files"],"zh":["使用稳定的ID对大型项目文件进行索引和搜索","自动化生成和更新索引缓存以实现高效的文件检索","通过快速定位文件中的特定行来简化开发工作流"],"ja":["安定したIDを使用して大規模なプロジェクトのファイルを索引および検索する","索引キャッシュの自動生成および更新を使用して効率的なファイルの取得を実現する","ファイル内の特定の行を迅速に位置付けることで開発ワークフローを合理化する"],"ko":["안정적인 ID를 사용하여 대규모 프로젝트 파일을 색인 및 검색하는 것","색인 캐시의 자동 생성 및 업데이트를 사용하여 효율적인 파일 검색을 구현하는 것","파일 내의 특정 줄을 신속하게 위치시키는ことで 개발 워크플로를 최적화하는 것"],"es":["Indexación y búsqueda de archivos de proyectos grandes utilizando IDs estables","Automatización de la generación y actualización de cachés indexados para una recuperación de archivos eficiente","Optimización de los flujos de trabajo de desarrollo al localizar rápidamente líneas específicas dentro de los archivos"],"fr":["Indexation et recherche de fichiers de projets importants à l''aide d''IDs stables","Automatisation de la génération et de la mise à jour de caches indexés pour une récupération de fichiers efficace","Optimisation des flux de travail de développement en localisant rapidement des lignes spécifiques à l''intérieur des fichiers"],"de":["Indizierung und Suche von Dateien in großen Projekten unter Verwendung stabiler IDs","Automatisierung der Erstellung und Aktualisierung von indizierten Caches für eine effiziente Dateiabruf","Optimierung der Entwicklungswerkflüsse durch schnelles Auffinden spezifischer Zeilen innerhalb von Dateien"],"pt":["Indexação e busca de arquivos de projeto grandes usando IDs estáveis","Automação da geração e atualização de caches indexados para recuperação eficiente de arquivos","Otimização dos fluxos de trabalho de desenvolvimento, localizando rapidamente linhas específicas dentro dos arquivos"],"ru":["Индексация и поиск файлов крупных проектов с использованием стабильных идентификаторов","Автоматизация генерации и обновления индексированных кэшей для эффективного извлечения файлов","Оптимизация рабочих процессов разработки, быстро находя конкретные строки внутри файлов"],"ar":["فهرسة وبحث ملفات المشاريع الكبيرة باستخدام معرفات مستقرة","تحسين آلي لإنشاء وتحديث مخازن مؤشرة لاسترجاع الملفات بكفاءة","تبسيط سير عمل التطوير من خلال تحديد موقع سريع للأسطر المحددة داخل الملفات"]},"limitations":{"en":["Requires Python environment for script execution","Dependent on specific directory structure and file naming conventions","Manual editing of indexed caches is prohibited"],"zh":["需要Python环境来执行脚本","依赖于特定的目录结构和文件命名约定","不允许手动编辑索引缓存"],"ja":["スクリプトの実行にはPython環境が必要","特定のディレクトリ構造とファイル命名規則に依存する","索引キャッシュの手動編集は禁止されている"],"ko":["스크립트 실행을 위해 Python 환경이 필요합니다.","특정 디렉토리 구조 및 파일命명 규칙에 의존합니다.","색인 캐시의 수동 편집은 금지되어 있습니다."],"es":["Requiere un entorno de Python para la ejecución de scripts","Depende de una estructura de directorios y convenciones de nomenclatura de archivos específicas","La edición manual de cachés indexados está prohibida"],"fr":["Nécessite un environnement Python pour l''exécution de scripts","Dépend d''une structure de répertoires et de conventions de dénomination de fichiers spécifiques","L''édition manuelle de caches indexés est interdite"],"de":["Benötigt eine Python-Umgebung für die Skriptausführung","Hängt von einer bestimmten Verzeichnisstruktur und Dateibenennungskonventionen ab","Manuelle Bearbeitung von indizierten Caches ist verboten"],"pt":["Requer ambiente Python para execução de scripts","Dependente de estrutura de diretório específica e convenções de nomenclatura de arquivos","Edição manual de caches indexados é proibida"],"ru":["Требуется среда Python для выполнения скриптов","Зависит от конкретной структуры директории и соглашений об именовании файлов","Ручное редактирование индексированных кэшей запрещено"],"ar":["يتطلب بيئة Python لتنفيذ السكريبتات","يعتمد على هيكل دليلي محدد وتوافق تسمية الملفات","التحرير اليدوي لمخازن المؤشرات محظور"]},"version":4},"contentHash":"620435182f869462557367ff0ab1f3fad85b69f8f6aa67dea70ef80c80a1b95b","qualityScore":30}');
