INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chen893/--skill/novel-indexing-and-searching', 'novel-indexing-and-searching', 'chen893', '--skill', 'community', 'novel-indexing-and-searching chen893 --skill community novel-indexing-and-searching enables developers to efficiently search and retrieve files using stable IDs and indexed caches. It benefits developers working with large projects. novel-indexing-and-searching是一种高效的索引与检索技术，使用Python和CLI脚本生成和更新索引。它能够实现精准定位到行，减少回读整书的时间。 novel-indexing-and-searchingは効率的なインデックスと検索技術であり、PythonとCLIスクリプトを使用してインデックスを生成および更新します。行への精密な位置付けを実現し、全書の再読み込み時間を短縮します。 novel-indexing-and-searching는 효율적인 색인 및 검색 기술입니다. Python 및 CLI 스크립트를 사용하여 색인을 생성하고 업데이트합니다. 행으로의 精密한 위치 지정이 가능하며, 전체 책의 다시 읽기 시간을 단축합니다. Novel-indexing-and-searching es una habilidad que permite la indexación y búsqueda de entidades en un proyecto, utilizando tecnologías como Python y CLI. Novel-indexing-and-searching est une compétence qui permet l''indexation et la recherche d''entités dans un projet, en utilisant des technologies telles que Python et CLI. Novel-indexing-and-searching ist eine Fähigkeit, die die Indizierung und Suche nach Entitäten in einem Projekt ermöglicht, unter Verwendung von Technologien wie Python und CLI. O skill de novel-indexing-and-searching permite a indexação e busca eficiente de novelas. Utilize essa ferramenta para melhorar a experiência do usuário. Навык novel-indexing-and-searching позволяет индексировать и искать романы эффективно. Используйте эту инструменту, чтобы улучшить опыт пользователя. المهارة novel-indexing-and-searching تسمح بفهرسة و بحث الروايات بكفاءة. استخدم هذه الأداة لتحسين تجربة المستخدم. how to use novel-indexing-and-searching novel-indexing-and-searching setup guide novel-indexing-and-searching vs traditional search methods novel-indexing-and-searching install what is novel-indexing-and-searching novel-indexing-and-searching alternative solutions novel-indexing-and-searching for AI agents novel-indexing-and-searching workflow optimization novel-indexing-and-searching file search efficiency novel-indexing-and-searching AI工具 索引与检索 Python CLI脚本 精准定位 实体类型 稳定ID Generates indexes using Python scripts in the `.codex/skills/novel-indexing-and-searching/scripts` directory Utilizes stable IDs for entities, such as `char-中文名` and `loc-中文名`, for reliable referencing Supports table structures in `open-threads.md` and `timeline.md` for easy parsing Creates derived caches in the `WORKDIR/_data` directory for fast access Allows for rebuilding indexes at any time, prohibiting manual modifications novel-indexing-and-searching is a skill that enables efficient file search and retrieval through indexing and caching, using stable IDs and table structures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ts-klassen/qrpc/changelog-root', 'community', 'ts-klassen', 'qrpc', 'ts-klassen/qrpc', 'changelog-root', 0, 0, 30, '2026-03-06T12:59:22.235Z', '2026-03-06T14:24:31.996Z', '8d0aa7fe214d3217479cdd9948e318f6d9e7138145f90349e027e24ae916ec49', '{"id":"ts-klassen/qrpc/changelog-root","name":"changelog-root","description":{"en":"The changelog-root skill updates the root ChangeLog entry and maintains consistent versioning. It benefits developers by automating the process of identifying change types and updating version lists.","zh":"Changelog Root更新根ChangeLog条目，保持版本一致性，支持patch、minor、major版本更新","ja":"Changelog RootはルートChangeLogエントリを更新し、バージョンを一致させます。パッチ、ミニマム、メジャーバージョンの更新をサポートします","ko":"Changelog Root는 루트 ChangeLog 항목을 업데이트하고 버전을 일관되게 유지합니다. 패치, 마이너, 메이저 버전 업데이트를 지원합니다","es":"Changelog-root actualiza la raíz de ChangeLog y mantiene la versión y lista de versiones consistentes. Identifica el tipo de cambio y calcula la versión objetivo","fr":"Changelog-root met à jour l''entrée de ChangeLog et maintient la version et la liste des versions cohérentes. Il identifie le type de changement et calcule la version cible","de":"Changelog-root aktualisiert die Wurzel von ChangeLog und hält die Version und Versionsliste konsistent. Es identifiziert den Änderungstyp und berechnet die Zielversion","pt":"O changelog-root atualiza a entrada do ChangeLog de raiz e mantém a versão de lançamento e listas de versão consistentes.","ru":"Changelog-root обновляет запись ChangeLog корня и поддерживает актуальность версии релиза и списков версий.","ar":"يحافظ changelog-root على تحديث الإدخال الرئيسي لسجل التغييرات ويمتلك إصدار الإصدار ومناقشة الإصدار المتوافقة."},"seo":{"title":{"en":"changelog-root: Automated ChangeLog Updates for AI Agents...","zh":"Changelog Root Setup Guide: AI工具版本更新","ja":"Changelog Root設定ガイド: AIエージェントによるバージョン管理","ko":"Changelog Root 설정 가이드: AI 에이전트를 이용한 버전 업데이트","es":"Guía de configuración de changelog-root para actualizacio...","fr":"Guide de mise en place de changelog-root pour la gestion ...","de":"Einrichtungsleitfaden für changelog-root zur Verwaltung v...","pt":"Guia de Configuração do Changelog-Root: Atualize a Versão...","ru":"Настройка Changelog-Root: ИИ Агенты для Обновления Версий","ar":"دليل إعداد Changelog-Root: تحديث الإصدارات بشكل فعال"},"description":{"en":"Learn how to keep your ChangeLog entries consistent with changelog-root. Discover how to automate updates and maintain accurate versioning.","zh":"了解Changelog Root的功能和优点，使用AI工具更新根ChangeLog条目并保持版本一致性","ja":"Changelog Rootの機能と利点を確認し、AIエージェントを使用してルートChangeLogエントリを更新してバージョンを一致させます","ko":"Changelog Root의 기능과 장점을 확인하고, AI 에이전트를 사용하여 루트 ChangeLog 항목을 업데이트하고 버전을 일관되게 유지합니다","es":"Aprende a utilizar changelog-root para actualizar la raíz de ChangeLog y mantener la versión y lista de versiones actualizadas","fr":"Découvrez comment utiliser changelog-root pour mettre à jour l''entrée de ChangeLog et maintenir la version et la liste des versions à jour","de":"Erfahren Sie, wie Sie changelog-root verwenden, um die Wurzel von ChangeLog zu aktualisieren und die Version und Versionsliste konsistent zu halten","pt":"Aprenda a atualizar o ChangeLog de raiz e manter a versão de lançamento consistente com o changelog-root","ru":"Используйте ИИ Агенты для обновления версий с changelog-root и поддерживайте актуальность ChangeLog","ar":"استخدم changelog-root لتحديث الإصدارات والاحتفاظ بالإصدارات المحددة في ChangeLog"},"definition":{"en":"changelog-root is a skill that automates the update of the root ChangeLog entry, ensuring consistent versioning and accurate release information.","zh":"Changelog Root是一种AI工具，用于更新根ChangeLog条目并保持版本一致性","ja":"Changelog Rootは、ルートChangeLogエントリを更新し、バージョンを一致させるAIエージェントの一種です","ko":"Changelog Root는 루트 ChangeLog 항목을 업데이트하고 버전을 일관되게 유지하는 AI 에이전트의 일종입니다","es":"Changelog-root es una herramienta de AI que actualiza la raíz de ChangeLog y mantiene la versión y lista de versiones consistentes","fr":"Changelog-root est un outil d''IA qui met à jour l''entrée de ChangeLog et maintient la version et la liste des versions à jour","de":"Changelog-root ist ein AI-Tool, das die Wurzel von ChangeLog aktualisiert und die Version und Versionsliste konsistent hält","pt":"O que é changelog-root? Uma ferramenta para atualizar a entrada do ChangeLog de raiz.","ru":"Что такое changelog-root? Инструмент для обновления записи ChangeLog корня.","ar":"ما هو changelog-root؟ أداة لتحديث الإدخال الرئيسي لسجل التغييرات."},"features":{"en":["Identifies change types (patch, minor, major) for accurate versioning","Reads the top entry in ChangeLog to determine if it''s UNRELEASED","Finds the latest released version from the first dated entry","Computes the target version based on the latest released version and change type","Updates the root ChangeLog entry to maintain consistency"],"zh":["支持patch、minor、major版本更新","自动更新根ChangeLog条目","保持版本一致性","支持UNRELEASED版本","计算目标版本"],"ja":["パッチ、ミニマム、メジャーバージョンの更新をサポート","ルートChangeLogエントリを自動更新","バージョンを一致させる","UNRELEASEDバージョンをサポート","ターゲットバージョンの計算"],"ko":["패치, 마이너, 메이저 버전 업데이트를 지원","루트 ChangeLog 항목을 자동 업데이트","버전에 대한 일관성을 유지","UNRELEASED 버전을 지원","타겟 버전 계산"],"es":["Identificación del tipo de cambio (patch, minor, major)","Lectura de la entrada superior en ChangeLog","Cálculo de la versión objetivo basada en la versión más reciente","Actualización de la raíz de ChangeLog","Mantenimiento de la versión y lista de versiones consistentes"],"fr":["Identification du type de changement (patch, minor, major)","Lecture de l''entrée supérieure dans ChangeLog","Calcul de la version cible basée sur la version la plus récente","Mise à jour de l''entrée de ChangeLog","Maintenance de la version et de la liste des versions à jour"],"de":["Identifizierung des Änderungstyps (patch, minor, major)","Lesevorgang der oberen Eintrag in ChangeLog","Berechnung der Zielversion basierend auf der neuesten Version","Aktualisierung der Wurzel von ChangeLog","Beibehaltung der Version und Versionsliste konsistent"],"pt":["Atualiza a entrada do ChangeLog de raiz","Mantém a versão de lançamento consistente","Identifica o tipo de alteração (patch, minor, major)","Lê a entrada superior em ChangeLog","Computa a versão alvo a partir da versão lançada mais recente"],"ru":["Обновляет запись ChangeLog корня","Поддерживает актуальность версии релиза","Определяет тип изменения (patch, minor, major)","Читает верхнюю запись в ChangeLog","Вычисляет целевую версию из последней выпущенной версии"],"ar":["يحديث الإدخال الرئيسي لسجل التغييرات","يمتلك إصدار الإصدار المتوافقة","يحدد نوع التغيير (patch, minor, major)","يقرأ الإدخال العلوي في سجل التغييرات","يحسب الإصدار المستهدف من الإصدار المنشور الأحدث"]},"keywords":{"en":["how to use changelog-root","changelog-root setup guide","changelog-root alternative","changelog-root vs manual versioning","automated changelog updates","change type identification","versioning best practices"],"zh":["AI工具","版本更新","ChangeLog","版本一致性","patch版本","minor版本","major版本","UNRELEASED版本"],"ja":["AIエージェント","バージョン更新","ChangeLog","バージョン一致性","パッチバージョン","ミニマムバージョン","メジャーバージョン","UNRELEASEDバージョン"],"ko":["AI 에이전트","버전 업데이트","ChangeLog","버전 일관성","패치 버전","마이너 버전","메이저 버전","UNRELEASED 버전"],"es":["changelog-root","herramientas de AI para desarrolladores","gestión de versiones","actualización de ChangeLog","versiones de software","control de versiones","desarrollo de software"],"fr":["changelog-root","outils d''IA pour les développeurs","gestion des versions","mise à jour de ChangeLog","versions de logiciels","contrôle des versions","développement de logiciels"],"de":["changelog-root","AI-Tools für Entwickler","Versionsverwaltung","Aktualisierung von ChangeLog","Software-Versionen","Versionskontrolle","Software-Entwicklung"],"pt":["changelog-root","atualizar changelog","versão de lançamento","ChangeLog","ferramenta de atualização","desenvolvimento de software","gerenciamento de versão"],"ru":["changelog-root","обновление changelog","версия релиза","ChangeLog","инструмент обновления","разработка программного обеспечения","управление версиями","ИИ Агенты"],"ar":["changelog-root","تحديث سجل التغييرات","إصدار الإصدار","سجل التغييرات","أداة تحديث","تطوير البرمجيات","إدارة الإصدار","أدوات الذكاء الاصطناعي"]}},"owner":"ts-klassen","repo":"qrpc","repoPath":"ts-klassen/qrpc","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.235Z","topics":[],"category":"community","skillMd":{"name":"changelog-root","description":"Update the repository root ChangeLog and keep the root release version metadata in sync. Use when updating the root version or syncing subsystem/package version lists in ChangeLog; touches ChangeLog at repo root and the release version in rebar.config. If you are not sure which changelog-* skill to read, read this first.","bodyPreview":"# Changelog Root\n\n## Overview\n\nUpdate the root ChangeLog entry and keep the root release version and version lists consistent.\n\n## Versioning\n\n1. Identify the change type (patch, minor, major). Ask if unclear.\n2. Read the top entry in `ChangeLog` and note whether it is `UNRELEASED`.\n3. Find the latest released version from the first dated entry.\n4. Compute the target version from the latest released version and the change type:\n   - Patch: fixes, docs, or internal changes without new features.","body":"# Changelog Root\n\n## Overview\n\nUpdate the root ChangeLog entry and keep the root release version and version lists consistent.\n\n## Versioning\n\n1. Identify the change type (patch, minor, major). Ask if unclear.\n2. Read the top entry in `ChangeLog` and note whether it is `UNRELEASED`.\n3. Find the latest released version from the first dated entry.\n4. Compute the target version from the latest released version and the change type:\n   - Patch: fixes, docs, or internal changes without new features.\n   - Minor: new features or notable behavior changes.\n   - Major: breaking changes.\n5. Apply one of these states:\n   - No `UNRELEASED` entry: insert a new `UNRELEASED` entry at the top with the target version.\n   - `UNRELEASED` exists but target version is higher: update the `* VERSION:` line to the target version.\n   - `UNRELEASED` exists and target version is the same or lower: keep the `* VERSION:` line unchanged.\n6. Never downgrade an existing `UNRELEASED` version.\n7. Update `rebar.config` at `{release, {qrpc, \"X.Y.Z\"}, ...}` to match the `UNRELEASED` version.\n8. Do not replace `UNRELEASED` with a date; only do that at release time.\n\n## Scope and Forbidden Reads\n\nOnly edit the repository root `ChangeLog`. Do not open or modify any other ChangeLog files in the repo. It is forbidden to read `apps/*/ChangeLog` or `config/pkgsrc/files/*/*/ChangeLog` for this task unless you edited them or asked to do so.\n\n## Subsystem Versioning\n\nRefresh `* SUBSYSTEM VERSIONS:` from `apps/*/src/*.app.src` (`vsn` values) if you edited them or asked to do so. Keep the existing order and formatting. Do not read new ChangeLog files just for this. If you are not sure what to do, skip this section.\n\n## Package Versioning\n\nRefresh `* PACKAGE VERSIONS:` from `config/pkgsrc/files/meta-pkgs/*/Makefile` (`DISTNAME` versions) if you edited those meta-pkg files or were asked to do so. Keep the existing order and formatting. Do not add versions for non-meta packages; their ChangeLogs (example: `config/pkgsrc/files/audio/voicevox_core/ChangeLog`) do not affect the root ChangeLog. Do not read new ChangeLog files just for this. If you are not sure what to do, skip this section.\n\n## Change Description\n\nAppend the new change line(s) under the version lists in the `UNRELEASED` entry.\n\n## Formatting Rules\n\nUse the existing ChangeLog formatting:\n- Use a header line like `UNRELEASED  ts-klassen  <qrpc@su-shiki.com>` or `YYYY-MM-DD  ts-klassen  <qrpc@su-shiki.com>`.\n- Keep a blank line after the header.\n- Use tabs for indentation and `*` bullets, matching the file.\n- Use 2 new lines in between entries.\n\n## Example Requests\n\n- \"Update ChangeLog\"\n- \"Update ChangeLog as minor update\"\n- \"Update the root ChangeLog and rebar.config release version to 0.2.0.\"\n\n## Example scenario\n\n### No UNRELEASED\n\ncurrent file:\n\n```\n2025-12-25  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.1.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tInitial setup.\n```\n\nupdated file:\n\n```\nUNRELEASED  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.2.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tAdded some feature.\n\n\n2025-12-25  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.1.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tInitial setup.\n```\n\n### UNRELEASED 0.1.1 to 0.2.0\n\ncurrent file:\n\n```\nUNRELEASED  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.1.1\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tFixed some bug.\n\n\n2025-12-25  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.1.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tInitial setup.\n```\n\nupdated file:\n\n```\nUNRELEASED  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.2.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tFixed some bug.\n\tAdded some feature.\n\n\n2025-12-25  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.1.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tInitial setup.\n```\n\n### append to UNRELEASED\n\ncurrent file:\n\n```\nUNRELEASED  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.2.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tAdded some feature.\n\n\n2025-12-25  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.1.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tInitial setup.\n```\n\nupdated file:\n\n```\nUNRELEASED  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.2.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tAdded some feature.\n\tAdded more feature.\n\n\n2025-12-25  ts-klassen  <qrpc@su-shiki.com>\n\n\t* VERSION: 0.1.0\n\t* SUBSYSTEM VERSIONS:\n\t\t* qrpc: 0.1.0\n\t\t* q_tut: 0.3.0\n\t\t* q_vvx: 0.1.0\n\t* PACKAGE VERSIONS:\n\t\t* qrpc-devel: 0.1.0\n\t\t* qrpc-prod: 0.1.0\n\tInitial setup.\n```\n\n## Related skills\n\n- changelog-pkg\n  - If you edited a file under ./config/pkgsrc, read this too if you haven''t.\n- changelog-app\n  - If you edited a file under ./apps, read this too if you haven''t.\n"},"lastSynced":"2026-03-06T14:24:31.996Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents requiring automated ChangeLog management and consistent versioning.","zh":"适用于需要自动化变更日志管理和一致版本控制的版本控制代理。","ja":"自動化された変更ログ管理と一貫したバージョニングが必要なバージョン管理エージェントに適しています。","ko":"자동화된 변경 기록 관리 및 일관된 버전 관리가 필요한 버전 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Control de Versiones que requieren una gestión automatizada de ChangeLog y versionado consistente.","fr":"Idéal pour les Agents de Contrôle de Version nécessitant une gestion automatique de ChangeLog et un versionnage cohérent.","de":"Ideal für Version Control Agents, die eine automatisierte ChangeLog-Verwaltung und ein konsistentes Versionieren erfordern.","pt":"Ideal para Agentes de Controle de Versão que exigem gerenciamento automatizado de ChangeLog e versionamento consistente.","ru":"Идеально для Агентов Контроля Версий, требующих автоматизированного управления ChangeLog и последовательного версионирования.","ar":"مثالي للوكلاء إدارة الإصدار الذين يتطلبون إدارة سجل التغييرات التلقائي وإصدار متسق."},"recommendation":{"en":"Empowers agents to maintain accurate version lists and update root ChangeLog entries by identifying change types such as patch, minor, or major, ensuring consistent versioning and automating the process of reading and updating ChangeLog files.","zh":"赋予代理维护准确的版本列表和更新根变化日志条目的能力，通过识别更改类型（如补丁、次要或主要），确保一致的版本控制和自动化变化日志文件的读取和更新过程。","ja":"エージェントが正確なバージョンリストを維持し、ルートの変更ログエントリを更新する能力を提供します。パッチ、 マイナー、またはメジャーなどの変更タイプを識別することで、一貫したバージョニングを保証し、変更ログファイルの読み取りと更新のプロセスを自動化します。","ko":"에이전트가 정확한 버전 목록을 유지하고 루트 변경 기록 항목을 업데이트할 수 있는 능력을 제공합니다. 패치, 보조 또는 주요와 같은 변경 유형을 식별함으로써 일관된 버전 관리를 보장하고 변경 기록 파일을 읽고 업데이트하는 프로세스를 자동화합니다.","es":"Habilita a los agentes a mantener listas de versiones precisas y actualizar las entradas de ChangeLog raíz identificando tipos de cambios como patch, menor o mayor, lo que garantiza un versionado coherente y automatiza el proceso de lectura y actualización de archivos ChangeLog.","fr":"Permet aux agents de maintenir des listes de versions précises et de mettre à jour les entrées de ChangeLog racine en identifiant les types de modifications tels que patch, mineur ou majeur, garantissant ainsi un versionnage cohérent et automatisant le processus de lecture et de mise à jour des fichiers ChangeLog.","de":"Ermächtigt Agenten, genaue Versionenlisten zu pflegen und die root ChangeLog-Einträge zu aktualisieren, indem Änderungstypen wie Patch, Minor oder Major identifiziert werden, was ein konsistentes Versionieren sicherstellt und den Prozess des Lesens und Aktualisierens von ChangeLog-Dateien automatisiert.","pt":"Habilita os agentes a manter listas de versão precisas e atualizar entradas de ChangeLog raiz identificando tipos de alterações, como patch, menor ou maior, garantindo versionamento consistente e automatizando o processo de leitura e atualização de arquivos ChangeLog.","ru":"Наделяет агентов возможностью поддерживать точные списки версий и обновлять записи ChangeLog корня, определяя типы изменений, такие как патч, минор или мажор, обеспечивая последовательное версионирование и автоматизируя процесс чтения и обновления файлов ChangeLog.","ar":"تمكين الوكلاء من الحفاظ على قوائم الإصدارات الدقيقة وتحديث إدخالات سجل التغييرات الجذرية عن طريق تحديد أنواع التغييرات مثل الباتش أو الأصغر أو الأكبر، وضمان الإصدار المتسق وتحسين عملية قراءة وتحديث ملفات سجل التغييرات."},"useCases":{"en":["Automating ChangeLog updates for new releases","Identifying and categorizing changes as patch, minor, or major","Maintaining consistent versioning across the project"],"zh":["自动化新的版本发布的变更日志更新","识别和分类更改为补丁、次要或主要","在整个项目中保持一致的版本控制"],"ja":["新しいリリースの変更ログ更新の自動化","変更をパッチ、 マイナー、またはメジャーとして識別および分類","プロジェクト全体で一貫したバージョニングを維持"],"ko":["새로운 버전 릴리스를 위한 변경 기록 업데이트 자동화","변경을 패치, 보조 또는 주요로 식별 및 분류","전체 프로젝트에서 일관된 버전 관리를 유지"],"es":["Automatizar las actualizaciones de ChangeLog para nuevos lanzamientos","Identificar y categorizar cambios como patch, menor o mayor","Mantener un versionado coherente en todo el proyecto"],"fr":["Automatiser les mises à jour de ChangeLog pour les nouveaux lancements","Identifier et catégoriser les modifications en tant que patch, mineur ou majeur","Maintenir un versionnage cohérent dans tout le projet"],"de":["Automatisieren von ChangeLog-Aktualisierungen für neue Releases","Identifizieren und Kategorisieren von Änderungen als Patch, Minor oder Major","Ein konsistentes Versionieren im gesamten Projekt aufrechterhalten"],"pt":["Automatizar atualizações de ChangeLog para novas versões","Identificar e categorizar alterações como patch, menor ou maior","Manter versionamento consistente em todo o projeto"],"ru":["Автоматизировать обновления ChangeLog для новых релизов","Определить и категоризировать изменения как патч, минор или мажор","Поддерживать последовательное версионирование на протяжении всего проекта"],"ar":["توفير تحديثات سجل التغييرات التلقائية لإصدارات جديدة","تحديد وفئة التغييرات مثل الباتش أو الأصغر أو الأكبر","الحفاظ على الإصدار المتسق في جميع أنحاء المشروع"]},"limitations":{"en":["Requires access to the ChangeLog file","Limited to projects using a ChangeLog file for version tracking"],"zh":["需要访问变更日志文件","仅限于使用变更日志文件进行版本跟踪的项目"],"ja":["変更ログファイルへのアクセスが必要","変更ログファイルを使用してバージョン追跡を行うプロジェクトのみに制限"],"ko":["변경 기록 파일에 접근할 수 있어야 함","변경 기록 파일을 사용하여 버전을 추적하는 프로젝트에만 제한"],"es":["Requiere acceso al archivo ChangeLog","Limitado a proyectos que utilizan un archivo ChangeLog para el seguimiento de versiones"],"fr":["Nécessite l''accès au fichier ChangeLog","Limité aux projets utilisant un fichier ChangeLog pour le suivi des versions"],"de":["Erfordert Zugriff auf die ChangeLog-Datei","Begrenzt auf Projekte, die eine ChangeLog-Datei für die Versionsverfolgung verwenden"],"pt":["Exige acesso ao arquivo ChangeLog","Limitado a projetos que usam um arquivo ChangeLog para rastreamento de versão"],"ru":["Требует доступа к файлу ChangeLog","Ограничен проектами, использующими файл ChangeLog для отслеживания версий"],"ar":["يتطلب الوصول إلى ملف سجل التغييرات","محدود بالمشاريع التي تستخدم ملف سجل التغييرات لتسجيل الإصدارات"]},"version":4},"contentHash":"8d0aa7fe214d3217479cdd9948e318f6d9e7138145f90349e027e24ae916ec49","qualityScore":30}');
