INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ts-klassen/qrpc/changelog-root', 'changelog-root', 'ts-klassen', 'qrpc', 'community', 'changelog-root ts-klassen qrpc community The changelog-root skill updates the root ChangeLog entry and maintains consistent versioning. It benefits developers by automating the process of identifying change types and updating version lists. Changelog Root更新根ChangeLog条目，保持版本一致性，支持patch、minor、major版本更新 Changelog RootはルートChangeLogエントリを更新し、バージョンを一致させます。パッチ、ミニマム、メジャーバージョンの更新をサポートします Changelog Root는 루트 ChangeLog 항목을 업데이트하고 버전을 일관되게 유지합니다. 패치, 마이너, 메이저 버전 업데이트를 지원합니다 Changelog-root actualiza la raíz de ChangeLog y mantiene la versión y lista de versiones consistentes. Identifica el tipo de cambio y calcula la versión objetivo Changelog-root met à jour l''entrée de ChangeLog et maintient la version et la liste des versions cohérentes. Il identifie le type de changement et calcule la version cible Changelog-root aktualisiert die Wurzel von ChangeLog und hält die Version und Versionsliste konsistent. Es identifiziert den Änderungstyp und berechnet die Zielversion O changelog-root atualiza a entrada do ChangeLog de raiz e mantém a versão de lançamento e listas de versão consistentes. Changelog-root обновляет запись ChangeLog корня и поддерживает актуальность версии релиза и списков версий. يحافظ changelog-root على تحديث الإدخال الرئيسي لسجل التغييرات ويمتلك إصدار الإصدار ومناقشة الإصدار المتوافقة. how to use changelog-root changelog-root setup guide changelog-root alternative changelog-root vs manual versioning automated changelog updates change type identification versioning best practices AI工具 版本更新 ChangeLog 版本一致性 patch版本 minor版本 major版本 UNRELEASED版本 Identifies change types (patch, minor, major) for accurate versioning Reads the top entry in ChangeLog to determine if it''s UNRELEASED Finds the latest released version from the first dated entry Computes the target version based on the latest released version and change type Updates the root ChangeLog entry to maintain consistency changelog-root is a skill that automates the update of the root ChangeLog entry, ensuring consistent versioning and accurate release information.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Richie1129/SDLs_fullStack_remix/auth-sync', 'community', 'Richie1129', 'SDLs_fullStack_remix', 'Richie1129/SDLs_fullStack_remix', 'auth-sync', 0, 1, 30, '2026-03-07T02:12:35Z', '2026-03-07T13:14:48.890Z', 'ad5c31fbbf6ff99cc30bd15a93bf781c1ff0c825d985aa82736c2a3686ea58ba', '{"id":"Richie1129/SDLs_fullStack_remix/auth-sync","name":"auth-sync","description":{"en":"The auth-sync skill scans and synchronizes auth pages, ensuring consistency across login, register, forgot password, and reset password pages. It benefits developers by automating the syncing process.","zh":"auth-sync 技術文檔：掃描三個 auth 頁面並比對一致性，自動同步所有差異","ja":"auth-sync AIエージェント：3つの認証ページをスキャンして一貫性を確認し、自動で同期します","ko":"auth-sync 설정 가이드: 3개의 인증 페이지를 스캔하고 일관성을 확인하여 자동으로同步합니다","es":"Auth-sync es una herramienta que verifica y sincroniza la coherencia de las páginas de autenticación en aplicaciones React","fr":"Auth-sync est un outil qui vérifie et synchronise la cohérence des pages d''authentification dans les applications React","de":"Auth-sync ist ein Tool, das die Konsistenz der Authentifizierungsseiten in React-Anwendungen überprüft und synchronisiert","pt":"O Auth-Sync é uma ferramenta que sincroniza páginas de autenticação para garantir a consistência. Ele verifica e sincroniza as páginas de login, registro e recuperação de senha.","ru":"Auth-Sync - это инструмент, который синхронизирует страницы аутентификации для обеспечения согласованности. Он проверяет и синхронизирует страницы входа, регистрации и восстановления пароля.","ar":"Auth-Sync هو أداة تزامن صفحات المصادقة لضمان الاتساق. يقوم بفحص ودمج صفحات الدخول والتسجيل واستعادة كلمة المرور."},"seo":{"title":{"en":"auth-sync: Automated Auth Page Sync Setup Guide | AI Agen...","zh":"auth-sync.setup","ja":"auth-sync AIエージェントの設定ガイド","ko":"auth-sync 설정 가이드","es":"Guía de configuración de auth-sync para desarrolladores","fr":"Mise en place d''auth-sync pour les développeurs","de":"Einrichtungsleitfaden für auth-sync-Entwickler","pt":"Guia de Configuração do Auth-Sync: Sincronização de Págin...","ru":"Настройка Auth-Sync: Синхронизация страниц аутентификации...","ar":"دليل إعداد Auth-Sync: مزامنة صفحات المصادقة باستخدام أدوا..."},"description":{"en":"Discover how to synchronize auth pages with ease using auth-sync. Learn how to fix inconsistencies and automate syncing with our expert guide.","zh":"auth-sync 技術文檔：掃描三個 auth 頁面並比對一致性，自動同步所有差異","ja":"auth-sync AIエージェント：3つの認証ページをスキャンして一貫性を確認し、自動で同期します","ko":"auth-sync 설정 가이드: 3개의 인증 페이지를 스캔하고 일관성을 확인하여 자동으로同步합니다","es":"Aprende a utilizar auth-sync para sincronizar y verificar la coherencia de las páginas de autenticación en tu aplicación","fr":"Découvrez comment utiliser auth-sync pour synchroniser et vérifier la cohérence des pages d''authentification dans votre application","de":"Erfahren Sie, wie Sie auth-sync verwenden, um die Konsistenz der Authentifizierungsseiten in Ihrer Anwendung zu synchronisieren und zu überprüfen","pt":"Aprenda a configurar o Auth-Sync para sincronizar páginas de autenticação e melhorar a experiência do usuário","ru":"Узнайте, как настроить Auth-Sync для синхронизации страниц аутентификации и улучшения пользовательского опыта с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Auth-Sync لدمج صفحات المصادقة وتحسين تجربة المستخدم باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"auth-sync is a skill that synchronizes auth pages, checking and fixing inconsistencies across multiple pages, including login, register, and password-related pages.","zh":"auth-sync 是一种技术技能，用于扫描三个 auth 页面并比对一致性","ja":"auth-sync は、3 つの認証ページをスキャンして一貫性を確認する AI エージェントです","ko":"auth-sync는 3개의 인증 페이지를 스캔하고 일관성을 확인하는 기술 스킬입니다","es":"Auth-sync es una herramienta de sincronización de autenticación que verifica la coherencia de las páginas de login, registro y recuperación de contraseña","fr":"Auth-sync est un outil de synchronisation d''authentification qui vérifie la cohérence des pages de connexion, d''inscription et de récupération de mot de passe","de":"Auth-sync ist ein Authentifizierungssynchronisationstool, das die Konsistenz der Login-, Registrierungs- und Passwiederherstellungsseiten überprüft","pt":"O Auth-Sync é uma ferramenta de sincronização de páginas de autenticação que garante a consistência entre as páginas de login, registro e recuperação de senha.","ru":"Auth-Sync - это инструмент синхронизации страниц аутентификации, который обеспечивает согласованность между страницами входа, регистрации и восстановления пароля.","ar":"Auth-Sync هو أداة مزامنة صفحات المصادقة التي تضمن الاتساق بين صفحات الدخول والتسجيل واستعادة كلمة المرور."},"features":{"en":["Scans three auth pages for inconsistencies using the `/auth-sync` command","Generates a difference report to identify inconsistencies","Automatically synchronizes all differences with the `/auth-sync fix` command","Supports targeted syncing of specific items, such as the brand panel width","Checks auth page paths, including `sdl-frontend-main/src/pages/login/Login.jsx` and other related pages"],"zh":["掃描三個 auth 頁面","比對一致性","自動同步所有差異","支援 `/auth-sync`、`/auth-sync fix`、`/auth-sync fix <項目>` 指令","適用於 React 框架","支援 CLI 操作"],"ja":["3つの認証ページをスキャン","一貫性を確認","自動で同期"," `/auth-sync`、`/auth-sync fix`、`/auth-sync fix <項目>` コマンドをサポート","React フレームワークに対応","CLI 操作をサポート"],"ko":["3개의 인증 페이지를 스캔","일관성을 확인","자동으로同步"," `/auth-sync`、`/auth-sync fix`、`/auth-sync fix <項目>` 명령어를 지원","React 프레임워크에対応","CLI 操作을 지원"],"es":["Verificación de coherencia en las páginas de autenticación","Sincronización automática de las diferencias encontradas","Soporte para páginas de login, registro y recuperación de contraseña","Compatibilidad con aplicaciones React","Uso de comandos CLI para ejecutar y configurar la herramienta"],"fr":["Vérification de la cohérence des pages d''authentification","Synchronisation automatique des différences trouvées","Prise en charge des pages de connexion, d''inscription et de récupération de mot de passe","Compatibilité avec les applications React","Utilisation de commandes CLI pour exécuter et configurer l''outil"],"de":["Überprüfung der Konsistenz der Authentifizierungsseiten","Automatische Synchronisation der gefundenen Unterschiede","Unterstützung für Login-, Registrierungs- und Passwiederherstellungsseiten","Kompatibilität mit React-Anwendungen","Verwendung von CLI-Befehlen zur Ausführung und Konfiguration des Tools"],"pt":["Sincronização de páginas de autenticação","Verificação de consistência entre as páginas de login, registro e recuperação de senha","Suporte a CLI para execução de comandos","Integração com React para desenvolvimento de interfaces de usuário","Capacidade de sincronizar páginas específicas ou todas as páginas de autenticação"],"ru":["Синхронизация страниц аутентификации","Проверка согласованности между страницами входа, регистрации и восстановления пароля","Поддержка CLI для выполнения команд","Интеграция с React для разработки интерфейсов пользователя","Возможность синхронизации отдельных страниц или всех страниц аутентификации"],"ar":["مزامنة صفحات المصادقة","فحص الاتساق بين صفحات الدخول والتسجيل واستعادة كلمة المرور","دعم CLI لتنفيذ الأوامر","التكامل مع React لتطوير واجهات المستخدم","القدرة على مزامنة صفحات محددة أو جميع صفحات المصادقة"]},"keywords":{"en":["how to use auth-sync","auth-sync setup guide","auth-sync alternative","auth-sync vs manual syncing","auth-sync install","what is auth-sync","auth-sync benefits for developers","automated auth page syncing","auth-sync command line interface"],"zh":["auth-sync","auth-sync setup","auth-sync 技術文檔","auth 頁面一致性同步","React auth-sync","CLI auth-sync","auth-sync AI エージェント"],"ja":["auth-sync","auth-sync AIエージェント","auth-sync 設定ガイド","3つの認証ページをスキャン","React auth-sync","CLI auth-sync","auth-sync 日本語"],"ko":["auth-sync","auth-sync 설정 가이드","auth-sync 기술 스킬","3개의 인증 페이지를 스캔","React auth-sync","CLI auth-sync","auth-sync 한국어"],"es":["auth-sync","sincronización de autenticación","coherencia de páginas","aplicaciones React","CLI","desarrollo de software","herramientas de desarrollo","autenticación y autorización"],"fr":["auth-sync","synchronisation d''authentification","cohérence des pages","applications React","CLI","développement de logiciels","outils de développement","authentification et autorisation"],"de":["auth-sync","Authentifizierungssynchronisation","Konsistenz der Seiten","React-Anwendungen","CLI","Software-Entwicklung","Entwicklungstools","Authentifizierung und Autorisierung"],"pt":["auth-sync","sincronização de páginas de autenticação","CLI","React","desenvolvimento de interfaces de usuário","autenticação","segurança","desenvolvimento web"],"ru":["auth-sync","синхронизация страниц аутентификации","CLI","React","разработка интерфейсов пользователя","аутентификация","безопасность","веб-разработка","ИИ Агенты"],"ar":["auth-sync","مزامنة صفحات المصادقة","CLI","React","تطوير واجهات المستخدم","مصادقة","أمان","تطوير الويب","أدوات الذكاء الاصطناعي"]}},"owner":"Richie1129","repo":"SDLs_fullStack_remix","repoPath":"Richie1129/SDLs_fullStack_remix","stars":0,"forks":1,"updatedAt":"2026-03-07T02:12:35Z","topics":[],"category":"community","skillMd":{"name":"auth-sync","description":"檢查並同步 Login、Register、ForgotPassword 三個 auth 頁面的樣式一致性。用表格顯示差異，讓你選擇要同步哪些項目。","bodyPreview":"# Auth 頁面一致性同步 Skill\n\n當使用者執行 `/auth-sync` 時，掃描三個 auth 頁面並比對一致性。\n\n## 使用方式\n```\n/auth-sync          # 檢查並顯示差異報告\n/auth-sync fix      # 檢查後自動同步所有差異\n/auth-sync fix <項目>  # 只同步特定項目（如 /auth-sync fix 品牌面板寬度）\n```\n\n## Auth 頁面路徑\n\n以下四個頁面共用品牌面板（左側 customgreen）+ 表單（右側）的左右佈局：\n- `sdl-frontend-main/src/pages/login/Login.jsx`\n- `sdl-frontend-main/src/pages/login/Register.jsx`\n- `sdl-frontend-main/src/pages/login/ForgotPassword.jsx`\n- `sdl-frontend-main/src/pages/login/ResetPassword.jsx`\n\n## 執行步驟\n\n### 步驟 1：讀取三個頁面","body":"# Auth 頁面一致性同步 Skill\n\n當使用者執行 `/auth-sync` 時，掃描三個 auth 頁面並比對一致性。\n\n## 使用方式\n```\n/auth-sync          # 檢查並顯示差異報告\n/auth-sync fix      # 檢查後自動同步所有差異\n/auth-sync fix <項目>  # 只同步特定項目（如 /auth-sync fix 品牌面板寬度）\n```\n\n## Auth 頁面路徑\n\n以下四個頁面共用品牌面板（左側 customgreen）+ 表單（右側）的左右佈局：\n- `sdl-frontend-main/src/pages/login/Login.jsx`\n- `sdl-frontend-main/src/pages/login/Register.jsx`\n- `sdl-frontend-main/src/pages/login/ForgotPassword.jsx`\n- `sdl-frontend-main/src/pages/login/ResetPassword.jsx`\n\n## 執行步驟\n\n### 步驟 1：讀取三個頁面\n\n同時讀取三個檔案，提取以下關鍵值：\n\n**品牌面板（左側）：**\n- 寬度 class（`w-1/2`, `w-2/5` 等）\n- 背景色（`bg-customgreen`, `bg-green-*` 等）\n- 是否有漸層（`from-*`, `to-*`）\n- 隱藏斷點（`hidden md:flex`, `hidden lg:flex` 等）\n\n**表單面板（右側）：**\n- 寬度 class\n- 垂直置中方式（`items-center`, `justify-center`）\n- 最大寬度（`max-w-md`, `max-w-sm` 等）\n\n**動畫：**\n- 動畫速度（`duration-fast`, `duration-normal`, `duration-slow` 或具體 ms 值）\n- 動畫類型（`transition-*`, `animate-*`）\n\n**整體佈局：**\n- 外層容器 class（`h-screen`, `min-h-screen`, `overflow-hidden` 等）\n- Flex 方向\n\n**密碼欄位（若有）：**\n- 是否有顯示/隱藏切換按鈕\n\n### 步驟 2：產出差異報告\n\n```\n## Auth 頁面一致性報告\n\n| 項目 | Login | Register | ForgotPassword | 狀態 |\n|------|-------|----------|----------------|------|\n| 品牌面板寬度 | w-1/2 | w-2/5 | w-1/2 | ⚠️ 不一致 |\n| 背景色 | customgreen | customgreen | customgreen | ✅ |\n| 動畫速度 | duration-normal | duration-fast | duration-normal | ⚠️ 不一致 |\n| 外層佈局 | h-screen overflow-hidden | h-screen | h-screen overflow-hidden | ⚠️ 不一致 |\n| 響應式斷點 | hidden md:flex | hidden lg:flex | hidden md:flex | ⚠️ 不一致 |\n| 密碼顯示切換 | ✅ 有 | ✅ 有 | - (無密碼欄) | ✅ |\n\n共發現 N 處不一致。\n```\n\n若**完全一致**，回報「✅ 三個頁面樣式完全一致，無需同步」。\n\n### 步驟 3：詢問如何處理（若未帶 fix 參數）\n\n```\n發現以上 N 處差異。要如何處理？\n1. 全部同步（以 Login.jsx 為基準）\n2. 選擇性同步\n3. 只查看報告，暫不修改\n```\n\n### 步驟 4：執行同步\n\n**同步基準：以 Login.jsx 為準**（除非使用者指定其他頁面）\n\n修改時：\n- 每次只修改一個檔案\n- 修改後列出具體變更的 class 名稱\n- 完成後再次執行步驟 1-2 驗證一致性\n\n### 步驟 5：驗證報告\n\n同步完成後，再跑一次比對，確認所有 ✅。\n\n## 注意事項\n- ForgotPassword 頁面沒有密碼欄位，跳過密碼相關項目的比對\n- ResetPassword 頁面有兩組密碼欄位（新密碼 + 確認密碼），皆需有顯示/隱藏切換\n- 若三個頁面各有不同邏輯需求（如 Register 有更多欄位），只同步視覺樣式，不改動表單結構\n- 修改前先確認使用者想以哪個頁面為基準\n"},"lastSynced":"2026-03-07T13:14:48.890Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing automated auth page synchronization and consistency checks.","zh":"非常适合需要自动同步和一致性检查的前端代理","ja":"自動での認証ページの同期と一貫性のチェックが必要なフロントエンドエージェントに最適","ko":"자동으로 인증 페이지를 동기화하고 일관성을 확인해야 하는 프론트엔드 에이전트에게 완벽한 솔루션","es":"Perfecto para Agentes Frontend que necesitan sincronización automática de páginas de autenticación y comprobaciones de coherencia.","fr":"Parfait pour les agents Frontend nécessitant une synchronisation automatique des pages d''authentification et des vérifications de cohérence.","de":"Perfekt für Frontend-Agents, die eine automatisierte Synchronisierung von Authentifizierungsseiten und Konsistenzprüfungen benötigen.","pt":"Perfeito para agentes Frontend que necessitam de sincronização automática de páginas de autenticação e verificações de consistência.","ru":"Идеально для агентов Frontend, которым необходима автоматизированная синхронизация страниц аутентификации и проверки согласованности.","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى تنسيق صفحات المصادقة وتحقق الاتساق التلقائي."},"recommendation":{"en":"Empowers agents to ensure consistency across login, register, forgot password, and reset password pages by scanning and synchronizing auth pages, utilizing JavaScript and React components like Login.jsx, Register.jsx, ForgotPassword.jsx, and ResetPassword.jsx.","zh":"赋予代理人通过扫描和同步登录、注册、忘记密码和重置密码页面来确保一致性，利用JavaScript和React组件，如Login.jsx、Register.jsx、ForgotPassword.jsx和ResetPassword.jsx","ja":"JavaScriptとReactコンポーネント（例：Login.jsx、Register.jsx、ForgotPassword.jsx、ResetPassword.jsx）を利用して、ログイン、登録、パスワード忘れ、パスワード再設定ページをスキャンして同期することで、一貫性を確保するエージェントを可能にします","ko":"자바스크립트와 리액트 컴포넌트를 이용하여 로그인, 회원가입, 비밀번호 찾기, 비밀번호 초기화 페이지를 스캔하고 동기화하여 일관성을 보장하는 에이전트를 강화합니다. 예를 들어, Login.jsx, Register.jsx, ForgotPassword.jsx, ResetPassword.jsx","es":"Permite a los agentes garantizar la coherencia en las páginas de inicio de sesión, registro, olvidó la contraseña y restablecimiento de la contraseña al escanear y sincronizar las páginas de autenticación, utilizando JavaScript y componentes de React como Login.jsx, Register.jsx, ForgotPassword.jsx y ResetPassword.jsx.","fr":"Permet aux agents de garantir la cohérence sur les pages de connexion, d''inscription, de mot de passe oublié et de réinitialisation du mot de passe en analysant et en synchronisant les pages d''authentification, en utilisant JavaScript et des composants React comme Login.jsx, Register.jsx, ForgotPassword.jsx et ResetPassword.jsx.","de":"Ermöglicht es den Agenten, die Konsistenz auf den Seiten für Anmeldung, Registrierung, Passwort vergessen und Passwort zurücksetzen sicherzustellen, indem sie Authentifizierungsseiten scannen und synchronisieren, unter Verwendung von JavaScript und React-Komponenten wie Login.jsx, Register.jsx, ForgotPassword.jsx und ResetPassword.jsx.","pt":"Habilita os agentes a garantir a consistência em todo o login, registrar, esqueci a senha e redefinir a senha páginas, digitalizando e sincronizando páginas de autenticação, utilizando JavaScript e componentes React como Login.jsx, Register.jsx, ForgotPassword.jsx e ResetPassword.jsx.","ru":"Наделяет агентов возможностью обеспечить согласованность во всех страницах входа, регистрации, забытого пароля и сброса пароля, сканируя и синхронизируя страницы аутентификации, используя JavaScript и компоненты React, такие как Login.jsx, Register.jsx, ForgotPassword.jsx и ResetPassword.jsx.","ar":"تمكّن الوكلاء من ضمان الاتساق عبر جميع صفحات الدخول والتسجيل ونسيان كلمة المرور وإعادة تعيين كلمة المرور من خلال مسح صفحات المصادقة وتحديثها، باستخدام JavaScript ومكونات React مثل Login.jsx و Register.jsx و ForgotPassword.jsx و ResetPassword.jsx."},"useCases":{"en":["Automating auth page syncing","Generating consistency reports for auth pages","Debugging auth page discrepancies"],"zh":["自动同步认证页面","生成认证页面一致性报告","调试认证页面差异"],"ja":["認証ページの自動同期","認証ページの一貫性レポートの生成","認証ページの差異のデバッグ"],"ko":["인증 페이지 자동 동기화","인증 페이지 일관성 보고서 생성","인증 페이지 차이점 디버깅"],"es":["Automatización de la sincronización de páginas de autenticación","Generación de informes de coherencia para páginas de autenticación","Depuración de discrepancias en las páginas de autenticación"],"fr":["Automatisation de la synchronisation des pages d''authentification","Génération de rapports de cohérence pour les pages d''authentification","Débogage des écarts dans les pages d''authentification"],"de":["Automatisierung der Synchronisierung von Authentifizierungsseiten","Generierung von Konsistenzberichten für Authentifizierungsseiten","Fehlerbehebung bei Abweichungen auf Authentifizierungsseiten"],"pt":["Automatizar a sincronização de páginas de autenticação","Gerar relatórios de consistência para páginas de autenticação","Depurar discrepâncias de páginas de autenticação"],"ru":["Автоматизировать синхронизацию страниц аутентификации","Генерировать отчеты о согласованности для страниц аутентификации","Отлаживать несоответствия страниц аутентификации"],"ar":["تحديث صفحات المصادقة تلقائيًا","توليد تقارير الاتساق لصفحات المصادقة","تصحيح أخطاء صفحات المصادقة"]},"limitations":{"en":["Requires access to sdl-frontend-main/src/pages/login directory","Limited to scanning four specific auth pages (Login, Register, ForgotPassword, ResetPassword)"],"zh":["需要访问sdl-frontend-main/src/pages/login目录","仅限扫描四个特定认证页面（登录、注册、忘记密码、重置密码）"],"ja":["sdl-frontend-main/src/pages/loginディレクトリへのアクセスが必要","特定の4つの認証ページ（ログイン、登録、パスワード忘れ、パスワード再設定）のみをスキャン可能"],"ko":["sdl-frontend-main/src/pages/login 디렉토리에 접근해야 함","로그인, 회원가입, 비밀번호 찾기, 비밀번호 초기화와 같은 4개의 특정 인증 페이지만을 스캔할 수 있음"],"es":["Requiere acceso al directorio sdl-frontend-main/src/pages/login","Limitado a la exploración de cuatro páginas de autenticación específicas (Login, Register, ForgotPassword, ResetPassword)"],"fr":["Nécessite un accès au répertoire sdl-frontend-main/src/pages/login","Limité à l''analyse de quatre pages d''authentification spécifiques (Login, Register, ForgotPassword, ResetPassword)"],"de":["Erfordert Zugriff auf das Verzeichnis sdl-frontend-main/src/pages/login","Begrenzt auf die Analyse von vier bestimmten Authentifizierungsseiten (Login, Register, ForgotPassword, ResetPassword)"],"pt":["Requer acesso ao diretório sdl-frontend-main/src/pages/login","Limitado à digitalização de quatro páginas de autenticação específicas (Login, Register, ForgotPassword, ResetPassword)"],"ru":["Требует доступа к каталогу sdl-frontend-main/src/pages/login","Ограничен сканированием четырех конкретных страниц аутентификации (Login, Register, ForgotPassword, ResetPassword)"],"ar":["يتطلب الوصول إلى الدليل sdl-frontend-main/src/pages/login","محدود بفحص أربعة صفحات مصادقة محددة (الدخول، التسجيل، نسيان كلمة المرور، إعادة تعيين كلمة المرور)"]},"version":4},"contentHash":"ad5c31fbbf6ff99cc30bd15a93bf781c1ff0c825d985aa82736c2a3686ea58ba","qualityScore":30}');
