INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Richie1129/SDLs_fullStack_remix/auth-sync', 'auth-sync', 'Richie1129', 'SDLs_fullStack_remix', 'community', 'auth-sync Richie1129 SDLs_fullStack_remix community The auth-sync skill scans and synchronizes auth pages, ensuring consistency across login, register, forgot password, and reset password pages. It benefits developers by automating the syncing process. auth-sync 技術文檔：掃描三個 auth 頁面並比對一致性，自動同步所有差異 auth-sync AIエージェント：3つの認証ページをスキャンして一貫性を確認し、自動で同期します auth-sync 설정 가이드: 3개의 인증 페이지를 스캔하고 일관성을 확인하여 자동으로同步합니다 Auth-sync es una herramienta que verifica y sincroniza la coherencia de las páginas de autenticación en aplicaciones React Auth-sync est un outil qui vérifie et synchronise la cohérence des pages d''authentification dans les applications React Auth-sync ist ein Tool, das die Konsistenz der Authentifizierungsseiten in React-Anwendungen überprüft und synchronisiert O Auth-Sync é uma ferramenta que sincroniza páginas de autenticação para garantir a consistência. Ele verifica e sincroniza as páginas de login, registro e recuperação de senha. Auth-Sync - это инструмент, который синхронизирует страницы аутентификации для обеспечения согласованности. Он проверяет и синхронизирует страницы входа, регистрации и восстановления пароля. Auth-Sync هو أداة تزامن صفحات المصادقة لضمان الاتساق. يقوم بفحص ودمج صفحات الدخول والتسجيل واستعادة كلمة المرور. how to use auth-sync auth-sync setup guide auth-sync alternative auth-sync vs manual syncing auth-sync install what is auth-sync auth-sync benefits for developers automated auth page syncing auth-sync command line interface auth-sync auth-sync setup auth-sync 技術文檔 auth 頁面一致性同步 React auth-sync CLI auth-sync auth-sync AI エージェント Scans three auth pages for inconsistencies using the `/auth-sync` command Generates a difference report to identify inconsistencies Automatically synchronizes all differences with the `/auth-sync fix` command Supports targeted syncing of specific items, such as the brand panel width Checks auth page paths, including `sdl-frontend-main/src/pages/login/Login.jsx` and other related pages auth-sync is a skill that synchronizes auth pages, checking and fixing inconsistencies across multiple pages, including login, register, and password-related pages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('inline-chat/inline/research', 'community', 'inline-chat', 'inline', 'inline-chat/inline', 'research', 642, 26, 30, '2026-02-25T16:07:21Z', '2026-03-06T06:27:18.006Z', '12a3befc365e999878a8fd77f28cef1248549d4171a21866dcb1745511db530c', '{"id":"inline-chat/inline/research","name":"research","description":{"en":"The research skill enables developers to investigate local project files, Google search best practices, and look for examples on GitHub to make informed decisions. It benefits developers by providing a structured approach to research.","zh":"研究技能提供了技术集成，包括谷歌搜索、GitHub 和 StackOverflow，用于提高开发效率","ja":"研究スキルは、Google 検索、GitHub、StackOverflow の技術統合を提供し、開発効率を向上させる","ko":"연구 스킬은 Google 검색, GitHub, StackOverflow의 기술적 통합을 제공하여 개발 효율성을 향상","es":"La investigación es un proceso clave para los desarrolladores. Nuestra guía cubre las mejores prácticas de búsqueda en Google, GitHub y más","fr":"La recherche est un processus clé pour les développeurs. Notre guide couvre les meilleures pratiques de recherche sur Google, GitHub et plus","de":"Die Recherche ist ein wichtiger Prozess für Entwickler. Unser Leitfaden deckt die Best Practices für die Suche auf Google, GitHub und mehr ab","pt":"A pesquisa avançada é uma habilidade que permite investigar arquivos de projeto locais, realizar buscas no Google e procurar exemplos em GitHub e StackOverflow","ru":"Исследование - это навык, который позволяет исследовать локальные проектные файлы, проводить поиск в Google и искать примеры на GitHub и StackOverflow","ar":"البحث المتقدم هو مهارة تمكنك من التحقيق في الملفات المحلية للمشروع وإجراء عمليات بحث على جوجل والبحث عن الأمثلة على جيثب وستاك أوفيرفلو"},"seo":{"title":{"en":"Research: Efficient Investigation Setup Guide | AI Agent ...","zh":"研究工具集成指南 - AIエージェント","ja":"研究ツールの設定ガイド - AIエージェント","ko":"연구 도구 설정 가이드 - AI 에이전트","es":"Guía de investigación para desarrolladores: mejores práct...","fr":"Guide de recherche pour les développeurs : meilleures pra...","de":"Forschungsleitfaden für Entwickler: Best Practices für di...","pt":"Guia de Configuração de Pesquisa Avançada com Ferramentas...","ru":"Настройка ИИ Агентов: Руководство по Исследованию","ar":"دليل إعداد بحث متقدم مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock informed decision-making with research skill. Investigate project files, Google best practices, and GitHub examples to construct better research","zh":"了解研究技能的技术细节，包括谷歌搜索、GitHub 和 StackOverflow 的集成","ja":"研究スキルの技術的詳細について学び、Google 検索、GitHub、StackOverflow の統合を実現","ko":"연구 스킬의 기술적 세부 사항을 학습하고, Google 검색, GitHub, StackOverflow의 통합을 구현","es":"Aprende a investigar de manera efectiva con nuestra guía de investigación para desarrolladores. Mejores prácticas de búsqueda en Google y GitHub","fr":"Apprenez à mener des recherches efficaces avec notre guide de recherche pour les développeurs. Meilleures pratiques de recherche sur Google et GitHub","de":"Erfahren Sie, wie Sie effektiv recherchieren mit unserem Forschungsleitfaden für Entwickler. Best Practices für die Suche auf Google und GitHub","pt":"Aprenda a configurar a pesquisa avançada com ferramentas de IA para melhorar a colaboração e a tomada de decisões informadas","ru":"Узнайте, как настроить исследование с помощью ИИ Агентов для улучшения сотрудничества и принятия обоснованных решений","ar":"تعرف على كيفية إعداد بحث متقدم مع أدوات الذكاء الاصطناعي لتحسين التعاون واتخاذ قرارات مستنيرة"},"definition":{"en":"Research is a systematic investigation process that involves analyzing local project files, searching Google, and exploring GitHub examples to gather information and construct better research outcomes","zh":"研究技能是一种AI工具，用于集成谷歌搜索、GitHub 和 StackOverflow 等技术","ja":"研究スキルは、Google 検索、GitHub、StackOverflow などの技術を統合する AI エージェントの一種","ko":"연구 스킬은 Google 검색, GitHub, StackOverflow 등의 기술을 통합하는 AI 에이전트의 일종","es":"La investigación es el proceso de búsqueda y análisis de información para tomar decisiones informadas","fr":"La recherche est le processus de recherche et d''analyse d''informations pour prendre des décisions éclairées","de":"Die Recherche ist der Prozess der Suche und Analyse von Informationen, um informierte Entscheidungen zu treffen","pt":"Pesquisa avançada é uma técnica de investigação que utiliza ferramentas de IA para coletar e analisar informações","ru":"Исследование - это техника исследования, которая использует ИИ Агенты для сбора и анализа информации","ar":"البحث المتقدم هو تقنية بحث تستخدم أدوات الذكاء الاصطناعي لجمع وتحليل المعلومات"},"features":{"en":["Investigates local project files related to the session","Conducts Google searches for best practices and documentations","Looks for examples on GitHub, Gist, or blog posts, and StackOverflow","Constructs research using a temporary markdown file","Makes informed decisions based on gathered information"],"zh":["谷歌搜索集成","GitHub 和 Gist 示例查找","StackOverflow 问题解决","临时 markdown 文件构建"," thông tin决策支持"],"ja":["Google 検索統合","GitHub と Gist の例の検索","StackOverflow の質問解決","一時的な Markdown ファイルの構築","情報に基づいた意思決定サポート"],"ko":["Google 검색 통합","GitHub 및 Gist 예제 검색","StackOverflow 문제 해결","임시 Markdown 파일 구축","정보에 의한 의사 결정 지원"],"es":["Búsqueda en Google para encontrar documentación y preguntas frecuentes","Investigación en GitHub para encontrar ejemplos y código abierto","Uso de StackOverflow para encontrar soluciones a problemas comunes","Creación de un archivo markdown temporal para organizar la investigación","Análisis de información para tomar decisiones informadas"],"fr":["Recherche sur Google pour trouver de la documentation et des questions fréquentes","Recherche sur GitHub pour trouver des exemples et du code open source","Utilisation de StackOverflow pour trouver des solutions à des problèmes courants","Création d''un fichier markdown temporaire pour organiser la recherche","Analyse d''informations pour prendre des décisions éclairées"],"de":["Suche auf Google, um Dokumentationen und häufige Fragen zu finden","Recherche auf GitHub, um Beispiele und Open-Source-Code zu finden","Verwendung von StackOverflow, um Lösungen für häufige Probleme zu finden","Erstellung einer temporären Markdown-Datei, um die Recherche zu organisieren","Analyse von Informationen, um informierte Entscheidungen zu treffen"],"pt":["Investigação de arquivos de projeto locais","Busca no Google por práticas recomendadas e documentação","Procura por exemplos em GitHub, Gist e StackOverflow","Criação de um arquivo markdown temporário para organizar informações","Tomada de decisões informadas com base nas informações coletadas"],"ru":["Исследование локальных проектных файлов","Поиск в Google по лучшим практикам и документации","Поиск примеров на GitHub, Gist и StackOverflow","Создание временного файла markdown для организации информации","Принятие обоснованных решений на основе собранной информации"],"ar":["التحقيق في الملفات المحلية للمشروع","البحث على جوجل على أفضل الممارسات والوثائق","البحث عن الأمثلة على جيثب وغيست وستاك أوفيرفلو","إنشاء ملف ماركداون مؤقت لتنظيم المعلومات","اتخاذ قرارات مستنيرة على أساس المعلومات المجمعة"]},"keywords":{"en":["how to use research skill","research alternative tools","research setup guide for AI agents","what is research in AI","research vs Google search","research install for developers"],"zh":["AI工具","研究技能","谷歌搜索","GitHub","StackOverflow","开发效率","技术集成","AIエージェント"],"ja":["AIエージェント","研究スキル","Google 検索","GitHub","StackOverflow","開発効率","技術統合","AIツール"],"ko":["AI 에이전트","연구 스킬","Google 검색","GitHub","StackOverflow","개발 효율성","기술적 통합","AI 도구"],"es":["investigación para desarrolladores","búsqueda en Google para desarrolladores","GitHub para desarrolladores","StackOverflow para desarrolladores","mejores prácticas de investigación","herramientas de investigación para desarrolladores","cómo investigar de manera efectiva","recherche pour les développeurs","AI herramientas para desarrolladores"],"fr":["recherche pour les développeurs","recherche sur Google pour les développeurs","GitHub pour les développeurs","StackOverflow pour les développeurs","meilleures pratiques de recherche","outils de recherche pour les développeurs","comment rechercher de manière efficace","recherche efficace pour les développeurs","outils d''IA pour les développeurs"],"de":["Recherche für Entwickler","Suche auf Google für Entwickler","GitHub für Entwickler","StackOverflow für Entwickler","Best Practices für die Recherche","Recherche-Tools für Entwickler","wie man effektiv recherchiert","effektive Recherche für Entwickler","KI-Tools für Entwickler"],"pt":["pesquisa avançada","ferramentas de ia","colaboração","tomada de decisões","github","stackoverflow","busca no google","arquivos de projeto locais"],"ru":["исследование","ИИ Агенты","сотрудничество","принятие решений","github","stackoverflow","поиск в google","локальные проектные файлы"],"ar":["البحث المتقدم","أدوات الذكاء الاصطناعي","التعاون","اتخاذ القرارات","جيثب","ستاك أوفيرفلو","البحث على جوجل","الملفات المحلية للمشروع"]}},"owner":"inline-chat","repo":"inline","repoPath":"inline-chat/inline","stars":642,"forks":26,"updatedAt":"2026-02-25T16:07:21Z","topics":[],"category":"community","skillMd":{"name":"research","description":"Research, gather information, investigate, find best practices, to ensure good solution or find a better solution.","bodyPreview":"- Investigate local project files related to the session if hasn''t already\n- Google search best practices, questions, documentations\n- Look for examples on GitHub, Gist, or blog posts, StackOverflow\n- If you''re finding a lot of information, add them to a temporary markdown file to construct your research better even if context gets compacted\n- Make informed decision on the best possible next step according to the information you have","body":"- Investigate local project files related to the session if hasn''t already\n- Google search best practices, questions, documentations\n- Look for examples on GitHub, Gist, or blog posts, StackOverflow\n- If you''re finding a lot of information, add them to a temporary markdown file to construct your research better even if context gets compacted\n- Make informed decision on the best possible next step according to the information you have\n"},"lastSynced":"2026-03-06T06:27:18.006Z","agentAnalysis":{"suitability":{"en":"Ideal for Knowledge Agents needing advanced information gathering and analysis capabilities through Google search, GitHub, and local project files.","zh":"适合需要通过Google搜索、GitHub和本地项目文件进行高级信息收集和分析的知识代理。","ja":"Google検索、GitHub、ローカルプロジェクトファイルを介した高度な情報収集および分析機能を必要とするナレッジエージェントに適しています。","ko":"Google 검색, GitHub, 로컬 프로젝트 파일을 통해 고급 정보 수집 및 분석 기능이 필요한 지식 에이전트에게 적합합니다.","es":"Ideal para Agentes de Conocimiento que necesitan capacidades avanzadas de recopilación y análisis de información a través de la búsqueda de Google, GitHub y archivos de proyectos locales.","fr":"Idéal pour les agents de connaissances ayant besoin de capacités avancées de collecte et d''analyse d''informations via la recherche Google, GitHub et les fichiers de projets locaux.","de":"Ideal für Wissensagenten, die erweiterte Informationen sammeln und analysieren müssen durch Google-Suche, GitHub und lokale Projektdateien.","pt":"Ideal para Agentes de Conhecimento que precisam de capacidades avançadas de coleta e análise de informações por meio da busca do Google, GitHub e arquivos de projeto locais.","ru":"Идеально для агентов знаний, которым требуются продвинутые возможности сбора и анализа информации через поиск Google, GitHub и локальные файлы проекта.","ar":"مثالية لوكلاء المعرفة الذين يحتاجون إلى قدرات متقدمة لجمع المعلومات و تحليلها من خلال بحث جوجل و جيثب و ملفات المشروع المحلية."},"recommendation":{"en":"Empowers agents to investigate local project files, conduct Google searches for best practices, and scour GitHub for examples, enabling informed decision-making through structured research methodologies and temporary markdown file organization.","zh":"使代理能够调查本地项目文件、进行Google搜索以获取最佳实践，并在GitHub上搜索示例，从而通过结构化的研究方法和临时的Markdown文件组织实现明智的决策。","ja":"エージェントがローカルプロジェクトファイルを調査し、Google検索でベストプラクティスを探し、GitHubとStackOverflowで参考例を探すことができるため、構造化された研究方法と一時的なMarkdownファイルの組織化を通じて情報に基づいた意思決定を可能にします。","ko":"에이전트가 로컬 프로젝트 파일을 조사하고 Google 검색을 통해 최고의 관행을 찾고 GitHub 및 StackOverflow에서 참조 예를 찾을 수 있으므로 구조화된 연구 방법론과 임시 Markdown 파일 조직화를 통해 정보에 기반한 의사 결정을 가능하게 합니다.","es":"Habilita a los agentes a investigar archivos de proyectos locales, realizar búsquedas en Google sobre las mejores prácticas y buscar ejemplos en GitHub, lo que permite la toma de decisiones informadas a través de metodologías de investigación estructuradas y la organización temporal de archivos markdown.","fr":"Permet aux agents d''enquêter sur les fichiers de projets locaux, de effectuer des recherches Google sur les meilleures pratiques et de rechercher des exemples sur GitHub, ce qui permet une prise de décision éclairée via des méthodologies de recherche structurées et une organisation temporaire de fichiers markdown.","de":"Ermächtigt die Agenten, lokale Projektdateien zu untersuchen, Google-Suchen nach Best Practices durchzuführen und Beispiele auf GitHub zu suchen, was eine informierte Entscheidungsfindung durch strukturierte Forschungsmethoden und temporäre Markdown-Dateiorganisation ermöglicht.","pt":"Habilita os agentes a investigarem arquivos de projeto locais, realizarem buscas no Google para melhores práticas e vasculharem o GitHub para exemplos, permitindo a tomada de decisões informadas por meio de metodologias de pesquisa estruturadas e organização temporária de arquivos markdown.","ru":"Наделяет агентов возможностью расследовать локальные файлы проекта, проводить поиск Google для лучших практик и искать примеры на GitHub, что позволяет принимать обоснованные решения посредством структурированных исследовательских методологий и временной организации файлов markdown.","ar":"تمكين الوكلاء من التحقيق في ملفات المشروع المحلية و إجراء عمليات بحث على جوجل للحصول على أفضل الممارسات و البحث عن الأمثلة على جيثب و ستاك أوفيرفلو للرجوع إليها، مما يتيح اتخاذ قرارات مدروسة من خلال منهجيات بحث منظم وتنظيم ملفات ماركداون المؤقت."},"useCases":{"en":["Investigating local project files for context","Searching Google for best practices and documentation","Finding examples on GitHub and StackOverflow for reference"],"zh":["调查本地项目文件以获取上下文","在Google上搜索最佳实践和文档","在GitHub和StackOverflow上找到参考示例"],"ja":["コンテキストを得るためにローカルプロジェクトファイルを調査する","ベストプラクティスとドキュメントを検索するためのGoogle検索","参考としてGitHubとStackOverflowで例を探す"],"ko":["컨텍스트를 얻기 위해 로컬 프로젝트 파일을 조사한다","최선의 관행 및 문서를 검색하기 위한 Google 검색","참조용으로 GitHub 및 StackOverflow에서 예를 찾는다"],"es":["Investigar archivos de proyectos locales para obtener contexto","Buscar en Google las mejores prácticas y la documentación","Encontrar ejemplos en GitHub y StackOverflow para referencia"],"fr":["Enquêter sur les fichiers de projets locaux pour obtenir le contexte","Rechercher sur Google les meilleures pratiques et la documentation","Trouver des exemples sur GitHub et StackOverflow pour référence"],"de":["Untersuchen lokaler Projektdateien für Kontext","Suchen nach Best Practices und Dokumentation auf Google","Finden von Beispielen auf GitHub und StackOverflow für Referenz"],"pt":["Investigação de arquivos de projeto locais para contexto","Pesquisa no Google para melhores práticas e documentação","Encontrar exemplos no GitHub e StackOverflow para referência"],"ru":["Расследование локальных файлов проекта для контекста","Поиск Google для лучших практик и документации","Поиск примеров на GitHub и StackOverflow для справки"],"ar":["التحقيق في ملفات المشروع المحلية للحصول على السياق","البحث على جوجل للحصول على أفضل الممارسات و الوثائق","العثور على الأمثلة على جيثب و ستاك أوفيرفلو للرجوع إليها"]},"limitations":{"en":["Requires internet access for Google search and GitHub retrieval","Dependent on quality and relevance of online resources"],"zh":["需要互联网访问来进行Google搜索和GitHub检索","依赖于在线资源的质量和相关性"],"ja":["Google検索とGitHubの取得にはインターネットアクセスが必要","オンラインリソースの品質と関連性に依存する"],"ko":["Google 검색 및 GitHub 검색을 위해 인터넷 액세스가 필요하다","온라인 리소스의 품질 및 관련성에 종속된다"],"es":["Requiere acceso a Internet para la búsqueda de Google y la recuperación de GitHub","Dependiente de la calidad y la relevancia de los recursos en línea"],"fr":["Nécessite un accès à Internet pour la recherche Google et la récupération de GitHub","Dépend de la qualité et de la pertinence des ressources en ligne"],"de":["Benötigt Internetzugang für Google-Suche und GitHub-Abruf","Abhängig von der Qualität und Relevanz der Online-Ressourcen"],"pt":["Requer acesso à internet para busca do Google e recuperação do GitHub","Dependente da qualidade e relevância dos recursos online"],"ru":["Требует доступа к интернету для поиска Google и извлечения GitHub","Зависит от качества и релевантности онлайн-ресурсов"],"ar":["يتطلب الوصول إلى الإنترنت للبحث على جوجل و استرجاع جيثب","يعتمد على جودة و صلة الموارد المتاحة على الإنترنت"]},"version":4},"contentHash":"12a3befc365e999878a8fd77f28cef1248549d4171a21866dcb1745511db530c","qualityScore":30}');
