INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('inline-chat/inline/research', 'research', 'inline-chat', 'inline', 'community', 'research inline-chat inline community The research skill enables developers to investigate local project files, Google search best practices, and look for examples on GitHub to make informed decisions. It benefits developers by providing a structured approach to research. 研究技能提供了技术集成，包括谷歌搜索、GitHub 和 StackOverflow，用于提高开发效率 研究スキルは、Google 検索、GitHub、StackOverflow の技術統合を提供し、開発効率を向上させる 연구 스킬은 Google 검색, GitHub, StackOverflow의 기술적 통합을 제공하여 개발 효율성을 향상 La investigación es un proceso clave para los desarrolladores. Nuestra guía cubre las mejores prácticas de búsqueda en Google, GitHub y más La recherche est un processus clé pour les développeurs. Notre guide couvre les meilleures pratiques de recherche sur Google, GitHub et plus Die Recherche ist ein wichtiger Prozess für Entwickler. Unser Leitfaden deckt die Best Practices für die Suche auf Google, GitHub und mehr ab A pesquisa avançada é uma habilidade que permite investigar arquivos de projeto locais, realizar buscas no Google e procurar exemplos em GitHub e StackOverflow Исследование - это навык, который позволяет исследовать локальные проектные файлы, проводить поиск в Google и искать примеры на GitHub и StackOverflow البحث المتقدم هو مهارة تمكنك من التحقيق في الملفات المحلية للمشروع وإجراء عمليات بحث على جوجل والبحث عن الأمثلة على جيثب وستاك أوفيرفلو how to use research skill research alternative tools research setup guide for AI agents what is research in AI research vs Google search research install for developers AI工具 研究技能 谷歌搜索 GitHub StackOverflow 开发效率 技术集成 AIエージェント Investigates local project files related to the session Conducts Google searches for best practices and documentations Looks for examples on GitHub, Gist, or blog posts, and StackOverflow Constructs research using a temporary markdown file Makes informed decisions based on gathered information Research is a systematic investigation process that involves analyzing local project files, searching Google, and exploring GitHub examples to gather information and construct better research outcomes');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('akiojin/llmlb/hotfix', 'community', 'akiojin', 'llmlb', 'akiojin/llmlb', 'hotfix', 2, 0, 30, '2026-02-28T09:28:07Z', '2026-03-06T07:07:39.069Z', '17cc1b01e20874dbb0a36060132e269a2dd4fd5942479d6c82754edcba26ff86', '{"id":"akiojin/llmlb/hotfix","name":"hotfix","description":{"en":"The hotfix skill automates the hotfix workflow for AI agents, enabling developers to efficiently manage and release patches. It benefits developers by simplifying the process from branch creation to release confirmation.","zh":"Hotfix是一种分布式LLM路由器，具有负载均衡和自动模型分布功能，用于提高开发效率","ja":"Hotfixは分散型LLMルーターであり、ロードバランシングと自動モデル配布機能を備えています","ko":"Hotfix는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 배포 기능을 제공하여 개발 효율성을 높입니다","es":"El hotfix es un enrutador LLM distribuido con equilibrio de carga y distribución automática de modelos para una implementación eficiente","fr":"Le hotfix est un routeur LLM distribué avec équilibrage de charge et distribution automatique de modèles pour une mise en œuvre efficace","de":"Der Hotfix ist ein verteilter LLM-Router mit Lastenausgleich und automatischer Modellverteilung für eine effiziente Implementierung","pt":"O hotfix é uma ferramenta de roteamento de LLM distribuído com balanceamento de carga e distribuição automática de modelos.","ru":"Hotfix - это инструмент распределенного маршрутизации LLM с балансировкой нагрузки и автоматическим распределением моделей.","ar":"Hotfix هو أداة موزع LLM الموزع مع توازن الحمل و توزيع نموذجي自动ي."},"seo":{"title":{"en":"hotfix: Automated Hotfix Workflow Setup Guide | AI Agent ...","zh":"Hotfix Setup Guide: 分布式LLM路由器与负载均衡","ja":"Hotfix セットアップガイド: 分散型LLMルーターと自動モデル配布","ko":"Hotfix 설치 가이드: 분산형 LLM 라우터 및 로드 밸런싱","es":"Guía de configuración de hotfix: enrutador LLM distribuido","fr":"Guide de configuration de hotfix : routeur LLM distribué","de":"Hotfix-Setup-Leitfaden: verteilter LLM-Router","pt":"Guia de Configuração do Hotfix: Roteamento de LLM Distrib...","ru":"Настройка Hotfix: Распределенный маршрутизатор LLM с бала...","ar":"دليل إعداد Hotfix: موزع LLM الموزع مع توازن الحمل"},"description":{"en":"Streamline your hotfix workflow with automated branching, testing, and release management - learn how to set up hotfix today!","zh":"了解Hotfix的分布式LLM路由器、负载均衡和自动模型分布功能，提高开发效率","ja":"Hotfixの分散型LLMルーター、自動モデル配布、ロードバランシング機能について","ko":"Hotfix의 분산형 LLM 라우터, 자동 모델 배포, 로드 밸런싱 기능을 통해 개발 효율성을 높여보세요","es":"Aprende a configurar hotfix con nuestro enrutador LLM distribuido y equilibrio de carga para una implementación eficiente","fr":"Découvrez comment configurer hotfix avec notre routeur LLM distribué et équilibrage de charge pour une mise en œuvre efficace","de":"Erfahren Sie, wie Sie hotfix mit unserem verteilter LLM-Router und Lastenausgleich für eine effiziente Implementierung konfigurieren","pt":"Aprenda a configurar o hotfix com roteamento de LLM distribuído e balanceamento de carga para desenvolvedores","ru":"Узнайте, как настроить hotfix с распределенным маршрутизатором LLM и балансировкой нагрузки для разработчиков","ar":"تعلم كيفية إعداد Hotfix مع موزع LLM الموزع و توازن الحمل لالمطورين"},"definition":{"en":"hotfix is a distributed LLM router with load balancing and automatic model distribution, facilitating efficient hotfix workflows","zh":"Hotfix是一种分布式LLM路由器，用于实现负载均衡和自动模型分布","ja":"Hotfixは分散型LLMルーターであり、ロードバランシングと自動モデル配布を実現します","ko":"Hotfix는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 배포를 지원하는 기술입니다","es":"Un hotfix es un enrutador LLM distribuido que permite la distribución automática de modelos y el equilibrio de carga","fr":"Un hotfix est un routeur LLM distribué qui permet la distribution automatique de modèles et l''équilibrage de charge","de":"Ein Hotfix ist ein verteilter LLM-Router, der die automatische Modellverteilung und den Lastenausgleich ermöglicht","pt":"O que é hotfix? É uma ferramenta de roteamento de LLM distribuído com balanceamento de carga.","ru":"Что такое hotfix? Это инструмент распределенного маршрутизации LLM с балансировкой нагрузки.","ar":"ما هو Hotfix? هو أداة موزع LLM الموزع مع توازن الحمل."},"features":{"en":["Creates `hotfix/*` branches from the `main` branch","Runs preflight checks using `git status --short` and `gh auth status`","Supports automatic model distribution and load balancing","Provides a guided workflow from branch creation to patch release confirmation","Allows for interactive hotfix creation using `./scripts/release/create-hotfix.sh`"],"zh":["分布式LLM路由器","负载均衡功能","自动模型分布","Git分支管理","Preflight检查","CLI脚本支持"],"ja":["分散型LLMルーター","ロードバランシング機能","自動モデル配布","Gitブランチ管理","Preflightチェック","CLIスクリプトサポート"],"ko":["분산형 LLM 라우터","로드 밸런싱 기능","자동 모델 배포","Git 브랜치 관리","Preflight 확인","CLI 스크립트 지원"],"es":["Enrutador LLM distribuido","Equilibrio de carga automático","Distribución automática de modelos","Creación de ramas hotfix/*","Verificación de estado de Git","Autenticación de GitHub"],"fr":["Routeur LLM distribué","Équilibrage de charge automatique","Distribution automatique de modèles","Création de branches hotfix/*","Vérification de l''état de Git","Authentification GitHub"],"de":["Verteilter LLM-Router","Automatischer Lastenausgleich","Automatische Modellverteilung","Erstellung von hotfix/*-Branches","Git-Status-Überprüfung","GitHub-Authentifizierung"],"pt":["Roteamento de LLM distribuído","Balanceamento de carga automático","Distribuição automática de modelos","Criação de branches hotfix/*","Integração com Git e GitHub"],"ru":["Распределенный маршрутизатор LLM","Автоматическая балансировка нагрузки","Автоматическое распределение моделей","Создание веток hotfix/*","Интеграция с Git и GitHub"],"ar":["موزع LLM الموزع","توازن الحمل الأوتوماتيكي","توزيع نموذجي أوتوماتي","إنشاء فروع hotfix/*","التكامل مع Git و GitHub"]},"keywords":{"en":["how to use hotfix","hotfix workflow automation","hotfix vs manual patching","hotfix install guide","what is hotfix in AI","hotfix alternative solutions","hotfix setup tutorial","hotfix load balancing","automated hotfix release management"],"zh":["Hotfix","分布式LLM路由器","负载均衡","自动模型分布","AIエージェント","Git分支管理","CLI脚本","Preflight检查"],"ja":["Hotfix","分散型LLMルーター","ロードバランシング","自動モデル配布","AIエージェント","Gitブランチ管理","CLIスクリプト","Preflightチェック"],"ko":["Hotfix","분산형 LLM 라우터","로드 밸런싱","자동 모델 배포","AI 에이전트","Git 브랜치 관리","CLI 스크립트","Preflight 확인"],"es":["hotfix","enrutador LLM distribuido","equilibrio de carga","distribución automática de modelos","creación de ramas hotfix","verificación de estado de Git","autenticación de GitHub","herramientas de desarrollo","desarrollo de software"],"fr":["hotfix","routeur LLM distribué","équilibrage de charge","distribution automatique de modèles","création de branches hotfix","vérification de l''état de Git","authentification GitHub","outils de développement","développement de logiciels"],"de":["Hotfix","verteilter LLM-Router","Lastenausgleich","automatische Modellverteilung","Erstellung von hotfix-Branches","Git-Status-Überprüfung","GitHub-Authentifizierung","Entwicklungstools","Software-Entwicklung"],"pt":["hotfix","roteamento de LLM","balanceamento de carga","distribuição de modelos","desenvolvimento de software","ferramentas de desenvolvimento","IA","Machine Learning","Git","GitHub"],"ru":["hotfix","распределенный маршрутизатор LLM","балансировка нагрузки","распределение моделей","разработка программного обеспечения","инструменты разработки","ИИ","Машинное обучение","Git","GitHub"],"ar":["Hotfix","موزع LLM الموزع","توازن الحمل","توزيع نموذجي","تطوير البرمجيات","أدوات التطوير","الذكاء الاصطناعي","تعلم الآلة","Git","GitHub"]}},"owner":"akiojin","repo":"llmlb","repoPath":"akiojin/llmlb","stars":2,"forks":0,"updatedAt":"2026-02-28T09:28:07Z","topics":[],"category":"community","skillMd":{"name":"hotfix","description":"Execute the hotfix workflow when the user asks `hotfix` or `/hotfix`: create a hotfix branch from main, guide fix+checks, open PR to main, and confirm patch release.","bodyPreview":"# Hotfix Workflow\n\n本番障害向けのホットフィックスフローを開始し、`hotfix/*` ブランチ作成からパッチリリース確認までを案内する。\n\n## Preflight\n\n- `git status --short` が空であること\n- `main` ブランチが存在すること\n- `gh auth status` が成功すること\n\n## 実行内容\n\n1. 前提条件チェック\n2. `main` から `hotfix/*` ブランチ作成\n3. 修正・品質チェック・PR作成・リリース確認の手順提示\n\n## 使用方法\n\n### パターンA: Issue番号を指定\n\n```bash\n./scripts/release/create-hotfix.sh 42\n# -> hotfix/42\n```\n\n### パターンB: 説明を指定\n\n```bash\n./scripts/release/create-hotfix.sh fix-critical-bug\n# -> hotfix/fix-critical-bug\n```\n\n### パターンC: 対話式\n\n```bash\n./scripts","body":"# Hotfix Workflow\n\n本番障害向けのホットフィックスフローを開始し、`hotfix/*` ブランチ作成からパッチリリース確認までを案内する。\n\n## Preflight\n\n- `git status --short` が空であること\n- `main` ブランチが存在すること\n- `gh auth status` が成功すること\n\n## 実行内容\n\n1. 前提条件チェック\n2. `main` から `hotfix/*` ブランチ作成\n3. 修正・品質チェック・PR作成・リリース確認の手順提示\n\n## 使用方法\n\n### パターンA: Issue番号を指定\n\n```bash\n./scripts/release/create-hotfix.sh 42\n# -> hotfix/42\n```\n\n### パターンB: 説明を指定\n\n```bash\n./scripts/release/create-hotfix.sh fix-critical-bug\n# -> hotfix/fix-critical-bug\n```\n\n### パターンC: 対話式\n\n```bash\n./scripts/release/create-hotfix.sh\n```\n\n## 修正後の流れ\n\n```bash\n# 1) 修正実装\ngit add .\ngit commit -m \"fix: 緊急修正の説明\"\n\n# 2) 品質チェック\nmake quality-checks\n\n# 3) プッシュ + PR\ngit push -u origin hotfix/xxx\ngh pr create --base main --head hotfix/xxx \\\n  --title \"fix: 緊急修正の説明\" \\\n  --label \"hotfix,auto-merge\"\n\n# 4) リリース確認\ngh release view\n```\n\n## 注意\n\n- 緊急修正以外の変更を含めない\n- Conventional Commits で `fix:` プレフィックスを使う\n- main マージ後はパッチ版（例: v1.2.4）が自動作成される\n"},"lastSynced":"2026-03-06T07:07:39.069Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing streamlined hotfix workflows for efficient patch management.","zh":"非常适合需要简化热修复工作流以实现高效补丁管理的DevOps代理。","ja":"DevOpsエージェントが効率的なパッチ管理のためのストリームライン化されたホットフィックスワークフローを必要とする場合に最適です。","ko":"효율적인 패치 관리를 위한 스트림 라인화된 핫픽스 워크 플로우가 필요한 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan flujos de trabajo de correcciones rápidas simplificados para una gestión de patches eficiente.","fr":"Parfait pour les agents DevOps qui ont besoin de flux de travail de correctifs simplifiés pour une gestion de patches efficace.","de":"Perfekt für DevOps-Agents, die vereinfachte Hotfix-Workflows für eine effiziente Patch-Verwaltung benötigen.","pt":"Perfeito para Agentes DevOps que precisam de fluxos de trabalho de hotfix simplificados para gerenciamento de patches eficiente.","ru":"Идеально подходит для агентов DevOps, которым необходимы оптимизированные рабочие процессы горячего исправления для эффективного управления патчами.","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى تدفقات عمل تصحيح ساخنة مبسطة لإدارة التصحيحات الفعالة."},"recommendation":{"en":"Empowers agents to automate the hotfix workflow from branch creation to release confirmation using Git and GitHub protocols, simplifying the process with preflight checks and guided steps for modification, quality checks, PR creation, and release validation.","zh":"赋予代理人使用Git和GitHub协议从分支创建到发布确认来自动化热修复工作流的能力，通过预飞行检查和修改、质量检查、PR创建和发布验证的指导步骤来简化该过程。","ja":"GitおよびGitHubのプロトコルを使用して、ブランチの作成からリリースの確認までのホットフィックスのワークフローを自動化する機能をエージェントに提供し、事前フライトチェックと変更、品質チェック、PRの作成、リリースの検証のためのガイド付きステップでプロセスを簡素化します。","ko":"Git 및 GitHub 프로토콜을 사용하여 브랜치 생성에서 릴리즈 확인까지의 핫픽스 워크플로를 자동화하여 에이전트에게 능력을 부여하고, 사전 비행 확인 및 수정, 품질 확인, PR 생성 및 릴리즈 검증을 위한 가이드付き 단계로 프로세스를 간소화합니다.","es":"Habilita a los agentes a automatizar el flujo de trabajo de correcciones rápidas desde la creación de la rama hasta la confirmación de lanzamiento utilizando protocolos Git y GitHub, simplificando el proceso con comprobaciones previas al vuelo y pasos guiados para modificación, comprobaciones de calidad, creación de PR y validación de lanzamiento.","fr":"Permet aux agents d''automatiser le flux de travail de correctifs de la création de branche à la confirmation de release en utilisant les protocoles Git et GitHub, en simplifiant le processus avec des vérifications préalables et des étapes guidées pour modification, contrôles de qualité, création de PR et validation de release.","de":"Ermächtigt Agenten, den Hotfix-Workflow von der Erstellung des Branches bis zur Release-Bestätigung mithilfe von Git- und GitHub-Protokollen zu automatisieren, wodurch der Prozess durch Vorab-Checks und geleitete Schritte für Modifizierung, Qualitätschecks, PR-Erstellung und Release-Validierung vereinfacht wird.","pt":"Habilita os agentes a automatizar o fluxo de trabalho de hotfix da criação de branch até a confirmação de lançamento usando protocolos Git e GitHub, simplificando o processo com verificações pré-voo e etapas guiadas para modificação, verificações de qualidade, criação de PR e validação de lançamento.","ru":"Позволяет агентам автоматизировать рабочий процесс горячего исправления от создания ветки до подтверждения выпуска, используя протоколы Git и GitHub, упрощая процесс с помощью предварительных проверок и пошаговых инструкций для изменения, проверки качества, создания PR и проверки выпуска.","ar":"تمكن الوكلاء من ت 자동化 تدفق عمل التصحيح الساخن من إنشاء الفرع إلى تأكيد الإصدار باستخدام بروتوكولات Git و GitHub ، وبذلك يُبسّط العملية باستخدام فحص ما قبل الطيران وخطوات توجيهية لتعديل ، وفحص الجودة ، وإنشاء PR ، وتأكيد الإصدار."},"useCases":{"en":["Automating hotfix branch creation with specific issue numbers or descriptive tags","Streamlining patch release confirmation processes","Guiding developers through quality checks and PR creation for hotfixes"],"zh":["使用特定问题编号或描述性标签自动创建热修复分支","简化补丁发布确认过程","指导开发人员完成热修复的质量检查和PR创建"],"ja":["特定の問題番号または記述的なタグを使用してホットフィックスブランチを自動的に作成する","パッチのリリース確認プロセスを簡素化する","開発者がホットフィックスの品質チェックとPRの作成を実行するためのガイダンスを提供する"],"ko":["특정 문제 번호 또는 설명적 태그를 사용하여 핫픽스 브랜치를 자동으로 생성합니다","패치 릴리즈 확인 프로세스를 간소화합니다","개발자가 핫픽스의 품질 확인 및 PR 생성을 수행하는 데 도움이 되는 가이드를 제공합니다"],"es":["Automatizar la creación de ramas de correcciones rápidas con números de problema específicos o etiquetas descriptivas","Simplificar los procesos de confirmación de lanzamiento de patches","Guiar a los desarrolladores a través de comprobaciones de calidad y creación de PR para correcciones rápidas"],"fr":["Automatiser la création de branches de correctifs avec des numéros de problème spécifiques ou des étiquettes descriptives","Simplifier les processus de confirmation de release de patches","Guider les développeurs à travers les contrôles de qualité et la création de PR pour les correctifs"],"de":["Automatisieren der Erstellung von Hotfix-Branches mit spezifischen Problemnummern oder beschreibenden Tags"," Vereinfachen der Prozesse zur Bestätigung von Patch-Releases","Entwickler durch Qualitätschecks und PR-Erstellung für Hotfixes führen"],"pt":["Automatizar a criação de branch de hotfix com números de problema específicos ou tags descritivas","Simplificar os processos de confirmação de lançamento de patches","Orientar os desenvolvedores por meio de verificações de qualidade e criação de PR para hotfixes"],"ru":["Автоматизировать создание ветки горячего исправления с конкретными номерами проблем или описательными тегами","Упростить процессы подтверждения выпуска патчей","Направлять разработчиков через проверки качества и создание PR для горячих исправлений"],"ar":["توفير إنشاء فرع تصحيح ساخن مع أرقام مشكلة محددة أو علامات وصفية","تبسيط عمليات تأكيد إصدار التصحيحات","توجيه المطورين من خلال فحص الجودة وإنشاء PR للتصحيحات الساخنة"]},"limitations":{"en":["Requires Git and GitHub setup","Needs ''gh auth status'' to be successful for authentication","Dependent on ''git status --short'' being empty and ''main'' branch existing"],"zh":["需要Git和GitHub的设置","需要''gh auth status''成功以进行身份验证","依赖于''git status --short''为空且''main''分支存在"],"ja":["GitおよびGitHubの設定が必要","''gh auth status''が成功して認証される必要がある","''git status --short''が空で、''main''ブランチが存在する必要がある"],"ko":["Git 및 GitHub 설정이 필요합니다","''gh auth status''가 성공하여 인증되야 합니다","''git status --short''가 비어 있고 ''main'' 브랜치가 존재해야 합니다"],"es":["Requiere configuración de Git y GitHub","Necesita que ''gh auth status'' sea exitoso para la autenticación","Dependiente de que ''git status --short'' esté vacío y la rama ''main'' exista"],"fr":["Nécessite une configuration Git et GitHub","Nécessite que ''gh auth status'' soit réussi pour l''authentification","Dépend de ce que ''git status --short'' soit vide et que la branche ''main'' existe"],"de":["Benötigt Git- und GitHub-Setup","Benötigt, dass ''gh auth status'' erfolgreich ist, um die Authentifizierung durchzuführen","Abhängig davon, dass ''git status --short'' leer ist und der ''main''-Branch existiert"],"pt":["Exige configuração do Git e GitHub","Necessita que ''gh auth status'' seja bem-sucedido para autenticação","Depende de ''git status --short'' estar vazio e da existência da branch ''main''"],"ru":["Требует настройки Git и GitHub","Требует, чтобы ''gh auth status'' был успешным для аутентификации","Зависит от того, что ''git status --short'' пуст и что ветка ''main'' существует"],"ar":["يتطلب إعداد Git و GitHub","يحتاج إلى أن يكون ''gh auth status'' ناجحًا للتأشير","يعتمد على أن يكون ''git status --short'' فارغًا ووجود فرع ''main''"]},"version":4},"contentHash":"17cc1b01e20874dbb0a36060132e269a2dd4fd5942479d6c82754edcba26ff86","qualityScore":30}');
