INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('akiojin/llmlb/hotfix', 'hotfix', 'akiojin', 'llmlb', 'community', 'hotfix akiojin llmlb community The hotfix skill automates the hotfix workflow for AI agents, enabling developers to efficiently manage and release patches. It benefits developers by simplifying the process from branch creation to release confirmation. Hotfix是一种分布式LLM路由器，具有负载均衡和自动模型分布功能，用于提高开发效率 Hotfixは分散型LLMルーターであり、ロードバランシングと自動モデル配布機能を備えています Hotfix는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 배포 기능을 제공하여 개발 효율성을 높입니다 El hotfix es un enrutador LLM distribuido con equilibrio de carga y distribución automática de modelos para una implementación eficiente Le hotfix est un routeur LLM distribué avec équilibrage de charge et distribution automatique de modèles pour une mise en œuvre efficace Der Hotfix ist ein verteilter LLM-Router mit Lastenausgleich und automatischer Modellverteilung für eine effiziente Implementierung O hotfix é uma ferramenta de roteamento de LLM distribuído com balanceamento de carga e distribuição automática de modelos. Hotfix - это инструмент распределенного маршрутизации LLM с балансировкой нагрузки и автоматическим распределением моделей. Hotfix هو أداة موزع LLM الموزع مع توازن الحمل و توزيع نموذجي自动ي. how to use hotfix hotfix workflow automation hotfix vs manual patching hotfix install guide what is hotfix in AI hotfix alternative solutions hotfix setup tutorial hotfix load balancing automated hotfix release management Hotfix 分布式LLM路由器 负载均衡 自动模型分布 AIエージェント Git分支管理 CLI脚本 Preflight检查 Creates `hotfix/*` branches from the `main` branch Runs preflight checks using `git status --short` and `gh auth status` Supports automatic model distribution and load balancing Provides a guided workflow from branch creation to patch release confirmation Allows for interactive hotfix creation using `./scripts/release/create-hotfix.sh` hotfix is a distributed LLM router with load balancing and automatic model distribution, facilitating efficient hotfix workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('robbyt/claude-skills/repo', 'community', 'robbyt', 'claude-skills', 'robbyt/claude-skills', 'repo', 0, 0, 30, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:40.826Z', 'f58258a4f49be5873ab19283cefc42fc5b99aa1883efd7b3fec515a89e0720ff', '{"id":"robbyt/claude-skills/repo","name":"repo","description":{"en":"The repo skill enables AI agents to manage GitHub repositories using the gh CLI, allowing for read-only operations such as viewing and listing repositories. This skill benefits developers and repository administrators.","zh":"repo 技能允许您使用 GitHub CLI 查看和管理仓库信息，包括查看当前仓库和列表仓库","ja":"repo スキルは、GitHub CLI を使用してリポジトリ情報を表示して管理することを可能にします。現在のリポジトリとリストのリポジトリを表示する","ko":"repo 기능은 GitHub CLI를 사용하여 저장소 정보를 보기 및 관리할 수 있게 해줍니다. 현재 저장소 및 목록 저장소를 표시합니다.","es":"El skill repo permite a los desarrolladores ver detalles de repositorio y listar repositorios con el comando gh CLI","fr":"Le skill repo permet aux développeurs d''afficher les détails de repository et de lister les repositories avec la commande gh CLI","de":"Das repo-Skill ermöglicht es Entwicklern, Repository-Details anzuzeigen und Repositories mit dem gh-CLI-Befehl aufzulisten","pt":"O skill repo fornece informações sobre repositórios e permite listar repositórios com o GitHub CLI. Saiba como configurar e utilizar","ru":"Навык репозитория предоставляет информацию о репозиториях и позволяет списывать репозитории с помощью GitHub CLI. Узнайте, как настроить и использовать","ar":"المهارة المستودع توفر معلومات حول المستودعات وتسمح بقائمة المستودعات باستخدام واجهة سطر الأوامر GitHub. تعرف على كيفية الإعداد والاستخدام"},"seo":{"title":{"en":"repo: GitHub Repository Management for AI Agents | AI Age...","zh":"repo Setup Guide: 使用 GitHub CLI 查看仓库信息","ja":"repo セットアップガイド: GitHub CLI を使用したリポジトリ情報の表示","ko":"repo 설정 가이드: GitHub CLI를 사용한 저장소 정보 보기","es":"Guía de configuración de repo para Claude Code","fr":"Guide de mise en place de repo pour Claude Code","de":"Einrichtungsleitfaden für repo in Claude Code","pt":"Guia de Configuração do Repositório com Claude Code","ru":"Настройка репозитория с помощью ИИ Агентов Claude Code","ar":"دليل إعداد المستودع مع Claude Code"},"description":{"en":"Unlock efficient GitHub repository management with the repo skill. Learn how to view and list repositories using the gh CLI and optimize your workflow today!","zh":"了解如何使用 GitHub CLI 查看和管理仓库信息，包括查看当前仓库和列表仓库","ja":"GitHub CLI を使用してリポジトリ情報を表示して管理する方法を学習する、現在のリポジトリとリストのリポジトリを表示する","ko":"GitHub CLI를 사용하여 저장소 정보를 보기 및 관리하는 방법을 알아보세요. 현재 저장소 및 목록 저장소를 표시합니다.","es":"Aprende a utilizar el comando gh para ver detalles de repositorio y listar repositorios en Claude Code","fr":"Découvrez comment utiliser la commande gh pour afficher les détails de repository et lister les repositories dans Claude Code","de":"Erfahren Sie, wie Sie den Befehl gh verwenden, um Repository-Details anzuzeigen und Repositories in Claude Code aufzulisten","pt":"Aprenda a visualizar detalhes do repositório e listar repositórios com o CLI do GitHub e Claude Code","ru":"Узнайте, как просматривать детали репозитория и список репозиториев с помощью GitHub CLI и ИИ Агентов Claude Code","ar":"تعرف على كيفية عرض تفاصيل المستودع وقائمة المستودعات باستخدام واجهة سطر الأوامر GitHub و Claude Code"},"definition":{"en":"repo is a skill that provides GitHub repository information and management capabilities using the gh CLI, supporting commands like gh repo view and gh repo list.","zh":"repo 是一个使用 GitHub CLI 查看和管理仓库信息的技能","ja":"repo は、GitHub CLI を使用してリポジトリ情報を表示して管理するスキルです","ko":"repo는 GitHub CLI를 사용하여 저장소 정보를 보기 및 관리하는 기능입니다","es":"El skill repo es una herramienta de línea de comandos para ver detalles de repositorio y listar repositorios en Claude Code","fr":"Le skill repo est un outil de ligne de commande pour afficher les détails de repository et lister les repositories dans Claude Code","de":"Das repo-Skill ist ein Kommandozeilen-Tool zum Anzeigen von Repository-Details und Auflisten von Repositories in Claude Code","pt":"O que é um repositório? Um repositório é um local de armazenamento de código-fonte","ru":"Что такое репозиторий? Репозиторий - это место хранения исходного кода","ar":"ما هو المستودع? المستودع هو مكان لتخزين الشفرة المصدرية"},"features":{"en":["View current repository details using gh repo view","List repositories for a specific owner with gh repo list owner","Supports read-only operations for repository management","Utilizes the GitHub CLI (gh) for authentication and commands","Enables viewing of specific repositories with gh repo view owner/repo","Provides a quick reference for common gh CLI repository commands"],"zh":["使用 gh CLI 查看当前仓库信息","使用 gh CLI 查看特定仓库信息","使用 gh CLI 列表仓库","支持只读操作","需要 GitHub CLI 安装和认证"],"ja":["gh CLI を使用して現在のリポジトリ情報を表示","gh CLI を使用して特定のリポジトリ情報を表示","gh CLI を使用してリストのリポジトリを表示","読み取り専用操作のみをサポート","GitHub CLI のインストールと認証が必要"],"ko":["gh CLI를 사용하여 현재 저장소 정보를 보기","gh CLI를 사용하여 특정 저장소 정보를 보기","gh CLI를 사용하여 목록 저장소를 표시","읽기 전용 작업만 지원","GitHub CLI 설치 및 인증 필요"],"es":["Ver detalles de repositorio con gh repo view","Listar repositorios de un propietario con gh repo list","Utilizar el comando gh CLI para operaciones de solo lectura","Requiere autenticación con GitHub CLI","Soporta la visualización de repositorios específicos con gh repo view owner/repo"],"fr":["Afficher les détails de repository avec gh repo view","Lister les repositories d''un propriétaire avec gh repo list","Utiliser la commande gh CLI pour des opérations en lecture seule","Requiert une authentification avec GitHub CLI","Prend en charge l''affichage de repositories spécifiques avec gh repo view owner/repo"],"de":["Anzeigen von Repository-Details mit gh repo view","Auflisten von Repositories eines Eigentümers mit gh repo list","Verwenden des gh-CLI-Befehls für Leseoperationen","Erfordert Authentifizierung mit GitHub CLI","Unterstützt die Anzeige spezifischer Repositories mit gh repo view owner/repo"],"pt":["Visualizar detalhes do repositório atual com `gh repo view`","Listar repositórios de um proprietário com `gh repo list`","Visualizar detalhes de um repositório específico com `gh repo view owner/repo`","Utilizar o GitHub CLI para operações de leitura apenas","Autenticação necessária com `gh auth status`"],"ru":["Просматривать детали текущего репозитория с помощью `gh repo view`","Списывать репозитории владельца с помощью `gh repo list`","Просматривать детали конкретного репозитория с помощью `gh repo view owner/repo`","Использовать GitHub CLI для операций чтения только","Аутентификация необходима с помощью `gh auth status`"],"ar":["عرض تفاصيل المستودع الحالي باستخدام `gh repo view`","قائمة المستودعات لمالك معين باستخدام `gh repo list`","عرض تفاصيل مستودع معين باستخدام `gh repo view owner/repo`","استخدام واجهة سطر الأوامر GitHub للعمليات القراءة فقط","التحقق مطلوب مع `gh auth status`"]},"keywords":{"en":["how to use repo","repo setup guide","github repository management","gh cli tutorial","repo vs github cli","what is repo","repo install","repo alternative","github cli commands","repo skill for ai agents"],"zh":["GitHub CLI","仓库信息","repo 技能","AI 工具","代码管理","GitHub 仓库","CLI 命令","仓库管理"],"ja":["GitHub CLI","リポジトリ情報","repo スキル","AI エージェント","コード管理","GitHub リポジトリ","CLI コマンド","リポジトリ管理"],"ko":["GitHub CLI","저장소 정보","repo 기능","AI 도구","코드 관리","GitHub 저장소","CLI 명령","저장소 관리"],"es":["repo skill"," Claude Code","comando gh","GitHub CLI","detalles de repositorio","listar repositorios","herramientas de desarrollo","línea de comandos"],"fr":["skill repo","Claude Code","commande gh","GitHub CLI","détails de repository","lister les repositories","outils de développement","ligne de commande"],"de":["repo-Skill","Claude Code","gh-Befehl","GitHub CLI","Repository-Details","Reposities auflisten","Entwicklungstools","Kommandozeile"],"pt":["repositório github","github cli","claude code","ai agents","repositório de código","visualizar repositório","listar repositórios","autenticação github"],"ru":["репозиторий github","github cli","claude code","ИИ Агенты","репозиторий кода","просматривать репозиторий","списывать репозитории","аутентификация github"],"ar":["مستودع github","واجهة سطر الأوامر github","claude code","وكلاء الذكاء الاصطناعي","مستودع الشفرة","عرض المستودع","قائمة المستودعات","التحقق من github"]}},"owner":"robbyt","repo":"claude-skills","repoPath":"robbyt/claude-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.264Z","topics":[],"category":"community","skillMd":{"name":"repo","description":"Repository information using GitHub CLI. Trigger when user wants to view repository details (show repo info, whats this repo about), list repositories (list my repos, show repos for user), or check repository metadata (stars, languages, topics).","bodyPreview":"# Repository Information\n\nView repository details and list repositories with the `gh` CLI. Read-only operations only.\n\n## Prerequisites\n\nGitHub CLI must be installed and authenticated:\n```bash\ngh auth status\n```\n\n## Quick Reference\n\n```bash\ngh repo view                        # View current repo\ngh repo view owner/repo             # View specific repo\ngh repo list owner                  # List repos for owner\n```\n\n## View Repository\n\n```bash\ngh repo view\ngh repo view owner/repo\ngh repo view owne","body":"# Repository Information\n\nView repository details and list repositories with the `gh` CLI. Read-only operations only.\n\n## Prerequisites\n\nGitHub CLI must be installed and authenticated:\n```bash\ngh auth status\n```\n\n## Quick Reference\n\n```bash\ngh repo view                        # View current repo\ngh repo view owner/repo             # View specific repo\ngh repo list owner                  # List repos for owner\n```\n\n## View Repository\n\n```bash\ngh repo view\ngh repo view owner/repo\ngh repo view owner/repo --json name,description,stargazersCount\ngh repo view owner/repo --web  # Open in browser\n```\n\n**Common JSON fields:**\n```bash\ngh repo view owner/repo --json name,description,url,stargazersCount,forkCount,isPrivate,languages,topics\n```\n\n## List Repositories\n\n```bash\ngh repo list\ngh repo list owner\ngh repo list owner --limit 50\ngh repo list owner --json name,description\ngh repo list owner --language go\ngh repo list owner --source  # Non-forks only\n```\n\n## Repository Search\n\n```bash\ngh search repos \"query\"\ngh search repos \"language:go stars:>100\"\ngh search repos \"org:anthropics\"\n```\n"},"lastSynced":"2026-03-08T01:59:40.826Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring seamless GitHub repository management and analysis.","zh":"适用于需要无缝管理和分析 GitHub 仓库的开发代理。","ja":"GitHub リポジトリの管理と分析をシームレスに実行する必要がある開発エージェントに最適です。","ko":"무결점한 GitHub 저장소 관리 및 분석이 필요한 개발 에이전트에게 적합합니다.","es":"Ideal para agentes de desarrollo que requieren una gestión y análisis de repositorios de GitHub sin problemas.","fr":"Idéal pour les agents de développement nécessitant une gestion et une analyse de référentiels GitHub sans heurts.","de":"Ideal für Entwicklungssagenten, die eine reibungslose GitHub-Repository-Verwaltung und -Analyse benötigen.","pt":"Ideal para Agentes de Desenvolvimento que requerem gerenciamento e análise de repositório GitHub sem interrupções.","ru":"Идеально для агентов разработки, требующих бесперебойного управления и анализа репозиториев GitHub.","ar":"مثالي لخصوم التطوير الذين يحتاجون إلى إدارة وأداة تحليل للمستودع GitHub دون انقطاع."},"recommendation":{"en":"Empowers agents to manage GitHub repositories using the gh CLI, enabling read-only operations such as viewing and listing repositories, and providing detailed repository information through commands like `gh repo view` and `gh repo list`.","zh":"通过 gh CLI 启用开发代理管理 GitHub 仓库，支持只读操作，如查看和列出仓库，并通过命令如 `gh repo view` 和 `gh repo list` 提供详细的仓库信息。","ja":"gh CLI を使用して GitHub リポジトリを管理する開発エージェントを可能にし、リポジトリの表示やリスト表示などの読み取り専用操作をサポートし、`gh repo view` および `gh repo list` などのコマンドを使用して詳細なリポジトリ情報を提供します。","ko":"gh CLI를 사용하여 개발 에이전트가 GitHub 저장소를 관리할 수 있도록 하여 저장소 보기 및 목록 보기와 같은 읽기 전용 작업을 지원하며 `gh repo view` 및 `gh repo list`와 같은 명령을 사용하여 자세한 저장소 정보를 제공합니다.","es":"Habilita a los agentes a gestionar repositorios de GitHub utilizando el CLI de gh, permitiendo operaciones de solo lectura como ver y listar repositorios, y proporcionando información detallada del repositorio a través de comandos como `gh repo view` y `gh repo list`.","fr":"Permet aux agents de gérer les référentiels GitHub à l''aide du CLI gh, permettant des opérations en lecture seule telles que la visualisation et la liste des référentiels, et fournissant des informations détaillées sur le référentiel via des commandes comme `gh repo view` et `gh repo list`.","de":"Ermächtigt Agenten, GitHub-Repositorys mithilfe des gh-CLI zu verwalten, wodurch Lesevorgänge wie Anzeigen und Auflisten von Repositorys ermöglicht werden und detaillierte Repository-Informationen durch Befehle wie `gh repo view` und `gh repo list` bereitgestellt werden.","pt":"Habilita os agentes a gerenciar repositórios GitHub usando o gh CLI, permitindo operações somente leitura, como visualizar e listar repositórios, e fornecendo informações detalhadas do repositório por meio de comandos como `gh repo view` e `gh repo list`.","ru":"Предоставляет агентам возможность управлять репозиториями GitHub с помощью gh CLI, позволяя выполнять операции только для чтения, такие как просмотр и перечисление репозиториев, и предоставляя подробную информацию о репозитории через команды như `gh repo view` и `gh repo list`.","ar":"يمكن الوكلاء من إدارة مستودعات GitHub باستخدام واجهة سطر الأوامر gh، وتمكين عمليات القراءة فقط مثل عرض وقائمة المستودعات، وتقديم معلومات مفصلة حول المستودع من خلال أوامر مثل `gh repo view` و `gh repo list`."},"useCases":{"en":["Viewing repository details","Listing repositories for a specific owner","Debugging repository issues using `gh repo view`"],"zh":["查看仓库详情","列出特定所有者的仓库","使用 `gh repo view` 调试仓库问题"],"ja":["リポジトリの詳細を表示する","特定の所有者のリポジトリを一覧表示する","`gh repo view` を使用してリポジトリの問題をデバッグする"],"ko":["저장소 세부 정보 보기","특정 소유자의 저장소를 나열","`gh repo view`를 사용하여 저장소 문제를 디버깅"],"es":["Visualización de detalles del repositorio","Listado de repositorios para un propietario específico","Depuración de problemas de repositorio utilizando `gh repo view`"],"fr":["Affichage des détails du référentiel","Liste des référentiels pour un propriétaire spécifique","Débogage des problèmes de référentiel en utilisant `gh repo view`"],"de":["Anzeigen von Repository-Details","Auflisten von Repositorys für einen bestimmten Besitzer","Fehlerbehebung bei Repository-Problemen mithilfe von `gh repo view`"],"pt":["Visualizar detalhes do repositório","Listar repositórios para um proprietário específico","Depurar problemas de repositório usando `gh repo view`"],"ru":["Просмотр деталей репозитория","Перечисление репозиториев для определенного владельца","Отладка проблем репозитория с помощью `gh repo view`"],"ar":["عرض تفاصيل المستودع","قائمة المستودعات لمالك معين","تصحيح مشاكل المستودع باستخدام `gh repo view`"]},"limitations":{"en":["Requires GitHub CLI installation and authentication","Read-only operations only","Limited to repositories accessible by the authenticated GitHub user"],"zh":["需要 GitHub CLI 安装和身份验证","仅支持只读操作","仅限已验证的 GitHub 用户可以访问的仓库"],"ja":["GitHub CLI のインストールと認証が必要","読み取り専用操作のみをサポート","認証された GitHub ユーザーがアクセスできるリポジトリのみに限定"],"ko":["GitHub CLI 설치 및 인증이 필요","읽기 전용 작업만 지원","인증된 GitHub 사용자가 액세스할 수 있는 저장소만 제한"],"es":["Requiere instalación y autenticación de GitHub CLI","Operaciones de solo lectura","Limitado a los repositorios accesibles por el usuario de GitHub autenticado"],"fr":["Nécessite l''installation et l''authentification du CLI GitHub","Opérations en lecture seule","Limité aux référentiels accessibles par l''utilisateur GitHub authentifié"],"de":["Benötigt GitHub-CLI-Installation und -Authentifizierung","Nur Lesevorgänge","Eingeschränkt auf Repositorys, die vom authentifizierten GitHub-Benutzer zugänglich sind"],"pt":["Requer instalação e autenticação do GitHub CLI","Operações somente leitura","Limitado a repositórios acessíveis pelo usuário autenticado do GitHub"],"ru":["Требуется установка и аутентификация GitHub CLI","Операции только для чтения","Ограничен до репозиториев, доступных для аутентифицированного пользователя GitHub"],"ar":["يتطلب تثبيت وتحقق من واجهة سطر الأوامر GitHub","عمليات القراءة فقط","محدود بالمستودعات التي يمكن الوصول إليها من قبل مستخدم GitHub المُؤمّن"]},"version":4},"contentHash":"f58258a4f49be5873ab19283cefc42fc5b99aa1883efd7b3fec515a89e0720ff","qualityScore":30}');
