INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('robbyt/claude-skills/repo', 'repo', 'robbyt', 'claude-skills', 'community', 'repo robbyt claude-skills community The repo skill enables AI agents to manage GitHub repositories using the gh CLI, allowing for read-only operations such as viewing and listing repositories. This skill benefits developers and repository administrators. repo 技能允许您使用 GitHub CLI 查看和管理仓库信息，包括查看当前仓库和列表仓库 repo スキルは、GitHub CLI を使用してリポジトリ情報を表示して管理することを可能にします。現在のリポジトリとリストのリポジトリを表示する repo 기능은 GitHub CLI를 사용하여 저장소 정보를 보기 및 관리할 수 있게 해줍니다. 현재 저장소 및 목록 저장소를 표시합니다. El skill repo permite a los desarrolladores ver detalles de repositorio y listar repositorios con el comando gh CLI Le skill repo permet aux développeurs d''afficher les détails de repository et de lister les repositories avec la commande gh CLI Das repo-Skill ermöglicht es Entwicklern, Repository-Details anzuzeigen und Repositories mit dem gh-CLI-Befehl aufzulisten O skill repo fornece informações sobre repositórios e permite listar repositórios com o GitHub CLI. Saiba como configurar e utilizar Навык репозитория предоставляет информацию о репозиториях и позволяет списывать репозитории с помощью GitHub CLI. Узнайте, как настроить и использовать المهارة المستودع توفر معلومات حول المستودعات وتسمح بقائمة المستودعات باستخدام واجهة سطر الأوامر GitHub. تعرف على كيفية الإعداد والاستخدام how to use repo repo setup guide github repository management gh cli tutorial repo vs github cli what is repo repo install repo alternative github cli commands repo skill for ai agents GitHub CLI 仓库信息 repo 技能 AI 工具 代码管理 GitHub 仓库 CLI 命令 仓库管理 View current repository details using gh repo view List repositories for a specific owner with gh repo list owner Supports read-only operations for repository management Utilizes the GitHub CLI (gh) for authentication and commands Enables viewing of specific repositories with gh repo view owner/repo Provides a quick reference for common gh CLI repository commands repo is a skill that provides GitHub repository information and management capabilities using the gh CLI, supporting commands like gh repo view and gh repo list.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jh941213/my-claude-code-asset/tdd', 'community', 'jh941213', 'my-claude-code-asset', 'jh941213/my-claude-code-asset', 'tdd', 0, 0, 30, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:11.925Z', '7b3706e134b9ae5d6a2050c57a4f11fa280702d12f0ecb5d19c36de497816964', '{"id":"jh941213/my-claude-code-asset/tdd","name":"tdd","description":{"en":"The TDD skill enables developers to apply test-driven development principles, writing tests before implementing code. This skill benefits developers who want to improve code quality and reliability.","zh":"TDD 测试驱动开发是一种先写测试然后编写代码的开发方法，通过 RED → GREEN → REFACTOR → REPEAT 循环提高代码质量","ja":"TDD テスト駆動開発は、テストを先に書いてからコードを実装する開発手法で、RED → GREEN → REFACTOR → REPEAT サイクルでコード品質を向上させる","ko":"TDD 테스트 주도 개발은 테스트를 먼저 작성하고 코드를 구현하는 개발 방식으로 RED → GREEN → REFACTOR → REPEAT 사이클을 통해 코드 품질을 향상합니다","es":"TDD es un enfoque de desarrollo que prioriza la escritura de tests antes de implementar el código, mejorando la calidad y reduciendo errores","fr":"TDD est une approche de développement qui donne la priorité à l''écriture de tests avant de mettre en œuvre le code, améliorant la qualité et réduisant les erreurs","de":"TDD ist ein Entwicklungsansatz, der die Erstellung von Tests vor der Implementierung des Codes priorisiert, um die Qualität zu verbessern und Fehler zu reduzieren","pt":"TDD é uma abordagem de desenvolvimento que prioriza a escrita de testes antes da implementação do código, garantindo uma base sólida para o desenvolvimento de software.","ru":"TDD — это подход к разработке, который отдает приоритет написанию тестов перед реализацией кода, обеспечивая прочную основу для разработки программного обеспечения.","ar":"توجيه التطوير القائم على الاختبار هو نهج في البرمجة يعتمد على كتابة الاختبارات قبل كتابة الكود، مما يضمن أساسا متينا لتطوير البرمجيات."},"seo":{"title":{"en":"TDD: Test-Driven Development Setup Guide | AI Agent Skill","zh":"TDD 测试驱动开发 Setup Guide","ja":"TDD テスト駆動開発 Best Practices","ko":"TDD 테스트 주도 개발 가이드","es":"Guía de configuración de TDD para desarrollo de software","fr":"Guide de mise en place de TDD pour les développeurs","de":"TDD-Setup-Anleitung für Entwickler: Testgetriebene Entwic...","pt":"Guia de Configuração TDD para Desenvolvedores","ru":"Настройка TDD для Разработчиков: Лучшие Практики","ar":"إعداد توجيه التطوير القائم على الاختبار للبرمجين"},"description":{"en":"Learn how to implement TDD with our step-by-step guide. Discover how to write tests first and improve your code quality with this AI agent skill.","zh":"了解 TDD 测试驱动开发的优势和实施步骤，提高代码质量和开发效率","ja":"TDD テスト駆動開発のメリットと実装方法を学び、コード品質と開発効率を向上させます","ko":"TDD 테스트 주도 개발의 이점과 적용 방법을 알아보고 코드 품질과 개발 효율을 높여보세요","es":"Aprende a implementar TDD en tu proceso de desarrollo con nuestra guía paso a paso, incluyendo RED, GREEN, REFACTOR y REPEAT","fr":"Découvrez comment mettre en place TDD dans votre processus de développement avec notre guide étape par étape, incluant RED, GREEN, REFACTOR et REPEAT","de":"Erfahren Sie, wie Sie TDD in Ihren Entwicklungsprozess integrieren können, mit unserer Schritt-für-Schritt-Anleitung, einschließlich RED, GREEN, REFACTOR und...","pt":"Aprenda a implementar TDD no seu fluxo de trabalho com nossa guia passo a passo, incluindo ciclo de teste e refatoração","ru":"Узнайте, как внедрить TDD в ваш рабочий процесс с помощью нашей пошаговой инструкции, включая цикл тестирования и рефакторинга","ar":"تعلم كيفية تطبيق توجيه التطوير القائم على الاختبار في عملك بسهولة مع دليلنا خطوة بخطوة، بما في ذلك دورة الاختبار وإعادة هيكلة الكود"},"definition":{"en":"TDD is a software development process that involves writing automated tests before writing the actual code, following a cycle of RED, GREEN, REFACTOR, and REPEAT.","zh":"TDD 测试驱动开发是一种开发方法，通过先写测试然后编写代码来提高代码质量","ja":"TDD テスト駆動開発は、テストを先に書いてからコードを実装する開発手法","ko":"TDD 테스트 주도 개발은 테스트를 먼저 작성하고 코드를 구현하는 개발 방식","es":"TDD significa Test-Driven Development, un enfoque que combina tests y código para mejorar la calidad del software","fr":"TDD signifie Test-Driven Development, une approche qui combine tests et code pour améliorer la qualité du logiciel","de":"TDD bedeutet Testgetriebene Entwicklung, ein Ansatz, der Tests und Code kombiniert, um die Qualität der Software zu verbessern","pt":"TDD significa Test-Driven Development, uma técnica de desenvolvimento de software que envolve a escrita de testes antes da codificação.","ru":"TDD означает Test-Driven Development, техника разработки программного обеспечения, включающая написание тестов перед кодированием.","ar":"توجيه التطوير القائم على الاختبار يعني تطوير البرمجيات القائم على الاختبارات، وهي تقنية في تطوير البرمجيات تتضمن كتابة الاختبارات قبل كتابة الكود."},"features":{"en":["Follows the TDD cycle: RED → GREEN → REFACTOR → REPEAT","Supports test writing for normal cases, edge cases, and error cases","Uses npm test command to execute tests, e.g., npm test -- path/to/file.test.ts","Enables minimal implementation to pass tests, followed by refactoring","Defines interfaces and functions using type signatures and scaffolding"],"zh":["RED → GREEN → REFACTOR → REPEAT 循环","接口定义（SCAFFOLD）","测试编写（RED）","最小实现（GREEN）","代码重构（REFACTOR）"],"ja":["RED → GREEN → REFACTOR → REPEAT サイクル","インターフェース定義（SCAFFOLD）","テスト作成（RED）","最小実装（GREEN）","コードリファクタリング（REFACTOR）"],"ko":["RED → GREEN → REFACTOR → REPEAT 사이클","인터페이스 정의（SCAFFOLD）","테스트 작성（RED）","최소 구현（GREEN）","리팩토링（REFACTOR）"],"es":["Ciclo de TDD: RED, GREEN, REFACTOR y REPEAT","Definición de interfaz con tipos e interfaces","Escritura de tests para casos normales y de borde","Implementación mínima para pasar tests","Refactorización de código para mejorar la calidad"],"fr":["Cycle de TDD : RED, GREEN, REFACTOR et REPEAT","Définition d''interface avec des types et des interfaces","Écriture de tests pour les cas normaux et de bord","Mise en œuvre minimale pour passer les tests","Refactoring de code pour améliorer la qualité"],"de":["TDD-Zyklus: RED, GREEN, REFACTOR und REPEAT","Schnittstellen-Definition mit Typen und Schnittstellen","Test-Erstellung für normale und Randfälle","Minimale Implementierung zum Bestehen von Tests","Code-Refactoring zur Qualitätsverbesserung"],"pt":["Ciclo de TDD: RED → GREEN → REFACTOR → REPEAT","Definição de interface e tipos antes da implementação","Escrita de testes para casos normais, de bordo e de erro","Execução de testes e verificação de falhas","Implementação mínima para passar nos testes","Refatoração do código para melhorar a legibilidade e manutenção"],"ru":["Цикл TDD: RED → GREEN → REFACTOR → REPEAT","Определение интерфейса и типов перед реализацией","Написание тестов для нормальных, граничных и ошибочных случаев","Выполнение тестов и проверка сбоев","Минимальная реализация для прохождения тестов","Рефакторинг кода для улучшения читаемости и поддержки"],"ar":["دورة توجيه التطوير القائم على الاختبار: RED → GREEN → REFACTOR → REPEAT","تحديد الواجهة والأنواع قبل التنفيذ","كتابة الاختبارات للحالات العادية وحالات الحافة والأخطاء","تشغيل الاختبارات والتحقق من الفشل","تنفيذ мінімي للنجاح في الاختبارات","إعادة هيكلة الكود لتحسين القراءة والصيانة"]},"keywords":{"en":["what is tdd","how to use tdd","tdd vs bdd","tdd setup guide","tdd install","test-driven development tutorial","tdd best practices","tdd alternative"],"zh":["TDD 测试驱动开发","AIエージェント","测试驱动开发方法","代码质量提高","开发效率提高","RED → GREEN → REFACTOR → REPEAT","接口定义","测试编写","最小实现","代码重构"],"ja":["TDD テスト駆動開発","AIエージェント","テスト駆動開発方法","コード品質向上","開発効率向上","RED → GREEN → REFACTOR → REPEAT","インターフェース定義","テスト作成","最小実装","コードリファクタリング"],"ko":["TDD 테스트 주도 개발","AI 에이전트","테스트 주도 개발 방법","코드 품질 향상","개발 효율 향상","RED → GREEN → REFACTOR → REPEAT","인터페이스 정의","테스트 작성","최소 구현","리팩토링"],"es":["TDD","desarrollo de software","tests unitarios","ciclo de TDD","refactorización de código","mejora de la calidad del software","herramientas de desarrollo","pruebas de software"],"fr":["TDD","développement de logiciels","tests unitaires","cycle de TDD","refactoring de code","amélioration de la qualité du logiciel","outils de développement","tests de logiciels"],"de":["TDD","Software-Entwicklung","Einheitstests","TDD-Zyklus","Code-Refactoring","Qualitätsverbesserung der Software","Entwicklertools","Software-Tests"],"pt":["TDD","Test-Driven Development","Desenvolvimento de software","Escrita de testes","Ciclo de TDD","Refatoração de código","Desenvolvimento ágil","Melhorias de código","Práticas de desenvolvimento de software"],"ru":["TDD","Test-Driven Development","Разработка программного обеспечения","Написание тестов","Цикл TDD","Рефакторинг кода","Гибкая разработка","Улучшение кода","Практики разработки программного обеспечения"],"ar":["توجيه التطوير القائم على الاختبار","تطوير البرمجيات","كتابة الاختبارات","دورة توجيه التطوير القائم على الاختبار","إعادة هيكلة الكود","تطوير البرمجيات المتنقل","تحسين الكود","مبادئ توجيه التطوير القائم على الاختبار","أدوات توجيه التطوير القائم على الاختبار"]}},"owner":"jh941213","repo":"my-claude-code-asset","repoPath":"jh941213/my-claude-code-asset","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"tdd","description":"테스트 주도 개발 - 테스트 먼저 작성 후 구현. TDD, 테스트 먼저, 테스트 주도 키워드에 활성화.","bodyPreview":"# TDD (테스트 주도 개발)\n\n테스트를 먼저 작성하고, 코드를 구현하는 TDD 방식을 적용합니다.\n\n## TDD 사이클\n\n```\nRED → GREEN → REFACTOR → REPEAT\n\nRED:      실패하는 테스트 작성\nGREEN:    테스트 통과하는 최소 코드 작성\nREFACTOR: 코드 개선 (테스트 유지)\nREPEAT:   다음 기능/시나리오\n```\n\n## 진행 순서\n\n1. **인터페이스 정의** (SCAFFOLD)\n   - 타입/인터페이스 먼저 정의\n   - 함수 시그니처 작성\n\n2. **테스트 작성** (RED)\n   - 정상 케이스\n   - 엣지 케이스 (빈 값, null, 최대값)\n   - 에러 케이스\n\n3. **테스트 실행 - 실패 확인**\n   ```bash\n   npm test -- path/to/file.test.ts\n   ```\n\n4. **최소 구현** (GREEN)\n   - 테스트만 통과하는 최소한의 코드\n\n5. **리팩토링** (REFACTOR)","body":"# TDD (테스트 주도 개발)\n\n테스트를 먼저 작성하고, 코드를 구현하는 TDD 방식을 적용합니다.\n\n## TDD 사이클\n\n```\nRED → GREEN → REFACTOR → REPEAT\n\nRED:      실패하는 테스트 작성\nGREEN:    테스트 통과하는 최소 코드 작성\nREFACTOR: 코드 개선 (테스트 유지)\nREPEAT:   다음 기능/시나리오\n```\n\n## 진행 순서\n\n1. **인터페이스 정의** (SCAFFOLD)\n   - 타입/인터페이스 먼저 정의\n   - 함수 시그니처 작성\n\n2. **테스트 작성** (RED)\n   - 정상 케이스\n   - 엣지 케이스 (빈 값, null, 최대값)\n   - 에러 케이스\n\n3. **테스트 실행 - 실패 확인**\n   ```bash\n   npm test -- path/to/file.test.ts\n   ```\n\n4. **최소 구현** (GREEN)\n   - 테스트만 통과하는 최소한의 코드\n\n5. **리팩토링** (REFACTOR)\n   - 테스트 유지하며 코드 개선\n\n6. **커버리지 확인**\n   ```bash\n   npm test -- --coverage\n   ```\n   - 목표: 80% 이상\n\n## 주의사항\n\n- 테스트를 먼저 작성 (구현 전에!)\n- 한 번에 하나의 테스트만 작성\n- 테스트가 실패하는지 반드시 확인\n- 최소한의 코드만 작성\n"},"lastSynced":"2026-03-08T02:00:11.925Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Development Agents needing robust test-driven development capabilities.","zh":"适合需要强大的测试驱动开发能力的代码开发代理。","ja":"コード開発エージェントが堅牢なテスト駆動開発機能を必要とする場合に適しています。","ko":"코드 개발 에이전트가 강력한 테스트 주도 개발 기능을 필요로 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Desarrollo de Código que necesitan capacidades de desarrollo dirigido por pruebas robustas.","fr":"Parfait pour les agents de développement de code nécessitant des capacités de développement piloté par les tests robustes.","de":"Perfekt für Code-Entwicklungsagenten, die robuste testgetriebene Entwicklungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Código que necessitam de capacidades de desenvolvimento dirigido por testes robustas.","ru":"Идеально подходит для агентов разработки кода, требующих надежных возможностей разработки, управляемой тестированием.","ar":"مثالي لعميل تطوير الشفرة الذي يحتاج إلى قدرات تطوير قوي مدفوع بالاختبار."},"recommendation":{"en":"Empowers agents to write reliable code using the TDD cycle, including RED, GREEN, and REFACTOR stages, with support for interface definition, test writing, and code refactoring, utilizing npm test and TypeScript.","zh":"赋予代理使用 TDD 周期编写可靠代码的能力，包括 RED、GREEN 和 REFACTOR 阶段，支持接口定义、测试编写和代码重构，利用 npm test 和 TypeScript。","ja":"エージェントが TDD サイクルを使用して信頼性の高いコードを記述できるようにし、RED、GREEN、REFACTOR ステージを含み、インターフェイス定義、テストの記述、コードのリファクタリングをサポートし、npm test と TypeScript を利用します。","ko":"에이전트가 TDD 주기를 사용하여 안정적인 코드를 작성할 수 있도록 하며, RED, GREEN, REFACTOR 단계를 포함하고 인터페이스 정의, 테스트 작성, 코드 리팩토링을 지원하며 npm test와 TypeScript를 활용합니다.","es":"Habilita a los agentes a escribir código confiable utilizando el ciclo TDD, incluidas las etapas RED, GREEN y REFACTOR, con soporte para la definición de interfaz, la escritura de pruebas y la refactorización de código, utilizando npm test y TypeScript.","fr":"Permet aux agents d''écrire du code fiable en utilisant le cycle TDD, y compris les étapes RED, GREEN et REFACTOR, avec une prise en charge de la définition d''interface, de l''écriture de tests et de la refactoring de code, en utilisant npm test et TypeScript.","de":"Ermöglicht es Agenten, zuverlässigen Code mit dem TDD-Zyklus zu schreiben, einschließlich der Stufen RED, GREEN und REFACTOR, mit Unterstützung für Schnittstellendefinition, Testschreiben und Code-Refactoring, unter Verwendung von npm test und TypeScript.","pt":"Habilita os agentes a escreverem código confiável usando o ciclo TDD, incluindo as etapas RED, GREEN e REFACTOR, com suporte para definição de interface, escrita de testes e refatoração de código, utilizando npm test e TypeScript.","ru":"Наделяет агентов возможностью писать надежный код, используя цикл TDD, включая стадии RED, GREEN и REFACTOR, с поддержкой определения интерфейса, написания тестов и рефакторинга кода, используя npm test и TypeScript.","ar":"تمكّن الوكيل من كتابة شفرة موثوقة باستخدام دورة TDD، بما في ذلك مراحل RED و GREEN و REFACTOR، مع دعم تعريف الواجهة وكتابة الاختبارات وإعادة هيكلة الشفرة، باستخدام npm test وTypeScript."},"useCases":{"en":["Automating unit testing for complex functions","Generating test cases for edge scenarios","Refactoring existing codebases for improved maintainability"],"zh":["自动化复杂函数的单元测试","为边缘场景生成测试用例","重构现有代码库以提高可维护性"],"ja":["複雑な関数の単体テストを自動化する","エッジシナリオのテストケースを生成する","既存のコードベースをリファクタリングして保守性を向上させる"],"ko":["복잡한 함수의 유닛 테스트를 자동화하는 것","엣지 시나리오의 테스트 케이스를 생성하는 것","기존 코드베이스를 리팩토링하여 유지 보수성을 향상시키는 것"],"es":["Automatización de pruebas unitarias para funciones complejas","Generación de casos de prueba para escenarios de borde","Reestructuración de bases de código existentes para una mejor mantenibilidad"],"fr":["Automatisation des tests unitaires pour des fonctions complexes","Génération de cas de test pour des scénarios de bord","Réorganisation de bases de code existantes pour une meilleure maintenabilité"],"de":["Automatisierung von Einheitstests für komplexe Funktionen","Generierung von Testfällen für Randfallszenarien","Umstrukturierung von bestehenden Codebasen für eine verbesserte Wartbarkeit"],"pt":["Automatizar testes unitários para funções complexas","Gerar casos de teste para cenários de bordo","Refatorar bases de código existentes para melhor manutenibilidade"],"ru":["Автоматизировать модульное тестирование для сложных функций","Генерировать тестовые случаи для граничных сценариев","Рефакторить существующие кодовые базы для улучшения поддерживаемости"],"ar":["تحسين الاختبارات الوحدوية للوظائف المعقدة","توليد حالات اختبار للسيناريوهات الحدية","إعادة هيكلة قواعد الشفرة الحالية لتحسين الصيانة"]},"limitations":{"en":["Requires npm and TypeScript setup","Limited to test-driven development workflow"],"zh":["需要 npm 和 TypeScript 设置","仅限于测试驱动开发工作流"],"ja":["npm と TypeScript の設定が必要","テスト駆動開発ワークフローに限定される"],"ko":["npm과 TypeScript 설정이 필요","테스트 주도 개발 워크플로에만 제한됨"],"es":["Requiere configuración de npm y TypeScript","Limitado al flujo de trabajo de desarrollo dirigido por pruebas"],"fr":["Nécessite une configuration npm et TypeScript","Limité au flux de travail de développement piloté par les tests"],"de":["Benötigt npm- und TypeScript-Setup","Begrenzt auf den Workflow des testgetriebenen Entwicklungsprozesses"],"pt":["Exige configuração do npm e TypeScript","Limitado ao fluxo de trabalho de desenvolvimento dirigido por testes"],"ru":["Требует настройки npm и TypeScript","Ограничен рабочим процессом разработки, управляемой тестированием"],"ar":["يتطلب إعداد npm وTypeScript","محدود بتدفق عمل تطوير مدفوع بالاختبار"]},"version":4},"contentHash":"7b3706e134b9ae5d6a2050c57a4f11fa280702d12f0ecb5d19c36de497816964","qualityScore":30}');
