INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jh941213/my-claude-code-asset/tdd', 'tdd', 'jh941213', 'my-claude-code-asset', 'community', 'tdd jh941213 my-claude-code-asset community The TDD skill enables developers to apply test-driven development principles, writing tests before implementing code. This skill benefits developers who want to improve code quality and reliability. TDD 测试驱动开发是一种先写测试然后编写代码的开发方法，通过 RED → GREEN → REFACTOR → REPEAT 循环提高代码质量 TDD テスト駆動開発は、テストを先に書いてからコードを実装する開発手法で、RED → GREEN → REFACTOR → REPEAT サイクルでコード品質を向上させる TDD 테스트 주도 개발은 테스트를 먼저 작성하고 코드를 구현하는 개발 방식으로 RED → GREEN → REFACTOR → REPEAT 사이클을 통해 코드 품질을 향상합니다 TDD es un enfoque de desarrollo que prioriza la escritura de tests antes de implementar el código, mejorando la calidad y reduciendo errores TDD est une approche de développement qui donne la priorité à l''écriture de tests avant de mettre en œuvre le code, améliorant la qualité et réduisant les erreurs TDD ist ein Entwicklungsansatz, der die Erstellung von Tests vor der Implementierung des Codes priorisiert, um die Qualität zu verbessern und Fehler zu reduzieren TDD é uma abordagem de desenvolvimento que prioriza a escrita de testes antes da implementação do código, garantindo uma base sólida para o desenvolvimento de software. TDD — это подход к разработке, который отдает приоритет написанию тестов перед реализацией кода, обеспечивая прочную основу для разработки программного обеспечения. توجيه التطوير القائم على الاختبار هو نهج في البرمجة يعتمد على كتابة الاختبارات قبل كتابة الكود، مما يضمن أساسا متينا لتطوير البرمجيات. what is tdd how to use tdd tdd vs bdd tdd setup guide tdd install test-driven development tutorial tdd best practices tdd alternative TDD 测试驱动开发 AIエージェント 测试驱动开发方法 代码质量提高 开发效率提高 RED → GREEN → REFACTOR → REPEAT 接口定义 测试编写 最小实现 代码重构 Follows the TDD cycle: RED → GREEN → REFACTOR → REPEAT Supports test writing for normal cases, edge cases, and error cases Uses npm test command to execute tests, e.g., npm test -- path/to/file.test.ts Enables minimal implementation to pass tests, followed by refactoring Defines interfaces and functions using type signatures and scaffolding TDD is a software development process that involves writing automated tests before writing the actual code, following a cycle of RED, GREEN, REFACTOR, and REPEAT.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EdgarPost/claude-code/nix-patterns', 'community', 'EdgarPost', 'claude-code', 'EdgarPost/claude-code', 'nix-patterns', 0, 0, 30, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:29.089Z', '371413907f18fb9774b3f1d6024be2aecc2147c52a6be5038e6c2803e35b9534', '{"id":"EdgarPost/claude-code/nix-patterns","name":"nix-patterns","description":{"en":"The nix-patterns skill provides a structured approach to configuring NixOS modules, benefiting developers and system administrators. It offers a standardized directory structure and package management.","zh":"Nix Patterns 提供了 NixOS 和 Home-manager 的配置模板，包括目录结构和包管理","ja":"Nix パターンは NixOS と Home-manager の設定テンプレートを提供し、ディレクトリ構造とパッケージ管理を含む","ko":"Nix 패턴은 NixOS 및 Home-manager 설정 템플릿을 제공하며 디렉토리 구조 및 패키지 관리를 포함합니다","es":"Nix-patterns es un conjunto de patrones de diseño para NixOS y Home-manager que simplifican la configuración y el desarrollo de aplicaciones","fr":"Nix-patterns est un ensemble de modèles de conception pour NixOS et Home-manager qui simplifient la configuration et le développement d''applications","de":"Nix-patterns ist eine Sammlung von Entwurfsmustern für NixOS und Home-manager, die die Konfiguration und Entwicklung von Anwendungen vereinfachen","pt":"Nix-Patterns é um conjunto de módulos para NixOS que facilita a configuração de ambientes de desenvolvimento personalizados","ru":"Nix-Patterns - это набор модулей для NixOS, упрощающий настройку индивидуальных сред разработки","ar":"Nix-Patterns هو مجموعة من الوحدات لموقع NixOS التي تسهل إعداد بيئات تطوير مخصصة"},"seo":{"title":{"en":"nix-patterns: NixOS Module Configuration Setup Guide | AI...","zh":"Nix Patterns 配置指南","ja":"Nix パターン設定ガイド - AIエージェント","ko":"Nix 패턴 설정 가이드 - AI Tools","es":"Guía de configuración de nix-patterns para desarrolladores","fr":"Guide de configuration de nix-patterns pour les développeurs","de":"Einrichtungsleitfaden für nix-patterns-Entwickler","pt":"Guia de Configuração Nix-Patterns para Desenvolvedores","ru":"ИИ Агенты: Настройка Nix-Patterns для Разработчиков","ar":"دليل تبحث Nix-Patterns لإعداد البيئة التطويرية"},"description":{"en":"Discover how to master NixOS module patterns with our expert guide. Learn to configure home-manager and system services with ease.","zh":"了解 Nix Patterns 的目录结构和配置方法，优化您的 NixOS 和 Home-manager 设置","ja":"Nix パターンのディレクトリ構造と設定方法を学び、NixOS と Home-manager の設定を最適化する","ko":"Nix 패턴의 디렉토리 구조와 설정 방법을 배우고 NixOS 및 Home-manager 설정을 최적화 하세요","es":"Aprende a configurar y utilizar nix-patterns para simplificar tu flujo de trabajo de desarrollo con NixOS y Home-manager","fr":"Découvrez comment configurer et utiliser nix-patterns pour simplifier votre flux de travail de développement avec NixOS et Home-manager","de":"Erfahren Sie, wie Sie nix-patterns konfigurieren und verwenden, um Ihren Entwicklungsprozess mit NixOS und Home-manager zu vereinfachen","pt":"Aprenda a configurar o Nix-Patterns para melhorar a produtividade dos desenvolvedores com módulos personalizados e gerenciamento de pacotes","ru":"Узнайте, как настроить Nix-Patterns для повышения производительности разработчиков с помощью индивидуальных модулей и управления пакетами","ar":"تعلم كيفية إعداد Nix-Patterns لتحسين إنتاجية المطورين باستخدام الوحدات المخصصة وإدارة الحزم"},"definition":{"en":"nix-patterns is a set of guidelines for organizing and configuring NixOS modules, including home-manager and system services, using a specific directory structure and package management syntax.","zh":"Nix Patterns 是一种 NixOS 和 Home-manager 的配置模板","ja":"Nix パターンは NixOS と Home-manager の設定テンプレートの一種","ko":"Nix 패턴은 NixOS 및 Home-manager 설정 템플릿의 일종입니다","es":"Nix-patterns es un conjunto de patrones de diseño para la configuración de NixOS y Home-manager","fr":"Nix-patterns est un ensemble de modèles de conception pour la configuration de NixOS et Home-manager","de":"Nix-patterns ist eine Sammlung von Entwurfsmustern für die Konfiguration von NixOS und Home-manager","pt":"Nix-Patterns é um conjunto de padrões de configuração para NixOS","ru":"Nix-Patterns - это набор шаблонов конфигурации для NixOS","ar":"Nix-Patterns هو مجموعة من أنماط التكوين لموقع NixOS"},"features":{"en":["Standardized directory structure using `modules/home` directories","Package management using `home.packages` and `lib.optionals`","Creation of custom modules using `{ pkgs, ... }: { ... }` syntax","Integration with home-manager for user packages and dotfiles","Conditional package installation based on `stdenv.hostPlatform.system`"],"zh":["支持 NixOS 和 Home-manager 配置","提供目录结构模板（modules/home）","提供主 Home-manager 入口点（home/default.nix）"],"ja":["NixOS と Home-manager の設定をサポート","ディレクトリ構造テンプレートを提供（modules/home）","メイン Home-manager エントリーポイントを提供（home/default.nix）"],"ko":["NixOS 및 Home-manager 설정을 지원","디렉토리 구조 템플릿을 제공（modules/home）","메인 Home-manager 엔트리 포인트를 제공（home/default.nix）"],"es":["Estructura de directorios personalizable para Home-manager y NixOS","Compatibilidad con paquetes de software personalizados","Soporte para configuraciones específicas de máquina","Integración con lib.optionals para condiciones de plataforma","Creación de módulos personalizados para NixOS y Home-manager"],"fr":["Structure de répertoire personnalisable pour Home-manager et NixOS","Compatibilité avec des paquets de logiciels personnalisés","Prise en charge de configurations spécifiques à la machine","Intégration avec lib.optionals pour les conditions de plate-forme","Création de modules personnalisés pour NixOS et Home-manager"],"de":["Anpassbare Verzeichnisstruktur für Home-manager und NixOS","Unterstützung für benutzerdefinierte Software-Pakete","Unterstützung für maschinenspezifische Konfigurationen","Integration mit lib.optionals für Plattformbedingungen","Erstellung benutzerdefinierter Module für NixOS und Home-manager"],"pt":["Módulos personalizados para NixOS","Gerenciamento de pacotes com Nix","Configuração de ambientes de desenvolvimento personalizados","Suporte a múltiplas plataformas","Integração com Home-manager"],"ru":["Индивидуальные модули для NixOS","Управление пакетами с помощью Nix","Настройка индивидуальных сред разработки","Поддержка нескольких платформ","Интеграция с Home-manager"],"ar":["وحدات مخصصة لموقع NixOS","إدارة الحزم باستخدام Nix","إعداد بيئات تطوير مخصصة","دعم منصات متعددة","التكامل مع Home-manager"]},"keywords":{"en":["nix-patterns setup guide","NixOS module configuration","home-manager setup","nix-patterns vs nixos-config","how to use nix-patterns","nix-patterns install","nix-patterns alternative","nixos-config vs home-manager","nix-patterns tutorial","nix-patterns documentation"],"zh":["Nix Patterns","NixOS","Home-manager","配置模板","目录结构","包管理","机器特定配置","AI 工具","开发工具"],"ja":["Nix パターン","NixOS","Home-manager","設定テンプレート","ディレクトリ構造","パッケージ管理","マシン固有の設定","AIエージェント","開発ツール"],"ko":["Nix 패턴","NixOS","Home-manager","설정 템플릿","디렉토리 구조","패키지 관리","기계 고유의 설정","AI 툴","개발 도구"],"es":["nix-patterns","NixOS","Home-manager","configuración de desarrollo","patrones de diseño","desarrollo de aplicaciones","herramientas de desarrollo","IA herramientas","Agentes de IA"],"fr":["nix-patterns","NixOS","Home-manager","configuration de développement","modèles de conception","développement d''applications","outils de développement","Outils d''IA","Agents d''IA"],"de":["nix-patterns","NixOS","Home-manager","EntwicklungsKonfiguration","Entwurfsmuster","Anwendungs-Entwicklung","Entwicklungstools","KI-Tools","KI-Agenten"],"pt":["nix patterns","nixos configuração","desenvolvimento de software","gerenciamento de pacotes","ambientes de desenvolvimento personalizados","home manager","nixos módulos"],"ru":["nix patterns","nixos настройка","разработка программного обеспечения","управление пакетами","индивидуальные среды разработки","home manager","nixos модули"],"ar":["نماذج نيكس","إعدادات نيكسوس","تطوير البرمجيات","إدارة الحزم","بيئات تطوير مخصصة","مدير المنزل","وحدات نيكسوس"]}},"owner":"EdgarPost","repo":"claude-code","repoPath":"EdgarPost/claude-code","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"nix-patterns","description":"NixOS module patterns. Use when creating or editing NixOS/home-manager modules, adding packages, or configuring programs.","bodyPreview":"# NixOS Module Patterns\n\n## Directory structure\n- `modules/home/*.nix` - Home-manager modules (user packages, dotfiles)\n- `modules/nixos/*.nix` - NixOS modules (system services)\n- `hosts/*/` - Machine-specific configuration\n- `home/default.nix` - Main home-manager entry point\n\n## Adding packages\n```nix\nhome.packages = with pkgs; [\n  package-name\n] ++ lib.optionals (stdenv.hostPlatform.system == \"x86_64-linux\") [\n  x86-only-package\n];\n```\n\n## Creating a module\n```nix\n{ pkgs, ... }:\n{\n  home.packa","body":"# NixOS Module Patterns\n\n## Directory structure\n- `modules/home/*.nix` - Home-manager modules (user packages, dotfiles)\n- `modules/nixos/*.nix` - NixOS modules (system services)\n- `hosts/*/` - Machine-specific configuration\n- `home/default.nix` - Main home-manager entry point\n\n## Adding packages\n```nix\nhome.packages = with pkgs; [\n  package-name\n] ++ lib.optionals (stdenv.hostPlatform.system == \"x86_64-linux\") [\n  x86-only-package\n];\n```\n\n## Creating a module\n```nix\n{ pkgs, ... }:\n{\n  home.packages = with pkgs; [ mypackage ];\n  xdg.configFile.\"app/config.json\".text = builtins.toJSON { setting = \"value\"; };\n}\n```\n\nImport in `home/default.nix`:\n```nix\nimports = [ ../modules/home/mymodule.nix ];\n```\n"},"lastSynced":"2026-03-08T02:00:29.089Z","agentAnalysis":{"suitability":{"en":"Perfect for System Administration Agents needing standardized NixOS configuration management.","zh":"非常适合需要标准化NixOS配置管理的系统管理代理。","ja":"NixOSの標準化された構成管理が必要なシステム管理エージェントに最適です。","ko":"표준화된 NixOS 구성 관리가 필요한 시스템 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de administración de sistemas que necesitan una gestión de configuración de NixOS estandarizada.","fr":"Parfait pour les agents d''administration système ayant besoin d''une gestion de configuration NixOS standardisée.","de":"Perfekt für Systemadministration-Agenten, die eine standardisierte NixOS-Konfigurationsverwaltung benötigen.","pt":"Perfeito para Agentes de Administração de Sistemas que necessitam de gerenciamento de configuração do NixOS padronizado.","ru":"Идеально подходит для агентов системного администрирования, требующих стандартизированного управления конфигурацией NixOS.","ar":"مثالي لعميل إدارة النظام الذي يحتاج إلى إدارة تكوين NixOS معيارية."},"recommendation":{"en":"Empowers agents to manage NixOS modules with a structured directory structure, standardized package management, and configuration options like home-manager modules and machine-specific configurations using Nix expressions.","zh":"赋予代理管理NixOS模块的能力，具有结构化的目录结构、标准化的包管理和配置选项，例如home-manager模块和使用Nix表达式的机器特定配置。","ja":"エージェントにNixOSモジュールを管理する機能を付与します。構造化されたディレクトリ構造、標準化されたパッケージ管理、およびhome-managerモジュールやNix式を使用したマシン固有の構成などの構成オプションがあります。","ko":"에이전트가 NixOS 모듈을 관리할 수 있도록 해주며, 구조화된 디렉토리 구조, 표준화된 패키지 관리 및 홈 매니저 모듈 및 Nix 식을 사용한 機器 특정 구성과 같은 구성 옵션이 있습니다.","es":"Habilita a los agentes a gestionar módulos de NixOS con una estructura de directorios estructurada, gestión de paquetes estandarizada y opciones de configuración como módulos de home-manager y configuraciones específicas de máquina utilizando expresiones Nix.","fr":"Permet aux agents de gérer les modules NixOS avec une structure de répertoire structurée, une gestion de paquets standardisée et des options de configuration comme les modules home-manager et les configurations spécifiques à la machine en utilisant des expressions Nix.","de":"Ermächtigt Agenten, NixOS-Module mit einer strukturierten Verzeichnisstruktur, standardisierter Paketverwaltung und Konfigurationsoptionen wie home-manager-Modulen und maschinenspezifischen Konfigurationen unter Verwendung von Nix-Ausdrücken zu verwalten.","pt":"Habilita os agentes a gerenciar módulos do NixOS com uma estrutura de diretório estruturada, gerenciamento de pacotes padronizado e opções de configuração como módulos home-manager e configurações específicas de máquina usando expressões Nix.","ru":"Наделяет агентов возможностью управлять модулями NixOS с помощью структурированной директорийной структуры, стандартизированного управления пакетами и опций конфигурации, таких как модули home-manager и конфигурации, специфичные для машины, с использованием выражений Nix.","ar":"يمنح العميل إمكانية إدارة مكونات NixOS بوسطة هيكل دلالي منظم، وإدارة حزم معيارية، وخيارات تكوين مثل الوحدات الإدارية للمنزل وتكوينات محددة للأجهزة باستخدام تعابير Nix."},"useCases":{"en":["Configuring NixOS modules for system services and user packages","Managing home-manager modules for dotfiles and user-specific configurations","Creating machine-specific configurations for hosts"],"zh":["为系统服务和用户包配置NixOS模块","管理home-manager模块以进行dotfiles和用户特定配置","为主机创建机器特定配置"],"ja":["システムサービスとユーザパッケージのためのNixOSモジュールの構成","ドットファイルとユーザー特定の構成のためのhome-managerモジュールの管理","ホストのためのマシン固有の構成の作成"],"ko":["시스템 서비스 및 사용자 패키지에 대한 NixOS 모듈 구성","홈 매니저 모듈을 사용한 도트 파일 및 사용자 특정 구성 관리","호스트를 위한 기계 특정 구성 생성"],"es":["Configuración de módulos de NixOS para servicios de sistema y paquetes de usuario","Gestión de módulos de home-manager para dotfiles y configuraciones específicas de usuario","Creación de configuraciones específicas de máquina para hosts"],"fr":["Configuration des modules NixOS pour les services système et les paquets utilisateur","Gestion des modules home-manager pour les dotfiles et les configurations spécifiques à l''utilisateur","Création de configurations spécifiques à la machine pour les hôtes"],"de":["Konfiguration von NixOS-Modulen für Systemdienste und Benutzeroberflächen-Pakete","Verwaltung von home-manager-Modulen für Benutzereinstellungen und benutzerspezifische Konfigurationen","Erstellung von maschinenspezifischen Konfigurationen für Hosts"],"pt":["Configurando módulos do NixOS para serviços de sistema e pacotes de usuário","Gerenciando módulos home-manager para arquivos de configuração e configurações específicas de usuário","Criando configurações específicas de máquina para hosts"],"ru":["Настройка модулей NixOS для системных служб и пакетов пользователя","Управление модулями home-manager для файлов конфигурации и конфигураций, специфичных для пользователя","Создание конфигураций, специфичных для машины, для хостов"],"ar":["تكوين مكونات NixOS لخدمات النظام وحزم المستخدم","إدارة وحدات إدارة المنزل لملفات التكوين وتكوينات محددة للمستخدم","إنشاء تكوينات محددة للأجهزة للمضيفين"]},"limitations":{"en":["Requires NixOS environment","Limited to Nix expression syntax","Dependent on Nix package manager"],"zh":["需要NixOS环境","仅限Nix表达式语法","依赖于Nix包管理器"],"ja":["NixOS環境が必要","Nix式の構文に限定される","Nixパッケージマネージャーに依存する"],"ko":["NixOS 환경이 필요함","Nix 식 문법으로 제한됨","Nix 패키지 관리자에 의존"],"es":["Requiere entorno de NixOS","Limitado a la sintaxis de expresiones Nix","Dependiente del administrador de paquetes Nix"],"fr":["Nécessite un environnement NixOS","Limité à la syntaxe d''expressions Nix","Dépendant du gestionnaire de paquets Nix"],"de":["Benötigt NixOS-Umgebung","Begrenzt auf Nix-Ausdruckssyntax","Abhängig vom Nix-Paketmanager"],"pt":["Requer ambiente do NixOS","Limitado à sintaxe de expressão Nix","Dependente do gerenciador de pacotes do Nix"],"ru":["Требует среды NixOS","Ограничен синтаксисом выражений Nix","Зависит от менеджера пакетов Nix"],"ar":["يتطلب بيئة NixOS","محدود بالتركيب النحوي لتعابير Nix","يعتمد على مدير الحزم Nix"]},"version":4},"contentHash":"371413907f18fb9774b3f1d6024be2aecc2147c52a6be5038e6c2803e35b9534","qualityScore":30}');
