INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EdgarPost/claude-code/nix-patterns', 'nix-patterns', 'EdgarPost', 'claude-code', 'community', 'nix-patterns EdgarPost claude-code community The nix-patterns skill provides a structured approach to configuring NixOS modules, benefiting developers and system administrators. It offers a standardized directory structure and package management. Nix Patterns 提供了 NixOS 和 Home-manager 的配置模板，包括目录结构和包管理 Nix パターンは NixOS と Home-manager の設定テンプレートを提供し、ディレクトリ構造とパッケージ管理を含む Nix 패턴은 NixOS 및 Home-manager 설정 템플릿을 제공하며 디렉토리 구조 및 패키지 관리를 포함합니다 Nix-patterns es un conjunto de patrones de diseño para NixOS y Home-manager que simplifican la configuración y el desarrollo de aplicaciones Nix-patterns est un ensemble de modèles de conception pour NixOS et Home-manager qui simplifient la configuration et le développement d''applications Nix-patterns ist eine Sammlung von Entwurfsmustern für NixOS und Home-manager, die die Konfiguration und Entwicklung von Anwendungen vereinfachen Nix-Patterns é um conjunto de módulos para NixOS que facilita a configuração de ambientes de desenvolvimento personalizados Nix-Patterns - это набор модулей для NixOS, упрощающий настройку индивидуальных сред разработки Nix-Patterns هو مجموعة من الوحدات لموقع NixOS التي تسهل إعداد بيئات تطوير مخصصة nix-patterns setup guide NixOS module configuration home-manager setup nix-patterns vs nixos-config how to use nix-patterns nix-patterns install nix-patterns alternative nixos-config vs home-manager nix-patterns tutorial nix-patterns documentation Nix Patterns NixOS Home-manager 配置模板 目录结构 包管理 机器特定配置 AI 工具 开发工具 Standardized directory structure using `modules/home` directories Package management using `home.packages` and `lib.optionals` Creation of custom modules using `{ pkgs, ... }: { ... }` syntax Integration with home-manager for user packages and dotfiles Conditional package installation based on `stdenv.hostPlatform.system` nix-patterns is a set of guidelines for organizing and configuring NixOS modules, including home-manager and system services, using a specific directory structure and package management syntax.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alinaqi/claude-bootstrap/react-native', 'community', 'alinaqi', 'claude-bootstrap', 'alinaqi/claude-bootstrap', 'react-native', 0, 0, 30, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:38.071Z', 'e08c94f85ed0dfda9f5223f8682b1ec4083d963089ed46a208b060999b49dedc', '{"id":"alinaqi/claude-bootstrap/react-native","name":"react-native","description":{"en":"The React Native skill provides opinionated project initialization for Claude Code, focusing on security-first and spec-driven development for AI-native applications. It benefits developers working with React Native and TypeScript.","zh":"React Native Skill 提供了安全、规格驱动的 AI 原生项目初始化，基于 TypeScript 和 React","ja":"React Native Skill は、TypeScript と React に基づいたセキュリティーと仕様に基づいた AI ネイティブプロジェクト初期化を提供","ko":"React Native Skill은 TypeScript 및 React 기반의 보안 및 규격 기반의 AI 네이티브 프로젝트 초기화를 제공합니다","es":"React Native es una skill de inicialización de proyectos opinada y segura, con una estructura de proyecto basada en TypeScript","fr":"React Native est une compétence d''initialisation de projet opinée et sécurisée, avec une structure de projet basée sur TypeScript","de":"React Native ist eine Meinungsführungs-Skill für die Initialisierung von Projekten, mit einer sicheren und TypeScript-basierten Projektstruktur","pt":"O React Native é uma ferramenta poderosa para desenvolver aplicativos móveis de IA. Aprenda a configurá-lo corretamente","ru":"React Native - мощный инструмент для разработки мобильных приложений ИИ. Узнайте, как его настроить","ar":"React Native هو أداة قوية لتطوير تطبيقات الهاتف المحمول الذكية. تعرف على كيفية إعدادها بشكل صحيح"},"seo":{"title":{"en":"React Native: Security-First Project Initialization for A...","zh":"React Native 项目初始化设置指南","ja":"React Native プロジェクト初期化のベストプラクティス","ko":"React Native 프로젝트 설정 가이드","es":"React Native: Guía de configuración para herramientas de IA","fr":"React Native: Guide de mise en place pour les outils d''IA","de":"React Native: Einrichtungsleitfaden für KI-Tools","pt":"Guia de Configuração do React Native para Ferramentas de IA","ru":"Настройка React Native для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد React Native للأدوات الذكية"},"description":{"en":"Discover how to set up a secure React Native project with AI-native capabilities. Learn more about spec-driven development and get started today!","zh":"使用 React Native Skill 实现安全、规格驱动的 AI 原生项目初始化，了解更多","ja":"React Native Skill を使用してセキュリティーと仕様に基づいた AI ネイティブプロジェクトを初期化","ko":"React Native Skill을 사용하여 보안 및 규격 기반의 AI 네이티브 프로젝트 초기화에 대해 알아보세요","es":"Aprende a configurar React Native para proyectos de IA con una estructura de proyecto segura y escalable","fr":"Découvrez comment configurer React Native pour les projets d''IA avec une structure de projet sécurisée et évolutivative","de":"Erfahren Sie, wie Sie React Native für KI-Projekte mit einer sicheren und skalierbaren Projektstruktur konfigurieren","pt":"Aprenda a configurar o React Native para projetos de IA com segurança e escalabilidade em mente","ru":"Узнайте, как настроить React Native для проектов ИИ с учетом безопасности и масштабируемости","ar":"تعرف على كيفية إعداد React Native لمشاريع الذكاء الاصطناعي مع التركيز على الأمان والتماسك"},"definition":{"en":"React Native is an opinionated project initialization skill for Claude Code, emphasizing security-first and spec-driven development with AI-native capabilities.","zh":"React Native Skill 是一种用于 React Native 项目初始化的工具，提供安全、规格驱动的 AI 原生功能","ja":"React Native Skill は、React Native プロジェクトの初期化に使用されるツールで、セキュリティーと仕様に基づいた AI ネイティブ機能を提供","ko":"React Native Skill은 React Native 프로젝트 초기화를 위한 도구로 보안 및 규격 기반의 AI 네이티브 기능을 제공합니다","es":"React Native es una herramienta de IA para la inicialización de proyectos móviles con una estructura de proyecto segura","fr":"React Native est un outil d''IA pour l''initialisation de projets mobiles avec une structure de projet sécurisée","de":"React Native ist ein KI-Tool für die Initialisierung von mobilen Projekten mit einer sicheren Projektstruktur","pt":"O que é React Native? Uma estrutura de desenvolvimento de aplicativos móveis de IA com foco em segurança e escalabilidade","ru":"Что такое React Native? Фреймворк для разработки мобильных приложений ИИ с учетом безопасности и масштабируемости","ar":"ما هو React Native؟ إطار عمل لتطوير تطبيقات الهاتف المحمول الذكية مع التركيز على الأمان والتماسك"},"features":{"en":["Generates project structure with separate core, components, and screens directories","Supports TypeScript for type safety and maintainability","Includes spec-driven development with tests (e.g., Button.test.tsx)","Provides barrel exports for easy component reuse (e.g., index.ts)","Organizes business logic in a pure core directory (no React dependencies)","Uses a services directory for encapsulating business logic"],"zh":["基于 TypeScript 的项目结构","安全、规格驱动的 AI 原生项目初始化","React 和 React Native 组件支持","Pure business logic 和 services 支持","可重用 UI 组件和屏幕组件"],"ja":["TypeScript に基づいたプロジェクト構造","セキュリティーと仕様に基づいた AI ネイティブプロジェクト初期化","React と React Native コンポーネントのサポート","Pure business logic と services のサポート","再利用可能な UI コンポーネントとスクリーンコンポーネント"],"ko":["TypeScript 기반 프로젝트 구조","보안 및 규격 기반의 AI 네이티브 프로젝트 초기화","React 및 React Native 컴포넌트 지원","Pure business logic 및 services 지원","재사용 가능한 UI 컴포넌트 및 스크린 컴포넌트"],"es":["Estructura de proyecto segura con TypeScript","Componentes reutilizables de UI","Pantallas de componentes personalizadas","Lógica de negocio pura sin React","Servicios y tipos personalizados"],"fr":["Structure de projet sécurisée avec TypeScript","Composants d''interface utilisateur réutilisables","Écrans de composants personnalisés","Logique métier pure sans React","Services et types personnalisés"],"de":["Sichere Projektstruktur mit TypeScript","Wiederverwendbare Benutzeroberflächenkomponenten","Benutzerdefinierte Bildschirmkomponenten","Reine Geschäftslogik ohne React","Benutzerdefinierte Dienste und Typen"],"pt":["Projeto de inicialização opinado para Claude Code","Estrutura de projeto com pastas para lógica de negócios, componentes e telas","Tipos e serviços definidos em arquivos TypeScript","Componentes reutilizáveis em pasta components","Telas em pasta screens com estrutura de barrel export"],"ru":["Проект инициализации с учетом безопасности и масштабируемости","Структура проекта с папками для бизнес-логики, компонентов и экранов","Типы и сервисы, определенные в файлах TypeScript","Переиспользуемые компоненты в папке components","Экраны в папке screens с структурой экспорта barrel"],"ar":["مشروع初ياز مع التركيز على الأمان والتماسك","هيئة المشروع مع مجلدات للlogic Επιχειρησιακή، مكونات و شاشات","الأنواع والخدمات المحددة في ملفات TypeScript","المكونات القابلة لإعادة الاستخدام في مجلد components","الشاشات في مجلد screens مع هيكل تصدير barrel"]},"keywords":{"en":["how to use react native","react native security best practices","react native alternative to flutter","react native install guide","what is react native","react native vs native ios development","react native setup for ai agents","react native typescript integration","react native project structure example"],"zh":["React Native 项目初始化","AI 原生项目","TypeScript 项目结构","React Native Skill","安全项目初始化","规格驱动项目初始化"],"ja":["React Native プロジェクト初期化","AI ネイティブプロジェクト","TypeScript プロジェクト構造","React Native Skill","セキュリティー プロジェクト初期化","仕様に基づいたプロジェクト初期化"],"ko":["React Native 프로젝트 초기화","AI 네이티브 프로젝트","TypeScript 프로젝트 구조","React Native Skill","보안 프로젝트 초기화","규격 기반 프로젝트 초기화"],"es":["react native","herramientas de ia","inicialización de proyectos","typescript","componentes de ui","pantallas de componentes","lógica de negocio","seguridad en proyectos","desarrollo móvil"],"fr":["react native","outils d''ia","initialisation de projets","typescript","composants d''interface utilisateur","écrans de composants","logique métier","sécurité dans les projets","développement mobile"],"de":["react native","ki-tools","projektinitialisierung","typescript","benutzeroberflächenkomponenten","bildschirmkomponenten","geschäftslogik","sicherheit in projekten","mobile entwicklung"],"pt":["react native","desenvolvimento de aplicativos móveis","ia","ferramentas de ia","segurança","escalabilidade","typescript","componentes reutilizáveis"],"ru":["react native","разработка мобильных приложений","ии","инструменты ии","безопасность","масштабируемость","typescript","переиспользуемые компоненты"],"ar":["react native","تطوير تطبيقات الهاتف المحمول","ذكاء اصطناعي","أدوات ذكاء اصطناعي","أمان","تماسك","typescript","مكونات قابلة لإعادة الاستخدام"]}},"owner":"alinaqi","repo":"claude-bootstrap","repoPath":"alinaqi/claude-bootstrap","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"react-native","description":"React Native mobile patterns, platform-specific code","bodyPreview":"# React Native Skill\n\n*Load with: base.md + typescript.md*\n\n---\n\n## Project Structure\n\n```\nproject/\n├── src/\n│   ├── core/                   # Pure business logic (no React)\n│   │   ├── types.ts\n│   │   └── services/\n│   ├── components/             # Reusable UI components\n│   │   ├── Button/\n│   │   │   ├── Button.tsx\n│   │   │   ├── Button.test.tsx\n│   │   │   └── index.ts\n│   │   └── index.ts            # Barrel export\n│   ├── screens/                # Screen components\n│   │   ├── Home/\n│","body":"# React Native Skill\n\n*Load with: base.md + typescript.md*\n\n---\n\n## Project Structure\n\n```\nproject/\n├── src/\n│   ├── core/                   # Pure business logic (no React)\n│   │   ├── types.ts\n│   │   └── services/\n│   ├── components/             # Reusable UI components\n│   │   ├── Button/\n│   │   │   ├── Button.tsx\n│   │   │   ├── Button.test.tsx\n│   │   │   └── index.ts\n│   │   └── index.ts            # Barrel export\n│   ├── screens/                # Screen components\n│   │   ├── Home/\n│   │   │   ├── HomeScreen.tsx\n│   │   │   ├── useHome.ts      # Screen-specific hook\n│   │   │   └── index.ts\n│   │   └── index.ts\n│   ├── navigation/             # Navigation configuration\n│   ├── hooks/                  # Shared custom hooks\n│   ├── store/                  # State management\n│   └── utils/                  # Utilities\n├── __tests__/\n├── android/\n├── ios/\n└── CLAUDE.md\n```\n\n---\n\n## Component Patterns\n\n### Functional Components Only\n```typescript\n// Good - simple, testable\ninterface ButtonProps {\n  label: string;\n  onPress: () => void;\n  disabled?: boolean;\n}\n\nexport function Button({ label, onPress, disabled = false }: ButtonProps): JSX.Element {\n  return (\n    <Pressable onPress={onPress} disabled={disabled}>\n      <Text>{label}</Text>\n    </Pressable>\n  );\n}\n```\n\n### Extract Logic to Hooks\n```typescript\n// useHome.ts - all logic here\nexport function useHome() {\n  const [items, setItems] = useState<Item[]>([]);\n  const [loading, setLoading] = useState(false);\n\n  const refresh = useCallback(async () => {\n    setLoading(true);\n    const data = await fetchItems();\n    setItems(data);\n    setLoading(false);\n  }, []);\n\n  return { items, loading, refresh };\n}\n\n// HomeScreen.tsx - pure presentation\nexport function HomeScreen(): JSX.Element {\n  const { items, loading, refresh } = useHome();\n  \n  return (\n    <ItemList items={items} loading={loading} onRefresh={refresh} />\n  );\n}\n```\n\n### Props Interface Always Explicit\n```typescript\n// Always define props interface, even if simple\ninterface ItemCardProps {\n  item: Item;\n  onPress: (id: string) => void;\n}\n\nexport function ItemCard({ item, onPress }: ItemCardProps): JSX.Element {\n  ...\n}\n```\n\n---\n\n## State Management\n\n### Local State First\n```typescript\n// Start with useState, escalate only when needed\nconst [value, setValue] = useState('''');\n```\n\n### Zustand for Global State (if needed)\n```typescript\n// store/useAppStore.ts\nimport { create } from ''zustand'';\n\ninterface AppState {\n  user: User | null;\n  setUser: (user: User | null) => void;\n}\n\nexport const useAppStore = create<AppState>((set) => ({\n  user: null,\n  setUser: (user) => set({ user }),\n}));\n```\n\n### React Query for Server State\n```typescript\n// hooks/useItems.ts\nimport { useQuery, useMutation, useQueryClient } from ''@tanstack/react-query'';\n\nexport function useItems() {\n  return useQuery({\n    queryKey: [''items''],\n    queryFn: fetchItems,\n  });\n}\n\nexport function useCreateItem() {\n  const queryClient = useQueryClient();\n  \n  return useMutation({\n    mutationFn: createItem,\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: [''items''] });\n    },\n  });\n}\n```\n\n---\n\n## Testing\n\n### Component Testing with React Native Testing Library\n```typescript\nimport { render, fireEvent } from ''@testing-library/react-native'';\nimport { Button } from ''./Button'';\n\ndescribe(''Button'', () => {\n  it(''calls onPress when pressed'', () => {\n    const onPress = jest.fn();\n    const { getByText } = render(<Button label=\"Click me\" onPress={onPress} />);\n    \n    fireEvent.press(getByText(''Click me''));\n    \n    expect(onPress).toHaveBeenCalledTimes(1);\n  });\n\n  it(''does not call onPress when disabled'', () => {\n    const onPress = jest.fn();\n    const { getByText } = render(<Button label=\"Click me\" onPress={onPress} disabled />);\n    \n    fireEvent.press(getByText(''Click me''));\n    \n    expect(onPress).not.toHaveBeenCalled();\n  });\n});\n```\n\n### Hook Testing\n```typescript\nimport { renderHook, act } from ''@testing-library/react-hooks'';\nimport { useCounter } from ''./useCounter'';\n\ndescribe(''useCounter'', () => {\n  it(''increments counter'', () => {\n    const { result } = renderHook(() => useCounter());\n    \n    act(() => {\n      result.current.increment();\n    });\n    \n    expect(result.current.count).toBe(1);\n  });\n});\n```\n\n---\n\n## Platform-Specific Code\n\n### Use Platform.select Sparingly\n```typescript\nimport { Platform } from ''react-native'';\n\nconst styles = StyleSheet.create({\n  shadow: Platform.select({\n    ios: {\n      shadowColor: ''#000'',\n      shadowOffset: { width: 0, height: 2 },\n      shadowOpacity: 0.1,\n    },\n    android: {\n      elevation: 2,\n    },\n  }),\n});\n```\n\n### Separate Files for Complex Differences\n```\nComponent/\n├── Component.tsx          # Shared logic\n├── Component.ios.tsx      # iOS-specific\n├── Component.android.tsx  # Android-specific\n└── index.ts\n```\n\n---\n\n## React Native Anti-Patterns\n\n- ❌ Inline styles - use StyleSheet.create\n- ❌ Logic in render - extract to hooks\n- ❌ Deep component nesting - flatten hierarchy\n- ❌ Anonymous functions in props - use useCallback\n- ❌ Index as key in lists - use stable IDs\n- ❌ Direct state mutation - always use setter\n- ❌ Mixing business logic with UI - keep core/ pure\n- ❌ Ignoring TypeScript errors - fix them\n- ❌ Large components - split into smaller pieces\n"},"lastSynced":"2026-03-08T02:00:38.071Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile Agents needing cross-platform app development with React Native and TypeScript","zh":"非常适合需要使用 React Native 和 TypeScript 进行跨平台应用开发的移动代理","ja":"React Native と TypeScript を使用したクロスプラットフォーム アプリケーション開発を必要とするモバイル エージェントに最適","ko":"React Native와 TypeScript를 사용한 크로스 플랫폼 애플리케이션 개발을 필요로 하는 모바일 에이전트에게 적합","es":"Perfecto para Agentes Móviles que necesitan desarrollo de aplicaciones multiplataforma con React Native y TypeScript","fr":"Parfait pour les Agents Mobiles ayant besoin de développement d''applications multiplateformes avec React Native et TypeScript","de":"Perfekt für Mobile Agenten, die eine cross-plattformübergreifende App-Entwicklung mit React Native und TypeScript benötigen","pt":"Perfeito para Agentes Móveis que necessitam de desenvolvimento de aplicativos cross-platform com React Native e TypeScript","ru":"Идеально для мобильных агентов, которым необходимо разработка кроссплатформенных приложений с помощью React Native и TypeScript","ar":"مثالي للوكلاء المحمولين الذين يحتاجون إلى تطوير تطبيقات متعددة المنصات مع React Native وTypeScript"},"recommendation":{"en":"Empowers agents to develop security-first and spec-driven AI-native applications using React Native, leveraging TypeScript for robust type checking and opinionated project initialization with Claude Code, facilitating the creation of scalable and maintainable mobile applications with features like Pure business logic separation and reusable UI components","zh":"赋予代理开发安全优先和规格驱动的 AI 原生应用程序的能力，使用 React Native，利用 TypeScript 进行强大的类型检查和经过 Claude Code 论证的项目初始化，促进可扩展和可维护的移动应用程序的创建，具有纯粹的业务逻辑分离和可重用的 UI 组件等特点","ja":"React Native を使用して、TypeScript を活用した堅牢な型チェックと Claude Code による意見を持ったプロジェクト初期化を提供し、純粋なビジネス ロジックの分離や再利用可能な UI コンポーネントなどの機能を備えた、拡張性と維持性に優れたモバイル アプリケーションの作成を促進する、セキュリティ優先の AI ネイティブ アプリケーションの開発をエージェントに可能にする","ko":"React Native를 사용하여 TypeScript를 활용한 강력한 타입 검사와 Claude Code를 통해 의견을持った 프로젝트 초기화를 제공하여,純粋한 비즈니스 로직 분리와 재사용 가능한 UI 컴포넌트 등의 기능을 갖춘 확장 가능하고 유지 보수 가능한 모바일 애플리케이션의 생성을促進하는, 보안 우선의 AI 네이티브 애플리케이션 개발을 에이전트에게 가능하게 함","es":"Habilita a los agentes a desarrollar aplicaciones nativas de IA con seguridad y especificaciones, utilizando React Native, aprovechando TypeScript para una comprobación de tipos robusta y una inicialización de proyectos con opiniones con Claude Code, facilitando la creación de aplicaciones móviles escalables y mantenibles con características como la separación lógica de negocios pura y componentes de IU reutilizables","fr":"Autonomise les agents pour développer des applications natives IA avec une sécurité et des spécifications de premier plan, en utilisant React Native, en exploitant TypeScript pour une vérification de types robuste et une initialisation de projet avisée avec Claude Code, facilitant la création d''applications mobiles évolutives et maintenables avec des fonctionnalités comme la séparation logique métier pure et des composants IU réutilisables","de":"Ermächtigt Agenten, Sicherheits- und spezifikationsgetriebene AI-native-Anwendungen mit React Native zu entwickeln, indem TypeScript für eine robuste Typüberprüfung und eine meinungsstarke Projekinitialisierung mit Claude Code genutzt wird, wodurch die Erstellung von skalierbaren und wartbaren mobilen Anwendungen mit Funktionen wie reiner Geschäftslogik-Trennung und wiederverwendbaren Benutzeroberflächenkomponenten erleichtert wird","pt":"Habilita os agentes a desenvolverem aplicações nativas de IA com segurança e especificações, utilizando React Native, aproveitando o TypeScript para verificação de tipo robusta e inicialização de projeto opinada com Claude Code, facilitando a criação de aplicações móveis escaláveis e mantenedoras com recursos como separação lógica de negócios pura e componentes de UI reutilizáveis","ru":"Наделяет агентов возможностью разрабатывать безопасные и спецификация-ориентированные приложения на основе ИИ, используя React Native, с использованием TypeScript для прочной проверки типов и инициализации проекта с помощью Claude Code, что облегчает создание масштабируемых и поддерживаемых мобильных приложений с функциями, такими как чистое разделение бизнес-логики и повторно используемые компоненты пользовательского интерфейса","ar":"يتمكّن الوكلاء من تطوير تطبيقات أصلية للذكاء الاصطناعي مع الأولوية للأمان والمواصفات باستخدام React Native، والاستفادة من TypeScript للتحقق من النوع بشكل قوي والتهيئة المحددة للمشروع مع Claude Code، مما يسهل إنشاء تطبيقات محمولة قابلة للتوسع والصيانة مع ميزات مثل فصل منطقي للأعمال والمركبات القابلة لإعادة الاستخدام"},"useCases":{"en":["Initializing secure React Native projects with TypeScript","Developing reusable UI components for cross-platform apps","Implementing spec-driven development for AI-native applications"],"zh":["使用 TypeScript 初始化安全的 React Native 项目","开发跨平台应用程序的可重用 UI 组件","实现规格驱动的 AI 原生应用程序开发"],"ja":["TypeScript を使用してセキュアな React Native プロジェクトを初期化する","クロスプラットフォーム アプリケーションの再利用可能な UI コンポーネントを開発する","規格駆動の AI ネイティブ アプリケーション開発を実現する"],"ko":["TypeScript를 사용하여 보안이 강화된 React Native 프로젝트를 초기화하는 것","크로스 플랫폼 애플리케이션을 위한 재사용 가능한 UI 컴포넌트를 개발하는 것","명세驱動의 AI 네이티브 애플리케이션 개발을 구현하는 것"],"es":["Inicialización de proyectos React Native seguros con TypeScript","Desarrollo de componentes de IU reutilizables para aplicaciones multiplataforma","Implementación de desarrollo dirigido por especificaciones para aplicaciones nativas de IA"],"fr":["Initialisation de projets React Native sécurisés avec TypeScript","Développement de composants IU réutilisables pour des applications multiplateformes","Mise en œuvre d''un développement piloté par des spécifications pour des applications natives IA"],"de":["Initialisierung sicherer React-Native-Projekte mit TypeScript","Entwicklung wiederverwendbarer Benutzeroberflächenkomponenten für cross-plattformübergreifende Apps","Implementierung spezifikationsgetriebener Entwicklung für AI-native-Anwendungen"],"pt":["Inicialização de projetos React Native seguros com TypeScript","Desenvolvimento de componentes de UI reutilizáveis para aplicativos cross-platform","Implementação de desenvolvimento orientado a especificações para aplicações nativas de IA"],"ru":["Инициализация безопасных проектов React Native с помощью TypeScript","Разработка повторно используемых компонентов пользовательского интерфейса для кроссплатформенных приложений","Реализация разработки, ориентированной на спецификации, для приложений на основе ИИ"],"ar":["تسهيل مشاريع React Native الآمنة مع TypeScript","تطوير مكونات واجهة المستخدم القابلة لإعادة الاستخدام لتطبيقات متعددة المنصات","تنفيذ تطوير موجه للمواصفات لتطبيقات الذكاء الاصطناعي الأصلية"]},"limitations":{"en":["Requires Claude Code integration","Focused on React Native and TypeScript","Security-first approach may add development complexity"],"zh":["需要 Claude Code 集成","专注于 React Native 和 TypeScript","安全优先的方法可能会增加开发复杂性"],"ja":["Claude Code の統合が必要","React Native と TypeScript に焦点を当てている","セキュリティ優先のアプローチにより開発の複雑性が増加する可能性がある"],"ko":["Claude Code 통합이 필요","React Native와 TypeScript에 중점을 두고 있음","보안 우선의 접근법으로 인해 개발 복잡성이 증가할 수 있음"],"es":["Requiere integración con Claude Code","Se centra en React Native y TypeScript","El enfoque de seguridad puede agregar complejidad al desarrollo"],"fr":["Nécessite une intégration avec Claude Code","Se concentre sur React Native et TypeScript","L''approche de sécurité peut ajouter de la complexité au développement"],"de":["Erfordert Claude-Code-Integration","Konzentriert sich auf React Native und TypeScript","Sicherheitsansatz kann die Entwicklungskomplexität erhöhen"],"pt":["Requer integração com Claude Code","Focado em React Native e TypeScript","Abordagem de segurança em primeiro lugar pode adicionar complexidade de desenvolvimento"],"ru":["Требует интеграции с Claude Code","Фокусируется на React Native и TypeScript","Подход, при котором безопасность стоит на первом месте, может добавить сложность разработки"],"ar":["يتطلب تكامل مع Claude Code","يركز على React Native وTypeScript","النهج الذي يضع الأمان في المقدمة قد يزيد من تعقيد التطوير"]},"version":4},"contentHash":"e08c94f85ed0dfda9f5223f8682b1ec4083d963089ed46a208b060999b49dedc","qualityScore":30}');
