INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alinaqi/claude-bootstrap/react-native', 'react-native', 'alinaqi', 'claude-bootstrap', 'community', 'react-native alinaqi claude-bootstrap community The React Native skill provides opinionated project initialization for Claude Code, focusing on security-first and spec-driven development for AI-native applications. It benefits developers working with React Native and TypeScript. React Native Skill 提供了安全、规格驱动的 AI 原生项目初始化，基于 TypeScript 和 React React Native Skill は、TypeScript と React に基づいたセキュリティーと仕様に基づいた AI ネイティブプロジェクト初期化を提供 React Native Skill은 TypeScript 및 React 기반의 보안 및 규격 기반의 AI 네이티브 프로젝트 초기화를 제공합니다 React Native es una skill de inicialización de proyectos opinada y segura, con una estructura de proyecto basada en TypeScript React Native est une compétence d''initialisation de projet opinée et sécurisée, avec une structure de projet basée sur TypeScript React Native ist eine Meinungsführungs-Skill für die Initialisierung von Projekten, mit einer sicheren und TypeScript-basierten Projektstruktur O React Native é uma ferramenta poderosa para desenvolver aplicativos móveis de IA. Aprenda a configurá-lo corretamente React Native - мощный инструмент для разработки мобильных приложений ИИ. Узнайте, как его настроить React Native هو أداة قوية لتطوير تطبيقات الهاتف المحمول الذكية. تعرف على كيفية إعدادها بشكل صحيح how to use react native react native security best practices react native alternative to flutter react native install guide what is react native react native vs native ios development react native setup for ai agents react native typescript integration react native project structure example React Native 项目初始化 AI 原生项目 TypeScript 项目结构 React Native Skill 安全项目初始化 规格驱动项目初始化 Generates project structure with separate core, components, and screens directories Supports TypeScript for type safety and maintainability Includes spec-driven development with tests (e.g., Button.test.tsx) Provides barrel exports for easy component reuse (e.g., index.ts) Organizes business logic in a pure core directory (no React dependencies) Uses a services directory for encapsulating business logic React Native is an opinionated project initialization skill for Claude Code, emphasizing security-first and spec-driven development with AI-native capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huifer/WellAlly-health/mental-health-analyzer', 'community', 'huifer', 'WellAlly-health', 'huifer/WellAlly-health', 'mental-health-analyzer', 0, 0, 30, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:38.194Z', '0b67fb34380e7cae23bdd9957d796f21a323e00f002a8c1cb6cedbd2b143f13b', '{"id":"huifer/WellAlly-health/mental-health-analyzer","name":"mental-health-analyzer","description":{"en":"The mental-health-analyzer skill provides in-depth mental health data analysis, helping users track psychological states, identify emotional patterns, and monitor crisis risks. It benefits individuals seeking to manage their mental well-being.","zh":"心理健康分析技能提供全面的心理健康数据分析功能，包括PHQ-9/GAD-7评分趋势分析和危机风险评估","ja":"メンタルヘルス分析AIエージェントは、包括的な心理健康データ分析機能を提供し、PHQ-9/GAD-7評価の傾向分析や危機リスク評価を行う","ko":"정신건강 분석 도구는 전반적인 정신건강 데이터 분석 기능을 제공하며, PHQ-9/GAD-7 평가의 추세 분석과 위기 리스크 평가 등을 수행합니다","es":"El analizador de salud mental es una herramienta de inteligencia artificial que proporciona un análisis integral de la salud mental, incluyendo la evaluación de la salud mental y el seguimiento del progreso terapéutico","fr":"L''analyseur de santé mentale est un outil d''intelligence artificielle qui fournit une analyse complète de la santé mentale, y compris l''évaluation de la santé mentale et le suivi de la progression thérapeutique","de":"Der Mental-Health-Analyzer ist ein künstliches Intelligenz-Tool, das eine umfassende Analyse der psychischen Gesundheit bietet, einschließlich der Bewertung der psychischen Gesundheit und der Verfolgung des therapeutischen Fortschritts","pt":"O mental-health-analyzer é uma ferramenta de análise de saúde mental que utiliza tecnologia de IA para fornecer insights sobre o estado mental do usuário","ru":"ИИ Агент mental-health-analyzer - это инструмент для анализа психического здоровья, использующий технологию ИИ для предоставления информации о психическом состоянии пользователя","ar":"mental-health-analyzer هو أداة لتحليل الصحة النفسية تستخدم تقنية الذكاء الاصطناعي لتقديم معلومات حول الحالة النفسية للمستخدم"},"seo":{"title":{"en":"mental-health-analyzer: Advanced Mental Health Analysis f...","zh":"心理健康分析技能搭建指南","ja":"メンタルヘルス分析AIエージェントの設定方法","ko":"정신건강 분석 도구 설정 가이드","es":"Guía de configuración del analizador de salud mental","fr":"Guide d''installation de l''analyseur de santé mentale","de":"Einrichtungsleitfaden für den Mental-Health-Analyzer","pt":"Guia de Configuração do mental-health-analyzer: Análise d...","ru":"Настройка ИИ Агента mental-health-analyzer: Анализ Психич...","ar":"دليل إعداد mental-health-analyzer: تحليل الصحة النفسية با..."},"description":{"en":"Unlock comprehensive mental health insights with mental-health-analyzer. Discover how to track symptoms, identify emotional patterns, and optimize treatment ...","zh":"了解心理健康分析技能的核心功能和技术详情，包括PHQ-9/GAD-7评分趋势分析和危机风险评估","ja":"メンタルヘルス分析AIエージェントの主な機能と技術的な詳細を紹介。PHQ-9/GAD-7評価の傾向分析や危機リスク評価など","ko":"정신건강 분석 도구의 핵심 기능과 기술적인 세부 사항을 알아보세요. PHQ-9/GAD-7 평가의 추세 분석과 위기 리스크 평가 등을 포함합니다","es":"Descubre cómo funciona el analizador de salud mental con tecnología de inteligencia artificial y aprende a implementarlo","fr":"Découvrez comment fonctionne l''analyseur de santé mentale avec la technologie d''intelligence artificielle et apprenez à le mettre en œuvre","de":"Erfahren Sie, wie der Mental-Health-Analyzer mit künstlicher Intelligenz funktioniert und wie Sie ihn implementieren können","pt":"Aprenda a configurar o mental-health-analyzer para análise de saúde mental com tecnologia de IA e melhore a gestão de saúde mental","ru":"Узнайте, как настроить ИИ Агент mental-health-analyzer для анализа психического здоровья с помощью технологии ИИ","ar":"تعرف على كيفية إعداد mental-health-analyzer لتحليل الصحة النفسية باستخدام تقنية الذكاء الاصطناعي"},"definition":{"en":"mental-health-analyzer is a specialized AI agent skill that offers advanced mental health analysis capabilities, including PHQ-9/GAD-7 score trend analysis and crisis risk assessment.","zh":"心理健康分析技能是一种智能的健康助手，通过自然语言交互帮助用户记录症状和管理健康","ja":"メンタルヘルス分析AIエージェントは、自然言語インタラクションを通じて利用者が症状を記録し、健康を管理するためのスマートなヘルスアシスタント","ko":"정신건강 분석 도구는 자연어 상호 작용을 통해 사용자가 증상을 기록하고 건강을 관리하는 데 도움을 주는 지능형 건강 보조 도구입니다","es":"Un analizador de salud mental es una herramienta que utiliza inteligencia artificial para evaluar y analizar la salud mental","fr":"Un analyseur de santé mentale est un outil qui utilise l''intelligence artificielle pour évaluer et analyser la santé mentale","de":"Ein Mental-Health-Analyzer ist ein Tool, das künstliche Intelligenz verwendet, um die psychische Gesundheit zu bewerten und zu analysieren","pt":"O que é mental-health-analyzer? É uma ferramenta de análise de saúde mental que utiliza tecnologia de IA","ru":"Что такое ИИ Агент mental-health-analyzer? Это инструмент для анализа психического здоровья, использующий технологию ИИ","ar":"ما هو mental-health-analyzer؟ هو أداة لتحليل الصحة النفسية تستخدم تقنية الذكاء الاصطناعي"},"features":{"en":["Provides psychological health assessment analysis using PHQ-9/GAD-7 score trend analysis","Supports emotional pattern recognition, identifying common emotions, triggers, and coping mechanisms","Enables therapy progress tracking, assessing treatment goal achievement and symptom improvement","Offers multi-level crisis risk detection and warning, including high, medium, and low-risk assessments","Analyzes sleep quality and its correlation with psychological states","Examines the relationship between exercise and emotional improvement"],"zh":["PHQ-9/GAD-7评分趋势分析","情绪模式识别","心理治疗进展追踪","危机风险评估","睡眠-心理关联分析","运动-情绪关联分析"],"ja":["PHQ-9/GAD-7評価の傾向分析","感情パターンの識別","精神療法の進展追跡","危機リスク評価","睡眠-精神の関連性分析","運動-感情の関連性分析"],"ko":["PHQ-9/GAD-7 평가의 추세 분석","정서 패턴 인식","정신 치료 진행 추적","위기 리스크 평가","수면-정신의 연관성 분석","운동-정서의 연관성 분석"],"es":["Evaluación de la salud mental mediante cuestionarios como PHQ-9 y GAD-7","Análisis de patrones de emociones y factores desencadenantes","Seguimiento del progreso terapéutico y evaluación de la efectividad del tratamiento","Detección de riesgos de crisis y alertas tempranas","Análisis de la relación entre el sueño y la salud mental","Análisis de la relación entre el ejercicio físico y la mejora del estado de ánimo"],"fr":["Évaluation de la santé mentale à l''aide de questionnaires tels que PHQ-9 et GAD-7","Analyse des modèles d''émotions et des facteurs déclencheurs","Suivi de la progression thérapeutique et évaluation de l''efficacité du traitement","Détection des risques de crise et alertes précoces","Analyse de la relation entre le sommeil et la santé mentale","Analyse de la relation entre l''exercice physique et l''amélioration de l''humeur"],"de":["Bewertung der psychischen Gesundheit mit Fragebögen wie PHQ-9 und GAD-7","Analyse von Emotionsmustern und Auslösern","Verfolgung des therapeutischen Fortschritts und Bewertung der Wirksamkeit der Behandlung","Erfassung von Krisenrisiken und Frühwarnsystem","Analyse der Beziehung zwischen Schlaf und psychischer Gesundheit","Analyse der Beziehung zwischen körperlicher Aktivität und Stimmungsverbesserung"],"pt":["Análise de tendências de saúde mental com PHQ-9/GAD-7","Reconhecimento de padrões de humor e identificação de fatores desencadeadores","Acompanhamento do progresso da terapia e avaliação de sintomas","Avaliação de risco de crise e alerta","Análise da relação entre sono e saúde mental","Análise da relação entre exercício e melhoria do humor"],"ru":["Анализ тенденций психического здоровья с помощью PHQ-9/GAD-7","Распознавание эмоциональных паттернов и выявление триггерных факторов","Отслеживание прогресса терапии и оценка симптомов","Оценка риска кризиса и предупреждение","Анализ связи между сном и психическим здоровьем","Анализ связи между физической активностью и улучшением настроения"],"ar":["تحليل الاتجاهات الصحية النفسية باستخدام PHQ-9/GAD-7","التعرف على أنماط المزاج وتحديد العوامل المسببة","متابعة تقدم العلاج وتقييم الأعراض","تقييم مخاطر الأزمة والإنذار","تحليل العلاقة بين النوم والصحة النفسية","تحليل العلاقة بين التمرين وتحسين المزاج"]},"keywords":{"en":["how to use mental-health-analyzer","mental-health-analyzer setup guide","what is mental-health-analyzer","mental-health-analyzer alternative","mental-health-analyzer vs other AI agents","installing mental-health-analyzer","mental health analysis for AI agents","AI-powered mental health tracking","crisis risk assessment tools"],"zh":["心理健康分析技能","AI健康助手","自然语言交互","PHQ-9/GAD-7评分","危机风险评估","睡眠-心理关联分析","运动-情绪关联分析"],"ja":["メンタルヘルス分析AIエージェント","AIヘルスアシスタント","自然言語インタラクション","PHQ-9/GAD-7評価","危機リスク評価","睡眠-精神の関連性分析","運動-感情の関連性分析"],"ko":["정신건강 분석 도구","AI 건강 보조 도구","자연어 상호 작용","PHQ-9/GAD-7 평가","위기 리스크 평가","수면-정신의 연관성 분석","운동-정서의 연관성 분석"],"es":["analizador de salud mental","inteligencia artificial en salud mental","evaluación de salud mental","seguimiento del progreso terapéutico","detección de riesgos de crisis","análisis de patrones de emociones","herramientas de inteligencia artificial para la salud mental","tecnología de inteligencia artificial para la salud mental","desarrollo de herramientas de salud mental","implementación de herramientas de salud mental"],"fr":["analyseur de santé mentale","intelligence artificielle en santé mentale","évaluation de la santé mentale","suivi de la progression thérapeutique","détection des risques de crise","analyse des modèles d''émotions","outils d''intelligence artificielle pour la santé mentale","technologie d''intelligence artificielle pour la santé mentale","développement d''outils de santé mentale","mise en œuvre d''outils de santé mentale"],"de":["Mental-Health-Analyzer","künstliche Intelligenz in der psychischen Gesundheit","Bewertung der psychischen Gesundheit","Verfolgung des therapeutischen Fortschritts","Erfassung von Krisenrisiken","Analyse von Emotionsmustern","Tools der künstlichen Intelligenz für die psychische Gesundheit","Technologie der künstlichen Intelligenz für die psychische Gesundheit","Entwicklung von Tools für die psychische Gesundheit","Implementierung von Tools für die psychische Gesundheit"],"pt":["mental-health-analyzer","análise de saúde mental","IA para saúde mental","ferramentas de análise de saúde mental","tecnologia de IA para saúde","saúde mental e IA","análise de tendências de saúde mental","reconhecimento de padrões de humor"],"ru":["ИИ Агент mental-health-analyzer","анализ психического здоровья","ИИ для психического здоровья","инструменты для анализа психического здоровья","технология ИИ для здравоохранения","психическое здоровье и ИИ","анализ тенденций психического здоровья","распознавание эмоциональных паттернов"],"ar":["mental-health-analyzer","تحليل الصحة النفسية","الذكاء الاصطناعي للصحة النفسية","أدوات تحليل الصحة النفسية","تقنية الذكاء الاصطناعي للرعاية الصحية","الصحة النفسية والذكاء الاصطناعي","تحليل الاتجاهات الصحية النفسية","التعرف على أنماط المزاج"]}},"owner":"huifer","repo":"WellAlly-health","repoPath":"huifer/WellAlly-health","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"mental-health-analyzer","description":"分析心理健康数据、识别心理模式、评估心理健康状况、提供个性化心理健康建议。支持与睡眠、运动、营养等其他健康数据的关联分析。","bodyPreview":"# 心理健康分析技能\n\n## 核心功能\n\n心理健康分析技能提供全面的心理健康数据分析功能，帮助用户追踪心理状态、识别情绪模式、监测危机风险和优化应对策略。\n\n**主要功能模块：**\n\n1. **心理健康评估分析** - PHQ-9/GAD-7等量表评分趋势分析\n2. **情绪模式识别** - 识别常见情绪、触发因素和应对方式效果\n3. **心理治疗进展追踪** - 治疗目标达成和症状改善评估\n4. **危机风险评估** - 多级危机风险检测（高/中/低）和预警\n5. **睡眠-心理关联分析** - 睡眠质量与心理状态的关联性分析\n6. **运动-情绪关联分析** - 运动与情绪改善的关系分析\n7. **营养-心理关联分析** - 饮食对情绪和焦虑的影响分析\n8. **慢性病-心理关联分析** - 慢性疾病与心理健康的关系分析\n\n## 触发条件\n\n技能在以下情况下自动触发：\n\n1. 用户使用 `/mental trend` 查看心理状况趋势\n2. 用户使用 `/mental pattern` 分析情绪模式\n3. 用户使用 `/mental therapy progress` 查看治疗进展","body":"# 心理健康分析技能\n\n## 核心功能\n\n心理健康分析技能提供全面的心理健康数据分析功能，帮助用户追踪心理状态、识别情绪模式、监测危机风险和优化应对策略。\n\n**主要功能模块：**\n\n1. **心理健康评估分析** - PHQ-9/GAD-7等量表评分趋势分析\n2. **情绪模式识别** - 识别常见情绪、触发因素和应对方式效果\n3. **心理治疗进展追踪** - 治疗目标达成和症状改善评估\n4. **危机风险评估** - 多级危机风险检测（高/中/低）和预警\n5. **睡眠-心理关联分析** - 睡眠质量与心理状态的关联性分析\n6. **运动-情绪关联分析** - 运动与情绪改善的关系分析\n7. **营养-心理关联分析** - 饮食对情绪和焦虑的影响分析\n8. **慢性病-心理关联分析** - 慢性疾病与心理健康的关系分析\n\n## 触发条件\n\n技能在以下情况下自动触发：\n\n1. 用户使用 `/mental trend` 查看心理状况趋势\n2. 用户使用 `/mental pattern` 分析情绪模式\n3. 用户使用 `/mental therapy progress` 查看治疗进展\n4. 用户使用 `/crisis assessment` 进行危机风险评估\n5. 用户使用 `/mental report` 生成心理健康报告\n\n## 医学安全边界\n\n**本技能不能做的事：**\n- ❌ 不进行心理疾病诊断\n- ❌ 不开具精神药物处方\n- ❌ 不预测自杀风险或自伤行为\n- ❌ 不替代专业心理治疗\n- ❌ 不处理急性精神危机\n\n**本技能能做的事：**\n- ✅ 识别心理健康趋势和模式\n- ✅ 评估危机风险等级并发出预警\n- ✅ 提供应对策略建议（非治疗性）\n- ✅ 追踪治疗进展和目标达成\n- ✅ 提供就医建议和专业资源信息\n- ✅ 分析心理健康与其他健康因素的关联\n\n## 执行步骤\n\n### 第1步：数据读取\n\n读取心理健康数据文件：\n- `data-example/mental-health-tracker.json` - 主心理健康档案\n- `data-example/mental-health-logs/.index.json` - 日志索引\n- `data-example/mental-health-logs/YYYY-MM/YYYY-MM-DD.json` - 每日情绪日记\n\n**数据验证：**\n- 检查文件是否存在\n- 验证数据结构完整性\n- 确认有足够的数据点进行分析（建议至少3次PHQ-9/GAD-7评估，或7天情绪日记）\n\n### 第2步：心理健康评估趋势分析\n\n**PHQ-9抑郁评分趋势分析：**\n```\n- 分析不同时间点的PHQ-9评分\n- 计算评分变化速率（分/月）\n- 识别严重程度变化（无/轻度/中度/重度）\n- 检测PHQ-9第9项（自伤意念）的变化\n- 预测未来趋势（改善/稳定/恶化）\n- 与治疗进展关联分析\n```\n\n**GAD-7焦虑评分趋势分析：**\n```\n- 分析GAD-7评分时序变化\n- 识别焦虑症状变化模式\n- 关联触发因素与焦虑水平\n- 评估应对方式效果\n- 预测焦虑趋势\n```\n\n**PSQI睡眠质量与心理状态关联：**\n```\n- PSQI评分与PHQ-9/GAD-7评分的相关性\n- 睡眠障碍对情绪的影响\n- 睡眠改善与心理状态改善的关系\n```\n\n**严重程度变化检测：**\n```\n- 识别严重程度升级（需要关注）\n- 识别严重程度降级（积极信号）\n- 检测快速恶化（≥5分/月，危机预警）\n- 检测快速改善（强化有效策略）\n```\n\n### 第3步：情绪模式识别\n\n**常见情绪统计：**\n```\n- 统计最常见的主要情绪（top 5）\n- 计算平均情绪强度\n- 识别情绪分布模式\n- 分析情绪多样性\n```\n\n**时间模式分析：**\n```\n- 一天中的情绪变化模式（早/中/晚）\n- 一周中的情绪变化模式（周一至周日）\n- 情绪波动程度（方差/标准差）\n- 情绪稳定性评估\n```\n\n**触发因素分析：**\n```\n- 统计高频触发因素（top 10）\n- 计算每个触发因素的平均影响\n- 识别高危触发因素（高影响+高频）\n- 触发因素与情绪类型的关联\n```\n\n**应对方式效果评估：**\n```\n- 计算每种应对方式的有效性（有帮助/没帮助的比例）\n- 识别高效应对策略（>80%有效）\n- 识别低效应对策略（<50%有效）\n- 应对方式与情绪类型的匹配分析\n```\n\n### 第4步：心理治疗进展追踪\n\n**治疗目标达成评估：**\n```\n- 计算每个目标的完成百分比\n- 评估症状改善程度（基线→当前→目标）\n- 预估目标达成时间\n- 识别滞后目标（需要调整）\n```\n\n**治疗过程分析：**\n```\n- 治疗频率和依从性\n- 作业完成率和质量\n- 治疗联盟强度\n- 咨询前后情绪变化\n```\n\n**症状改善评估：**\n```\n- PHQ-9/GAD-7评分变化（治疗前→治疗后）\n- 症状缓解百分比\n- 功能水平改善\n- 生活质量变化\n```\n\n### 第5步：危机风险评估（优先级：最高）\n\n**多级风险检测机制：**\n\n```\n风险等级计算（总分0-20+）：\n\n1. PHQ-9第9项检测（最高优先级）\n   - 得分=2（经常）：+10分，直接判定高风险\n   - 得分=1（有时）：+5分\n   - 得分=0（完全不会）：+0分\n\n2. 症状快速恶化检测\n   - 快速恶化（≥5分/月）：+5分\n   - 恶化（2-4分/月）：+3分\n   - 稳定（-1至1分/月）：+0分\n   - 改善（≤-2分/月）：-2分\n\n3. 高强度负面情绪占比检测\n   - 占比>70%：+3分\n   - 占比50-70%：+2分\n   - 占比<50%：+0分\n\n4. 情绪波动检测\n   - 方差>6（波动大）：+2分\n   - 方差4-6（波动中）：+1分\n   - 方差<4（波动小）：+0分\n\n5. 危机计划预警信号检测\n   - 每出现一个预警信号：+2分\n\n6. 社会退缩检测\n   - 严重退缩（独处时间>80%）：+3分\n   - 中度退缩（独处时间50-80%）：+2分\n   - 轻度/无退缩：+0分\n\n7. 功能受损检测\n   - 严重受损（≥5天/周）：+4分\n   - 中度受损（3-4天/周）：+2分\n   - 轻度/无受损：+0分\n\n风险等级判定：\n- 高风险（≥10分）：立即就医，启动危机干预\n- 中风险（5-9分）：密切关注，考虑就医（48小时内）\n- 低风险（0-4分）：继续监测，定期评估\n```\n\n**危机预警信号检测：**\n```\n- 绝望感（hopelessness）\n- 社会退缩（social_withdrawal）\n- 极端情绪波动（extreme_mood_swings）\n- 谈论死亡（talk_of_death）\n- 送走财物（giving_away_possessions）\n- 自伤意念（self_harm）\n- 自杀想法（suicidal_thoughts）\n- 物质滥用（substance_abuse）\n```\n\n**紧急行动触发条件：**\n```\n立即就医（24小时内）：\n- PHQ-9第9项得分≥2\n- 总风险评分≥10分\n- 出现幻觉或妄想\n- 有自伤或自杀计划\n\n尽快就医（48小时内）：\n- PHQ-9≥15分或GAD-7≥15分\n- 总风险评分5-9分\n- 症状快速恶化（≥5分/月）\n- 严重影响功能\n\n定期就医（1个月内）：\n- PHQ-9 10-14分或GAD-7 10-14分\n- 总风险评分<5分但症状持续\n- 需要专业支持\n```\n\n### 第6步：睡眠-心理关联分析\n\n**数据来源：**\n- 读取 `data-example/sleep-tracker.json`\n- 提取睡眠时长、睡眠质量（PSQI）、入睡时间等数据\n\n**关联分析：**\n```\n- 睡眠时长与PHQ-9评分的相关性\n- 睡眠质量与GAD-7评分的相关性\n- 失眠症状与情绪稳定性的关系\n- 睡眠改善与心理状态改善的时间关系\n- 睡眠障碍类型与特定心理症状的关联\n```\n\n**分析输出：**\n```\n- 相关性系数和统计显著性\n- 睡眠对心理状态的影响程度（高/中/低）\n- 睡眠改善建议\n- 睡眠与情绪的双向关系分析\n```\n\n### 第7步：运动-情绪关联分析\n\n**数据来源：**\n- 读取 `data-example/fitness-tracker.json`\n- 提取运动频率、运动类型、运动强度、运动时长等数据\n\n**关联分析：**\n```\n- 运动频率与平均情绪强度的关系\n- 运动类型与情绪改善效果的关系\n- 运动强度与焦虑水平的关系\n- 运动时长与情绪持续时间的关系\n- 运动后的情绪变化模式\n- 运动习惯与抑郁症状的关系\n```\n\n**分析输出：**\n```\n- 运动对情绪的积极影响程度\n- 最有效的运动类型推荐\n- 最佳运动频率建议\n- 运动与应对方式的关系\n```\n\n### 第8步：营养-心理关联分析\n\n**数据来源：**\n- 读取 `data-example/nutrition-tracker.json`\n- 提取咖啡因摄入、糖分摄入、饮食习惯等数据\n\n**关联分析：**\n```\n- 咖啡因摄入量与GAD-7焦虑评分的关系\n- 糖分摄入与情绪波动的关联\n- 饮食规律性与情绪稳定性的关系\n- 特定营养素缺乏（维生素D、Omega-3）与抑郁症状\n- 饮食模式与整体心理健康\n```\n\n**分析输出：**\n```\n- 饮食对心理状态的影响程度\n- 营养建议（如减少咖啡因、均衡饮食）\n- 可能的营养缺乏提示\n- 饮食调整建议\n```\n\n### 第9步：慢性病-心理关联分析\n\n**数据来源：**\n- 读取相关慢性病数据文件（如 `diabetes-tracker.json`, `hypertension-tracker.json`）\n- 提取疾病控制情况、症状负担、功能受限等数据\n\n**关联分析：**\n```\n- 慢性疼痛与抑郁症状的关系\n- 疾病控制情况与心理状态的关系\n- 功能受限与心理健康的关系\n- 疾病负担与焦虑水平的关系\n- 共病模式识别\n- 药物副作用对情绪的影响\n- 药物依从性与症状改善的关系\n```\n```\n\n**分析输出：**\n```\n- 慢性疾病对心理健康的影响程度\n- 需要特别关注的心理问题\n- 整体健康管理建议\n- 心理支持对疾病管理的益处\n```\n\n### 第10步：生成报告\n\n输出包括：\n- 心理健康状况摘要\n- 评估量表趋势分析\n- 情绪模式和触发因素\n- 治疗进展评估\n- 危机风险等级和建议\n- 与其他健康因素的关联分析\n- 个性化建议和行动计划\n\n## 输出格式\n\n### 心理健康分析报告结构\n\n```markdown\n# 心理健康分析报告\n\n**报告日期**: YYYY-MM-DD\n**分析周期**: YYYY-MM-DD 至 YYYY-MM-DD\n**数据完整性**: 良好\n\n⚠️ **重要提示**：本报告仅供参考，不构成医学诊断。如有严重心理困扰，请寻求专业心理医生帮助。\n\n---\n\n## 危机风险预警\n\n**当前风险等级**: 🟢 低风险 | 🟡 中风险 | 🔴 高风险\n\n**风险评分**: X/20\n\n**风险因素**:\n- [列出检测到的风险因素]\n\n**建议行动**:\n- [根据风险等级提供具体建议]\n\n---\n\n## 1. 心理健康状况摘要\n\n[整体评价：优秀/良好/一般/需改进/危机]\n- PHQ-9评分：X分（严重程度）\n- GAD-7评分：X分（严重程度）\n- 睡眠质量：X分（PSQI）\n- 整体趋势：改善/稳定/恶化\n\n## 2. 心理评估趋势分析\n\n### PHQ-9抑郁评分趋势\n- 当前评分：X分\n- 基线评分：X分\n- 变化：±X分\n- 变化速率：X分/月\n- 趋势：改善/稳定/恶化\n- 严重程度变化：[严重程度1] → [严重程度2]\n\n**图表描述**：\n- [折线图展示PHQ-9评分变化]\n- [标记严重程度分界线：5, 10, 15]\n\n**特别关注**：\n- 第9项（自伤意念）得分：X\n- 最高分项：[条目名称]\n- 持续存在问题：[列出条目]\n\n### GAD-7焦虑评分趋势\n- 当前评分：X分\n- 基线评分：X分\n- 变化：±X分\n- 变化速率：X分/月\n- 趋势：改善/稳定/恶化\n\n**图表描述**：\n- [折线图展示GAD-7评分变化]\n- [标记严重程度分界线：5, 10, 15]\n\n**主要焦虑症状**：\n- 最高分项：[条目名称]\n- 主要触发因素：[列出]\n\n### PSQI睡眠质量\n- 总分：X分\n- 睡眠质量：[评价]\n- 主要问题：[列出问题成分]\n\n## 3. 情绪模式分析\n\n### 常见情绪\n1. [情绪1] - 占比X%，平均强度X/10\n2. [情绪2] - 占比X%，平均强度X/10\n3. [情绪3] - 占比X%，平均强度X/10\n\n**图表描述**：\n- [饼图展示情绪分布]\n- [雷达图展示多维度情绪]\n\n### 时间模式\n- 早晨：主要情绪[情绪]，平均强度X/10\n- 下午：主要情绪[情绪]，平均强度X/10\n- 晚上：主要情绪[情绪]，平均强度X/10\n\n### 周模式\n- 周一至周五：主要情绪[情绪]，平均强度X/10\n- 周末：主要情绪[情绪]，平均强度X/10\n\n### 情绪稳定性\n- 波动程度：高/中/低\n- 情绪方差：X\n\n**图表描述**：\n- [折线图展示情绪强度时序变化]\n- [波动范围可视化]\n\n## 4. 触发因素分析\n\n### 高频触发因素（Top 10）\n| 排名 | 触发因素 | 频次 | 平均影响 |\n|------|----------|------|----------|\n| 1 | [触发因素1] | X次 | 高/中/低 |\n| 2 | [触发因素2] | X次 | 高/中/低 |\n| ... |\n\n### 高危触发因素（高影响+高频）\n- [触发因素1] - 频次X，影响高，建议：[应对建议]\n- [触发因素2] - 频次X，影响高，建议：[应对建议]\n\n**图表描述**：\n- [柱状图展示触发因素频次]\n- [热图展示触发因素与情绪类型的关联]\n\n## 5. 应对方式效果评估\n\n### 应对方式排名（按效果）\n| 应对方式 | 有效次数 | 无效次数 | 有效率 | 排名 |\n|----------|----------|----------|--------|------|\n| [应对方式1] | X次 | X次 | XX% | 1 |\n| [应对方式2] | X次 | X次 | XX% | 2 |\n| ... |\n\n### 高效应对策略（>80%有效）\n- [策略1] - 有效率XX%，推荐使用\n- [策略2] - 有效率XX%，推荐使用\n\n### 低效应对策略（<50%有效）\n- [策略1] - 有效率XX%，建议调整或停止\n- [策略2] - 有效率XX%，建议调整或停止\n\n**图表描述**：\n- [条形图展示应对方式效果排名]\n- [饼图展示有效/无效比例]\n\n## 6. 心理治疗进展\n\n### 治疗概况\n- 治疗类型：[CBT/心理动力学/人本主义等]\n- 治疗频率：[每周/每两周等]\n- 已进行咨询次数：X次\n- 治疗时长：X个月\n\n### 治疗目标进展\n| 目标 | 基线 | 当前 | 目标 | 进展 | 预计达成时间 |\n|------|------|------|------|------|--------------|\n| [目标1] | X分 | X分 | X分 | XX% | YYYY-MM-DD |\n| [目标2] | X分 | X分 | X分 | XX% | YYYY-MM-DD |\n\n**整体进展评价**：[优秀/良好/一般/需改进]\n\n### 症状改善\n- PHQ-9评分变化：X分 → X分，改善XX%\n- GAD-7评分变化：X分 → X分，改善XX%\n- 整体功能水平：[改善/稳定/恶化]\n\n### 作业完成情况\n- 平均完成率：XX%\n- 高质量完成：XX%\n- 需要加强的方面：[列出]\n\n## 7. 危机风险评估\n\n### 风险等级\n**当前风险等级**: 🟢 低风险 | 🟡 中风险 | 🔴 高风险\n\n**风险评分**: X/20\n\n### 风险因素分析\n| 风险因素 | 得分 | 详情 |\n|----------|------|------|\n| PHQ-9第9项 | X分 | 得分X，[详情] |\n| 症状变化 | X分 | [快速恶化/恶化/稳定/改善] |\n| 情绪强度 | X分 | 高强度负面情绪占比XX% |\n| 情绪波动 | X分 | 波动[大/中/小] |\n| 预警信号 | X分 | 出现X个预警信号：[列出] |\n| 社会退缩 | X分 | [严重/中度/轻度/无]退缩 |\n| 功能受损 | X分 | [严重/中度/轻度/无]受损 |\n\n### 检测到的预警信号\n- [如有列出]\n\n### 建议行动\n- [根据风险等级提供具体行动建议]\n\n### 紧急资源\n- 心理危机热线：400-xxx-xxxx（24小时）\n- 精神科急诊：就近三甲医院\n- 急救电话：120\n\n## 8. 与其他健康因素的关联分析\n\n### 睡眠-心理关联\n**关联强度**: 高/中/低\n\n**主要发现**:\n- 睡眠时长与PHQ-9评分的相关性：r=X.XX\n- 睡眠质量与情绪稳定性的关系：[描述]\n- 主要睡眠问题：[列出]\n- 改善睡眠对心理状态的潜在益处：[描述]\n\n**建议**:\n- [具体的睡眠改善建议]\n\n### 运动-情绪关联\n**关联强度**: 高/中/低\n\n**主要发现**:\n- 运动频率与情绪改善的关系：[描述]\n- 最有效的运动类型：[列出]\n- 运动后的情绪变化：[描述]\n\n**建议**:\n- [具体的运动建议]\n\n### 营养-心理关联\n**关联强度**: 高/中/低\n\n**主要发现**:\n- 咖啡因摄入与焦虑的关系：[描述]\n- 糖分摄入与情绪波动的关系：[描述]\n- 可能的营养缺乏：[列出]\n\n**建议**:\n- [具体的营养建议]\n\n### 慢性病-心理关联\n**关联强度**: 高/中/低\n\n**主要发现**:\n- [慢性病]与心理状态的关系：[描述]\n- 疾病负担对心理健康的影响：[描述]\n- 功能受限与情绪的关系：[描述]\n\n**建议**:\n- [具体的整体健康管理建议]\n\n## 9. 综合建议\n\n### 立即行动（如适用）\n- [如有紧急问题，列出立即需要采取的行动]\n\n### 本周行动计划\n1. [行动项1] - 优先级：高/中/低\n2. [行动项2] - 优先级：高/中/低\n3. ...\n\n### 本月目标\n1. [目标1]\n2. [目标2]\n3. ...\n\n### 继续保持的方面\n- [列出做得好的方面，鼓励继续保持]\n\n### 需要改进的方面\n- [列出需要改进的方面，提供具体建议]\n\n### 推荐资源\n- [书籍/APP/支持团体/在线资源等]\n\n## 10. 数据质量说明\n\n- 数据完整性：[优秀/良好/一般/需改进]\n- PHQ-9评估次数：X次\n- GAD-7评估次数：X次\n- 情绪日记条目：X条\n- 时间跨度：X天\n\n---\n\n**报告生成时间**: YYYY-MM-DD HH:MM:SS\n**下次评估建议时间**: YYYY-MM-DD\n\n⚠️ **免责声明**：本报告由心理健康分析技能自动生成，仅供参考，不构成医学诊断或治疗建议。如有任何心理健康问题，请寻求专业心理医生或精神科医生的帮助。\n```\n\n## 使用示例\n\n### 示例1：趋势分析\n\n**用户输入**：\n```\n/mental trend 3months\n```\n\n**技能执行**：\n1. 读取最近3个月的PHQ-9和GAD-7评估数据\n2. 计算评分变化速率和趋势\n3. 分析严重程度变化\n4. 检测PHQ-9第9项变化\n5. 生成趋势报告\n\n**输出**：\n```markdown\n# 心理健康趋势分析（近3个月）\n\n## 整体趋势\n- PHQ-9：14分 → 8分，改善6分，趋势：改善 ✓\n- GAD-7：12分 → 6分，改善6分，趋势：改善 ✓\n- 变化速率：约2分/月\n\n## 严重程度变化\n- PHQ-9：中度抑郁 → 轻度抑郁 ✓\n- GAD-7：中度焦虑 → 轻度焦虑 ✓\n\n## 积极信号\n- 症状持续改善\n- PHQ-9第9项得分：1 → 0 ✓\n- 治疗效果良好\n\n## 建议\n- 继续当前治疗\n- 保持运动和睡眠习惯\n- 下次评估：1个月后\n```\n\n### 示例2：情绪模式分析\n\n**用户输入**：\n```\n/mental pattern\n```\n\n**技能执行**：\n1. 读取情绪日记数据\n2. 统计常见情绪和时间模式\n3. 分析触发因素和应对方式\n4. 生成模式识别报告\n\n**输出**：\n```markdown\n# 情绪模式分析\n\n## 常见情绪（Top 3）\n1. 焦虑 - 占比35%，平均强度7/10\n2. 疲劳 - 占比25%，平均强度6/10\n3. 平静 - 占比20%，平均强度7/10\n\n## 时间模式\n- 早晨：平静（强度7/10）😌\n- 下午：焦虑（强度7/10）😰\n- 晚上：疲劳（强度6/10）😴\n\n## 主要触发因素（Top 5）\n1. 工作压力 - 12次，影响高\n2. 睡眠不足 - 8次，影响中\n3. 运动 - 6次，影响积极\n4. 社交 - 5次，影响积极\n5. 交通拥堵 - 4次，影响中\n\n## 高效应对策略\n1. 运动 - 有效率90% ✓\n2. 冥想 - 有效率85% ✓\n3. 深呼吸 - 有效率75% ✓\n\n## 建议\n- 下午工作压力大时，可使用深呼吸或短暂散步\n- 保持规律运动，对情绪改善效果显著\n- 改善睡眠有助于减轻焦虑和疲劳\n```\n\n### 示例3：危机风险评估\n\n**用户输入**：\n```\n/crisis assessment\n```\n\n**技能执行**：\n1. 读取最近的PHQ-9/GAD-7评估\n2. 读取最近的情绪日记\n3. 执行危机风险检测算法\n4. 计算风险评分和等级\n5. 生成危机风险报告\n\n**输出**：\n```markdown\n# 危机风险评估\n\n## 当前风险等级：🟢 低风险\n\n**风险评分**: 3/20\n\n## 风险因素分析\n| 风险因素 | 得分 | 详情 |\n|----------|------|------|\n| PHQ-9第9项 | 0分 | 得分0，无自伤意念 ✓ |\n| 症状变化 | -2分 | 改善趋势 ✓ |\n| 情绪强度 | 2分 | 高强度负面情绪占比45% |\n| 情绪波动 | 1分 | 波动中等 |\n| 预警信号 | 0分 | 未检测到 ✓ |\n| 社会退缩 | 0分 | 社交活动良好 ✓ |\n| 功能受损 | 0分 | 功能正常 ✓ |\n| **总分** | **3分** | **低风险** ✓ |\n\n## 建议行动\n- 继续监测心理状态\n- 保持健康的生活习惯\n- 定期进行心理评估（每月1次）\n- 继续心理治疗（如有）\n\n## 紧急资源（备用）\n- 心理危机热线：400-xxx-xxxx（24小时）\n- 精神科急诊：就近三甲医院\n- 急救电话：120\n\n⚠️ 如出现以下情况，请立即寻求专业帮助：\n- 有自伤或自杀想法或计划\n- 幻觉、妄想\n- 完全失去功能\n- 无法控制的情绪爆发\n```\n\n### 示例4：治疗进展分析\n\n**用户输入**：\n```\n/mental therapy progress\n```\n\n**技能执行**：\n1. 读取治疗记录和目标\n2. 计算目标完成百分比\n3. 分析症状改善程度\n4. 评估作业完成情况\n5. 生成治疗进展报告\n\n**输出**：\n```markdown\n# 心理治疗进展分析\n\n## 治疗概况\n- 治疗类型：CBT（认知行为治疗）\n- 治疗频率：每周1次\n- 已进行咨询：24次\n- 治疗时长：5个月\n\n## 治疗目标进展\n| 目标 | 基线 | 当前 | 目标 | 进展 | 预计达成时间 |\n|------|------|------|------|------|--------------|\n| 降低焦虑水平 | 14分 | 8分 | 5分 | 57% | 2025-08-01 |\n| 改善睡眠质量 | 10分 | 6分 | 4分 | 60% | 2025-07-15 |\n| 增加愉快活动 | 2次/周 | 5次/周 | 7次/周 | 50% | 2025-07-01 |\n\n**整体进展评价**: 良好 ✓\n\n## 症状改善\n- PHQ-9评分：14分 → 8分，改善43% ✓\n- GAD-7评分：14分 → 6分，改善57% ✓\n- 整体功能水平：显著改善 ✓\n\n## 作业完成情况\n- 平均完成率：85%\n- 高质量完成：60%\n- 需要加强：认知重构练习\n\n## 治疗亮点\n- 焦虑症状显著改善\n- 睡眠质量明显提升\n- 行为激活效果良好\n- 认知扭曲识别能力提升\n\n## 继续保持\n- 每周心理咨询\n- 每日放松练习\n- 行为激活（运动、社交）\n- 思维记录\n\n## 需要加强\n- 认知重构练习\n- 应对技巧应用\n- 睡眠卫生维持\n```\n\n### 示例5：关联分析\n\n**用户输入**：\n```\n/mental analysis correlations\n```\n\n**技能执行**：\n1. 读取心理健康、睡眠、运动、营养、慢性病数据\n2. 计算相关性系数\n3. 分析影响程度\n4. 生成关联分析报告\n\n**输出**：\n```markdown\n# 心理健康关联分析\n\n## 睡眠-心理关联（关联强度：高）\n\n### 主要发现\n- 睡眠时长与PHQ-9评分呈负相关（r=-0.72, p<0.01）\n- 睡眠质量与情绪稳定性呈正相关（r=0.68, p<0.01）\n- PSQI评分每改善1分，PHQ-9评分平均降低1.2分\n\n### 睡眠问题影响\n- 入睡困难 → 次日焦虑增加40%\n- 夜间易醒 → 次日情绪低落增加35%\n- 睡眠不足 → 注意力不集中，情绪波动加大\n\n### 建议\n- 保持规律作息，每晚23:00前入睡\n- 改善睡眠卫生：避免咖啡因下午摄入\n- 继续放松练习，促进睡眠\n\n## 运动-情绪关联（关联强度：高）\n\n### 主要发现\n- 运动频率与积极情绪占比呈正相关（r=0.75, p<0.01）\n- 运动日情绪平均强度比非运动日高1.5分\n- 运动后焦虑感平均降低50%\n\n### 最有效的运动类型\n1. 有氧运动（跑步、游泳）- 改善率85%\n2. 瑜伽 - 改善率80%\n3. 户外散步 - 改善率75%\n\n### 建议\n- 保持每周3-5次运动，每次30分钟以上\n- 优先选择有氧运动\n- 焦虑时可进行户外散步\n\n## 营养-心理关联（关联强度：中）\n\n### 主要发现\n- 咖啡因摄入与GAD-7评分呈正相关（r=0.52, p<0.05）\n- 高糖饮食与情绪波动呈正相关（r=0.48, p<0.05）\n- Omega-3摄入不足可能与抑郁症状相关\n\n### 建议\n- 减少咖啡因摄入（每天≤2杯）\n- 减少添加糖摄入\n- 考虑补充Omega-3（咨询医生）\n\n## 综合建议\n基于关联分析，以下生活方式对改善心理健康最有效：\n1. **规律运动**（每周3-5次，30分钟+）\n2. **充足睡眠**（7-8小时，23:00前入睡）\n3. **均衡饮食**（减少咖啡因和糖分）\n4. **持续治疗**（CBT心理治疗）\n\n这4个方面的综合干预对您的心理健康改善贡献率为**75%**。\n```\n\n### 示例6：完整报告生成\n\n**用户输入**：\n```\n/mental report\n```\n\n**技能执行**：\n1. 读取所有相关数据\n2. 执行完整分析流程\n3. 生成交互式HTML报告\n4. 包含危机警告和建议\n\n**输出**：\n生成完整的心理健康分析报告HTML文件，包含：\n- 所有图表（ECharts交互式图表）\n- 危机风险警告（如适用）\n- 详细分析和建议\n- 可下载或打印\n\n---\n\n## 错误处理\n\n### 数据文件不存在\n```\n错误：未找到心理健康数据文件\n建议：请先使用 /mental assess 或 /mental mood 命令创建数据\n```\n\n### 数据不足\n```\n警告：数据不足以进行趋势分析\n建议：至少需要3次PHQ-9/GAD-7评估或7天情绪日记\n当前数据：PHQ-9评估X次，情绪日记X条\n```\n\n### 危机风险高\n```\n🔴 危机警告：检测到高风险因素\n\n立即行动：\n1. 联系心理危机热线：400-xxx-xxxx（24小时）\n2. 前往最近的精神科急诊\n3. 拨打急救电话：120\n4. 联系家人或朋友陪伴\n\n检测到的风险因素：\n- [列出高风险因素]\n\n不要犹豫，立即寻求专业帮助！\n```\n\n## 数据源说明\n\n**主要数据源**：\n- `data-example/mental-health-tracker.json` - 心理健康主数据\n- `data-example/mental-health-logs/` - 情绪日记日志\n\n**关联数据源**：\n- `data-example/sleep-tracker.json` - 睡眠数据\n- `data-example/fitness-tracker.json` - 运动数据\n- `data-example/nutrition-tracker.json` - 营养数据\n- `data-example/diabetes-tracker.json` - 糖尿病数据（如适用）\n- `data-example/hypertension-tracker.json` - 高血压数据（如适用）\n- `data-example/medication-tracker.json` - 用药数据\n\n## 性能优化\n\n对于大量数据（如>6个月的情绪日记），采用以下优化策略：\n- 数据聚合：按周/月聚合情绪数据\n- 抽样分析：随机抽样代表性数据点\n- 增量分析：仅分析新增数据\n- 缓存中间结果\n\n---\n\n**技能版本**: v1.0.0\n**最后更新**: 2025-01-06\n**维护者**: WellAlly Tech\n"},"lastSynced":"2026-03-08T02:00:38.194Z","agentAnalysis":{"suitability":{"en":"Perfect for Health Monitoring Agents needing advanced mental health data analysis and crisis risk assessment capabilities.","zh":"非常适合需要高级心理健康数据分析和危机风险评估能力的健康监测代理。","ja":"高度な精神保健データ分析と危機リスク評価機能を必要とするヘルスモニタリングエージェントに最適です。","ko":"고급 정신 건강 데이터 분석 및 위기 리스크 평가 기능이 필요한 헬스 모니터링 에이전트에 적합합니다.","es":"Perfecto para agentes de monitoreo de salud que necesitan un análisis de datos de salud mental avanzado y capacidades de evaluación de riesgo de crisis.","fr":"Parfait pour les agents de surveillance de la santé nécessitant une analyse de données de santé mentale avancée et des capacités d''évaluation du risque de crise.","de":"Perfekt für Gesundheitsüberwachungsagenten, die eine erweiterte Analyse von psychischen Gesundheitsdaten und Krisenrisikobewertungsfunktionen benötigen.","pt":"Perfeito para Agentes de Monitoramento de Saúde que necessitam de análise avançada de dados de saúde mental e capacidades de avaliação de risco de crise.","ru":"Идеально подходит для агентов мониторинга здоровья, которым необходимы расширенные возможности анализа данных о психическом здоровье и оценки риска кризиса.","ar":"مثالي للوكلاء الذين يركزون على مراقبة الصحة و kteří يحتاجون إلى تحليل متقدم للبيانات المتعلقة بالصحة النفسية وقدرات تقييم مخاطر الأزمات."},"recommendation":{"en":"Empowers agents to analyze psychological states, identify emotional patterns, and monitor crisis risks using PHQ-9/GAD-7 scoring trends, sentiment analysis, and machine learning algorithms, while also providing insights into sleep, exercise, nutrition, and chronic disease correlations.","zh":"赋予代理分析心理状态、识别情绪模式和监测危机风险的能力，使用PHQ-9/GAD-7评分趋势、情绪分析和机器学习算法，同时提供对睡眠、运动、营养和慢性疾病相关性的洞察。","ja":"エージェントに心理状態を分析し、感情パターンを特定し、危機リスクを監視する機能を提供し、PHQ-9/GAD-7 スコア링の傾向、感情分析、機械学習アルゴリズムを使用し、同時に睡眠、運動、栄養、慢性疾患の相関に関する洞察を提供します。","ko":"에이전트가 심리 상태를 분석하고 감정 패턴을 식별하며 위기 리스크를 모니터링할 수 있는 기능을 제공하며, PHQ-9/GAD-7 스코어링 트렌드, 감정 분석 및 기계 학습 알고리즘을 사용하며,同時に 수면, 운동, 영양 및 만성 질환의 상관 관계에 대한 통찰력을 제공합니다.","es":"Habilita a los agentes para analizar estados psicológicos, identificar patrones emocionales y monitorear riesgos de crisis utilizando tendencias de puntuación PHQ-9/GAD-7, análisis de sentimiento y algoritmos de aprendizaje automático, mientras también proporciona información sobre correlaciones de sueño, ejercicio, nutrición y enfermedades crónicas.","fr":"Permet aux agents d''analyser les états psychologiques, d''identifier les modèles émotionnels et de surveiller les risques de crise en utilisant les tendances de notation PHQ-9/GAD-7, l''analyse des sentiments et les algorithmes d''apprentissage automatique, tout en fournissant des informations sur les corrélations entre sommeil, exercice, nutrition et maladies chroniques.","de":"Ermöglicht es Agenten, psychische Zustände zu analysieren, emotionale Muster zu identifizieren und Krisenrisiken unter Verwendung von PHQ-9/GAD-7-Bewertungstrends, Sentiment-Analyse und Machine-Learning-Algorithmen zu überwachen, während es auch Einblicke in Schlaf-, Bewegungs-, Ernährungs- und chronische Krankheitskorrelationen bietet.","pt":"Habilita os agentes a analisar estados psicológicos, identificar padrões emocionais e monitorar riscos de crise usando tendências de pontuação PHQ-9/GAD-7, análise de sentimento e algoritmos de aprendizado de máquina, além de fornecer insights sobre sono, exercício, nutrição e correlações de doenças crônicas.","ru":"Позволяет агентам анализировать психологические состояния, выявлять эмоциональные закономерности и отслеживать риски кризиса с помощью трендов оценок PHQ-9/GAD-7, анализа настроений и алгоритмов машинного обучения, а также предоставляет информацию о корреляциях между сном, упражнениями, питанием и хроническими заболеваниями.","ar":"تمكّن الوكلاء من تحليل الحالات النفسية وتحديد الأنماط العاطفية ومراقبة مخاطر الأزمات باستخدام اتجاهات التقييم PHQ-9/GAD-7 وتحليل المشاعر وخوارزميات التعلم الآلي، بالإضافة إلى تقديم رؤى حول النوم والتمارين الرياضية والتغذية وعلاقات الأمراض المزمنة."},"useCases":{"en":["Tracking psychological state trends using PHQ-9/GAD-7 assessments","Identifying emotional patterns and triggering factors for personalized interventions","Monitoring crisis risks and generating alerts for high-risk individuals"],"zh":["使用PHQ-9/GAD-7评估跟踪心理状态趋势","识别情绪模式和触发因素以进行个性化干预","监测危机风险并为高风险个人生成警报"],"ja":["PHQ-9/GAD-7 アセスメントを使用して心理状態の傾向を追跡する","感情パターンとトリガー要因を特定して個別の介入を行う","危機リスクを監視し、高リスク個人のためにアラートを生成する"],"ko":["PHQ-9/GAD-7 평가를 사용하여 심리 상태 트렌드를 추적하는 것","감정 패턴과 트리거 요인을 식별하여 개인화된 개입을 하는 것","위기 리스크를 모니터링하고 고위험 개인을 위한 경보를 생성하는 것"],"es":["Seguimiento de tendencias del estado psicológico utilizando evaluaciones PHQ-9/GAD-7","Identificación de patrones emocionales y factores desencadenantes para intervenciones personalizadas","Monitoreo de riesgos de crisis y generación de alertas para personas de alto riesgo"],"fr":["Suivi des tendances de l''état psychologique à l''aide d''évaluations PHQ-9/GAD-7","Identification des modèles émotionnels et des facteurs déclencheurs pour des interventions personnalisées","Surveillance des risques de crise et génération d''alertes pour les personnes à risque élevé"],"de":["Verfolgung von Trends des psychischen Zustands unter Verwendung von PHQ-9/GAD-7-Bewertungen","Identifizierung emotionaler Muster und Auslösefaktoren für personalisierte Interventionen","Überwachung von Krisenrisiken und Generierung von Warnungen für Hochrisikopersonen"],"pt":["Rastrear tendências de estados psicológicos usando avaliações PHQ-9/GAD-7","Identificar padrões emocionais e fatores desencadeadores para intervenções personalizadas","Monitorar riscos de crise e gerar alertas para indivíduos de alto risco"],"ru":["Отслеживать тенденции психологических состояний с помощью оценок PHQ-9/GAD-7","Выявлять эмоциональные закономерности и факторы, вызывающие их, для персонализированных вмешательств","Мониторить риски кризиса и генерировать предупреждения для людей с высоким риском"],"ar":["تتبع اتجاهات الحالات النفسية باستخدام تقييمات PHQ-9/GAD-7","تحديد الأنماط العاطفية وعوامل الإنشاء لها من أجل تدخلات مُصممة خصيصًا","مراقبة مخاطر الأزمات وتوليد تنبيهات للأفراد ذوي خطر cao"]},"limitations":{"en":["Requires user input and historical data for accurate analysis","Limited to analyzing data from supported mental health assessments (PHQ-9/GAD-7)","May require additional integrations for accessing external health data (e.g., sleep, exercise, nutrition)"],"zh":["需要用户输入和历史数据以进行准确分析","仅限于分析支持的精神健康评估数据（PHQ-9/GAD-7）","可能需要额外集成以访问外部健康数据（例如睡眠、运动、营养）"],"ja":["正確な分析を行うためにユーザー入力と歴史データが必要","サポートされている精神保健アセスメントデータ（PHQ-9/GAD-7）のみを分析する","外部のヘルスデータ（例：睡眠、運動、栄養）にアクセスするには追加の統合が必要になる場合がある"],"ko":["정확한 분석을 수행하기 위해 사용자 입력 및 역사 데이터가 필요함","지원되는 정신 건강 평가 데이터만 분석함（PHQ-9/GAD-7）","외부 건강 데이터（예：수면, 운동, 영양）에 접근하기 위해 추가 통합이 필요할 수 있음"],"es":["Requiere entrada de usuario y datos históricos para un análisis preciso","Limitado a analizar datos de evaluaciones de salud mental compatibles (PHQ-9/GAD-7)","Puede requerir integraciones adicionales para acceder a datos de salud externos (por ejemplo, sueño, ejercicio, nutrición)"],"fr":["Nécessite une saisie utilisateur et des données historiques pour une analyse précise","Limité à l''analyse des données d''évaluations de santé mentale prises en charge (PHQ-9/GAD-7)","Peut nécessiter des intégrations supplémentaires pour accéder à des données de santé externes (par exemple, sommeil, exercice, nutrition)"],"de":["Benötigt Benutzereingaben und historische Daten für eine genaue Analyse","Begrenzt auf die Analyse von Daten aus unterstützten psychischen Gesundheitsbewertungen (PHQ-9/GAD-7)","Kann zusätzliche Integrationen erfordern, um auf externe Gesundheitsdaten zuzugreifen (z. B. Schlaf, Bewegung, Ernährung)"],"pt":["Requer entrada do usuário e dados históricos para análise precisa","Limitado à análise de dados de avaliações de saúde mental suportadas (PHQ-9/GAD-7)","Pode requerer integrações adicionais para acessar dados de saúde externos (por exemplo, sono, exercício, nutrição)"],"ru":["Требует ввода пользователя и исторических данных для точного анализа","Ограничен анализом данных поддерживаемых оценок психического здоровья (PHQ-9/GAD-7)","Может потребовать дополнительных интеграций для доступа к внешним данным о здоровье (например, сон, упражнения, питание)"],"ar":["يتطلب إدخال المستخدم والبيانات التاريخية من أجل تحليل دقيق","محدود بالتحليل البيانات من تقييمات الصحة النفسية المدعومة (PHQ-9/GAD-7)","يمكن أن يتطلب تكاملات إضافية للوصول إلى بيانات صحية خارجية (على سبيل المثال، النوم والتمارين الرياضية والتغذية)"]},"version":4},"contentHash":"0b67fb34380e7cae23bdd9957d796f21a323e00f002a8c1cb6cedbd2b143f13b","qualityScore":30}');
