INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huifer/WellAlly-health/mental-health-analyzer', 'mental-health-analyzer', 'huifer', 'WellAlly-health', 'community', 'mental-health-analyzer huifer WellAlly-health community The mental-health-analyzer skill provides in-depth mental health data analysis, helping users track psychological states, identify emotional patterns, and monitor crisis risks. It benefits individuals seeking to manage their mental well-being. 心理健康分析技能提供全面的心理健康数据分析功能，包括PHQ-9/GAD-7评分趋势分析和危机风险评估 メンタルヘルス分析AIエージェントは、包括的な心理健康データ分析機能を提供し、PHQ-9/GAD-7評価の傾向分析や危機リスク評価を行う 정신건강 분석 도구는 전반적인 정신건강 데이터 분석 기능을 제공하며, PHQ-9/GAD-7 평가의 추세 분석과 위기 리스크 평가 등을 수행합니다 El analizador de salud mental es una herramienta de inteligencia artificial que proporciona un análisis integral de la salud mental, incluyendo la evaluación de la salud mental y el seguimiento del progreso terapéutico L''analyseur de santé mentale est un outil d''intelligence artificielle qui fournit une analyse complète de la santé mentale, y compris l''évaluation de la santé mentale et le suivi de la progression thérapeutique Der Mental-Health-Analyzer ist ein künstliches Intelligenz-Tool, das eine umfassende Analyse der psychischen Gesundheit bietet, einschließlich der Bewertung der psychischen Gesundheit und der Verfolgung des therapeutischen Fortschritts O mental-health-analyzer é uma ferramenta de análise de saúde mental que utiliza tecnologia de IA para fornecer insights sobre o estado mental do usuário ИИ Агент mental-health-analyzer - это инструмент для анализа психического здоровья, использующий технологию ИИ для предоставления информации о психическом состоянии пользователя mental-health-analyzer هو أداة لتحليل الصحة النفسية تستخدم تقنية الذكاء الاصطناعي لتقديم معلومات حول الحالة النفسية للمستخدم how to use mental-health-analyzer mental-health-analyzer setup guide what is mental-health-analyzer mental-health-analyzer alternative mental-health-analyzer vs other AI agents installing mental-health-analyzer mental health analysis for AI agents AI-powered mental health tracking crisis risk assessment tools 心理健康分析技能 AI健康助手 自然语言交互 PHQ-9/GAD-7评分 危机风险评估 睡眠-心理关联分析 运动-情绪关联分析 Provides psychological health assessment analysis using PHQ-9/GAD-7 score trend analysis Supports emotional pattern recognition, identifying common emotions, triggers, and coping mechanisms Enables therapy progress tracking, assessing treatment goal achievement and symptom improvement Offers multi-level crisis risk detection and warning, including high, medium, and low-risk assessments Analyzes sleep quality and its correlation with psychological states Examines the relationship between exercise and emotional improvement mental-health-analyzer is a specialized AI agent skill that offers advanced mental health analysis capabilities, including PHQ-9/GAD-7 score trend analysis and crisis risk assessment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jyasuu/cheat-sheet/ufw', 'community', 'jyasuu', 'cheat-sheet', 'jyasuu/cheat-sheet', 'ufw', 0, 0, 30, '2026-03-08T01:57:15.281Z', '2026-03-08T02:00:51.266Z', 'b0a61952d5686637265b4b83d89cc4454dc97657b65f8ad0b8acaa57a5d4f6a1', '{"id":"jyasuu/cheat-sheet/ufw","name":"ufw","description":{"en":"The ufw skill enables AI agents to manage and configure Uncomplicated Firewall rules, allowing developers to securely control incoming and outgoing network traffic. It benefits developers working with network security and Linux-based systems.","zh":"ufw是一种不复杂的防火墙配置工具，用于管理Linux服务器的网络访问控制","ja":"ufwはLinuxサーバーのネットワークアクセス制御を管理するためのシンプルなファイアウォール設定ツールです","ko":"ufw는 Linux 서버의 네트워크 액세스 제어를 관리하는 간단한 방화벽 설정 도구입니다","es":"ufw es una herramienta de firewall para administradores de sistemas que permite configurar reglas de acceso y denegación de tráfico de red","fr":"ufw est un outil de pare-feu pour les administrateurs système qui permet de configurer des règles d''accès et de déni de trafic réseau","de":"ufw ist ein Firewall-Tool für Systemadministratoren, mit dem Regeln für den Netzwerkzugriff und die Ablehnung von Netzwerkverkehr konfiguriert werden können","pt":"O ufw é uma ferramenta de controle de tráfego de rede que permite configurar regras de acesso com comandos como sudo ufw allow e sudo ufw deny","ru":"ufw - это инструмент контроля сетевого трафика, который позволяет настраивать правила доступа с помощью команд như sudo ufw allow и sudo ufw deny от ИИ Агентов","ar":"ufw هو أداة للتحكم في حركة المرور الشبكي التي تسمح بتثبيت قواعد الوصول باستخدام أوامر مثل sudo ufw allow و sudo ufw deny مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"ufw: Setup Guide for AI Agents | Secure Firewall Configur...","zh":"ufw 防火墙设置指南","ja":"ufw セキュリティ設定ガイド","ko":"ufw 방화벽 설정 가이드","es":"Guía de configuración de ufw para administradores de sist...","fr":"Guide de configuration de ufw pour les administrateurs sy...","de":"ufw-Konfigurationsleitfaden für Systemadministratoren","pt":"Guia de Configuração ufw: Controle de Tráfego de Rede","ru":"Настройка ufw: Руководство по Контролю Сетевого Трафика о...","ar":"دليل تثبيت ufw: التحكم في حركة المرور الشبكي باستخدام أدو..."},"description":{"en":"Unlock the full potential of ufw with our expert guide. Learn how to configure and optimize your firewall for maximum security and performance. Get started now!","zh":"了解ufw的基本用法和高级配置，包括允许和拒绝特定IP和端口的访问，优化您的服务器安全","ja":"ufwの基本的な使い方と高度な設定を学び、特定のIPとポートへのアクセスを許可または拒否してサーバーのセキュリティを最適化する","ko":"ufw의 기본 사용법과 고급 설정을 알아보고 특정 IP와 포트에 대한 액세스를 허용 또는 거부하여 서버 보안을 최적화하는 방법","es":"Aprende a configurar y administrar ufw para proteger tus servidores con reglas de firewall personalizadas","fr":"Découvrez comment configurer et gérer ufw pour protéger vos serveurs avec des règles de pare-feu personnalisées","de":"Erfahren Sie, wie Sie ufw konfigurieren und verwalten, um Ihre Server mit benutzerdefinierten Firewall-Regeln zu schützen","pt":"Aprenda a configurar o ufw para controlar o tráfego de rede com comandos como sudo ufw allow e sudo ufw deny","ru":"Узнайте, как настроить ufw для контроля сетевого трафика с помощью команд như sudo ufw allow и sudo ufw deny от ИИ Агентов","ar":"تعلم كيفية تثبيت ufw للتحكم في حركة المرور الشبكي باستخدام أوامر مثل sudo ufw allow و sudo ufw deny مع أدوات الذكاء الاصطناعي"},"definition":{"en":"ufw is a command-line interface for managing firewall rules, providing an easy-to-use syntax for allowing or denying network traffic based on IP addresses, ports, and protocols.","zh":"ufw是Uncomplicated Firewall的简称，是一种用于Linux系统的防火墙配置工具","ja":"ufwはUncomplicated Firewallの略称で、Linuxシステム用のファイアウォール設定ツールです","ko":"ufw는 Uncomplicated Firewall의 약자이며 Linux 시스템용 방화벽 설정 도구입니다","es":"ufw es un cortafuegos de red que permite administrar el tráfico de red mediante reglas personalizadas","fr":"ufw est un pare-feu réseau qui permet de gérer le trafic réseau à l''aide de règles personnalisées","de":"ufw ist ein Netzwerk-Firewall, der die Verwaltung von Netzwerkverkehr durch benutzerdefinierte Regeln ermöglicht","pt":"ufw é uma ferramenta de controle de tráfego de rede baseada em CLI","ru":"ufw - это инструмент контроля сетевого трафика на основе CLI от ИИ Агентов","ar":"ufw هو أداة للتحكم في حركة المرور الشبكي مبنية على واجهة سطر الأوامر"},"features":{"en":["Allows incoming traffic from specific IP addresses using the ''allow from'' command","Enables port-specific rules, such as allowing SSH traffic on port 22","Supports protocol-specific rules, including TCP and UDP","Provides a numbered status output for easy rule management","Enables rule insertion and deletion using the ''insert'' and ''delete'' commands"],"zh":["允许特定IP地址访问特定端口","拒绝特定IP地址访问特定端口","支持TCP和UDP协议","可以插入和删除规则","支持查看当前规则状态"],"ja":["特定のIPアドレスが特定のポートにアクセスできるようにする","特定のIPアドレスが特定のポートにアクセスできないようにする","TCPとUDPプロトコルのサポート","ルールの挿入と削除","現在のルール状態の表示"],"ko":["특정 IP 주소가 특정 포트에 액세스할 수 있도록 허용","특정 IP 주소가 특정 포트에 액세스하지 못하도록 거부","TCP 및 UDP 프로토콜 지원","규칙 삽입 및 삭제","현재 규칙 상태 표시"],"es":["Configuración de reglas de acceso y denegación de tráfico de red","Compatibilidad con protocolos TCP y UDP","Posibilidad de insertar y eliminar reglas de firewall","Verificación del estado del firewall con el comando ''sudo ufw status numbered''","Permitir el acceso a puertos específicos, como el puerto 22 para SSH"],"fr":["Configuration de règles d''accès et de déni de trafic réseau","Compatibilité avec les protocoles TCP et UDP","Possibilité d''insérer et de supprimer des règles de pare-feu","Vérification de l''état du pare-feu avec la commande ''sudo ufw status numbered''","Autorisation d''accès à des ports spécifiques, tels que le port 22 pour SSH"],"de":["Konfiguration von Regeln für den Netzwerkzugriff und die Ablehnung von Netzwerkverkehr","Unterstützung für die Protokolle TCP und UDP","Möglichkeit, Regeln für die Firewall zu insertieren und zu löschen","Überprüfung des Firewall-Status mit dem Befehl ''sudo ufw status numbered''","Ermöglichung des Zugriffs auf bestimmte Ports, wie z. B. Port 22 für SSH"],"pt":["Controle de tráfego de rede com comandos como sudo ufw allow","Configuração de regras de acesso com sudo ufw deny","Suporte a protocolos TCP e UDP","Integração com firewall para controle de tráfego","Gerenciamento de regras de acesso com números de linha"],"ru":["Контроль сетевого трафика с помощью команд как sudo ufw allow","Настройка правил доступа с помощью sudo ufw deny от ИИ Агентов","Поддержка протоколов TCP и UDP","Интеграция с брандмауэром для контроля трафика","Управление правилами доступа с помощью номеров строк"],"ar":["التحكم في حركة المرور الشبكي باستخدام أوامر مثل sudo ufw allow","تثبيت قواعد الوصول باستخدام أوامر مثل sudo ufw deny مع أدوات الذكاء الاصطناعي","دعم بروتوكولات TCP و UDP","التكامل مع جدار الحماية للتحكم في حركة المرور","إدارة قواعد الوصول باستخدام أرقام الأسطر"]},"keywords":{"en":["how to use ufw","ufw setup guide","ufw vs iptables","ufw alternative","ufw install on ubuntu","what is ufw","ufw configuration best practices","ufw for linux","ufw network security"],"zh":["ufw配置","Linux防火墙","网络访问控制","ufw设置指南","服务器安全","ufw命令"],"ja":["ufw設定","Linuxファイアウォール","ネットワークアクセス制御","ufw設定ガイド","サーバーセキュリティ","ufwコマンド"],"ko":["ufw 설정","Linux 방화벽","네트워크 액세스 제어","ufw 설정 가이드","서버 보안","ufw 명령"],"es":["ufw","firewall","seguridad de red","administración de sistemas","reglas de acceso","denegación de tráfico de red","SSH","puertos de red","seguridad de servidor"],"fr":["ufw","pare-feu","sécurité réseau","administration système","règles d''accès","déni de trafic réseau","SSH","ports réseau","sécurité du serveur"],"de":["ufw","Firewall","Netzwerksicherheit","Systemadministration","Zugriffsregeln","Ablehnung von Netzwerkverkehr","SSH","Netzwerkports","Server-Sicherheit"],"pt":["ufw","controle de tráfego de rede","sudo ufw allow","sudo ufw deny","firewall","CLI","segurança de rede","configuração de rede"],"ru":["ufw","контроль сетевого трафика","sudo ufw allow","sudo ufw deny","брандмауэр","CLI","безопасность сети","настройка сети от ИИ Агентов"],"ar":["ufw","التحكم في حركة المرور الشبكي","sudo ufw allow","sudo ufw deny","جدار الحماية","واجهة سطر الأوامر","أمان الشبكة","تثبيت الشبكة مع أدوات الذكاء الاصطناعي"]}},"owner":"jyasuu","repo":"cheat-sheet","repoPath":"jyasuu/cheat-sheet","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.281Z","topics":[],"category":"community","skillMd":{"name":"ufw","description":"Uncomplicated Firewall management commands.","bodyPreview":"# ufw\n\n```bash\nsudo ufw allow from 192.168.1.0/24 to any port 22\nsudo ufw status numbered\nsudo ufw insert 1 deny from 192.168.1.0/24 to any port 80,443 proto tcp\nsudo ufw delete 1\n```","body":"# ufw\n\n```bash\nsudo ufw allow from 192.168.1.0/24 to any port 22\nsudo ufw status numbered\nsudo ufw insert 1 deny from 192.168.1.0/24 to any port 80,443 proto tcp\nsudo ufw delete 1\n```"},"lastSynced":"2026-03-08T02:00:51.266Z","agentAnalysis":{"suitability":{"en":"Ideal for Network Security Agents requiring advanced Uncomplicated Firewall configuration capabilities.","zh":"适用于需要高级 Uncomplicated Firewall 配置功能的网络安全代理。","ja":"ネットワークセキュリティエージェントが高度な Uncomplicated Firewall 構成機能を必要とする場合に最適です。","ko":"고급 Uncomplicated Firewall 구성 기능이 필요한 네트워크 보안 에이전트에 적합합니다.","es":"Ideal para agentes de seguridad de red que requieren capacidades de configuración avanzadas de Uncomplicated Firewall.","fr":"Idéal pour les agents de sécurité réseau nécessitant des capacités de configuration avancées de Uncomplicated Firewall.","de":"Ideal für Netzwerksicherheitsagenten, die erweiterte Uncomplicated Firewall-Konfigurationsfunktionen erfordern.","pt":"Ideal para Agentes de Segurança de Rede que requerem capacidades de configuração avançadas de Firewall Descomplicado.","ru":"Идеально для агентов сетевой безопасности, требующих расширенных возможностей настройки несложного брандмауэра.","ar":"مثالي لعميل أمن الشبكة الذي يتطلب قدرات متقدمة لتكوين جدار الحماية البسيط."},"recommendation":{"en":"Empowers agents to securely control incoming and outgoing network traffic using Uncomplicated Firewall rules, enabling protocol-specific filtering with TCP and UDP, and managing IP address-based access control. It provides granular control over port-based access, including allowing and denying traffic on specific ports like 22 and 80,443. This superpower is achieved through the use of commands like ''ufw allow'' and ''ufw deny'', which can be easily integrated into agent workflows.","zh":"赋予代理安全控制入站和出站网络流量的能力，使用 Uncomplicated Firewall 规则，实现基于 TCP 和 UDP 的协议特定过滤，并管理基于 IP 地址的访问控制。它提供了对基于端口的访问的细粒度控制，包括允许和拒绝特定端口（如 22 和 80,443）上的流量。这种超能力是通过使用 ''ufw allow'' 和 ''ufw deny'' 等命令实现的，这些命令可以轻松地集成到代理工作流中。","ja":"エージェントに、Uncomplicated Firewall ルールを使用して、安全に الداخ外ネットワークトラフィックを制御する能力を与え、TCP と UDP のプロトコル固有のフィルタリングを可能にし、IP アドレスベースのアクセス制御を管理します。特定のポート（たとえば 22 と 80,443）でのトラフィックを許可または拒否することを含む、ポートベースのアクセスの詳細な制御を提供します。この超能力は、''ufw allow'' や ''ufw deny'' などのコマンドを使用することで実現され、これらのコマンドはエージェントのワークフローに簡単に統合できます。","ko":"에이전트가 Uncomplicated Firewall 규칙을 사용하여 안전하게 入站 및 出站 네트워크 트래픽을 제어할 수 있는 기능을 부여하며, TCP 및 UDP를 위한 프로토콜별 필터링을 가능하게 하고, IP 주소 기반의 접근 제어를 관리합니다. 특정 포트(예: 22 및 80,443)에서 트래픽을 허용 또는 거부하는 것을 포함하여 포트 기반 접근의 세부적인 제어가 가능합니다. 이러한 슈퍼 파워는 ''ufw allow'' 및 ''ufw deny''와 같은 명령어를 사용함으로써 달성되며, 이러한 명령어는 에이전트의 워크플로에 쉽게 통합될 수 있습니다.","es":"Habilita a los agentes a controlar de forma segura el tráfico de red entrante y saliente utilizando reglas de Uncomplicated Firewall, permitiendo el filtrado específico de protocolo con TCP y UDP, y gestionando el control de acceso basado en direcciones IP. Proporciona un control granular sobre el acceso basado en puertos, incluyendo permitir y denegar tráfico en puertos específicos como 22 y 80,443. Esta superpotencia se logra mediante el uso de comandos como ''ufw allow'' y ''ufw deny'', que se pueden integrar fácilmente en los flujos de trabajo de los agentes.","fr":"Permet aux agents de contrôler de manière sécurisée le trafic réseau entrant et sortant en utilisant des règles de pare-feu Uncomplicated Firewall, permettant un filtrage spécifique de protocole avec TCP et UDP, et gérant le contrôle d''accès basé sur les adresses IP. Fournit un contrôle granulaire sur l''accès basé sur les ports, notamment en permettant et en refusant le trafic sur des ports spécifiques tels que 22 et 80,443. Ce superpouvoir est réalisé grâce à l''utilisation de commandes comme ''ufw allow'' et ''ufw deny'', qui peuvent être facilement intégrées dans les flux de travail des agents.","de":"Ermächtigt die Agenten, den eingehenden und ausgehenden Netzwerkverkehr mithilfe von Uncomplicated Firewall-Regeln sicher zu steuern, ermöglicht protokollspezifische Filterung mit TCP und UDP und verwaltet den IP-Adress-basierten Zugriffsschutz. Bietet eine granulare Kontrolle über den portbasierten Zugriff, einschließlich der Zulassung und Ablehnung von Verkehr auf bestimmten Ports wie 22 und 80,443. Diese Superkraft wird durch die Verwendung von Befehlen wie ''ufw allow'' und ''ufw deny'' erreicht, die leicht in die Arbeitsabläufe der Agenten integriert werden können.","pt":"Habilita os agentes a controlar de forma segura o tráfego de rede de entrada e saída usando regras de Firewall Descomplicado, permitindo filtragem específica de protocolo com TCP e UDP, e gerenciando controle de acesso baseado em endereço IP. Ele fornece controle granular sobre acesso baseado em porta, incluindo permitir e negar tráfego em portas específicas como 22 e 80,443. Este superpoder é alcançado por meio do uso de comandos como ''ufw allow'' e ''ufw deny'', que podem ser facilmente integrados aos fluxos de trabalho dos agentes.","ru":"Наделяет агентов возможностью безопасно контролировать входящий и исходящий сетевой трафик с помощью правил несложного брандмауэра, обеспечивая фильтрацию конкретных протоколов с помощью TCP и UDP, а также управление контролем доступа на основе адреса IP. Он предоставляет детальный контроль над доступом на основе портов, включая разрешение и запрет трафика на определенных портах, таких как 22 и 80,443. Эта сверхспособность достигается за счет использования команд, таких как ''ufw allow'' и ''ufw deny'', которые могут быть легко интегрированы в рабочие процессы агентов.","ar":"يمنح العميل سيطرة آمنة على حركة المرور القادمة والمغادرة باستخدام قواعد جدار الحماية البسيط، وتمكين التصفية النوعية للبروتوكول باستخدام TCP وUDP، وإدارة سيطرة الوصول القائمة على عنوان IP. كما يوفر سيطرة دقيقة على الوصول القائم على المنافذ، بما في ذلك السماح ورفض حركة المرور على منافذ محددة مثل 22 و 80 و 443. يتم تحقيق هذه القوة الفائقة من خلال استخدام أوامر مثل ''ufw allow'' و ''ufw deny''، والتي يمكن دمجها بسهولة في سير عمل العميل."},"useCases":{"en":["Configuring IP address-based access control for Linux-based systems","Managing protocol-specific filtering for TCP and UDP traffic","Automating firewall rule updates for dynamic network environments"],"zh":["为基于 Linux 的系统配置 IP 地址基于的访问控制","管理 TCP 和 UDP 流量的协议特定过滤","自动更新动态网络环境中的防火墙规则"],"ja":["LinuxベースのシステムのIPアドレスベースのアクセス制御を構成する","TCPおよびUDPトラフィックのプロトコル固有のフィルタリングを管理する","動的ネットワーク環境のファイアウォールルールを自動更新する"],"ko":["리눅스 기반 시스템의 IP 주소 기반 접근 제어를 구성하는 것","TCP 및 UDP 트래픽의 프로토콜별 필터링을 관리하는 것","동적 네트워크 환경의 방화벽 규칙을 자동으로 업데이트하는 것"],"es":["Configuración del control de acceso basado en direcciones IP para sistemas basados en Linux","Gestión del filtrado específico de protocolo para tráfico TCP y UDP","Automatización de actualizaciones de reglas de firewall para entornos de red dinámicos"],"fr":["Configuration du contrôle d''accès basé sur les adresses IP pour les systèmes basés sur Linux","Gestion du filtrage spécifique de protocole pour le trafic TCP et UDP","Automatisation des mises à jour des règles de pare-feu pour les environnements réseau dynamiques"],"de":["Konfiguration der IP-Adress-basierten Zugriffskontrolle für Linux-basierte Systeme","Verwaltung der protokollspezifischen Filterung für TCP- und UDP-Verkehr","Automatisierung von Firewall-Regel-Aktualisierungen für dynamische Netzumgebungen"],"pt":["Configurando controle de acesso baseado em endereço IP para sistemas baseados em Linux","Gerenciando filtragem específica de protocolo para tráfego TCP e UDP","Automatizando atualizações de regras de firewall para ambientes de rede dinâmicos"],"ru":["Настройка контроля доступа на основе адреса IP для систем на основе Linux","Управление фильтрацией конкретных протоколов для трафика TCP и UDP","Автоматизация обновлений правил брандмауэра для динамичных сетевых окружений"],"ar":["تكوين سيطرة الوصول القائمة على عنوان IP لنظم مبنية على لينكس","إدارة التصفية النوعية للبروتوكول لحركة المرور TCP وUDP","أتمتة تحديثات قواعد جدار الحماية للبيئات الشبكية الديناميكية"]},"limitations":{"en":["Requires sudo privileges for configuration","Limited to Linux-based systems","Dependent on Uncomplicated Firewall installation and setup"],"zh":["需要 sudo 权限进行配置","仅限于 Linux 基础系统","依赖于 Uncomplicated Firewall 的安装和设置"],"ja":["構成にはsudo権限が必要","Linuxベースのシステムのみに対応","Uncomplicated Firewallのインストールおよび設定に依存"],"ko":["구성하기 위해서는 sudo 권한이 필요합니다.","리눅스 기반 시스템만対応합니다.","Uncomplicated Firewall의 설치 및 설정에 의존합니다."],"es":["Requiere privilegios de sudo para la configuración","Limitado a sistemas basados en Linux","Dependiente de la instalación y configuración de Uncomplicated Firewall"],"fr":["Nécessite des privilèges sudo pour la configuration","Limité aux systèmes basés sur Linux","Dépendant de l''installation et de la configuration de Uncomplicated Firewall"],"de":["Benötigt sudo-Rechte für die Konfiguration","Begrenzt auf Linux-basierte Systeme","Abhängig von der Installation und Einrichtung von Uncomplicated Firewall"],"pt":["Requer privilégios de sudo para configuração","Limitado a sistemas baseados em Linux","Dependente da instalação e configuração do Firewall Descomplicado"],"ru":["Требует привилегий sudo для настройки","Ограничен системами на основе Linux","Зависит от установки и настройки несложного брандмауэра"],"ar":["يتطلب امتيازات sudo للتكوين","محدود بنظم مبنية على لينكس","يعتمد على تثبيت وضبط جدار الحماية البسيط"]},"version":4},"contentHash":"b0a61952d5686637265b4b83d89cc4454dc97657b65f8ad0b8acaa57a5d4f6a1","qualityScore":30}');
