INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jyasuu/cheat-sheet/ufw', 'ufw', 'jyasuu', 'cheat-sheet', 'community', 'ufw jyasuu cheat-sheet community The ufw skill enables AI agents to manage and configure Uncomplicated Firewall rules, allowing developers to securely control incoming and outgoing network traffic. It benefits developers working with network security and Linux-based systems. ufw是一种不复杂的防火墙配置工具，用于管理Linux服务器的网络访问控制 ufwはLinuxサーバーのネットワークアクセス制御を管理するためのシンプルなファイアウォール設定ツールです ufw는 Linux 서버의 네트워크 액세스 제어를 관리하는 간단한 방화벽 설정 도구입니다 ufw es una herramienta de firewall para administradores de sistemas que permite configurar reglas de acceso y denegación de tráfico de red ufw est un outil de pare-feu pour les administrateurs système qui permet de configurer des règles d''accès et de déni de trafic réseau ufw ist ein Firewall-Tool für Systemadministratoren, mit dem Regeln für den Netzwerkzugriff und die Ablehnung von Netzwerkverkehr konfiguriert werden können O ufw é uma ferramenta de controle de tráfego de rede que permite configurar regras de acesso com comandos como sudo ufw allow e sudo ufw deny ufw - это инструмент контроля сетевого трафика, который позволяет настраивать правила доступа с помощью команд như sudo ufw allow и sudo ufw deny от ИИ Агентов ufw هو أداة للتحكم في حركة المرور الشبكي التي تسمح بتثبيت قواعد الوصول باستخدام أوامر مثل sudo ufw allow و sudo ufw deny مع أدوات الذكاء الاصطناعي how to use ufw ufw setup guide ufw vs iptables ufw alternative ufw install on ubuntu what is ufw ufw configuration best practices ufw for linux ufw network security ufw配置 Linux防火墙 网络访问控制 ufw设置指南 服务器安全 ufw命令 Allows incoming traffic from specific IP addresses using the ''allow from'' command Enables port-specific rules, such as allowing SSH traffic on port 22 Supports protocol-specific rules, including TCP and UDP Provides a numbered status output for easy rule management Enables rule insertion and deletion using the ''insert'' and ''delete'' commands ufw is a command-line interface for managing firewall rules, providing an easy-to-use syntax for allowing or denying network traffic based on IP addresses, ports, and protocols.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ThibautBaissac/rails_ai_agents/rails-model-generator', 'community', 'ThibautBaissac', 'rails_ai_agents', 'ThibautBaissac/rails_ai_agents', 'rails-model-generator', 0, 0, 30, '2026-03-08T01:57:15.284Z', '2026-03-08T02:00:54.960Z', 'f209895b084d06ed2d11ffe77cd2f1ece03c12abfe99a6b77a7fecea3bdee833', '{"id":"ThibautBaissac/rails_ai_agents/rails-model-generator","name":"rails-model-generator","description":{"en":"The rails-model-generator skill creates models for Rails 8.1 development using a TDD approach, benefiting developers who follow test-driven development principles.","zh":"Rails Model Generator是一种AI驱动的开发工具，用于创建Rails 8.1模型，遵循TDD最佳实践","ja":"Rails Model Generatorは、TDDベストプラクティスに従ったRails 8.1モデルを作成するためのAI駆動開発ツールです","ko":"Rails Model Generator는 TDD 최적의 방법을 따르는 Rails 8.1 모델을 생성하기 위한 AI 구동 개발 도구입니다","es":"El generador de modelos Rails es una colección de agentes de IA especializados para desarrollo Rails 8.1, que siguen las mejores prácticas de TDD.","fr":"Le générateur de modèles Rails est un ensemble d''agents IA spécialisés pour le développement Rails 8.1, qui suivent les meilleures pratiques de TDD.","de":"Der Rails-Modellgenerator ist eine Sammlung spezialisierter KI-Agenten für Rails-8.1-Entwicklung, die den TDD-Ansatz befolgen.","pt":"O Rails Model Generator é uma coleção de agentes de IA especializados para desenvolvimento Rails 8.1, seguindo as melhores práticas de TDD.","ru":"ИИ Агент Rails Model Generator - это коллекция специализированных агентов ИИ для разработки приложений Rails 8.1, следующая лучшим практикам TDD.","ar":"جهاز إنتاج نماذج ريلز هو مجموعة من وكلاء الذكاء الاصطناعي المتخصصين لإنشاء تطبيقات ريلز 8.1، يتبع أفضل الممارسات للت اختبار."},"seo":{"title":{"en":"rails-model-generator: TDD-Compliant Model Creation for R...","zh":"Rails Model Generator Setup Guide - AIエージェント开发工具","ja":"Rails Model Generator ベストプラクティス - AIエージェントを使用した開発","ko":"Rails Model Generator 구축 가이드 - AI 에이전트 개발 도구","es":"Guía de configuración de Rails Model Generator para desar...","fr":"Configurer le générateur de modèles Rails pour le dévelop...","de":"Einrichtungsleitfaden für Rails-Modellgenerator mit TDD-A...","pt":"Guia de Configuração do Rails Model Generator para Desenv...","ru":"Настройка ИИ Агента Rails Model Generator для TDD Разработки","ar":"دليل إعداد جهاز إ产生 نماذج ريلز للتنمية القائمة على الت اخ..."},"description":{"en":"Streamline your Rails development workflow with the rails-model-generator AI agent, following TDD best practices for model creation, spec writing, and migrat...","zh":"使用Rails Model Generator实现TDD开发，自动创建模型、_specs和迁移脚本，提高开发效率","ja":"Rails Model Generatorを使用してTDD開発を実現し、モデル、_specs、移行スクリプトを自動的に生成します","ko":"Rails Model Generator를 사용하여 TDD 개발을 구현하고 모델, _specs, 마이그레이션 스크립트를 자동으로 생성하여 개발 효율성을 높입니다","es":"Descubre cómo el generador de modelos Rails puede mejorar tu desarrollo con TDD. Aprende a crear modelos de manera eficiente con este conjunto de agentes de ...","fr":"Découvrez comment le générateur de modèles Rails peut améliorer votre développement avec TDD. Apprenez à créer des modèles de manière efficace avec cet ensem...","de":"Erfahren Sie, wie der Rails-Modellgenerator Ihr Entwicklungsteam mit TDD-Ansatz unterstützen kann. Lernen Sie, Modelle effizient mit diesem Satz spezialisier...","pt":"Aprenda a usar o Rails Model Generator para desenvolver aplicações Rails 8.1 com TDD, incluindo definição de requisitos e criação de modelos","ru":"Узнайте, как использовать ИИ Агент Rails Model Generator для разработки приложений Rails 8.1 с TDD, включая определение требований и создание моделей","ar":"تعلم كيفية استخدام جهاز إنتاج نماذج ريلز لإنشاء تطبيقات ريلز 8.1 باستخدام الت اختبار، بما في ذلك تعريف المتطلبات وإنشاء النماذج"},"definition":{"en":"rails-model-generator is a specialized AI agent for generating Rails models according to TDD principles, including model specs, factory creation, and migration generation.","zh":"Rails Model Generator是一种AI工具，用于自动创建Rails模型、_specs和迁移脚本","ja":"Rails Model Generatorは、Railsモデル、_specs、移行スクリプトを自動的に生成するAIツールです","ko":"Rails Model Generator는 Rails 모델, _specs, 마이그레이션 스크립트를 자동으로 생성하는 AI 도구입니다","es":"Un generador de modelos Rails es un conjunto de herramientas de IA que facilitan la creación de modelos de datos siguiendo el enfoque de TDD.","fr":"Un générateur de modèles Rails est un ensemble d''outils IA qui facilitent la création de modèles de données en suivant l''approche TDD.","de":"Ein Rails-Modellgenerator ist eine Sammlung von KI-Tools, die die Erstellung von Datenmodellen unter Verwendung des TDD-Ansatzes erleichtern.","pt":"O que é o Rails Model Generator? É uma ferramenta de IA para desenvolvimento Rails 8.1 que segue a abordagem TDD.","ru":"Что такое ИИ Агент Rails Model Generator? Это инструмент ИИ для разработки приложений Rails 8.1, следующий подход TDD.","ar":"ما هو جهاز إنتاج نماذج ريلز؟ هو أداة ذكاء اصطناعي لإنشاء تطبيقات ريلز 8.1 يتبع نهج الت اختبار."},"features":{"en":["Defines model requirements, including attributes, validations, and associations","Writes model specs with expected behavior for RED stage","Creates factories for test data generation","Generates migrations for model implementation","Implements models to pass specs, following GREEN stage","Refactors model code as needed for optimization"],"zh":["定义模型要求（属性、验证、关联）","自动创建模型_spec以实现预期行为","生成工厂用于测试数据","创建迁移脚本","实现模型以通过_spec","重构模型（如果需要）"],"ja":["モデル要件（属性、バリデーション、関連付け）を定義する","モデル_specを自動的に生成して予期された動作を実現する","テストデータ用のファクトリを生成する","移行スクリプトを生成する","モデルを実装して_specをパスする","モデルをリファクタリングする（必要に応じて）"],"ko":["모델 요구 사항（속성, 유효성 검사, 연관성）을 정의","모델_spec을 자동으로 생성하여 예상한 동작을 구현","테스트 데이터를 위한 팩토리를 생성","마이그레이션 스크립트를 생성","모델을 구현하여 _spec을 통과","모델을 리팩토링（필요한 경우）"],"es":["Definición de requisitos de modelo (atributos, validaciones, asociaciones)","Creación de especificaciones de modelo con comportamiento esperado (RED)","Generación de fábricas para datos de prueba","Creación de migraciones","Implementación de modelos para pasar las especificaciones (GREEN)"],"fr":["Définition des exigences de modèle (attributs, validations, associations)","Création de spécifications de modèle avec comportement attendu (RED)","Génération de fabriques pour les données de test","Création de migrations","Implémentation de modèles pour passer les spécifications (GREEN)"],"de":["Definition der Modellanforderungen (Attribute, Validierungen, Assoziationen)","Erstellung von Modellspezifikationen mit erwartetem Verhalten (RED)","Generierung von Fabriken für Testdaten","Erstellung von Migrationen","Implementierung von Modellen, um die Spezifikationen zu bestehen (GREEN)"],"pt":["Definição de requisitos para modelos","Criação de modelos com TDD","Geração de migrações","Implementação de modelos para passar nos testes","Refatoração de código","Criação de fábricas para dados de teste"],"ru":["Определение требований для моделей","Создание моделей с TDD","Генерация миграций","Реализация моделей для прохождения тестов","Рефакторинг кода","Создание фабрик для тестовых данных"],"ar":["تعريف المتطلبات للنماذج","إنشاء نماذج باستخدام الت اختبار","إنتاج هجرات","تنفيذ النماذج لتمرير الاختبارات","إعادة هيكلة الكود","إنشاء مصانع للبيانات التجريبية"]},"keywords":{"en":["how to use rails-model-generator","rails-model-generator TDD approach","rails-model-generator vs scaffold","rails-model-generator install guide","what is rails-model-generator","rails-model-generator alternative for Rails 8.1","rails-model-generator setup for test-driven development","rails-model-generator migration generation","rails-model-generator spec writing","rails-model-generator factory creation"],"zh":["Rails Model Generator","TDD开发","AI驱动开发","Rails 8.1","模型生成","迁移脚本","AIエージェント开发工具"],"ja":["Rails Model Generator","TDD開発","AI駆動開発","Rails 8.1","モデル生成","移行スクリプト","AIエージェント開発ツール"],"ko":["Rails Model Generator","TDD 개발","AI 구동 개발","Rails 8.1","모델 생성","마이그레이션 스크립트","AI 에이전트 개발 도구"],"es":["generador de modelos Rails","desarrollo TDD","agentes de IA para Rails","mejores prácticas de TDD","Rails 8.1","creación de modelos de datos","especificaciones de modelo","migraciones de base de datos"],"fr":["générateur de modèles Rails","développement TDD","agents IA pour Rails","meilleures pratiques de TDD","Rails 8.1","création de modèles de données","spécifications de modèle","migrations de base de données"],"de":["Rails-Modellgenerator","TDD-Entwicklung","KI-Agenten für Rails","TDD-Best-Practices","Rails 8.1","Erstellung von Datenmodellen","Modellspezifikationen","Datenbankmigrationen"],"pt":["rails model generator","desenvolvimento tdd","rails 8.1","ia para desenvolvimento","ferramentas de ia para rails","tdd em rails","desenvolvimento ágil","test driven development"],"ru":["ии агент rails model generator","разработка с tdd","rails 8.1","ии для разработки","инструменты ии для rails","tdd в rails","гибкая разработка","test driven development"],"ar":["جهاز إنتاج نماذج ريلز","التنمية القائمة على الت اختبار","ريلز 8.1","الذكاء الاصطناعي للتنمية","أدوات الذكاء الاصطناعي لريلز","الت اختبار في ريلز","التنمية المرنة","الت اختبار الموجه"]}},"owner":"ThibautBaissac","repo":"rails_ai_agents","repoPath":"ThibautBaissac/rails_ai_agents","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.284Z","topics":[],"category":"community","skillMd":{"name":"rails-model-generator","description":"Creates Rails models using TDD approach - spec first, then migration, then model. Use when creating new models, adding model validations, defining associations, or setting up database tables.","bodyPreview":"# Rails Model Generator (TDD Approach)\n\n## Overview\n\nThis skill creates models the TDD way:\n1. Define requirements (attributes, validations, associations)\n2. Write model spec with expected behavior (RED)\n3. Create factory for test data\n4. Generate migration\n5. Implement model to pass specs (GREEN)\n6. Refactor if needed\n\n## Workflow Checklist\n\n```\nModel Creation Progress:\n- [ ] Step 1: Define requirements (attributes, validations, associations)\n- [ ] Step 2: Create model spec (RED)\n- [ ] Step 3:","body":"# Rails Model Generator (TDD Approach)\n\n## Overview\n\nThis skill creates models the TDD way:\n1. Define requirements (attributes, validations, associations)\n2. Write model spec with expected behavior (RED)\n3. Create factory for test data\n4. Generate migration\n5. Implement model to pass specs (GREEN)\n6. Refactor if needed\n\n## Workflow Checklist\n\n```\nModel Creation Progress:\n- [ ] Step 1: Define requirements (attributes, validations, associations)\n- [ ] Step 2: Create model spec (RED)\n- [ ] Step 3: Create factory\n- [ ] Step 4: Run spec (should fail - no model/table)\n- [ ] Step 5: Generate migration\n- [ ] Step 6: Run migration\n- [ ] Step 7: Create model file (empty)\n- [ ] Step 8: Run spec (should fail - no validations)\n- [ ] Step 9: Add validations and associations\n- [ ] Step 10: Run spec (GREEN)\n```\n\n## Step 1: Requirements Template\n\nBefore writing code, define the model:\n\n```markdown\n## Model: [ModelName]\n\n### Table: [table_name]\n\n### Attributes\n| Name | Type | Constraints | Default |\n|------|------|-------------|---------|\n| name | string | required, unique | - |\n| email | string | required, unique, email format | - |\n| status | integer | enum | 0 (pending) |\n| organization_id | bigint | foreign key | - |\n\n### Associations\n- belongs_to :organization\n- has_many :posts, dependent: :destroy\n- has_one :profile, dependent: :destroy\n\n### Validations\n- name: presence, uniqueness, length(max: 100)\n- email: presence, uniqueness, format(email)\n- status: inclusion in enum values\n\n### Scopes\n- active: status = active\n- recent: ordered by created_at desc\n- by_organization(org): where organization_id = org.id\n\n### Instance Methods\n- full_name: combines first_name and last_name\n- active?: checks if status is active\n\n### Callbacks\n- before_save :normalize_email\n- after_create :send_welcome_email\n```\n\n## Step 2: Create Model Spec\n\nLocation: `spec/models/[model_name]_spec.rb`\n\n```ruby\n# frozen_string_literal: true\n\nrequire ''rails_helper''\n\nRSpec.describe ModelName, type: :model do\n  subject { build(:model_name) }\n\n  # === Associations ===\n  describe ''associations'' do\n    it { is_expected.to belong_to(:organization) }\n    it { is_expected.to have_many(:posts).dependent(:destroy) }\n  end\n\n  # === Validations ===\n  describe ''validations'' do\n    it { is_expected.to validate_presence_of(:name) }\n    it { is_expected.to validate_uniqueness_of(:email).case_insensitive }\n    it { is_expected.to validate_length_of(:name).is_at_most(100) }\n  end\n\n  # === Scopes ===\n  describe ''.active'' do\n    let!(:active_record) { create(:model_name, status: :active) }\n    let!(:inactive_record) { create(:model_name, status: :inactive) }\n\n    it ''returns only active records'' do\n      expect(described_class.active).to include(active_record)\n      expect(described_class.active).not_to include(inactive_record)\n    end\n  end\n\n  # === Instance Methods ===\n  describe ''#full_name'' do\n    subject { build(:model_name, first_name: ''John'', last_name: ''Doe'') }\n\n    it ''returns combined name'' do\n      expect(subject.full_name).to eq(''John Doe'')\n    end\n  end\nend\n```\n\nSee [templates/model_spec.erb](templates/model_spec.erb) for full template.\n\n## Step 3: Create Factory\n\nLocation: `spec/factories/[model_name_plural].rb`\n\n```ruby\n# frozen_string_literal: true\n\nFactoryBot.define do\n  factory :model_name do\n    sequence(:name) { |n| \"Name #{n}\" }\n    sequence(:email) { |n| \"user#{n}@example.com\" }\n    status { :pending }\n    association :organization\n\n    trait :active do\n      status { :active }\n    end\n\n    trait :with_posts do\n      after(:create) do |record|\n        create_list(:post, 3, model_name: record)\n      end\n    end\n  end\nend\n```\n\nSee [templates/factory.erb](templates/factory.erb) for full template.\n\n## Step 4: Run Spec (Verify RED)\n\n```bash\nbundle exec rspec spec/models/model_name_spec.rb\n```\n\nExpected: Failure because model/table doesn''t exist.\n\n## Step 5: Generate Migration\n\n```bash\nbin/rails generate migration CreateModelNames \\\n  name:string \\\n  email:string:uniq \\\n  status:integer \\\n  organization:references\n```\n\nReview the generated migration and add:\n- Null constraints: `null: false`\n- Defaults: `default: 0`\n- Indexes: `add_index :table, :column`\n\n```ruby\n# db/migrate/YYYYMMDDHHMMSS_create_model_names.rb\nclass CreateModelNames < ActiveRecord::Migration[8.0]\n  def change\n    create_table :model_names do |t|\n      t.string :name, null: false\n      t.string :email, null: false\n      t.integer :status, null: false, default: 0\n      t.references :organization, null: false, foreign_key: true\n\n      t.timestamps\n    end\n\n    add_index :model_names, :email, unique: true\n    add_index :model_names, :status\n  end\nend\n```\n\n## Step 6: Run Migration\n\n```bash\nbin/rails db:migrate\n```\n\nVerify with:\n```bash\nbin/rails db:migrate:status\n```\n\n## Step 7: Create Model File\n\nLocation: `app/models/[model_name].rb`\n\n```ruby\n# frozen_string_literal: true\n\nclass ModelName < ApplicationRecord\nend\n```\n\n## Step 8: Run Spec (Still RED)\n\n```bash\nbundle exec rspec spec/models/model_name_spec.rb\n```\n\nExpected: Failures for missing validations/associations.\n\n## Step 9: Add Validations & Associations\n\n```ruby\n# frozen_string_literal: true\n\nclass ModelName < ApplicationRecord\n  # === Associations ===\n  belongs_to :organization\n  has_many :posts, dependent: :destroy\n\n  # === Enums ===\n  enum :status, { pending: 0, active: 1, suspended: 2 }\n\n  # === Validations ===\n  validates :name, presence: true,\n                   uniqueness: true,\n                   length: { maximum: 100 }\n  validates :email, presence: true,\n                    uniqueness: { case_sensitive: false },\n                    format: { with: URI::MailTo::EMAIL_REGEXP }\n\n  # === Scopes ===\n  scope :active, -> { where(status: :active) }\n  scope :recent, -> { order(created_at: :desc) }\n\n  # === Instance Methods ===\n  def full_name\n    \"#{first_name} #{last_name}\".strip\n  end\nend\n```\n\n## Step 10: Run Spec (GREEN)\n\n```bash\nbundle exec rspec spec/models/model_name_spec.rb\n```\n\nAll specs should pass.\n\n## References\n\n- See [templates/model_spec.erb](templates/model_spec.erb) for spec template\n- See [templates/factory.erb](templates/factory.erb) for factory template\n- See [reference/validations.md](reference/validations.md) for validation patterns\n\n## Common Patterns\n\n### Enum with Validation\n\n```ruby\nenum :status, { draft: 0, published: 1, archived: 2 }\nvalidates :status, inclusion: { in: statuses.keys }\n```\n\n### Polymorphic Association\n\n```ruby\nbelongs_to :commentable, polymorphic: true\n```\n\n### Counter Cache\n\n```ruby\nbelongs_to :organization, counter_cache: true\n# Add: organization.posts_count column\n```\n\n### Soft Delete\n\n```ruby\nscope :active, -> { where(deleted_at: nil) }\nscope :deleted, -> { where.not(deleted_at: nil) }\n\ndef soft_delete\n  update(deleted_at: Time.current)\nend\n```\n"},"lastSynced":"2026-03-08T02:00:54.960Z","agentAnalysis":{"suitability":{"en":"Ideal for Ruby-focused AI Agents requiring automated model generation for Rails development with a Test-Driven Development (TDD) approach","zh":"适合于需要自动模型生成的 Ruby 专注的 AI 代理，用于 Rails 开发，并采用测试驱动开发 (TDD) 方法","ja":"Ruby に焦点を当てた AI エージェントが、Rails 開発の自動モデルの生成を必要とする場合に最適です。テスト駆動開発 (TDD) アプローチを使用します","ko":"Ruby에 중점을 둔 AI 에이전트가 자동 모델 생성을 필요로 하는 Rails 개발에 적합하며, 테스트 주도 개발(TDD) 접근 방식을 사용합니다","es":"Ideal para agentes de inteligencia artificial enfocados en Ruby que requieren generación de modelos automatizados para el desarrollo de Rails con un enfoque de Desarrollo Dirigido por Pruebas (TDD)","fr":"Idéal pour les agents d''intelligence artificielle axés sur Ruby nécessitant une génération de modèles automatisée pour le développement Rails avec une approche de développement piloté par les tests (TDD)","de":"Ideal für Ruby-fokussierte KI-Agents, die eine automatisierte Modellgenerierung für die Rails-Entwicklung mit einem testgetriebenen Entwicklungsansatz (TDD) benötigen","pt":"Ideal para Agentes de IA com foco em Ruby que exigem geração automática de modelos para desenvolvimento Rails com abordagem de Desenvolvimento Dirigido por Testes (TDD)","ru":"Идеально для агентов ИИ, ориентированных на Ruby, требующих автоматизированного создания моделей для разработки на Rails с подходом Test-Driven Development (TDD)","ar":"مثالي لعميل الذكاء الاصطناعي ذي التوجه نحو روبي الذي يتطلب توليد نموذج آلي لتنمية ريلز باستخدام نهج التطوير الموجه بالاختبار (TDD)"},"recommendation":{"en":"Empowers agents to create Rails models using TDD principles, including defining requirements, writing model specs, generating migrations, and implementing models to pass specs, all while leveraging Ruby on Rails 8.1 and TDD methodologies","zh":"赋予代理创建使用 TDD 原则的 Rails 模型的能力，包括定义要求、编写模型规格、生成迁移和实现模型以通过规格，同时利用 Ruby on Rails 8.1 和 TDD 方法论","ja":"エージェントが TDD の原則を使用して Rails モデルを作成する能力を与えます。要件の定義、モデル仕様の記述、移行の生成、モデルを実装して仕様を通過するなどです。Ruby on Rails 8.1 と TDD の方法論を利用します","ko":"에이전트가 TDD 원칙을 사용하여 Rails 모델을 생성할 수 있는 능력을 부여합니다. 요구 사항 정의, 모델 사양 작성, 마이그레이션 생성 및 모델 구현을 통해 사양을 통과하는 등입니다. Ruby on Rails 8.1 및 TDD 방법론을 활용합니다","es":"Habilita a los agentes a crear modelos de Rails utilizando principios de TDD, incluyendo la definición de requisitos, la escritura de especificaciones de modelo, la generación de migraciones y la implementación de modelos para aprobar las especificaciones, todo mientras aprovecha Ruby on Rails 8.1 y las metodologías de TDD","fr":"Permet aux agents de créer des modèles Rails en utilisant les principes de TDD, y compris la définition des exigences, l''écriture de spécifications de modèle, la génération de migrations et la mise en œuvre de modèles pour passer les spécifications, le tout en exploitant Ruby on Rails 8.1 et les méthodologies de TDD","de":"Ermächtigt die Agents, Rails-Modelle unter Verwendung von TDD-Prinzipien zu erstellen, einschließlich der Definition von Anforderungen, des Schreibens von Modellspezifikationen, der Generierung von Migrationen und der Implementierung von Modellen, um die Spezifikationen zu bestehen, all dies unter Ausnutzung von Ruby on Rails 8.1 und TDD-Methoden","pt":"Habilita os agentes a criar modelos Rails usando princípios TDD, incluindo definição de requisitos, escrita de especificações de modelo, geração de migrações e implementação de modelos para passar nas especificações, tudo isso aproveitando Ruby on Rails 8.1 e metodologias TDD","ru":"Наделяет агентов возможностью создавать модели Rails с использованием принципов TDD, включая определение требований, написание спецификаций моделей, генерацию миграций и реализацию моделей для прохождения спецификаций, все это при помощи Ruby on Rails 8.1 и методологий TDD","ar":"تمكّن العميل من إنشاء نماذج ريلز باستخدام مبادئ التطوير الموجه بالاختبار، بما في ذلك تعريف المتطلبات وكتابة مواصفات النموذج وتوليد الهجرات وتنفيذ النماذج للنجاح في المواصفات، كل ذلك بالاستفادة من روبي أون ريلز 8.1 ومنهجيات التطوير الموجه بالاختبار"},"useCases":{"en":["Automating model creation for new Rails applications","Generating model specs for existing Rails projects","Streamlining TDD workflow for Rails development"],"zh":["为新 Rails 应用程序自动创建模型","为现有 Rails 项目生成模型规格","简化 Rails 开发的 TDD 工作流"],"ja":["新しい Rails アプリケーションの自動モデル作成","既存の Rails プロジェクトのモデル仕様の生成","Rails 開発の TDD ワークフローの最適化"],"ko":["새로운 Rails 애플리케이션에 대한 자동 모델 생성","기존 Rails 프로젝트에 대한 모델 사양 생성","Rails 개발을 위한 TDD 워크플로우 최적화"],"es":["Automatización de la creación de modelos para nuevas aplicaciones de Rails","Generación de especificaciones de modelo para proyectos de Rails existentes","Optimización del flujo de trabajo de TDD para el desarrollo de Rails"],"fr":["Automatisation de la création de modèles pour les 