INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ThibautBaissac/rails_ai_agents/rails-model-generator', 'rails-model-generator', 'ThibautBaissac', 'rails_ai_agents', 'community', 'rails-model-generator ThibautBaissac rails_ai_agents community The rails-model-generator skill creates models for Rails 8.1 development using a TDD approach, benefiting developers who follow test-driven development principles. Rails Model Generator是一种AI驱动的开发工具，用于创建Rails 8.1模型，遵循TDD最佳实践 Rails Model Generatorは、TDDベストプラクティスに従ったRails 8.1モデルを作成するためのAI駆動開発ツールです Rails Model Generator는 TDD 최적의 방법을 따르는 Rails 8.1 모델을 생성하기 위한 AI 구동 개발 도구입니다 El generador de modelos Rails es una colección de agentes de IA especializados para desarrollo Rails 8.1, que siguen las mejores prácticas de TDD. Le générateur de modèles Rails est un ensemble d''agents IA spécialisés pour le développement Rails 8.1, qui suivent les meilleures pratiques de TDD. Der Rails-Modellgenerator ist eine Sammlung spezialisierter KI-Agenten für Rails-8.1-Entwicklung, die den TDD-Ansatz befolgen. O Rails Model Generator é uma coleção de agentes de IA especializados para desenvolvimento Rails 8.1, seguindo as melhores práticas de TDD. ИИ Агент Rails Model Generator - это коллекция специализированных агентов ИИ для разработки приложений Rails 8.1, следующая лучшим практикам TDD. جهاز إنتاج نماذج ريلز هو مجموعة من وكلاء الذكاء الاصطناعي المتخصصين لإنشاء تطبيقات ريلز 8.1، يتبع أفضل الممارسات للت اختبار. how to use rails-model-generator rails-model-generator TDD approach rails-model-generator vs scaffold rails-model-generator install guide what is rails-model-generator rails-model-generator alternative for Rails 8.1 rails-model-generator setup for test-driven development rails-model-generator migration generation rails-model-generator spec writing rails-model-generator factory creation Rails Model Generator TDD开发 AI驱动开发 Rails 8.1 模型生成 迁移脚本 AIエージェント开发工具 Defines model requirements, including attributes, validations, and associations Writes model specs with expected behavior for RED stage Creates factories for test data generation Generates migrations for model implementation Implements models to pass specs, following GREEN stage Refactors model code as needed for optimization rails-model-generator is a specialized AI agent for generating Rails models according to TDD principles, including model specs, factory creation, and migration generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cryfs/cryfs/async-drop', 'community', 'cryfs', 'cryfs', 'cryfs/cryfs', 'async-drop', 0, 0, 30, '2026-03-08T01:57:15.291Z', '2026-03-08T02:01:01.178Z', '54e5fa7b617c82bcdefdf7f39abb3d7dcda5436deb25ba8a1814a335b341792a', '{"id":"cryfs/cryfs/async-drop","name":"async-drop","description":{"en":"The async-drop skill provides a cryptographic filesystem for the cloud, enabling async cleanup for types holding resources. It benefits developers working with async resource management","zh":"Async-Drop是一种用于云存储的加密文件系统，支持异步清理和资源释放","ja":"Async-Dropはクラウドストレージ用の暗号化ファイルシステムであり、非同期クリーンアップとリソースの解放をサポート","ko":"Async-Drop는 클라우드 저장소용 암호화 파일 시스템으로 비동기 정리 및 리소스 해제를 지원","es":"Async-drop es un patrón que permite la limpieza asíncrona para tipos que mantienen recursos que requieren una eliminación asíncrona","fr":"Async-drop est un modèle qui permet le nettoyage asynchrone pour les types qui maintiennent des ressources nécessitant une suppression asynchrone","de":"Async-drop ist ein Muster, das die asynchrone Bereinigung für Typen ermöglicht, die Ressourcen aufrechterhalten, die eine asynchrone Eliminierung erfordern","pt":"O Async-Drop é um padrão para limpeza assíncrona em Rust, permitindo a limpeza de recursos de forma eficiente","ru":"Async-Drop - это паттерн для асинхронной очистки в Rust, обеспечивающий эффективную очистку ресурсов","ar":"Async-Drop هو نمط للتنظيف التزامني في Rust، يسمح بتنظيف الموارد بفعالية"},"seo":{"title":{"en":"async-drop: Async Cleanup Setup Guide | AI Agent Skill","zh":"Async-Droppatterns Setup Guide - AIエージェント","ja":"Async-Dropパターンセットアップガイド - AIエージェント","ko":"Async-Drop 설정 가이드 - AI 에이전트","es":"Guía de configuración de async-drop para limpieza asíncrona","fr":"Guide de mise en place d''async-drop pour nettoyage asynch...","de":"Setup-Anleitung für async-drop zur asynchronen Bereinigung","pt":"Guia de Con