INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cryfs/cryfs/async-drop', 'async-drop', 'cryfs', 'cryfs', 'community', 'async-drop cryfs cryfs community The async-drop skill provides a cryptographic filesystem for the cloud, enabling async cleanup for types holding resources. It benefits developers working with async resource management Async-Drop是一种用于云存储的加密文件系统，支持异步清理和资源释放 Async-Dropはクラウドストレージ用の暗号化ファイルシステムであり、非同期クリーンアップとリソースの解放をサポート Async-Drop는 클라우드 저장소용 암호화 파일 시스템으로 비동기 정리 및 리소스 해제를 지원 Async-drop es un patrón que permite la limpieza asíncrona para tipos que mantienen recursos que requieren una eliminación asíncrona Async-drop est un modèle qui permet le nettoyage asynchrone pour les types qui maintiennent des ressources nécessitant une suppression asynchrone Async-drop ist ein Muster, das die asynchrone Bereinigung für Typen ermöglicht, die Ressourcen aufrechterhalten, die eine asynchrone Eliminierung erfordern O Async-Drop é um padrão para limpeza assíncrona em Rust, permitindo a limpeza de recursos de forma eficiente Async-Drop - это паттерн для асинхронной очистки в Rust, обеспечивающий эффективную очистку ресурсов Async-Drop هو نمط للتنظيف التزامني في Rust، يسمح بتنظيف الموارد بفعالية how to use async-drop async-drop setup guide async-drop vs synchronous cleanup async-drop install for cloud filesystems what is async-drop pattern async-drop alternative for resource management async-drop and Rust''s Drop trait async-drop for cryptographic filesystems async-drop async cleanup example Async-Drop 加密文件系统 云存储 异步清理 Rust Drop trait 非同期teardown AIエージェント Wraps values in AsyncDropGuard<T> for async cleanup Requires explicit async_drop().await calls for resource management Panics if cleanup is forgotten to ensure secure resource handling Utilizes Rust''s Drop trait for synchronous cleanup Enables async cleanup for network connections and file handles Supports background tasks for asynchronous teardown async-drop is a pattern that enables asynchronous cleanup for types holding resources, requiring async teardown, such as network connections and file handles');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('quickwit-oss/tantivy/simple-pr', 'community', 'quickwit-oss', 'tantivy', 'quickwit-oss/tantivy', 'simple-pr', 0, 0, 30, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:09.841Z', '1cfa210ff5fcefe144f4968411f8656b9874aad4e79180e54847356cefe2f390', '{"id":"quickwit-oss/tantivy/simple-pr","name":"simple-pr","description":{"en":"simple-pr automates Git workflows by creating PRs from staged changes. It benefits developers by ensuring a clean and up-to-date main branch.","zh":"Simple PR是一种基于Git的代码管理工具，帮助开发者创建和管理代码变更","ja":"Simple PRはGitベースのコード管理ツールで、開発者がコードの変更を作成して管理するのに役立ちます","ko":"Simple PR은 Git 기반의 코드 관리 도구로 개발자가 코드 변경을 생성하고 관리하는 데 도움을 줍니다","es":"Simple-pr es una herramienta para crear solicitudes de extracción simples, que verifica el estado del espacio de trabajo y actualiza la rama main antes de crear la solicitud","fr":"Simple-pr est un outil pour créer des demandes d''extraction simples, qui vérifie l''état de l''espace de travail et met à jour la branche main avant de créer la demande","de":"Simple-pr ist ein Tool zum Erstellen einfacher Pull-Anfragen, das den Arbeitsbereich überprüft und den main-Zweig aktualisiert, bevor es die Anfrage erstellt","pt":"O Simple-PR é uma ferramenta que permite criar PRs simples, seguindo os passos de verificar o estado do workspace e garantir que o branch main esteja atualizado","ru":"Simple-PR - это инструмент, который позволяет создавать простые PR, следуя шагам проверки состояния рабочего пространства и обеспечивая актуальность основной ветки для ИИ Агентов","ar":"Simple-PR هو أداة تمكن من إنشاء طلبات مراجعة بسيطة باتباع خطوات التحقق من حالة المساحة العمل وضمان تحديث الفرع الرئيسي للأدوات الذكية"},"seo":{"title":{"en":"simple-pr: Git Workflow Automation Setup Guide | AI Agent...","zh":"Simple PR_SETUP GUIDE: 基于Git的代码管理","ja":"Simple PR_SETUP GUIDE: Gitベースのコード管理","ko":"Simple PR_SETUP GUIDE: Git 기반 코드 관리","es":"Guía de configuración de simple-pr para desarrolladores","fr":"Guide de mise en place de simple-pr pour les développeurs","de":"Einrichtungsleitfaden für simple-pr für Entwickler","pt":"Guia de Configuração do Simple-PR para Desenvolvedores","ru":"Настройка Simple-PR: Руководство для Разработчиков ИИ Аге...","ar":"دليل إعداد Simple-PR للأدوات الذكية"},"description":{"en":"Streamline your Git workflow with simple-pr. Learn how to create a simple PR from staged changes and ensure your main branch is up to date. Get started now!","zh":"了解Simple PR的技术细节，包括Git状态检查和分支管理，帮助开发者高效管理代码","ja":"Simple PRの技術的詳細を学び、Gitの状態チェックとブランチ管理をマスターしてコード管理を効率化する","ko":"Simple PR의 기술적인 세부 사항을 익히고 Git 상태 확인 및 브랜치 관리를 통해 코드 관리를 효율화 하세요","es":"Aprende a crear una solicitud de extracción simple con simple-pr, incluyendo verificación del estado del espacio de trabajo y actualización de la rama main","fr":"Découvrez comment créer une demande d''extraction simple avec simple-pr, y compris la vérification de l''état de l''espace de travail et la mise à jour de la br...","de":"Erfahren Sie, wie Sie eine einfache Pull-Anfrage mit simple-pr erstellen, einschließlich Überprüfung des Arbeitsbereichs und Aktualisierung des main-Zweigs","pt":"Aprenda a criar um PR simples com o Simple-PR, uma ferramenta inspirada em Apache Lucene e escrita em Rust","ru":"Узнайте, как создать простой PR с помощью Simple-PR, библиотеки поиска текста, вдохновленной Apache Lucene и написанной на Rust для ИИ Агентов","ar":"تعرف على كيفية إنشاء طلب مراجعة بسيط مع Simple-PR، وهو محرك بحث نصي مستوحى من Apache Lucene ومكتوب بلغة Rust للأدوات الذكية"},"definition":{"en":"simple-pr is a Git workflow automation tool that creates simple PRs from staged changes, ensuring a clean and up-to-date main branch.","zh":"Simple PR是一种代码管理工具，用于创建和管理Git代码仓库的变更","ja":"Simple PRは、Gitコードリポジトリの変更を作成して管理するためのコード管理ツールです","ko":"Simple PR은 Git 코드 저장소의 변경을 생성하고 관리하기 위한 코드 관리 도구입니다","es":"Simple-pr es una herramienta de línea de comandos que automatiza la creación de solicitudes de extracción simples","fr":"Simple-pr est un outil en ligne de commande qui automatise la création de demandes d''extraction simples","de":"Simple-pr ist ein Kommandozeilen-Tool, das die Erstellung einfacher Pull-Anfragen automatisiert","pt":"O que é Simple-PR? É uma ferramenta de criação de PRs simples inspirada em Apache Lucene e escrita em Rust","ru":"Что такое Simple-PR? Это инструмент для создания простых PR, вдохновленный Apache Lucene и написанный на Rust для ИИ Агентов","ar":"ما هو Simple-PR؟ هو أداة لإنشاء طلبات مراجعة بسيطة مستوحاة من Apache Lucene ومكتوبة بلغة Rust للأدوات الذكية"},"features":{"en":["Runs `git status` to verify staged changes","Ensures main branch is up to date with `git pull origin main`","Verifies all changes are staged with no unstaged changes","Aborts if unstaged changes are found, prompting user to stage with `git add`","Switches to main branch if not already on it"],"zh":["基于Git的代码管理","自动检查Git状态","确保main分支更新","创建简单的PR","支持Git add和Git pull命令"],"ja":["Gitベースのコード管理","Git状態の自動チェック","mainブランチの更新を確保","シンプルなPRの作成","Git addとGit pullコマンドのサポート"],"ko":["Git 기반의 코드 관리","Git 상태 자동 확인","main 브랜치 업데이트를 보장","간단한 PR 생성","Git add 및 Git pull 명령어 지원"],"es":["Verificación del estado del espacio de trabajo con git status","Actualización de la rama main con git pull origin main","Creación de solicitudes de extracción simples desde cambios staged","Compatibilidad con Git","Automatización de tareas de solicitud de extracción","Integración con flujos de trabajo de desarrollo"],"fr":["Vérification de l''état de l''espace de travail avec git status","Mise à jour de la branche main avec git pull origin main","Création de demandes d''extraction simples à partir de changements staged","Compatibilité avec Git","Automatisation des tâches de demande d''extraction","Intégration avec les flux de travail de développement"],"de":["Überprüfung des Arbeitsbereichs mit git status","Aktualisierung des main-Zweigs mit git pull origin main","Erstellung einfacher Pull-Anfragen aus gestagten Änderungen","Kompatibilität mit Git","Automatisierung von Pull-Anfrage-Aufgaben","Integration in Entwicklungswerksflüsse"],"pt":["Verificação do estado do workspace","Garantia de atualização do branch main","Criação de PRs simples com Git","Integração com bibliotecas de busca de texto","Suporte à linguagem Rust"],"ru":["Проверка состояния рабочего пространства","Обеспечение актуальности основной ветки","Создание простых PR с помощью Git для ИИ Агентов","Интеграция с библиотеками поиска текста","Поддержка языка Rust"],"ar":["التحقق من حالة المساحة العمل","ضمان تحديث الفرع الرئيسي","إنشاء طلبات مراجعة بسيطة مع Git للأدوات الذكية","التكامل مع مكتبات البحث النصي","دعم لغة Rust"]},"keywords":{"en":["how to use simple-pr","simple-pr setup guide","git workflow automation","simple-pr vs git flow","simple-pr install","what is simple-pr","simple-pr alternative","git pull origin main","git status"],"zh":["Simple PR","Git代码管理","代码变更管理","AIエージェント","代码仓库管理","Git add","Git pull","代码管理工具"],"ja":["Simple PR","Gitコード管理","コード変更管理","AIエージェント","コードリポジトリ管理","Git add","Git pull","コード管理ツール"],"ko":["Simple PR","Git 코드 관리","코드 변경 관리","AI 에이전트","코드 저장소 관리","Git add","Git pull","코드 관리 도구"],"es":["simple-pr","herramientas de desarrollo","git","solicitudes de extracción","desarrollo de software","automatización de tareas","integración con git","desarrollo de aplicaciones","herramientas de línea de comandos"],"fr":["simple-pr","outils de développement","git","demandes d''extraction","développement de logiciels","automatisation de tâches","intégration avec git","développement d''applications","outils en ligne de commande"],"de":["simple-pr","Entwicklungstools","git","Pull-Anfragen","Software-Entwicklung","Automatisierung von Aufgaben","Integration mit Git","Anwendungs-Entwicklung","Kommandozeilen-Tools"],"pt":["Simple-PR","Guia de configuração","Criação de PRs","Git","Rust","Apache Lucene","Desenvolvimento de software","Ferramentas de desenvolvimento"],"ru":["Simple-PR","Настройка","Создание PR","Git","Rust","Apache Lucene","Разработка программного обеспечения","ИИ Агенты","Инструменты для разработчиков"],"ar":["Simple-PR","دليل الإعداد","إنشاء طلبات مراجعة","Git","Rust","Apache Lucene","تطوير البرمجيات","أدوات التطوير","الأدوات الذكية"]}},"owner":"quickwit-oss","repo":"tantivy","repoPath":"quickwit-oss/tantivy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"simple-pr","description":"Create a simple PR from staged changes with an auto-generated commit message","bodyPreview":"# Simple PR\n\nFollow these steps to create a simple PR from staged changes:\n\n## Step 1: Check workspace state\n\nRun: `git status`\n\nVerify that all changes have been staged (no unstaged changes). If there are unstaged changes, abort and ask the user to stage their changes first with `git add`.\n\nAlso verify that we are on the `main` branch. If not, abort and ask the user to switch to main first.\n\n## Step 2: Ensure main is up to date\n\nRun: `git pull origin main`\n\nThis ensures we''re working from the l","body":"# Simple PR\n\nFollow these steps to create a simple PR from staged changes:\n\n## Step 1: Check workspace state\n\nRun: `git status`\n\nVerify that all changes have been staged (no unstaged changes). If there are unstaged changes, abort and ask the user to stage their changes first with `git add`.\n\nAlso verify that we are on the `main` branch. If not, abort and ask the user to switch to main first.\n\n## Step 2: Ensure main is up to date\n\nRun: `git pull origin main`\n\nThis ensures we''re working from the latest code.\n\n## Step 3: Review staged changes\n\nRun: `git diff --cached`\n\nReview the staged changes to understand what the PR will contain.\n\n## Step 4: Generate commit message\n\nBased on the staged changes, generate a concise commit message (1-2 sentences) that describes the \"why\" rather than the \"what\".\n\nDisplay the proposed commit message to the user and ask for confirmation before proceeding.\n\n## Step 5: Create a new branch\n\nGet the git username: `git config user.name | tr '' '' ''-'' | tr ''[:upper:]'' ''[:lower:]''`\n\nCreate a short, descriptive branch name based on the changes (e.g., `fix-typo-in-readme`, `add-retry-logic`, `update-deps`).\n\nCreate and checkout the branch: `git checkout -b {username}/{short-descriptive-name}`\n\n## Step 6: Commit changes\n\nCommit with the message from step 3:\n```\ngit commit -m \"{commit-message}\"\n```\n\n## Step 7: Push and open a PR\n\nPush the branch and open a PR:\n```\ngit push -u origin {branch-name}\ngh pr create --title \"{commit-message-title}\" --body \"{longer-description-if-needed}\"\n```\n\nReport the PR URL to the user when complete.\n"},"lastSynced":"2026-03-08T02:01:09.841Z","agentAnalysis":{"suitability":{"en":"Perfect for Git Workflow Agents needing automated PR creation from staged changes.","zh":"适合需要从暂存更改自动创建PR的Git Workflow代理。","ja":"ステージングされた変更から自動的にPRを作成する必要があるGit Workflowエージェントに適しています。","ko":"暂存된 변경 사항에서 자동으로 PR을 생성해야 하는 Git Workflow 에이전트에 적합합니다.","es":"Perfecto para agentes de flujo de trabajo de Git que necesitan la creación automática de PR desde cambios en espera.","fr":"Parfait pour les agents de workflow Git ayant besoin de la création automatique de PR à partir de modifications en attente.","de":"Perfekt für Git-Workflow-Agents, die eine automatisierte PR-Erstellung aus gestagten Änderungen benötigen.","pt":"Perfeito para Agentes de Fluxo de Trabalho do Git que necessitam de criação automática de PR a partir de alterações em stage.","ru":"Идеально подходит для агентов рабочего процесса Git, которым требуется автоматическое создание PR из изменений в стадии.","ar":"مثالي لعمليات وكيل تدفق العمل Git التي تحتاج إلى إنشاء طلبات سحب أتمتيكية من التغييرات في المرحلة."},"recommendation":{"en":"Empowers agents to automate Git workflows by creating PRs from staged changes using Git commands like `git status` and `git pull`, ensuring a clean and up-to-date main branch via protocols like Git over SSH or HTTPS.","zh":"通过使用Git命令（如`git status`和`git pull`）从暂存更改创建PR，实现Git工作流的自动化，同时通过SSH或HTTPS等协议确保主分支的干净和更新。","ja":"ステージングされた変更からPRを作成するために、`git status`や`git pull`などのGitコマンドを使用し、SSHまたはHTTPSなどのプロトコルを使用してメインブランチをクリーンで最新の状態に保ちつつ、Gitワークフローの自動化を実現します。","ko":"暂存된 변경 사항에서 PR을 생성하기 위해 `git status` 및 `git pull`과 같은 Git 명령을 사용하고 SSH 또는 HTTPS와 같은 프로토콜을 사용하여 메인 브랜치가 깨끗하고 최신 상태로 유지되도록 하여 Git 워크플로우의 자동화를 실현합니다.","es":"Habilita a los agentes a automatizar flujos de trabajo de Git creando PR desde cambios en espera utilizando comandos de Git como `git status` y `git pull`, asegurando una rama principal limpia y actualizada a través de protocolos como Git sobre SSH o HTTPS.","fr":"Permet aux agents d''automatiser les workflows Git en créant des PR à partir de modifications en attente en utilisant des commandes Git comme `git status` et `git pull`, garantissant une branche principale propre et à jour via des protocoles comme Git sur SSH ou HTTPS.","de":"Ermöglicht es den Agents, Git-Workflows zu automatisieren, indem PRs aus gestagten Änderungen erstellt werden, indem Git-Befehle wie `git status` und `git pull` verwendet werden, um eine saubere und aktuelle Hauptverzweigung über Protokolle wie Git über SSH oder HTTPS sicherzustellen.","pt":"Habilita os agentes a automatizar fluxos de trabalho do Git criando PRs a partir de alterações em stage usando comandos Git como `git status` e `git pull`, garantindo uma branch principal limpa e atualizada por meio de protocolos como Git sobre SSH ou HTTPS.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы Git, создавая PR из изменений в стадии с помощью команд Git, таких как `git status` и `git pull`, обеспечивая чистую и актуальную основную ветку через протоколы, такие как Git по SSH или HTTPS.","ar":"يمنح الوكلاء القدرة على تطبيق العمليات الآلية على تدفقات العمل Git من خلال إنشاء طلبات سحب من التغييرات في المرحلة باستخدام أوامر Git مثل `git status` و `git pull`، وضمان فرع رئيسي نظيف ومحدث بواسطة بروتوكولات مثل Git عبر SSH أو HTTPS."},"useCases":{"en":["Automating PR creation from staged changes","Ensuring main branch is up-to-date with `git pull origin main`","Verifying workspace state with `git status` before creating PRs"],"zh":["从暂存更改自动创建PR","使用`git pull origin main`确保主分支是最新的","在创建PR之前使用`git status`验证工作空间状态"],"ja":["ステージングされた変更からPRを作成する自動化","`git pull origin main`を使用してメインブランチが最新であることを確認する","PRを作成する前に`git status`を使用してワークスペースの状態を確認する"],"ko":["暂存된 변경 사항에서 PR을 자동으로 생성하는 것","`git pull origin main`을 사용하여 메인 브랜치가 최신인지 확인","PR을 생성하기 전에 `git status`를 사용하여 워크스페이스의 상태를 확인"],"es":["Automatizar la creación de PR desde cambios en espera","Asegurar que la rama principal esté actualizada con `git pull origin main`","Verificar el estado del espacio de trabajo con `git status` antes de crear PR"],"fr":["Automatiser la création de PR à partir de modifications en attente","Assurer que la branche principale est à jour avec `git pull origin main`","Vérifier l''état de l''espace de travail avec `git status` avant de créer des PR"],"de":["Automatisieren der PR-Erstellung aus gestagten Änderungen","Sicherstellen, dass die Hauptverzweigung mit `git pull origin main` aktualisiert ist","Überprüfen des Arbeitsbereichszustands mit `git status` vor der Erstellung von PRs"],"pt":["Automatizar a criação de PR a partir de alterações em stage","Garantir que a branch principal esteja atualizada com `git pull origin main`","Verificar o estado do espaço de trabalho com `git status` antes de criar PRs"],"ru":["Автоматизировать создание PR из изменений в стадии","Обеспечить актуальность основной ветки с помощью `git pull origin main`","Проверить состояние рабочего пространства с помощью `git status` перед созданием PR"],"ar":["تطبيق العمليات الآلية لإنشاء طلبات سحب من التغييرات في المرحلة","ضمان تحديث الفرع الرئيسي بواسطة `git pull origin main`","التحقق من حالة مساحة العمل باستخدام `git status` قبل إنشاء طلبات سحب"]},"limitations":{"en":["Requires Git installation and configuration","Needs to be on the main branch to function correctly","Aborts if there are unstaged changes or if not on the main branch"],"zh":["需要Git的安装和配置","需要在主分支上才能正常工作","如果有未暂存的更改或不在主分支上，则会中止"],"ja":["Gitのインストールと設定が必要","正常に機能するにはメインブランチ上にいる必要がある","ステージングされていない変更がある場合、またはメインブランチ上にいない場合、処理は中止される"],"ko":["Git 설치 및 구성이 필요","정상적으로 작동하려면 메인 브랜치에 있어야 함","暂存되지 않은 변경 사항이 있거나 메인 브랜치에 있지 않은 경우, 처리가 중단"],"es":["Requiere instalación y configuración de Git","Necesita estar en la rama principal para funcionar correctamente","Abandona si hay cambios no en espera o si no está en la rama principal"],"fr":["Nécessite l''installation et la configuration de Git","Doit être sur la branche principale pour fonctionner correctement","Abandonne si des modifications non en attente sont présentes ou si ce n''est pas sur la branche principale"],"de":["Benötigt die Installation und Konfiguration von Git","Muss sich auf der Hauptverzweigung befinden, um korrekt zu funktionieren","Abbricht, wenn es nicht gestagte Änderungen gibt oder wenn es sich nicht auf der Hauptverzweigung befindet"],"pt":["Requer instalação e configuração do Git","Precisa estar na branch principal para funcionar corretamente","Aborta se houver alterações não em stage ou se não estiver na branch principal"],"ru":["Требует установки и настройки Git","Должен быть на основной ветке, чтобы функционировать правильно","Прерывает работу, если есть не зафиксированные изменения или если не находится на основной ветке"],"ar":["يتطلب تثبيت وتهيئة Git","يجب أن يكون على الفرع الرئيسي ليعمل بشكل صحيح","يلغي إذا كانت هناك تغييرات غير مرحلة أو إذا لم يكن على الفرع الرئيسي"]},"version":4},"contentHash":"1cfa210ff5fcefe144f4968411f8656b9874aad4e79180e54847356cefe2f390","qualityScore":30}');
