INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('quickwit-oss/tantivy/simple-pr', 'simple-pr', 'quickwit-oss', 'tantivy', 'community', 'simple-pr quickwit-oss tantivy community simple-pr automates Git workflows by creating PRs from staged changes. It benefits developers by ensuring a clean and up-to-date main branch. Simple PR是一种基于Git的代码管理工具，帮助开发者创建和管理代码变更 Simple PRはGitベースのコード管理ツールで、開発者がコードの変更を作成して管理するのに役立ちます Simple PR은 Git 기반의 코드 관리 도구로 개발자가 코드 변경을 생성하고 관리하는 데 도움을 줍니다 Simple-pr es una herramienta para crear solicitudes de extracción simples, que verifica el estado del espacio de trabajo y actualiza la rama main antes de crear la solicitud Simple-pr est un outil pour créer des demandes d''extraction simples, qui vérifie l''état de l''espace de travail et met à jour la branche main avant de créer la demande Simple-pr ist ein Tool zum Erstellen einfacher Pull-Anfragen, das den Arbeitsbereich überprüft und den main-Zweig aktualisiert, bevor es die Anfrage erstellt O Simple-PR é uma ferramenta que permite criar PRs simples, seguindo os passos de verificar o estado do workspace e garantir que o branch main esteja atualizado Simple-PR - это инструмент, который позволяет создавать простые PR, следуя шагам проверки состояния рабочего пространства и обеспечивая актуальность основной ветки для ИИ Агентов Simple-PR هو أداة تمكن من إنشاء طلبات مراجعة بسيطة باتباع خطوات التحقق من حالة المساحة العمل وضمان تحديث الفرع الرئيسي للأدوات الذكية how to use simple-pr simple-pr setup guide git workflow automation simple-pr vs git flow simple-pr install what is simple-pr simple-pr alternative git pull origin main git status Simple PR Git代码管理 代码变更管理 AIエージェント 代码仓库管理 Git add Git pull 代码管理工具 Runs `git status` to verify staged changes Ensures main branch is up to date with `git pull origin main` Verifies all changes are staged with no unstaged changes Aborts if unstaged changes are found, prompting user to stage with `git add` Switches to main branch if not already on it simple-pr is a Git workflow automation tool that creates simple PRs from staged changes, ensuring a clean and up-to-date main branch.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jkomoros/community-patterns/git-workflow', 'community', 'jkomoros', 'community-patterns', 'jkomoros/community-patterns', 'git-workflow', 0, 0, 30, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:16.809Z', '93afdccefe7bfc409a118d9c2f528d039a88cbd699068a15b4beba781eadca1e', '{"id":"jkomoros/community-patterns/git-workflow","name":"git-workflow","description":{"en":"The git-workflow skill helps developers manage their Git repositories by providing patterns for committing, updating, and sharing work. It benefits developers working on community-driven projects.","zh":"Git Workflow 是一个社区创建的模式仓库，提供提交、更新和创建 Pull Requests 的步骤","ja":"Git Workflow はコミュニティによって作成されたパターンリポジトリであり、コミット、更新、プルリクエストの作成の手順を提供します","ko":"Git Workflow는 커뮤니티에서 생성한 패턴仓库로 커밋, 업데이트, 풀リクエ스트 생성의 단계를 제공합니다","es":"El flujo de trabajo Git es una forma de colaborar en proyectos de código abierto. Utiliza comandos como ''git add'' y ''git commit'' para realizar cambios y compartirlos","fr":"Le flux de travail Git est un moyen de collaborer sur des projets de code source ouvert. Il utilise des commandes comme ''git add'' et ''git commit'' pour effectuer des modifications et les partager","de":"Der Git-Workflow ist eine Möglichkeit, an Open-Source-Projekten zu arbeiten. Er verwendet Befehle wie ''git add'' und ''git commit'', um Änderungen vorzunehmen und sie zu teilen","pt":"O fluxo de trabalho Git é um repositório de padrões criados pela comunidade. Aprenda a committar, atualizar e compartilhar trabalho upstream","ru":"Поток работы Git - это репозиторий шаблонов, созданных сообществом. Узнайте, как фиксировать, обновлять и делиться работой upstream","ar":"Fluxo de Trabalho Git هو مستودع لأنماط تم إنشاؤها من قبل المجتمع. تعلم كيف committar، وتحديث ومشاركة العمل upstream"},"seo":{"title":{"en":"git-workflow: Git Repository Management Setup Guide | AI ...","zh":"Git Workflow 设置指南 - AIエージェント工具","ja":"Git Workflow ベストプラクティス - AIエージェント","ko":"Git Workflow 설정 가이드 - AI 에이전트 도구","es":"Guía de Configuración de Flujo de Trabajo Git","fr":"Guide de Configuration du Flux de Travail Git","de":"Git-Workflow-Setup-Anleitung","pt":"Guia de Configuração do Fluxo de Trabalho Git","ru":"Настройка Потока Работы Git: ИИ Агенты","ar":"إعداد Fluxo de Trabalho Git: أدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to manage your Git repository with ease using the git-workflow skill. Discover how to commit, update, and share your work efficiently.","zh":"学习 Git Workflow 的设置和最佳实践，包括提交、更新和创建 Pull Requests 的步骤，使用 AIエージェント工具提高开发效率","ja":"Git Workflow の設定とベストプラクティスを学び、コミット、更新、プルリクエストの作成をマスターして、AIエージェントを使用して開発効率を向上させる","ko":"Git Workflow 설정과最佳实践을 학습하고, 커밋, 업데이트, 풀リクエ스트 생성을 마스터하여 AI 에이전트 도구를 사용하여 개발 효율성을 높이세요","es":"Aprende a configurar y utilizar el flujo de trabajo Git para colaborar en proyectos de código abierto con nuestros patrones y ejemplos prácticos","fr":"Découvrez comment configurer et utiliser le flux de travail Git pour collaborer sur des projets de code source ouvert avec nos modèles et exemples pratiques","de":"Erfahren Sie, wie Sie den Git-Workflow konfigurieren und verwenden, um an Open-Source-Projekten mit unseren Mustern und Praxisbeispielen zu arbeiten","pt":"Aprenda a configurar o fluxo de trabalho Git com padrões criados pela comunidade. Veja como committar, atualizar e compartilhar trabalho upstream","ru":"Узнайте, как настроить поток работы Git с помощью шаблонов, созданных сообществом. Посмотрите, как фиксировать, обновлять и делиться работой upstream с помощ...","ar":"تعلم كيفية إعداد Fluxo de Trabalho Git باستخدام الأنماط التي-created من قبل المجتمع. انظر كيف committar، وتحديث ومشاركة العمل upstream مع أدوات الذكاء الاصطناعي"},"definition":{"en":"git-workflow is a repository management skill that provides patterns for Git workflow, enabling developers to efficiently commit, update, and share their work.","zh":"Git Workflow 是一个用于管理 Git 仓库的工作流程，包括提交、更新和创建 Pull Requests 的步骤","ja":"Git Workflow は Git リポジトリを管理するためのワークフローであり、コミット、更新、プルリクエストの作成の手順を定義します","ko":"Git Workflow는 Git仓库를 관리하는 작업 흐름으로 커밋, 업데이트, 풀リクエ스트 생성의 단계를 정의합니다","es":"El flujo de trabajo Git es un conjunto de patrones y procesos para colaborar en proyectos de código abierto utilizando Git","fr":"Le flux de travail Git est un ensemble de modèles et de processus pour collaborer sur des projets de code source ouvert en utilisant Git","de":"Der Git-Workflow ist eine Sammlung von Mustern und Prozessen zur Zusammenarbeit an Open-Source-Projekten mit Git","pt":"O fluxo de trabalho Git é um conjunto de padrões e práticas para gerenciar o código-fonte","ru":"Поток работы Git - это набор шаблонов и практик для управления исходным кодом","ar":"Fluxo de Trabalho Git هو مجموعة من الأنماط والممارسات لإدارة الكود المصدري"},"features":{"en":["Commits work using `git add` and `git commit` commands","Updates repositories using `git fetch` and `git pull` commands","Shares work upstream by creating pull requests","Uses `git push` to update the origin main branch","Follows a specific commit message format for clarity","Requires manual approval before creating pull requests"],"zh":["使用 Git 命令行工具提交和更新代码","创建 Pull Requests 并等待审查","使用 Git Fetch 和 Git Pull 命令更新代码","使用 Git Commit 和 Git Push 命令提交代码","支持多个 Git 仓库和分支"],"ja":["Git コマンドラインツールを使用してコードをコミットして更新する","プルリクエストを作成してレビュー待ちする","Git Fetch と Git Pull コマンドを使用してコードを更新する","Git Commit と Git Push コマンドを使用してコードをコミットする","複数の Git リポジトリとブランチをサポートする"],"ko":["Git 명령줄 도구를 사용하여 코드를 커밋하고 업데이트하는 기능","풀リクエ스트를 생성하고審查를 기다리는 기능","Git Fetch와 Git Pull 명령을 사용하여 코드를 업데이트하는 기능","Git Commit과 Git Push 명령을 사용하여 코드를 커밋하는 기능","複数의 Git仓库와 브랜치를 지원하는 기능"],"es":["Utiliza ''git add'' para agregar cambios","Utiliza ''git commit'' para confirmar cambios","Utiliza ''git push'' para compartir cambios","Utiliza ''git fetch'' y ''git pull'' para obtener actualizaciones","Crea solicitudes de extracción (pull requests) para compartir cambios"],"fr":["Utilisez ''git add'' pour ajouter des modifications","Utilisez ''git commit'' pour valider des modifications","Utilisez ''git push'' pour partager des modifications","Utilisez ''git fetch'' et ''git pull'' pour obtenir des mises à jour","Créez des demandes d''extraction (pull requests) pour partager des modifications"],"de":["Verwenden Sie ''git add'', um Änderungen hinzuzufügen","Verwenden Sie ''git commit'', um Änderungen zu bestätigen","Verwenden Sie ''git push'', um Änderungen zu teilen","Verwenden Sie ''git fetch'' und ''git pull'', um Updates zu erhalten","Erstellen Sie Pull-Requests, um Änderungen zu teilen"],"pt":["Committar trabalho com git add e git commit","Atualizar repositório com git fetch e git pull","Compartilhar trabalho upstream com git push e pull requests","Uso de padrões criados pela comunidade","Suporte a múltiplos repositórios com git remote"],"ru":["Фиксирование работы с помощью git add и git commit","Обновление репозитория с помощью git fetch и git pull","Обмен работой upstream с помощью git push и pull requests","Использование шаблонов, созданных сообществом","Поддержка нескольких репозиториев с помощью git remote"],"ar":["committar العمل مع git add و git commit","تحديث المستودع مع git fetch و git pull","مشاركة العمل upstream مع git push و pull requests","استخدام الأنماط التي-created من قبل المجتمع","دعم متعدد المستودعات مع git remote"]},"keywords":{"en":["git-workflow setup guide","how to use git-workflow","git repository management","git workflow patterns","git-workflow vs git flow","git-workflow install","git-workflow tutorial","git workflow best practices","git-workflow alternative"],"zh":["Git Workflow","AIエージェント工具","Git 命令行工具","Pull Requests","Git Fetch","Git Pull","Git Commit","Git Push","代码管理"],"ja":["Git Workflow","AIエージェント","Git コマンドラインツール","プルリクエスト","Git Fetch","Git Pull","Git Commit","Git Push","コード管理"],"ko":["Git Workflow","AI 에이전트 도구","Git 명령줄 도구","풀リクエ스트","Git Fetch","Git Pull","Git Commit","Git Push","코드 관리"],"es":["flujo de trabajo git","colaboración en proyectos de código abierto","git add","git commit","git push","git fetch","git pull","solicitudes de extracción","herramientas de desarrollo de software"],"fr":["flux de travail git","collaboration sur des projets de code source ouvert","git add","git commit","git push","git fetch","git pull","demandes d''extraction","outils de développement de logiciels"],"de":["git-workflow","zusammenarbeit an open-source-projekten","git add","git commit","git push","git fetch","git pull","pull-requests","software-entwicklungstools"],"pt":["fluxo de trabalho git","padrões de código","committar trabalho","atualizar repositório","compartilhar trabalho upstream","git add","git commit","git fetch","git pull","pull requests"],"ru":["поток работы git","шаблоны кода","фиксирование работы","обновление репозитория","обмен работой upstream","git add","git commit","git fetch","git pull","pull requests"],"ar":["fluxo de trabalho git","أنماط الكود","committar العمل","تحديث المستودع","مشاركة العمل upstream","git add","git commit","git fetch","git pull","pull requests"]}},"owner":"jkomoros","repo":"community-patterns","repoPath":"jkomoros/community-patterns","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"git-workflow","description":">","bodyPreview":"# Git Workflow\n\n## Committing Work\n\n```bash\ncd ~/Code/community-patterns\n\ngit add patterns/$GITHUB_USER/pattern.tsx\ngit commit -m \"Add pattern: description\"\ngit push origin main\n```\n\n## Getting Updates (Already done in Step 1)\n\n```bash\ngit fetch upstream\ngit pull --rebase upstream main\ngit push origin main\n```\n\n## Sharing Work Upstream (Creating Pull Requests)\n\n**IMPORTANT: Wait for user to tell you to create a PR.** Don''t push or create PRs automatically.\n\n**Before creating any PR, you MUST upd","body":"# Git Workflow\n\n## Committing Work\n\n```bash\ncd ~/Code/community-patterns\n\ngit add patterns/$GITHUB_USER/pattern.tsx\ngit commit -m \"Add pattern: description\"\ngit push origin main\n```\n\n## Getting Updates (Already done in Step 1)\n\n```bash\ngit fetch upstream\ngit pull --rebase upstream main\ngit push origin main\n```\n\n## Sharing Work Upstream (Creating Pull Requests)\n\n**IMPORTANT: Wait for user to tell you to create a PR.** Don''t push or create PRs automatically.\n\n**Before creating any PR, you MUST update from main and rebase your branch:**\n\n### Step 0: Update and Rebase Before Creating PR\n\n**Use cached repository type from workspace config:**\n\n```bash\n# Read IS_FORK from .claude-workspace (set during Step 2)\nIS_FORK=$(grep \"^is_fork=\" .claude-workspace | cut -d= -f2)\n\n# Determine which remote to use\nif [ \"$IS_FORK\" = \"true\" ]; then\n  echo \"Working on fork - will fetch from upstream\"\n  MAIN_REMOTE=\"upstream\"\nelse\n  echo \"Working on main repo - will fetch from origin\"\n  MAIN_REMOTE=\"origin\"\nfi\n```\n\n**Then fetch latest main and rebase your branch:**\n\n```bash\n# Fetch latest main\ngit fetch $MAIN_REMOTE\n\n# Rebase current branch on top of main\ngit rebase $MAIN_REMOTE/main\n\n# If rebase succeeds, push (force-with-lease if on feature branch)\nif [ \"$(git branch --show-current)\" != \"main\" ]; then\n  git push origin $(git branch --show-current) --force-with-lease\nelse\n  git push origin main\nfi\n```\n\n**If rebase has conflicts:**\n1. Show conflict files: `git status`\n2. Help resolve conflicts\n3. Continue: `git rebase --continue`\n4. Then push\n\n**Why this matters:**\n- Ensures your PR is based on the latest main\n- Avoids merge conflicts during PR review\n- Makes PR review easier\n\n---\n\n### If User Has Their Own Fork (Most Common)\n\nWhen user wants to contribute patterns from their fork to upstream:\n\n**Step 1: Ensure changes are committed and pushed to their fork**\n```bash\ncd ~/Code/community-patterns\ngit status  # Verify all changes are committed\ngit push origin main\n```\n\n**Step 2: Update and rebase (see Step 0 above)**\n\n**Step 3: Create pull request to upstream**\n```bash\ngh pr create \\\n  --repo jkomoros/community-patterns \\\n  --title \"Add: pattern name\" \\\n  --body \"$(cat <<''EOF''\n## Summary\n- Brief description of the pattern\n- Key features\n- Use cases\n\n## Testing\n- [x] Pattern compiles without errors\n- [x] Tested in browser at http://localhost:8000\n- [x] All features working as expected\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\nEOF\n)\"\n```\n\n### If Working Directly on jkomoros/community-patterns\n\n**CRITICAL: When working directly on the upstream repository, you MUST use branches and PRs. Direct pushes to main are NOT allowed.**\n\n**Step 1: Create feature branch**\n```bash\ncd ~/Code/community-patterns\ngit checkout -b username/feature-name\n```\n\n**Step 2: Commit and push branch**\n```bash\ngit add patterns/$GITHUB_USER/\ngit commit -m \"Add: pattern name\"\ngit push origin username/feature-name\n```\n\n**Step 3: Update and rebase (see Step 0 above)**\n\n**Step 4: Create pull request**\n```bash\ngh pr create \\\n  --title \"Add: pattern name\" \\\n  --body \"$(cat <<''EOF''\n## Summary\n- Brief description\n\n## Testing\n- [x] Tested and working\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\nEOF\n)\"\n```\n\n**Step 5: Merge with rebase (when approved)**\n```bash\ngh pr merge PR_NUMBER --rebase --delete-branch\n```\n\n### Important Notes\n\n- **Always wait for user permission** before creating PRs\n- **All PRs are merged with `--rebase`** (NOT `--squash` or `--merge`)\n- This preserves individual commit history\n- Commit frequently locally, but only create PR when user asks\n- PRs will be reviewed before merging to upstream\n- After merge, everyone gets your patterns automatically on next update\n"},"lastSynced":"2026-03-08T02:01:16.809Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Management Agents requiring automated Git repository updates and collaborative workflow management.","zh":"适用于需要自动化Git仓库更新和协作工作流管理的代码管理代理。","ja":"コード管理エージェントが自動化されたGitリポジトリの更新と共同のワークフロー管理を必要とする場合に適しています。","ko":"自动화된 Git 저장소 업데이트와 협업 워크플로 관리가 필요한 코드 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de código que requieren actualizaciones automatizadas de repositorios Git y gestión de flujos de trabajo colaborativos.","fr":"Idéal pour les agents de gestion de code nécessitant des mises à jour automatiques de référentiels Git et une gestion de workflow collaboratif.","de":"Ideal für Code-Management-Agents, die automatisierte Git-Repository-Updates und collaborative Workflow-Management erfordern.","pt":"Ideal para Agentes de Gerenciamento de Código que exigem atualizações automatizadas de repositórios Git e gerenciamento de fluxo de trabalho colaborativo.","ru":"Идеально для агентов управления кодом, требующих автоматического обновления репозиториев Git и управления совместным рабочим процессом.","ar":"مثالي للوكلاء إدارة الكود الذين يتطلبون تحديثات مستودع Git أتمتيكي وإدارة تدفق عمل تعاوني."},"recommendation":{"en":"Empowers agents to manage Git repositories efficiently using Git commands like git add, git commit, and git push, facilitating seamless collaboration and version control through protocols like Git fetch and Git pull.","zh":"赋予代理管理Git仓库的效率，使用Git命令，如git add、git commit和git push，通过Git fetch和Git pull等协议实现无缝的协作和版本控制。","ja":"Git add、Git commit、Git pushなどのGitコマンドを使用して、エージェントがGitリポジトリを効率的に管理できるようにし、Git fetchやGit pullなどのプロトコルを介して無縫のコラボレーションとバージョン管理を実現します。","ko":"Git add, Git commit, Git push와 같은 Git 명령을 사용하여 에이전트가 Git 저장소를 효율적으로 관리할 수 있도록 하며, Git fetch 및 Git pull과 같은 프로토콜을 통해 무결점의 협업 및 버전 관리를 구현합니다.","es":"Habilita a los agentes a gestionar los repositorios Git de manera eficiente utilizando comandos Git como git add, git commit y git push, lo que facilita la colaboración y el control de versiones a través de protocolos como Git fetch y Git pull.","fr":"Permet aux agents de gérer les référentiels Git de manière efficace en utilisant des commandes Git comme git add, git commit et git push, ce qui facilite la collaboration et le contrôle de version via des protocoles comme Git fetch et Git pull.","de":"Ermächtigt die Agenten, Git-Repositorys effizient zu verwalten, indem sie Git-Befehle wie git add, git commit und git push verwenden, wodurch eine nahtlose Zusammenarbeit und Versionskontrolle durch Protokolle wie Git fetch und Git pull ermöglicht wird.","pt":"Habilita os agentes a gerenciar repositórios Git de forma eficiente usando comandos Git como git add, git commit e git push, facilitando a colaboração sem interrupções e o controle de versão por meio de protocolos como Git fetch e Git pull.","ru":"Позволяет агентам эффективно управлять репозиториями Git, используя команды Git, такие как git add, git commit и git push, что облегчает бесперебойное сотрудничество и контроль версий через протоколы, такие как Git fetch и Git pull.","ar":"يمكن الوكلاء من إدارة مستودعات Git بشكل فعال باستخدام أوامر Git مثل git add و git commit و git push، وتسهيل التعاون بدون انقطاع ومراقبة الإصدار من خلال بروتوكولات مثل Git fetch و Git pull."},"useCases":{"en":["Automating commit messages with descriptive updates","Updating local repositories with upstream changes using git fetch and git pull","Creating pull requests for community-driven projects"],"zh":["使用描述性更新自动化提交消息","使用git fetch和git pull更新本地仓库以获取上游更改","为社区驱动的项目创建拉取请求"],"ja":["記述的な更新を使用してコミットメッセージを自動化する","Git fetchとGit pullを使用してローカルリポジトリを上流の変更で更新する","コミュニティ駆動のプロジェクトのためにプルリクエストを作成する"],"ko":["기술적인 업데이트를 사용하여 커밋 메시지를 자동화하는 것","Git fetch 및 Git pull을 사용하여 로컬 저장소를 업스트림 변경으로 업데이트하는 것","커뮤니티 주도 프로젝트를 위한 풀 리퀘스트 만들기"],"es":["Automatizar mensajes de confirmación con actualizaciones descriptivas","Actualizar repositorios locales con cambios de origen utilizando git fetch y git pull","Crear solicitudes de extracción para proyectos impulsados por la comunidad"],"fr":["Automatiser les messages de validation avec des mises à jour descriptives","Mettre à jour les référentiels locaux avec les modifications en amont en utilisant git fetch et git pull","Créer des demandes d''extraction pour les projets pilotés par la communauté"],"de":["Automatisieren von Commit-Nachrichten mit beschreibenden Updates","Aktualisieren von lokalen Repositorys mit Upstream-Änderungen unter Verwendung von git fetch und git pull","Erstellen von Pull-Requests für community-getriebene Projekte"],"pt":["Automatizar mensagens de commit com atualizações descritivas","Atualizar repositórios locais com alterações upstream usando git fetch e git pull","Criar solicitações de pull para projetos impulsionados pela comunidade"],"ru":["Автоматизировать сообщения о коммитах с описательными обновлениями","Обновлять локальные репозитории с изменениями upstream, используя git fetch и git pull","Создавать запросы на pull для проектов, управляемых сообществом"],"ar":["تحديث رسائل الالتزام تلقائيًا مع تحديثات وصفية","تحديث مستودعات محلية بالتغيرات المستقبلية باستخدام git fetch و git pull","إنشاء طلبات سحب لمشاريع مدفوعة بالمجتمع"]},"limitations":{"en":["Requires Git installation and configuration","Needs repository access and credentials","Manual intervention required for creating pull requests"],"zh":["需要Git安装和配置","需要仓库访问和凭证","创建拉取请求需要手动干预"],"ja":["Gitのインストールと構成が必要","リポジトリへのアクセスと資格情報が必要","プルリクエストの作成には手動での介入が必要"],"ko":["Git 설치 및 구성이 필요함","저장소 액세스 및 자격 증명이 필요함","풀 리퀘스트 생성에는 수동 개입이 필요함"],"es":["Requiere instalación y configuración de Git","Necesita acceso y credenciales de repositorio","Se requiere intervención manual para crear solicitudes de extracción"],"fr":["Nécessite l''installation et la configuration de Git","A besoin d''un accès et de références de référentiel","Requiert une intervention manuelle pour créer des demandes d''extraction"],"de":["Benötigt Git-Installation und -Konfiguration","Benötigt Repository-Zugriff und -Anmeldeinformationen","Benötigt manuelle Eingriffe zur Erstellung von Pull-Requests"],"pt":["Exige instalação e configuração do Git","Necessita acesso e credenciais de repositório","Intervenção manual necessária para criar solicitações de pull"],"ru":["Требует установки и конфигурации Git","Требует доступа и учетных данных репозитория","Требуется ручное вмешательство для создания запросов на pull"],"ar":["يتطلب تثبيت وضبط Git","يتطلب الوصول وال资redentials للمستودع","يتطلب تدخل يدوي لإنشاء طلبات السحب"]},"version":4},"contentHash":"93afdccefe7bfc409a118d9c2f528d039a88cbd699068a15b4beba781eadca1e","qualityScore":30}');
