INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jkomoros/community-patterns/git-workflow', 'git-workflow', 'jkomoros', 'community-patterns', 'community', 'git-workflow jkomoros community-patterns community The git-workflow skill helps developers manage their Git repositories by providing patterns for committing, updating, and sharing work. It benefits developers working on community-driven projects. Git Workflow 是一个社区创建的模式仓库，提供提交、更新和创建 Pull Requests 的步骤 Git Workflow はコミュニティによって作成されたパターンリポジトリであり、コミット、更新、プルリクエストの作成の手順を提供します Git Workflow는 커뮤니티에서 생성한 패턴仓库로 커밋, 업데이트, 풀リクエ스트 생성의 단계를 제공합니다 El flujo de trabajo Git es una forma de colaborar en proyectos de código abierto. Utiliza comandos como ''git add'' y ''git commit'' para realizar cambios y compartirlos Le flux de travail Git est un moyen de collaborer sur des projets de code source ouvert. Il utilise des commandes comme ''git add'' et ''git commit'' pour effectuer des modifications et les partager Der Git-Workflow ist eine Möglichkeit, an Open-Source-Projekten zu arbeiten. Er verwendet Befehle wie ''git add'' und ''git commit'', um Änderungen vorzunehmen und sie zu teilen O fluxo de trabalho Git é um repositório de padrões criados pela comunidade. Aprenda a committar, atualizar e compartilhar trabalho upstream Поток работы Git - это репозиторий шаблонов, созданных сообществом. Узнайте, как фиксировать, обновлять и делиться работой upstream Fluxo de Trabalho Git هو مستودع لأنماط تم إنشاؤها من قبل المجتمع. تعلم كيف committar، وتحديث ومشاركة العمل upstream git-workflow setup guide how to use git-workflow git repository management git workflow patterns git-workflow vs git flow git-workflow install git-workflow tutorial git workflow best practices git-workflow alternative Git Workflow AIエージェント工具 Git 命令行工具 Pull Requests Git Fetch Git Pull Git Commit Git Push 代码管理 Commits work using `git add` and `git commit` commands Updates repositories using `git fetch` and `git pull` commands Shares work upstream by creating pull requests Uses `git push` to update the origin main branch Follows a specific commit message format for clarity Requires manual approval before creating pull requests git-workflow is a repository management skill that provides patterns for Git workflow, enabling developers to efficiently commit, update, and share their work.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shibayu36/config-file/clarify-message', 'community', 'shibayu36', 'config-file', 'shibayu36/config-file', 'clarify-message', 0, 0, 30, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:17.385Z', '6030d67b55b74998f3ea6ba4f3474657a04048750dd33db7f365a6925265508c', '{"id":"shibayu36/config-file/clarify-message","name":"clarify-message","description":{"en":"The Clarify-Message skill refines messages through interactive dialogue, benefiting developers and users alike by ensuring clear communication. It involves a structured workflow to understand the target audience and desired action.","zh":"Clarify Message 技术是一种对话式整理和构成案设计方法，通过三个阶段帮助用户明确传达目标","ja":"Clarify Message 技術は、対話的に進めることでユーザーの伝えたいことを整理し、構成案を一緒に作り上げる","ko":"Clarify Message 기술은 대화식으로 진행하여 사용자의 전달할 메시지를 정리하고, 구성안을 함께 설계합니다","es":"Clarify Message es un agente de IA que te ayuda a estructurar mensajes de manera efectiva, a través de un proceso de diálogo interactivo","fr":"Clarify Message est un outil d''IA qui vous aide à structurer vos messages de manière efficace, via un processus de dialogue interactif","de":"Clarify Message ist ein KI-Tool, das Ihnen hilft, Nachrichten effektiv zu strukturieren, durch einen interaktiven Dialogprozess","pt":"O Clarify Message é uma ferramenta de interação que ajuda a esclarecer mensagens de forma eficaz, com foco em feedback e compreensão do usuário","ru":"ИИ Агент Clarify Message - это инструмент для уточнения сообщений, который помогает эффективно разъяснять сообщения с учетом обратной связи и понимания пользователя","ar":"Clarify Message هو أداة تفاعلية لتوضيح الرسائل بفعالية، مع التركيز على الرد والفهم المستخدم"},"seo":{"title":{"en":"Clarify-Message: Interactive Message Refining Setup Guide...","zh":"Clarify Message 配置指南：对话式整理和构成案设计","ja":"Clarify Message セットアップガイド：対話的に整理し、構成案を一緒に作り上げる","ko":"Clarify Message 설정 가이드: 대화식 정리 및 구성안 설계","es":"Guía de configuración para Clarify Message: Agentes de IA...","fr":"Guide de mise en place de Clarify Message : Outils d''IA p...","de":"Einrichtungsleitfaden für Clarify Message: KI-Tools für E...","pt":"Guia de Configuração do Clarify Message: Ferramenta de In...","ru":"Настройка ИИ Агента Clarify Message: Инструмент для Уточн...","ar":"دليل إعداد Clarify Message: أداة تفاعلية لتوضيح الرسائل"},"description":{"en":"Discover how Clarify-Message AI skill helps refine your message through interactive dialogue. Learn how to set it up and improve your communication today!","zh":"了解 Clarify Message 技术的详细指南，包括对话式整理、构成案设计和关键原则等","ja":"Clarify Message 技術の詳細ガイド。対話的に進める、ユーザーの言葉を大切にする、実際の執筆はしないなどの重要な原則を紹介","ko":"Clarify Message 기술의 자세한 가이드. 대화식으로 진행하고, 사용자의 말을 소중히 여기는 등 중요한 원칙들에 대해 소개합니다","es":"Aprende a configurar Clarify Message, un agente de IA que te ayuda a estructurar mensajes de manera efectiva, con pasos y ejemplos prácticos","fr":"Découvrez comment configurer Clarify Message, un outil d''IA qui vous aide à structurer vos messages de manière efficace, avec des étapes et des exemples prat...","de":"Erfahren Sie, wie Sie Clarify Message konfigurieren, ein KI-Tool, das Ihnen hilft, Nachrichten effektiv zu strukturieren, mit Schritten und praktischen Beisp...","pt":"Aprenda a configurar o Clarify Message, uma ferramenta de interação para esclarecer mensagens de forma eficaz, com foco em feedback e compreensão do usuário","ru":"Узнайте, как настроить ИИ Агент Clarify Message, инструмент для уточнения сообщений с учетом обратной связи и понимания пользователя","ar":"تعرف على كيفية إعداد Clarify Message، أداة تفاعلية لتوضيح الرسائل بفعالية، مع التركيز على الرد والفهم المستخدم"},"definition":{"en":"Clarify-message is a skill that facilitates interactive message refinement, focusing on understanding the target audience and desired outcome to create effective communication plans.","zh":"Clarify Message 是一种通过对话式整理和构成案设计来帮助用户明确传达目标的技术","ja":"Clarify Message は、対話的に進めることでユーザーの伝えたいことを整理し、構成案を一緒に作り上げる技術","ko":"Clarify Message는 대화식으로 진행하여 사용자의 전달할 메시지를 정리하고, 구성안을 함께 설계하는 기술입니다","es":"Un agente de IA que ayuda a estructurar mensajes de manera efectiva a través de un proceso de diálogo interactivo","fr":"Un outil d''IA qui aide à structurer les messages de manière efficace via un processus de dialogue interactif","de":"Ein KI-Tool, das hilft, Nachrichten effektiv zu strukturieren, durch einen interaktiven Dialogprozess","pt":"O Clarify Message é uma ferramenta de interação que utiliza técnicas de feedback e compreensão do usuário para esclarecer mensagens","ru":"ИИ Агент Clarify Message - это инструмент, использующий методы обратной связи и понимания пользователя для уточнения сообщений","ar":"Clarify Message هو أداة تفاعلية تستخدم تقنيات الرد والفهم المستخدم لتوضيح الرسائل"},"features":{"en":["Conducts purpose hearing to identify the target audience and desired action","Performs material hearing to gather information and clarify unclear points","Asks questions to deepen understanding of key concepts and terminology","Confirms additional information through questions like ''Is there anything else you want to convey?''","Develops a composition plan based on user feedback and input"],"zh":["对话式整理","构成案设计","三个阶段的工作流：目的ヒアリング、素材ヒアリング、構成案ヒアリング","重要原则：对话式进展、用户的语言至关重要、不进行实际的写作","支持用户自由表达想法","通过提问进行深入了解"],"ja":["対話的に進める","構成案を一緒に作り上げる","3つのフェーズ：目的ヒアリング、素材ヒアリング、構成案ヒアリング","重要な原則：対話的に進める、ユーザーの言葉を大切にする、実際の執筆はしない","ユーザーが自由に話すことができる","質問を通じて深く理解する"],"ko":["대화식으로 진행","구성안을 함께 설계","3つの 단계: 목적ヒアリング, 재료ヒアリング, 구성안ヒアリング","중요한 원칙: 대화식으로 진행, 사용자의 말은 소중히 여긴다, 실제 작성은 하지 않는다","사용자가 자유롭게 생각을 표현할 수 있다","질문을 통해 깊이 이해한다"],"es":["Proceso de diálogo interactivo para estructurar mensajes","Análisis de la audiencia objetivo y sus necesidades","Identificación de la acción deseada después de leer o escuchar el mensaje","Recopilación de información adicional a través de preguntas","Creación de un plan de estructura para el mensaje"],"fr":["Processus de dialogue interactif pour structurer les messages","Analyse du public cible et de ses besoins","Identification de l''action souhaitée après avoir lu ou écouté le message","Collecte d''informations supplémentaires via des questions","Création d''un plan de structure pour le message"],"de":["Interaktiver Dialogprozess zur Strukturierung von Nachrichten","Analyse der Zielgruppe und ihrer Bedürfnisse","Identifizierung der gewünschten Aktion nach dem Lesen oder Hören der Nachricht","Erfassung zusätzlicher Informationen durch Fragen","Erstellung eines Strukturplans für die Nachricht"],"pt":["Utiliza feedback do usuário para esclarecer mensagens","Foco em compreensão do usuário para melhorar a interação","Permite a coleta de informações adicionais para esclarecer mensagens","Utiliza técnicas de perguntas para aprofundar a compreensão do usuário","Permite a identificação de pontos de confusão e ambiguidade nas mensagens"],"ru":["Использует обратную связь пользователя для уточнения сообщений","Фокусируется на понимании пользователя для улучшения взаимодействия","Позволяет собирать дополнительную информацию для уточнения сообщений","Использует методы вопросов для более глубокого понимания пользователя","Позволяет выявлять точки неясности и двусмысленности в сообщениях"],"ar":["تستخدم ردود فعل المستخدم لتوضيح الرسائل","تركز على فهم المستخدم لتحسين التفاعل","تمكن من جمع معلومات إضافية لتوضيح الرسائل","تستخدم تقنيات الأسئلة لتعميق فهم المستخدم","تمكن من تحديد نقاط الغموض واللبس في الرسائل"]},"keywords":{"en":["how to use clarify-message","what is clarify-message","clarify-message alternative","clarify-message setup guide","clarify-message install","interactive message refining","ai agent skills for communication","message refinement workflow","target audience identification"],"zh":["AIエージェント","对话式整理","构成案设计","Clarify Message 技术","传达目标","用户体验","人工智能工具","自然语言处理"],"ja":["AIエージェント","対話的に進める","構成案を一緒に作り上げる","Clarify Message 技術","伝えたいことを整理","ユーザー体験","人工知能ツール","自然言語処理"],"ko":["AI 에이전트","대화식으로 진행","구성안을 함께 설계","Clarify Message 기술","전달할 메시지를 정리","사용자 경험","인공 지능 도구","자연어 처리"],"es":["agentes de IA para desarrolladores","herramientas de IA para la estructura de mensajes","configuración de Clarify Message","proceso de diálogo interactivo","análisis de audiencia objetivo","creación de planes de estructura para mensajes"],"fr":["outils d''IA pour les développeurs","outils d''IA pour la structure de messages","configuration de Clarify Message","processus de dialogue interactif","analyse du public cible","création de plans de structure pour les messages"],"de":["KI-Tools für Entwickler","KI-Tools für die Strukturierung von Nachrichten","Konfiguration von Clarify Message","interaktiver Dialogprozess","Analyse der Zielgruppe","Erstellung von Strukturplänen für Nachrichten"],"pt":["Clarify Message","ferramenta de interação","esclarecimento de mensagens","feedback do usuário","compreensão do usuário","inteligência artificial","IA","desenvolvimento de software"],"ru":["ИИ Агент Clarify Message","инструмент для уточнения сообщений","обратная связь пользователя","понимание пользователя","искусственный интеллект","ИИ","разработка программного обеспечения"],"ar":["Clarify Message","أداة تفاعلية","توضيح الرسائل","ردود فعل المستخدم","فهم المستخدم","الذكاء الاصطناعي","AI","تطوير البرمجيات"]}},"owner":"shibayu36","repo":"config-file","repoPath":"shibayu36/config-file","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"clarify-message","description":"伝えたいことを明確にし、構成案を一緒に作り上げるファシリテーター。記事、プレゼン、ドキュメントなどコンテンツの種類を問わず汎用的に使える。ユーザーが「伝えたいことを整理したい」「構成を考えたい」「アウトラインを作りたい」「メッセージを明確にしたい」と言った時に使う。実際の執筆・ドラフト作成は行わず、構成案の確定までを担当する。","bodyPreview":"# Clarify Message\n\n伝えたいことを対話的に整理し、構成案を一緒に作り上げる。\n\n## 重要な原則\n\n- **対話的に進める**: 一方的に提案せず、常にフィードバックをもらいながら進める\n    - もしYes/No or 選択式でわたしに質問する場合、AskUserQuestionツールを活用\n- **ユーザーの言葉を大切にする**: ユーザーの表現をそのまま活かす\n- **実際の執筆はしない**: このスキルは構成案を確定するところまで\n\n## ワークフロー\n\n### フェーズ1: 目的ヒアリング（必須・最初に必ず行う）\n\n以下の2点を必ず確認する：\n\n1. **誰に向けた内容か**（読者・聞き手のペルソナ）\n   - どんな人？背景知識は？立場は？\n2. **読後/聞いた後にどんなアクションを起こしてほしいか**\n   - 理解してほしい？行動してほしい？考えを変えてほしい？\n\n### フェーズ2: 素材ヒアリング\n\n- ユーザーに伝えたいことを自由に話してもらう\n- 足りない情報や曖昧な点を質問で深掘りする\n- 理解できない固有名詞や概念については、ユーザーに","body":"# Clarify Message\n\n伝えたいことを対話的に整理し、構成案を一緒に作り上げる。\n\n## 重要な原則\n\n- **対話的に進める**: 一方的に提案せず、常にフィードバックをもらいながら進める\n    - もしYes/No or 選択式でわたしに質問する場合、AskUserQuestionツールを活用\n- **ユーザーの言葉を大切にする**: ユーザーの表現をそのまま活かす\n- **実際の執筆はしない**: このスキルは構成案を確定するところまで\n\n## ワークフロー\n\n### フェーズ1: 目的ヒアリング（必須・最初に必ず行う）\n\n以下の2点を必ず確認する：\n\n1. **誰に向けた内容か**（読者・聞き手のペルソナ）\n   - どんな人？背景知識は？立場は？\n2. **読後/聞いた後にどんなアクションを起こしてほしいか**\n   - 理解してほしい？行動してほしい？考えを変えてほしい？\n\n### フェーズ2: 素材ヒアリング\n\n- ユーザーに伝えたいことを自由に話してもらう\n- 足りない情報や曖昧な点を質問で深掘りする\n- 理解できない固有名詞や概念については、ユーザーに質問して理解を深める\n- 「他に伝えたいことはありますか？」で漏れを確認\n\n### フェーズ3: 構成案ヒアリング（対話的に）\n\n1. 大まかな構成の方向性を2〜3案提案 → フィードバックをもらう\n2. 選ばれた方向性で、各セクションの内容を一緒に詰めていく\n3. 順番や強調点を調整\n4. 「この構成でいいですか？」と確認しながら進める\n\n### フェーズ4: 構成案確定\n\n最終的な構成案を以下の形式でまとめて提示する：\n\n```markdown\n# 構成案: [タイトル]\n\n## 目的\n- **対象読者**: [誰に向けた内容か]\n- **期待するアクション**: [読後にどうなってほしいか]\n\n## 構成\n### 1. [セクション名]\n- 伝えること: ...\n- ポイント: ...\n\n### 2. [セクション名]\n- 伝えること: ...\n- ポイント: ...\n\n（以下続く）\n\n## 補足メモ\n- [執筆時に気をつけること、トーンなど]\n```\n\n## 注意事項\n\n- 各フェーズで十分な確認を取ってから次に進む\n- ユーザーが「もう十分」と言ったらフェーズをスキップしてよい\n- 構成案は押し付けず、複数案から選んでもらう形で進める\n"},"lastSynced":"2026-03-08T02:01:17.385Z","agentAnalysis":{"suitability":{"en":"Perfect for Conversational Agents needing advanced message clarification capabilities through interactive dialogue.","zh":"非常适合需要通过交互式对话进行高级消息澄清功能的对话式代理。","ja":"会話エージェントが高度なメッセージの明確化機能を対話形式で必要とする場合に最適です。","ko":"대화형 대리자가 상호작용 대화를 통해 고급 메시지澄清 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes Conversacionales que necesitan capacidades avanzadas de aclaración de mensajes a través de diálogos interactivos.","fr":"Parfait pour les Agents Conversationnels ayant besoin de capacités de clarification de messages avancées via un dialogue interactif.","de":"Perfekt für Conversational Agents, die erweiterte Nachrichtenklärungsfähigkeiten durch interaktives Dialog benötigen.","pt":"Perfeito para Agentes Conversacionais que necessitam de capacidades avançadas de esclarecimento de mensagens por meio de diálogo interativo.","ru":"Идеально подходит для Конверсационных Агентов, которым требуются расширенные возможности разъяснения сообщений через интерактивный диалог.","ar":"مثالي للوكلاء المحادثين الذين يحتاجون إلى قدرات متقدمة لتوضيح الرسائل من خلال حوار تفاعلي."},"recommendation":{"en":"Empowers agents to refine messages through structured workflows, ensuring clear communication by understanding target audiences and desired actions, utilizing tools like AskUserQuestion for yes/no or multiple-choice questions.","zh":"赋予代理人通过结构化工作流精化消息的能力，通过了解目标受众和期望的操作，确保清晰的沟通，利用诸如 AskUserQuestion 之类的工具进行是/否或多项选择问题。","ja":"エージェントに構造化されたワークフローを通じてメッセージを洗練する能力を付与し、ターゲットオーディエンスと望ましいアクションを理解し、AskUserQuestion などのツールを使用してはい/いいえまたは多項選択の質問を行い、クリアなコミュニケーションを確実に行う。","ko":"대리자에게 구조화된 워크플로우를 통해 메시지를 세부화하는 능력을 부여하여 대상 청중과 원하는 동작을 이해하고 AskUserQuestion과 같은 도구를 사용하여 예/아니요 또는 다중 선택 질문을 통해 명확한 의사소통을 보장합니다.","es":"Habilita a los agentes a refinar los mensajes a través de flujos de trabajo estructurados, garantizando una comunicación clara mediante la comprensión de las audiencias objetivo y las acciones deseables, utilizando herramientas como AskUserQuestion para preguntas de sí/no o de múltiple opción.","fr":"Permet aux agents d''affiner les messages via des flux de travail structurés, garantissant une communication claire en comprenant les publics cibles et les actions souhaitées, en utilisant des outils comme AskUserQuestion pour des questions oui/non ou à choix multiple.","de":"Ermächtigt die Agenten, Nachrichten durch strukturierte Workflows zu verfeinern, eine klare Kommunikation sicherzustellen, indem sie Zielgruppen und gewünschte Aktionen verstehen, mit Tools wie AskUserQuestion für Ja/Nein- oder Multiple-Choice-Fragen.","pt":"Habilita os agentes a refinar as mensagens por meio de fluxos de trabalho estruturados, garantindo uma comunicação clara por meio da compreensão do público-alvo e das ações desejadas, utilizando ferramentas como AskUserQuestion para perguntas sim/não ou de múltipla escolha.","ru":"Наделяет агентов возможностью уточнять сообщения посредством структурированных рабочих процессов, обеспечивая четкую коммуникацию за счет понимания целевой аудитории и желаемых действий, используя инструменты типа AskUserQuestion для вопросов да/нет или с несколькими вариантами ответа.","ar":"تمكن الوكلاء من تحسين الرسائل من خلال سير عمل مهيكلة، مما يضمن تواصلًا واضحًا من خلال فهم الجمهور المستهدف والإجراءات المطلوبة، باستخدام أدوات مثل AskUserQuestion للأسئلة نعم / لا أو متعددة الخيارات."},"useCases":{"en":["Automating message refinement for clearer user communication","Generating structured conversation flows for target audience analysis","Debugging ambiguous messages through iterative feedback"],"zh":["为更清晰的用户沟通自动化消息精化","为目标受众分析生成结构化的会话流","通过迭代反馈调试模糊的消息"],"ja":["クリアなユーザー コミュニケーションのためにメッセージの洗練を自動化する","ターゲット オーディエンス分析のための構造化された会話フローを生成する","反復的なフィードバックを通じてあやしいメッセージをデバッグする"],"ko":["보다 명확한 사용자 통신을 위해 메시지 세부화를 자동화하는 것","대상 청중 분석을 위한 구조화된 대화 흐름을 생성하는 것","반복적인 피드백을 통해 모호한 메시지를 디버깅하는 것"],"es":["Automatización de la refinación de mensajes para una comunicación de usuario más clara","Generación de flujos de conversación estructurados para el análisis de la audiencia objetivo","Depuración de mensajes ambiguos a través de la retroalimentación iterativa"],"fr":["Automatisation de l''affinement des messages pour une communication utilisateur plus claire","Génération de flux de conversation structurés pour l''analyse du public cible","Débogage de messages ambigus via une rétroaction itérative"],"de":["Automatisierung der Nachrichtenverfeinerung für eine klarere Benutzerkommunikation","Erzeugung von strukturierten Konversationsflüssen für die Zielgruppenanalyse","Fehlerbehebung von mehrdeutigen Nachrichten durch iterative Rückmeldung"],"pt":["Automatizar o refinamento de mensagens para uma comunicação de usuário mais clara","Gerar fluxos de conversação estruturados para análise de público-alvo","Depurar mensagens ambíguas por meio de feedback iterativo"],"ru":["Автоматизация уточнения сообщений для более четкого общения с пользователем","Генерация структурированных потоков разговора для анализа целевой аудитории","Отладка неоднозначных сообщений посредством итеративной обратной связи"],"ar":["تأتميم تحسين الرسائل لتحقيق تواصل مستخدم أوضح","генерация تدفقات محادثة مهيكلة لتحليل الجمهور المستهدف","تصحيح رسائل غامضة من خلال ملاحظات تكرارية"]},"limitations":{"en":["Requires interactive user feedback","Limited to message refinement, does not include actual content creation"],"zh":["需要交互式用户反馈","仅限于消息精化，不包括实际内容创建"],"ja":["インタラクティブなユーザー フィードバックが必要","メッセージの洗練のみに限定され、実際のコンテンツ作成は含まない"],"ko":["상호작용 사용자 피드백이 필요함","메시지 세부화에만 국한되고 실제 콘텐츠 생성은 포함하지 않음"],"es":["Requiere retroalimentación interactiva del usuario","Limitado a la refinación de mensajes, no incluye la creación de contenido real"],"fr":["Nécessite une rétroaction interactive de l''utilisateur","Limité à l''affinement des messages, n''inclut pas la création de contenu réel"],"de":["Benötigt interaktive Benutzerrückmeldung","Begrenzt auf die Verfeinerung von Nachrichten, enthält keine tatsächliche Inhaltserschaffung"],"pt":["Requer feedback interativo do usuário","Limitado ao refinamento de mensagens, não inclui criação de conteúdo real"],"ru":["Требуется интерактивная обратная связь от пользователя","Ограничен до уточнения сообщений, не включает создание реального контента"],"ar":["يتطلب ملاحظات تفاعلية من المستخدم","محدود بتحسين الرسائل، ولا يتضمن إنشاء محتوى فعلي"]},"version":4},"contentHash":"6030d67b55b74998f3ea6ba4f3474657a04048750dd33db7f365a6925265508c","qualityScore":30}');
