INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shibayu36/config-file/clarify-message', 'clarify-message', 'shibayu36', 'config-file', 'community', 'clarify-message shibayu36 config-file community The Clarify-Message skill refines messages through interactive dialogue, benefiting developers and users alike by ensuring clear communication. It involves a structured workflow to understand the target audience and desired action. Clarify Message 技术是一种对话式整理和构成案设计方法，通过三个阶段帮助用户明确传达目标 Clarify Message 技術は、対話的に進めることでユーザーの伝えたいことを整理し、構成案を一緒に作り上げる Clarify Message 기술은 대화식으로 진행하여 사용자의 전달할 메시지를 정리하고, 구성안을 함께 설계합니다 Clarify Message es un agente de IA que te ayuda a estructurar mensajes de manera efectiva, a través de un proceso de diálogo interactivo Clarify Message est un outil d''IA qui vous aide à structurer vos messages de manière efficace, via un processus de dialogue interactif Clarify Message ist ein KI-Tool, das Ihnen hilft, Nachrichten effektiv zu strukturieren, durch einen interaktiven Dialogprozess O Clarify Message é uma ferramenta de interação que ajuda a esclarecer mensagens de forma eficaz, com foco em feedback e compreensão do usuário ИИ Агент Clarify Message - это инструмент для уточнения сообщений, который помогает эффективно разъяснять сообщения с учетом обратной связи и понимания пользователя Clarify Message هو أداة تفاعلية لتوضيح الرسائل بفعالية، مع التركيز على الرد والفهم المستخدم how to use clarify-message what is clarify-message clarify-message alternative clarify-message setup guide clarify-message install interactive message refining ai agent skills for communication message refinement workflow target audience identification AIエージェント 对话式整理 构成案设计 Clarify Message 技术 传达目标 用户体验 人工智能工具 自然语言处理 Conducts purpose hearing to identify the target audience and desired action Performs material hearing to gather information and clarify unclear points Asks questions to deepen understanding of key concepts and terminology Confirms additional information through questions like ''Is there anything else you want to convey?'' Develops a composition plan based on user feedback and input Clarify-message is a skill that facilitates interactive message refinement, focusing on understanding the target audience and desired outcome to create effective communication plans.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TTT1231/claude-rules/vue', 'community', 'TTT1231', 'claude-rules', 'TTT1231/claude-rules', 'vue', 0, 0, 30, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:23.918Z', 'b511c04ca268af4dc0f64c6937e25bc74bc12919dede205a4a9ee4dcb0f697c5', '{"id":"TTT1231/claude-rules/vue","name":"vue","description":{"en":"The Vue skill generates high-quality Vue code and audits Vue files based on user input, benefiting developers who need to create and review Vue components efficiently.","zh":"Vue 组件开发技能提供代码生成和审查功能，支持创建、生成、封装、编写和拆分 Vue 组件","ja":"Vue コンポーネント開発スキルは、コード生成とレビュー機能を提供し、Vue コンポーネントの作成、生成、カプセル化、書き込み、分割をサポートします","ko":"Vue 컴포넌트 개발 스킬은 코드 생성 및審查 기능을 제공하며 Vue 컴포넌트의 생성, 생성, 캡슐화, 작성 및 분할을 지원합니다","es":"Desarrolla componentes Vue personalizados con funcionalidades avanzadas como generación de código y análisis de tipo","fr":"Développez des composants Vue personnalisés avec des fonctionnalités avancées comme la génération de code et l''analyse de type","de":"Entwickeln Sie benutzerdefinierte Vue-Komponenten mit erweiterten Funktionen wie Codegenerierung und Typanalyse","pt":"O Vue é uma estrutura para desenvolver componentes personalizados com regras de claudecode, melhorando a produtividade de desenvolvimento","ru":"Vue - это фреймворк для разработки индивидуальных компонентов с правилами claudecode, повышающий производительность разработки","ar":"Vue هو إطار عمل لإنشاء مكونات مخصصة بقواعد claudecode، مما يحسن إنتاجية التطوير"},"seo":{"title":{"en":"Vue: Customized Code Generation for AI Agents | AI Agent ...","zh":"Vue 组件开发技能：代码生成和审查指南","ja":"Vue コンポーネント開発スキル：AI エージェントを使用したコード生成とレビュー","ko":"Vue 컴포넌트 개발 스킬: 코드 생성 및審查 가이드","es":"Guía de configuración de Vue: Desarrollo de componentes p...","fr":"Guide de configuration de Vue: Développement de composant...","de":"Vue-Konfigurationsleitfaden: Entwicklung von benutzerdefi...","pt":"Guia de Configuração do Vue: Desenvolvimento de Component...","ru":"Настройка Vue: Руководство по разработке индивидуальных к...","ar":"إعداد Vue: دليل لإنشاء مكونات مخصصة"},"description":{"en":"Unlock efficient Vue development with AI-powered code generation and auditing - try it now and streamline your workflow!","zh":"了解如何使用 Vue 组件开发技能生成高质量的 Vue 代码，并审查指定路径下的 Vue 文件","ja":"Vue コンポーネント開発スキルを使用して、高品質の Vue コードを生成し、指定されたパスの Vue ファイルをレビューする方法について学びます","ko":"Vue 컴포넌트 개발 스킬을 사용하여 높은 품질의 Vue 코드를 생성하고 지정된 경로의 Vue 파일을審查하는 방법에 대해 알아보세요","es":"Aprende a configurar y desarrollar componentes Vue personalizados con nuestra guía paso a paso","fr":"Découvrez comment configurer et développer des composants Vue personnalisés avec notre guide étape par étape","de":"Erfahren Sie, wie Sie benutzerdefinierte Vue-Komponenten konfigurieren und entwickeln können, mit unserem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a criar componentes Vue personalizados com regras de claudecode e melhore sua produtividade de desenvolvimento","ru":"Узнайте, как создавать индивидуальные компоненты Vue с помощью правил claudecode и повышайте свою производительность разработки","ar":"تعلم كيفية إنشاء مكونات Vue مخصصة باستخدام قواعد claudecode و تحسين إنتاجية التطوير"},"definition":{"en":"Vue is a skill that provides customized code generation and auditing capabilities for Vue components, utilizing commands like `/vue <path>` and integrating with Element Plus and TypeScript.","zh":"Vue 组件开发技能是指使用 AI 技术生成和审查 Vue 组件的能力","ja":"Vue コンポーネント開発スキルとは、AI 技術を使用して Vue コンポーネントを生成およびレビューする能力です","ko":"Vue 컴포넌트 개발 스킬은 AI 기술을 사용하여 Vue 컴포ーネ�트를 생성 및審查하는 능력입니다","es":"Vue es un framework JavaScript para desarrollar componentes personalizados y escalables","fr":"Vue est un framework JavaScript pour développer des composants personnalisés et évolutifs","de":"Vue ist ein JavaScript-Framework für die Entwicklung von benutzerdefinierten und skalierbaren Komponenten","pt":"O que é Vue? É uma estrutura para desenvolver componentes personalizados com regras de claudecode","ru":"Что такое Vue? Это фреймворк для разработки индивидуальных компонентов с правилами claudecode","ar":"ما هو Vue؟ إنه إطار عمل لإنشاء مكونات مخصصة بقواعد claudecode"},"features":{"en":["Generates Vue code based on user descriptions containing keywords like ''create'', ''generate'', and ''encapsulate''","Audits Vue files using the `/vue <path>` command, supporting paths like `src/components` and `src/views/Dashboard.vue`","Utilizes a decision tree for type judgment and generates code according to specifications","Ensures complete TypeScript type definitions for generated code","Supports development mode for creating new components and audit mode for reviewing existing code"],"zh":["支持创建、生成、封装、编写和拆分 Vue 组件","生成高质量的 Vue 代码","审查指定路径下的 Vue 文件","支持 TypeScript 类型定义","使用决策树确定组件类型"],"ja":["Vue コンポーネントの作成、生成、カプセル化、書き込み、分割をサポート","高品質の Vue コードを生成","指定されたパスの Vue ファイルをレビュー","TypeScript 型定義をサポート","決定木を使用してコンポーネントの種類を決定"],"ko":["Vue 컴포넌트의 생성, 생성, 캡슐화, 작성 및 분할을 지원","높은 품질의 Vue 코드를 생성","지정된 경로의 Vue 파일을審查","TypeScript 유형 정의를 지원","결정 트리를 사용하여 컴포넌트 유형을 결정"],"es":["Generación de código Vue personalizado","Análisis de tipo con TypeScript","Desarrollo de componentes con Element Plus","Soporte para comandos de auditoría","Funcionalidades de desarrollo y auditoría"],"fr":["Génération de code Vue personnalisé","Analyse de type avec TypeScript","Développement de composants avec Element Plus","Prise en charge des commandes d''audit","Fonctionnalités de développement et d''audit"],"de":["Generierung von benutzerdefiniertem Vue-Code","Typanalyse mit TypeScript","Entwicklung von Komponenten mit Element Plus","Unterstützung für Audit-Befehle","Funktionen für Entwicklung und Audit"],"pt":["Criação de componentes Vue personalizados com regras de claudecode","Desenvolvimento de componentes com Element Plus","Uso de composable para melhorar a produtividade","Análise de código Vue com comando /vue","Suporte a TypeScript para definição de tipos","Divisão de componentes grandes em menores"],"ru":["Создание индивидуальных компонентов Vue с правилами claudecode","Разработка компонентов с помощью Element Plus","Использование composable для повышения производительности","Анализ кода Vue с помощью команды /vue","Поддержка TypeScript для определения типов","Разделение крупных компонентов на меньшие"],"ar":["إنشاء مكونات Vue مخصصة بقواعد claudecode","تطوير مكونات مع Element Plus","استخدام composable لتحسين الإنتاجية","تحليل كود Vue باستخدام أمر /vue","دعم TypeScript لتعريف الأنواع","تقسيم مكونات كبيرة إلى أصغر"]},"keywords":{"en":["how to use vue with ai","vue code generation tutorial","vue alternative for react developers","vue vs angular performance","vue install guide for windows","vue setup guide for mac","what is vue used for","vue audit tool","vue best practices for development"],"zh":["Vue 组件开发","AI 代码生成","Vue 代码审查","TypeScript","决策树","Vue 开发技能","AI开发工具"],"ja":["Vue コンポーネント開発","AI コード生成","Vue コードレビュー","TypeScript","決定木","Vue 開発スキル","AI エージェント"],"ko":["Vue 컴포넌트 개발","AI 코드 생성","Vue 코드審查","TypeScript","결정 트리","Vue 개발 스킬","AI 에이전트"],"es":["desarrollo de componentes vue","vue js","element plus","typescript","generación de código","análisis de tipo","auditoría de código","herramientas de desarrollo vue"],"fr":["développement de composants vue","vue js","element plus","typescript","génération de code","analyse de type","audit de code","outils de développement vue"],"de":["entwicklung von vue-komponenten","vue js","element plus","typescript","codegenerierung","typanalyse","code-audit","entwicklungstools für vue"],"pt":["vue","componentes personalizados","regras de claudecode","desenvolvimento de componentes","Element Plus","composable","análise de código","TypeScript","divisão de componentes"],"ru":["vue","индивидуальные компоненты","правила claudecode","разработка компонентов","Element Plus","composable","анализ кода","TypeScript","разделение компонентов"],"ar":["vue","مكونات مخصصة","قواعد claudecode","تطوير مكونات","Element Plus","composable","تحليل كود","TypeScript","تقسيم مكونات"]}},"owner":"TTT1231","repo":"claude-rules","repoPath":"TTT1231/claude-rules","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.299Z","topics":[],"category":"community","skillMd":{"name":"vue","description":"Vue 组件开发与代码审查技能 - 开发模式：描述需求时生成高质量 Vue 组件/Composable - 审查模式：/vue <path> 审查该路径下所有 Vue 文件","bodyPreview":"# Vue 组件开发技能\n\n## 功能说明\n\n### 开发模式\n\n当用户描述需求时，生成高质量的 Vue 代码：\n\n```\n创建一个用户列表组件\n封装 Element Plus 的 Table 组件\n写一个 useTable composable\n这个组件太大了，帮我拆分\n```\n\n**触发条件**：用户描述包含\"创建\"、\"生成\"、\"封装\"、\"编写\"、\"拆分\"等关键词\n\n### 审查模式\n\n当用户使用 `/vue <path>` 命令时，审查指定路径下的 Vue 文件：\n\n```\n/vue src/components\n/vue src/views/Dashboard.vue\n/vue                          # 审查当前目录\n```\n\n---\n\n## 模式分发\n\n### 1. 开发模式\n\n**执行流程**：\n\n1. **需求解析** — 理解用户想要实现的功能\n2. **类型判断** — 使用决策树确定组件类型\n3. **代码生成** — 按照规范生成代码\n4. **类型提示** — 确保完整的 TypeScript 类型定义\n\n### 2. 审查模式\n\n*","body":"# Vue 组件开发技能\n\n## 功能说明\n\n### 开发模式\n\n当用户描述需求时，生成高质量的 Vue 代码：\n\n```\n创建一个用户列表组件\n封装 Element Plus 的 Table 组件\n写一个 useTable composable\n这个组件太大了，帮我拆分\n```\n\n**触发条件**：用户描述包含\"创建\"、\"生成\"、\"封装\"、\"编写\"、\"拆分\"等关键词\n\n### 审查模式\n\n当用户使用 `/vue <path>` 命令时，审查指定路径下的 Vue 文件：\n\n```\n/vue src/components\n/vue src/views/Dashboard.vue\n/vue                          # 审查当前目录\n```\n\n---\n\n## 模式分发\n\n### 1. 开发模式\n\n**执行流程**：\n\n1. **需求解析** — 理解用户想要实现的功能\n2. **类型判断** — 使用决策树确定组件类型\n3. **代码生成** — 按照规范生成代码\n4. **类型提示** — 确保完整的 TypeScript 类型定义\n\n### 2. 审查模式\n\n**执行流程**：\n\n1. **文件扫描** — 使用 Glob 查找指定路径下的所有 `.vue` 和 composables 文件\n2. **展示检查清单** — 展示可检查项，等待用户确认：\n\n   ```\n   以下是可执行的检查项，请确认需要检查哪些（默认全选，回复排除项的编号即可）：\n\n   1. [x] 组件结构\n   2. [x] TypeScript 类型\n   3. [x] 组件封装\n   4. [x] Composable\n   5. [x] 性能\n   6. [x] 现代语法\n   7. [x] 代码规范\n   8. [x] 可访问性 (a11y)\n   9. [ ] 测试（默认不选，需明确指定）\n   ```\n\n3. **逐项检查** — 按照清单扫描代码，记录问题\n4. **输出诊断报告** — 按统一格式输出结果（见下方）\n\n---\n\n## 快速决策树\n\n```\n用户请求 → 判断类型\n\n是纯逻辑复用吗？\n  → YES: Composable (useXxx)\n  → NO: 继续\n\n是封装组件库组件吗？\n  → YES: 二次封装（保证类型透传）\n  → NO: 继续\n\n业务逻辑复杂 或 >1300 行？\n  → YES: 拆分为子组件 + Composable\n  → NO: 单文件组件\n```\n\n---\n\n## 代码生成规范 (AI 必须遵守)\n\n1. **语法标准**：\n   - 必须使用 `<script setup lang=\"ts\">`\n   - 优先使用 `const` 声明变量\n   - 必须使用 `async/await` 处理异步操作，并包裹在 `try/catch` 中\n   - 优先使用 Vue 3.5+ 新特性（如 `useTemplateRef`, `useId`, `defineModel`）\n2. **类型定义**：\n   - 必须为所有 Props、Emits、Refs 提供明确的 TypeScript 类型\n   - 避免使用 `any`，优先使用 `unknown` 或具体类型\n   - 复杂类型定义应提取到单独的 `types.ts` 文件中\n3. **状态管理**：\n   - 局部状态使用 `ref` 或 `reactive`\n   - 跨组件状态优先使用 `Provide/Inject`\n   - 全局状态使用 Pinia\n4. **性能优化**：\n   - 列表渲染必须提供唯一的 `:key`\n   - 频繁更新的非响应式数据不要使用 `ref`\n   - 庞大的只读数据使用 `shallowRef`\n\n---\n\n## 审查输出格式\n\n```markdown\n## 📋 [文件名] 审查结果\n\n### ✅ 通过项\n\n- [x] 组件结构合理\n- [x] TypeScript 类型完整\n- [x] ...\n\n### ❌ 问题项\n\n- [ ] **[问题标题]**\n   - 位置：[文件:行号]\n   - 问题：[描述]\n   - 建议：[改进方案]\n\n### 📊 总评：X/10\n```\n\n---\n\n## 引用文件\n\n详细规则位于 `references/` 目录：\n\n- `references/component-types.md` — 组件分类、大组件拆分规则、Props/Emits、Provide/Inject\n- `references/wrapper-pattern.md` — 二次封装完整指南、v-model 处理、动态插槽\n- `references/composable-rules.md` — Composable 编写规则、副作用清理、状态共享\n- `references/modern-features.md` — Vue 3.3+ / 3.5+ 新特性\n- `references/review-checklist.md` — 详细的审查清单\n- `references/project-setup.md` — Vue Web 项目配置（Pinia, Router, Axios, unplugin 等）\n- `references/performance-optimization.md` — 性能优化指南（shallowRef, v-memo, 虚拟滚动等）\n"},"lastSynced":"2026-03-08T02:01:23.918Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient Vue component generation and auditing capabilities.","zh":"非常适合需要高效Vue组件生成和审计功能的前端代理。","ja":"フロントエンドエージェントが効率的なVueコンポーネント生成と監査機能を必要とする場合に最適です。","ko":"프론트엔드 에이전트가 효율적인 Vue 컴포넌트 생성 및 감사 기능을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de Frontend que necesitan una generación eficiente de componentes Vue y capacidades de auditoría.","fr":"Parfait pour les agents Frontend qui ont besoin d''une génération efficace de composants Vue et de capacités d''audit.","de":"Perfekt für Frontend-Agents, die eine effiziente Erstellung von Vue-Komponenten und Überprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de geração eficiente de componentes Vue e capacidades de auditoria.","ru":"Идеально подходит для агентов Frontend, которым необходима эффективная генерация компонентов Vue и возможности аудита.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى توليد مكونات Vue فعالة وقدرات تدقيق."},"recommendation":{"en":"Empowers agents to generate high-quality Vue code and audit Vue files based on user input, utilizing Element Plus and TypeScript for robust component development, and provides features like automatic code generation and type checking.","zh":"赋予代理生成高质量的Vue代码和根据用户输入审核Vue文件的能力，利用Element Plus和TypeScript进行强大的组件开发，并提供自动代码生成和类型检查等功能。","ja":"エージェントがユーザー入力に基づいて高品質のVueコードを生成し、Vueファイルを監査する能力を与え、Element PlusとTypeScriptを使用した強力なコンポーネント開発を実現し、自動コード生成や型チェックなどの機能を提供します。","ko":"에이전트가 사용자 입력에 따라 높은 품질의 Vue 코드를 생성하고 Vue 파일을 감사하는 능력을 부여하며, Element Plus와 TypeScript를 사용하여 강력한 컴포넌트 개발을 제공하고 자동 코드 생성 및 타입 확인 등의 기능을 제공합니다.","es":"Habilita a los agentes a generar código Vue de alta calidad y a auditar archivos Vue en función de la entrada del usuario, utilizando Element Plus y TypeScript para un desarrollo de componentes robusto, y proporciona características como la generación automática de código y la comprobación de tipos.","fr":"Permet aux agents de générer du code Vue de haute qualité et d''auditer des fichiers Vue en fonction de la saisie de l''utilisateur, en utilisant Element Plus et TypeScript pour un développement de composants robuste, et fournit des fonctionnalités comme la génération automatique de code et la vérification de types.","de":"Ermöglicht es Agenten, hochwertigen Vue-Code zu generieren und Vue-Dateien basierend auf Benutzereingaben zu überprüfen, wobei Element Plus und TypeScript für eine robuste Komponentenentwicklung verwendet werden, und bietet Funktionen wie automatische Codegenerierung und Typüberprüfung.","pt":"Habilita os agentes a gerar código Vue de alta qualidade e auditar arquivos Vue com base na entrada do usuário, utilizando Element Plus e TypeScript para desenvolvimento de componentes robustos, e fornece recursos como geração automática de código e verificação de tipo.","ru":"Наделяет агентов возможностью генерировать код Vue высокого качества и аудировать файлы Vue на основе ввода пользователя, используя Element Plus и TypeScript для разработки прочных компонентов, и предоставляет функции, такие как автоматическая генерация кода и проверка типов.","ar":"يمنح الوكلاء القدرة على توليد رمز Vue عالي الجودة وتدقيق ملفات Vue بناءً على إدخال المستخدم، باستخدام Element Plus وTypeScript لتطوير مكونات قوية، ويوفر ميزات مثل توليد رمز تلقائي وفتح النوع."},"useCases":{"en":["Generating reusable Vue components","Auditing Vue files for best practices","Creating composable functions like useTable"],"zh":["生成可重用的Vue组件","根据最佳实践审计Vue文件","创建可组合函数，如useTable"],"ja":["再利用可能なVueコンポーネントを生成する","ベストプラクティスに基づいてVueファイルを監査する","useTableなどの組み合わせ可能な関数を作成する"],"ko":["재사용 가능한 Vue 컴포넌트를 생성하는 것","베스트 프랙티스에 따라 Vue 파일을 감사하는 것","useTable 등의 조합 가능한 함수를 생성하는 것"],"es":["Generación de componentes Vue reutilizables","Auditoría de archivos Vue para las mejores prácticas","Creación de funciones componibles como useTable"],"fr":["Génération de composants Vue réutilisables","Audit de fichiers Vue pour les meilleures pratiques","Création de fonctions componibles comme useTable"],"de":["Erstellung wiederverwendbarer Vue-Komponenten","Überprüfung von Vue-Dateien für die besten Praktiken","Erstellung von komponiblen Funktionen wie useTable"],"pt":["Geração de componentes Vue reutilizáveis","Auditoria de arquivos Vue para melhores práticas","Criação de funções compostas como useTable"],"ru":["Генерация повторно используемых компонентов Vue","Аудит файлов Vue для лучших практик","Создание составных функций, таких как useTable"],"ar":["توليد مكونات Vue قابلة لإعادة الاستخدام","تدقيق ملفات Vue لأفضل الممارسات","إنشاء دوال قابلة للتكوين مثل useTable"]},"limitations":{"en":["Requires user input for code generation","Limited to Vue framework","Dependent on Element Plus for table components"],"zh":["代码生成需要用户输入","仅限于Vue框架","依赖于Element Plus进行表格组件"],"ja":["コード生成にはユーザー入力が必要","Vueフレームワークのみに限定される","テーブルコンポーネントにはElement Plusに依存する"],"ko":["코드 생성에는 사용자 입력이 필요합니다","Vue 프레임워크에만 제한됩니다","테이블 컴포넌트에는 Element Plus에 의존합니다"],"es":["Requiere la entrada del usuario para la generación de código","Limitado al marco de Vue","Dependiente de Element Plus para componentes de tabla"],"fr":["Nécessite une saisie de l''utilisateur pour la génération de code","Limité au framework Vue","Dépendant d''Element Plus pour les composants de tableau"],"de":["Benutzereingabe für die Codegenerierung erforderlich","Begrenzt auf das Vue-Framework","Von Element Plus für Tabellenkomponenten abhängig"],"pt":["Exige entrada do usuário para geração de código","Limitado ao framework Vue","Dependente de Element Plus para componentes de tabela"],"ru":["Требует ввода пользователя для генерации кода","Ограничен фреймворком Vue","Зависит от Element Plus для компонентов таблицы"],"ar":["يتطلب إدخال المستخدم لتوليد الرمز","محدود بإطار عمل Vue","يعتمد على Element Plus لمكونات الجدول"]},"version":4},"contentHash":"b511c04ca268af4dc0f64c6937e25bc74bc12919dede205a4a9ee4dcb0f697c5","qualityScore":30}');
