INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TTT1231/claude-rules/vue', 'vue', 'TTT1231', 'claude-rules', 'community', 'vue TTT1231 claude-rules community The Vue skill generates high-quality Vue code and audits Vue files based on user input, benefiting developers who need to create and review Vue components efficiently. Vue 组件开发技能提供代码生成和审查功能，支持创建、生成、封装、编写和拆分 Vue 组件 Vue コンポーネント開発スキルは、コード生成とレビュー機能を提供し、Vue コンポーネントの作成、生成、カプセル化、書き込み、分割をサポートします Vue 컴포넌트 개발 스킬은 코드 생성 및審查 기능을 제공하며 Vue 컴포넌트의 생성, 생성, 캡슐화, 작성 및 분할을 지원합니다 Desarrolla componentes Vue personalizados con funcionalidades avanzadas como generación de código y análisis de tipo Développez des composants Vue personnalisés avec des fonctionnalités avancées comme la génération de code et l''analyse de type Entwickeln Sie benutzerdefinierte Vue-Komponenten mit erweiterten Funktionen wie Codegenerierung und Typanalyse O Vue é uma estrutura para desenvolver componentes personalizados com regras de claudecode, melhorando a produtividade de desenvolvimento Vue - это фреймворк для разработки индивидуальных компонентов с правилами claudecode, повышающий производительность разработки Vue هو إطار عمل لإنشاء مكونات مخصصة بقواعد claudecode، مما يحسن إنتاجية التطوير how to use vue with ai vue code generation tutorial vue alternative for react developers vue vs angular performance vue install guide for windows vue setup guide for mac what is vue used for vue audit tool vue best practices for development Vue 组件开发 AI 代码生成 Vue 代码审查 TypeScript 决策树 Vue 开发技能 AI开发工具 Generates Vue code based on user descriptions containing keywords like ''create'', ''generate'', and ''encapsulate'' Audits Vue files using the `/vue <path>` command, supporting paths like `src/components` and `src/views/Dashboard.vue` Utilizes a decision tree for type judgment and generates code according to specifications Ensures complete TypeScript type definitions for generated code Supports development mode for creating new components and audit mode for reviewing existing code Vue is a skill that provides customized code generation and auditing capabilities for Vue components, utilizing commands like `/vue <path>` and integrating with Element Plus and TypeScript.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AoEiuV020/flutter_melos_template/init-import-sorter', 'community', 'AoEiuV020', 'flutter_melos_template', 'AoEiuV020/flutter_melos_template', 'init-import-sorter', 0, 0, 30, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:27.515Z', 'ac54f6fb89df70e37d4a8cdf68a8fb241ff9e9c3421f552e82078822d50172d6', '{"id":"AoEiuV020/flutter_melos_template/init-import-sorter","name":"init-import-sorter","description":{"en":"The init-import-sorter skill helps developers manage Flutter monorepo projects by sorting imports. It supports pub workspaces and can be used with melos.","zh":"init-import-sorter 是一个用于 Flutter 多模块项目的 import 排序工具，帮助开发者保持代码的整洁和可读性","ja":"init-import-sorter は、Flutter マルチモジュール プロジェクトの import を整理するツールで、コードの整頓と可読性を向上させます","ko":"init-import-sorter는 Flutter 멀티 모듈 프로젝트의 import를 정렬하는 도구로 코드의 깔끔함과 가독성을 유지하는 데 도움이 됩니다","es":"Init-import-sorter es una herramienta para ordenar importaciones en proyectos Flutter. Aprende a instalar y utilizarla con melos","fr":"Init-import-sorter est un outil pour trier les importations dans les projets Flutter. Découvrez comment l''installer et l''utiliser avec melos","de":"Init-Import-Sorter ist ein Tool zum Ordnen von Importen in Flutter-Projekten. Erfahren Sie, wie Sie es installieren und mit melos verwenden","pt":"O init-import-sorter é uma ferramenta para organizar imports em projetos Flutter com melos, garantindo um código mais legível e manutenível","ru":"Init-import-sorter - это инструмент для организации импортов в проектах Flutter с melos, обеспечивающий более читаемый и поддерживаемый код","ar":"init-import-sorter هو أداة لتنظيم الاستيراد في مشاريع Flutter مع melos، مما يضمن código أكثر قراءة وسهولة في الصيانة"},"seo":{"title":{"en":"init-import-sorter: Setup Guide for Flutter Monorepo Proj...","zh":"init-import-sorter 安装指南：Flutter 多模块项目模板","ja":"init-import-sorter Setup Guide: Flutter マルチモジュール プロジェクト テ...","ko":"init-import-sorter 설정 가이드: Flutter 멀티 모듈 프로젝트 템플릿","es":"Configuración de init-import-sorter: Guía de Instalación ...","fr":"Configurer init-import-sorter : Guide d''Installation et d...","de":"Init-Import-Sorter einrichten: Installations- und Benutze...","pt":"Guia de Configuração do init-import-sorter para Projetos ...","ru":"Установка и Настройка init-import-sorter для Проектов Flu...","ar":"دليل تثبيت وتشغيل init-import-sorter للأمشاريع Flutter"},"description":{"en":"Get started with init-import-sorter for your Flutter projects, learn how to install and use it to sort imports efficiently, and explore its features","zh":"学习如何安装和使用 init-import-sorter，对 Flutter 多模块项目进行 import 排序，提高代码质量","ja":"init-import-sorter をインストールして使用する方法を学び、Flutter マルチモジュール プロジェクトの import を整理してコード品質を向上させましょう","ko":"init-import-sorter 설치 및 사용 방법을 알아보고 Flutter 멀티 모듈 프로젝트의 import를 정렬하여 코드 품질을 향상시키세요","es":"Aprende a instalar y utilizar init-import-sorter en proyectos Flutter multi-módulo con melos","fr":"Découvrez comment installer et utiliser init-import-sorter dans les projets Flutter multi-modules avec melos","de":"Erfahren Sie, wie Sie init-import-sorter in Flutter-Multi-Modul-Projekten mit melos installieren und verwenden","pt":"Aprenda a instalar e usar o init-import-sorter para organizar imports em projetos Flutter com melos","ru":"Узнайте, как установить и использовать init-import-sorter для организации импортов в проектах Flutter с melos","ar":"تعلم كيفية تثبيت وتشغيل init-import-sorter لتنظيم الاستيراد في مشاريع Flutter مع melos"},"definition":{"en":"init-import-sorter is a tool for managing Flutter monorepo projects, providing import sorting capabilities for efficient code organization","zh":"init-import-sorter 是一个 Dart 包，用于对 Flutter 项目中的 import 进行排序和整理","ja":"init-import-sorter は、Flutter プロジェクトの import を整理する Dart パッケージです","ko":"init-import-sorter는 Flutter 프로젝트의 import를 정렬하는 Dart 패키지입니다","es":"Init-import-sorter es una herramienta de ordenación de importaciones para proyectos Flutter multi-módulo","fr":"Init-import-sorter est un outil de tri des importations pour les projets Flutter multi-modules","de":"Init-Import-Sorter ist ein Tool zum Ordnen von Importen für Flutter-Multi-Modul-Projekte","pt":"O init-import-sorter é uma ferramenta de linha de comando para organizar imports em projetos Flutter","ru":"Init-import-sorter - это командная утилита для организации импортов в проектах Flutter","ar":"init-import-sorter هو أداة سطر أوامر لتنظيم الاستيراد في مشاريع Flutter"},"features":{"en":["Installs via dart pub global activate for easy setup","Supports monorepo pub workspaces for large-scale projects","Sorts imports in individual files using the dart pub global run command","Integrates with melos for automated import sorting across all packages","Allows for comment exclusion during import sorting via the --no-comments flag"],"zh":["支持 monorepo pub workspaces","可以对单个文件进行 import 排序","可以通过 melos 对所有包进行 import 排序","使用 dart pub global activate 进行安装","支持 fix/monorepo-pub-workspaces 分支"],"ja":["monorepo pub workspaces をサポート","単一ファイルの import を整理できます","melos を使用してすべてのパッケージの import を整理できます","dart pub global activate を使用してインストール","fix/monorepo-pub-workspaces ブランチをサポート"],"ko":["monorepo pub workspaces 지원","단일 파일의 import를 정렬할 수 있습니다","melos를 사용하여 모든 패키지의 import를 정렬할 수 있습니다","dart pub global activate를 사용하여 설치","fix/monorepo-pub-workspaces 브랜치 지원"],"es":["Soporte para pub workspaces","Instalación mediante dart pub global activate","Ordenación de importaciones en archivos individuales","Ordenación de importaciones en todos los paquetes mediante melos","Compatibilidad con proyectos Flutter multi-módulo","Uso de la opción --no-comments para ordenar importaciones"],"fr":["Prise en charge des espaces de travail pub","Installation via dart pub global activate","Trier les importations dans des fichiers individuels","Trier les importations dans tous les packages via melos","Compatibilité avec les projets Flutter multi-modules","Utilisation de l''option --no-comments pour trier les importations"],"de":["Unterstützung für pub-Workspaces","Installation über dart pub global activate","Ordnen von Importen in einzelnen Dateien","Ordnen von Importen in allen Paketen über melos","Kompatibilität mit Flutter-Multi-Modul-Projekten","Verwendung der Option --no-comments zum Ordnen von Importen"],"pt":["Instalação via dart pub global activate","Suporte a monorepo com pub workspaces","Organização de imports em projetos Flutter com melos","Comando para ordenar imports em um arquivo específico","Comando para ordenar imports em todos os pacotes com melos"],"ru":["Установка через dart pub global activate","Поддержка монорепозитория с pub workspaces","Организация импортов в проектах Flutter с melos","Команда для сортировки импортов в отдельном файле","Команда для сортировки импортов во всех пакетах с melos"],"ar":["التثبيت عبر dart pub global activate","دعم مونوريبوزتوري مع pub workspaces","تنظيم الاستيراد في مشاريع Flutter مع melos","أمر لترتيب الاستيراد في ملف معين","أمر لترتيب الاستيراد في جميع الحزم مع melos"]},"keywords":{"en":["how to use init-import-sorter","init-import-sorter setup guide","init-import-sorter vs import_sorter","init-import-sorter install","flutter monorepo project management","import sorting for dart","melos integration with init-import-sorter","init-import-sorter alternative tools","dart pub global activate init-import-sorter"],"zh":["init-import-sorter","Flutter 多模块项目","import 排序","Dart 包","monorepo pub workspaces","melos","dart pub global activate"],"ja":["init-import-sorter","Flutter マルチモジュール プロジェクト","import 整理","Dart パッケージ","monorepo pub workspaces","melos","dart pub global activate","AIエージェント"],"ko":["init-import-sorter","Flutter 멀티 모듈 프로젝트","import 정렬","Dart 패키지","monorepo pub workspaces","melos","dart pub global activate"],"es":["init-import-sorter","herramientas de desarrollo Flutter","ordenación de importaciones","proyectos multi-módulo","melos","dart pub global activate","desarrollo de aplicaciones móviles","Flutter","programación"],"fr":["init-import-sorter","outils de développement Flutter","tri des importations","projets multi-modules","melos","dart pub global activate","développement d''applications mobiles","Flutter","programmation"],"de":["init-import-sorter","Entwicklungstools für Flutter","Ordnen von Importen","Multi-Modul-Projekte","melos","dart pub global activate","Mobile-App-Entwicklung","Flutter","Programmierung"],"pt":["init-import-sorter","Flutter","melos","organizar imports","dart pub global activate","monorepo","pub workspaces","linha de comando"],"ru":["init-import-sorter","Flutter","melos","организация импортов","dart pub global activate","монорепозиторий","pub workspaces","командная строка"],"ar":["init-import-sorter","Flutter","melos","تنظيم الاستيراد","dart pub global activate","مونوريبوزتوري","pub workspaces","سطر الأوامر"]}},"owner":"AoEiuV020","repo":"flutter_melos_template","repoPath":"AoEiuV020/flutter_melos_template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.299Z","topics":[],"category":"community","skillMd":{"name":"init-import-sorter","description":"Install import_sorter for Dart import sorting. Use when user needs import sorting, wants to sort imports, or gets import_sorter not found. Triggers on install import_sorter, init import sorter, sort imports, setup import_sorter.","bodyPreview":"# 安装 Import Sorter\n\n确保 import_sorter 已安装并可用。使用支持 pub workspaces 的修复版本。\n\n## 安装步骤\n\n```bash\n# 1. 检查是否已安装\ndart pub global list | grep import_sorter\n\n# 2. 如果未安装，从修复分支安装（支持 monorepo pub workspaces）\ndart pub global activate --source git https://github.com/myConsciousness/import_sorter.git --git-ref fix/monorepo-pub-workspaces\n```\n\n## 使用\n\n```bash\n# 对单个文件排序\ndart pub global run import_sorter --no-comments\n\n# 通过 melos 对所有包排序\nmelos sort\n```","body":"# 安装 Import Sorter\n\n确保 import_sorter 已安装并可用。使用支持 pub workspaces 的修复版本。\n\n## 安装步骤\n\n```bash\n# 1. 检查是否已安装\ndart pub global list | grep import_sorter\n\n# 2. 如果未安装，从修复分支安装（支持 monorepo pub workspaces）\ndart pub global activate --source git https://github.com/myConsciousness/import_sorter.git --git-ref fix/monorepo-pub-workspaces\n```\n\n## 使用\n\n```bash\n# 对单个文件排序\ndart pub global run import_sorter --no-comments\n\n# 通过 melos 对所有包排序\nmelos sort\n```\n"},"lastSynced":"2026-03-08T02:01:27.515Z","agentAnalysis":{"suitability":{"en":"Perfect for Flutter Development Agents needing efficient import management in monorepo projects.","zh":"非常适合需要在单体仓库项目中高效管理导入的Flutter开发代理。","ja":"モノレポプロジェクトでの効率的なインポート管理が必要なFlutter開発エージェントに最適です。","ko":"모노레포 프로젝트에서 효율적인 가져오기 관리가 필요한 Flutter 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de Flutter que necesitan una gestión de importación eficiente en proyectos monorepo.","fr":"Parfait pour les agents de développement Flutter ayant besoin d''une gestion d''importation efficace dans les projets monorepo.","de":"Perfekt für Flutter-Entwicklungsagenten, die eine effiziente Importverwaltung in Monorepo-Projekten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Flutter que necessitam de gerenciamento de importação eficiente em projetos monorepo.","ru":"Идеально подходит для агентов разработки Flutter, которым необходим эффективный менеджмент импорта в монорепозиторных проектах.","ar":"مثالي للوكلاء التطوير Flutter الذين يحتاجون إلى إدارة الاستيراد الفعالة في مشاريع monorepo."},"recommendation":{"en":"Empowers agents to organize Flutter codebases by sorting imports, supporting pub workspaces and integration with melos for streamlined development, utilizing dart pub global for activation and management.","zh":"赋予代理组织Flutter代码库的能力，通过排序导入、支持pub工作区和与melos集成以实现开发流程的简化，利用dart pub global进行激活和管理。","ja":"エージェントにFlutterコードベースを整理する能力を与え、インポートの並び替え、pubワークスペースのサポート、melosとの統合による開発の簡素化を実現し、dart pub globalを使用してアクティブ化と管理を行う。","ko":"에이전트에 Flutter 코드베이스를 정리할 수 있는 능력을 부여하여, 가져오기 정렬, pub 작업 공간 지원 및 melos와의 통합을 통해 개발을 간소화하며, dart pub global을 사용하여 활성화 및 관리합니다.","es":"Habilita a los agentes a organizar las bases de código de Flutter ordenando las importaciones, admitiendo espacios de trabajo de pub y la integración con melos para un desarrollo fluido, utilizando dart pub global para la activación y la gestión.","fr":"Permet aux agents d''organiser les bases de code Flutter en triant les imports, en prenant en charge les espaces de travail pub et l''intégration avec melos pour un développement fluide, en utilisant dart pub global pour l''activation et la gestion.","de":"Ermächtigt die Agenten, die Flutter-Codebasis zu organisieren, indem die Importe sortiert, die pub-Arbeitsbereiche unterstützt und die Integration mit melos für eine reibungslose Entwicklung ermöglicht wird, wobei dart pub global für die Aktivierung und Verwaltung verwendet wird.","pt":"Habilita os agentes a organizar codebases Flutter, classificando imports, suportando pub workspaces e integração com melos para desenvolvimento otimizado, utilizando dart pub global para ativação e gerenciamento.","ru":"Наделяет агентов возможностью организовывать кодовые базы Flutter, сортируя импорты, поддерживая pub workspaces и интеграцию с melos для оптимизированного развития, используя dart pub global для активации и управления.","ar":"يمنح الوكلاء khảية تنظيم قواعد Flutter بالترتيب imports، دعم مساحات العمل pub وتكامل مع melos من أجل التطوير المتدفق، باستخدام dart pub global للتفعيل والإدارة."},"useCases":{"en":["Sorting imports in individual Flutter files","Automating import sorting across all packages with melos","Maintaining consistent code structure in monorepo projects"],"zh":["在单个Flutter文件中排序导入","使用melos自动对所有包进行导入排序","在单体仓库项目中保持一致的代码结构"],"ja":["個々のFlutterファイルでのインポートの並び替え","melosを使用してすべてのパッケージでインポートの並び替えを自動化する","モノレポプロジェクトで一貫したコード構造を維持する"],"ko":["개별 Flutter 파일에서 가져오기 정렬","melos를 사용하여 모든 패키지에서 가져오기 정렬 자동화","모노레포 프로젝트에서 일관된 코드 구조 유지"],"es":["Ordenar importaciones en archivos Flutter individuales","Automatizar la ordenación de importaciones en todos los paquetes con melos","Mantener una estructura de código consistente en proyectos monorepo"],"fr":["Trier les imports dans les fichiers Flutter individuels","Automatiser le tri des imports dans tous les packages avec melos","Maintenir une structure de code cohérente dans les projets monorepo"],"de":["Importe in einzelnen Flutter-Dateien sortieren","Automatisieren des Import-Sortierens in allen Paketen mit melos","Beibehalten einer konsistenten Code-Struktur in Monorepo-Projekten"],"pt":["Classificação de imports em arquivos Flutter individuais","Automatização da classificação de imports em todos os pacotes com melos","Manutenção de estrutura de código consistente em projetos monorepo"],"ru":["Сортировка импортов в отдельных файлах Flutter","Автоматизация сортировки импортов во всех пакетах с melos","Поддержание последовательной структуры кода в монорепозиторных проектах"],"ar":["ترتيب imports في ملفات Flutter الفردية","أتمتة ترتيب imports في جميع الحزم مع melos","الحفاظ على هيكل التعليمات البرمجية المتسق في مشاريع monorepo"]},"limitations":{"en":["Requires dart pub global installation","Specifically designed for Flutter and Dart ecosystems"],"zh":["需要安装dart pub global","专门为Flutter和Dart生态系统设计"],"ja":["dart pub globalのインストールが必要","FlutterおよびDartエコシステム専用に設計"],"ko":["dart pub global 설치가 필요","Flutter 및 Dart 생태계 전용으로 설계"],"es":["Requiere la instalación de dart pub global","Diseñado específicamente para los ecosistemas de Flutter y Dart"],"fr":["Nécessite l''installation de dart pub global","Conçu spécifiquement pour les écosystèmes Flutter et Dart"],"de":["Erfordert die Installation von dart pub global","Speziell für die Flutter- und Dart-Ökosysteme konzipiert"],"pt":["Requer instalação do dart pub global","Especificamente projetado para os ecossistemas Flutter e Dart"],"ru":["Требует установки dart pub global","Спецально разработан для экосистем Flutter и Dart"],"ar":["يتطلب تثبيت dart pub global","صمّم خصيصًا لأنظمة Flutter وDart"]},"version":4},"contentHash":"ac54f6fb89df70e37d4a8cdf68a8fb241ff9e9c3421f552e82078822d50172d6","qualityScore":30}');
