INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AoEiuV020/flutter_melos_template/init-import-sorter', 'init-import-sorter', 'AoEiuV020', 'flutter_melos_template', 'community', 'init-import-sorter AoEiuV020 flutter_melos_template community The init-import-sorter skill helps developers manage Flutter monorepo projects by sorting imports. It supports pub workspaces and can be used with melos. init-import-sorter 是一个用于 Flutter 多模块项目的 import 排序工具，帮助开发者保持代码的整洁和可读性 init-import-sorter は、Flutter マルチモジュール プロジェクトの import を整理するツールで、コードの整頓と可読性を向上させます init-import-sorter는 Flutter 멀티 모듈 프로젝트의 import를 정렬하는 도구로 코드의 깔끔함과 가독성을 유지하는 데 도움이 됩니다 Init-import-sorter es una herramienta para ordenar importaciones en proyectos Flutter. Aprende a instalar y utilizarla con melos Init-import-sorter est un outil pour trier les importations dans les projets Flutter. Découvrez comment l''installer et l''utiliser avec melos Init-Import-Sorter ist ein Tool zum Ordnen von Importen in Flutter-Projekten. Erfahren Sie, wie Sie es installieren und mit melos verwenden O init-import-sorter é uma ferramenta para organizar imports em projetos Flutter com melos, garantindo um código mais legível e manutenível Init-import-sorter - это инструмент для организации импортов в проектах Flutter с melos, обеспечивающий более читаемый и поддерживаемый код init-import-sorter هو أداة لتنظيم الاستيراد في مشاريع Flutter مع melos، مما يضمن código أكثر قراءة وسهولة في الصيانة how to use init-import-sorter init-import-sorter setup guide init-import-sorter vs import_sorter init-import-sorter install flutter monorepo project management import sorting for dart melos integration with init-import-sorter init-import-sorter alternative tools dart pub global activate init-import-sorter init-import-sorter Flutter 多模块项目 import 排序 Dart 包 monorepo pub workspaces melos dart pub global activate Installs via dart pub global activate for easy setup Supports monorepo pub workspaces for large-scale projects Sorts imports in individual files using the dart pub global run command Integrates with melos for automated import sorting across all packages Allows for comment exclusion during import sorting via the --no-comments flag init-import-sorter is a tool for managing Flutter monorepo projects, providing import sorting capabilities for efficient code organization');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kmylpenter/KFG-CCv2-Installer-Stable/updatekfg', 'community', 'kmylpenter', 'KFG-CCv2-Installer-Stable', 'kmylpenter/KFG-CCv2-Installer-Stable', 'updatekfg', 0, 0, 30, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:29.993Z', '1d02bc1e8e77a33256466101656eeb2f407c3c71a689f5da4299faaa4d5bb898', '{"id":"kmylpenter/KFG-CCv2-Installer-Stable/updatekfg","name":"updatekfg","description":{"en":"The updatekfg skill updates the KFG environment to synchronize changes across all devices, benefiting developers working with KFG CCv2 installations.","zh":"updatekfg 是用于 KFG CCv2 安装和备份的工具，确保在 CCv3 迁移前数据的安全","ja":"updatekfg は KFG CCv2 のインストールとバックアップを行うツールです。CCv3 への移行前にデータのセキュリティを確保します","ko":"updatekfg는 KFG CCv2 설치 및 백업을 위한 도구로 CCv3 마이그레이션 전에 데이터의 보안을 보장합니다","es":"Updatekfg es una herramienta para actualizar el entorno KFG y sincronizar cambios en todos los dispositivos","fr":"Updatekfg est un outil pour mettre à jour l''environnement KFG et synchroniser les modifications sur tous les appareils","de":"Updatekfg ist ein Tool zum Aktualisieren der KFG-Umgebung und zur Synchronisierung von Änderungen auf allen Geräten","pt":"O updatekfg é um skill que atualiza o ambiente KFG para sincronizar alterações em todos os dispositivos com o instalador KFG CCv2 estável.","ru":"updatekfg — это навык, который обновляет среду KFG для синхронизации изменений на все устройства с помощью установщика KFG CCv2 стабильной версии.","ar":"updatekfg هو مهارة تحديث بيئة KFG لتزامن التغييرات على جميع الأجهزة باستخدام مثبت KFG CCv2 المستقر."},"seo":{"title":{"en":"updatekfg: KFG CCv2 Installer Setup Guide | AI Agent Skill","zh":"updatekfg 安装指南 - KFG CCv2 升级和备份","ja":"updatekfg セットアップガイド - KFG CCv2 インストーラーとバックアップ","ko":"updatekfg 설치 가이드 - KFG CCv2 설치 및 백업","es":"Guía de configuración de updatekfg para KFG CCv2","fr":"Guide d''installation de updatekfg pour KFG CCv2","de":"Einrichtungsanleitung für updatekfg in KFG CCv2","pt":"Guia de Configuração updatekfg: Instalador KFG CCv2 Estável","ru":"Настройка updatekfg: Установщик KFG CCv2 Стабильный","ar":"دليل إعداد updatekfg: مثبت KFG CCv2 مستقر"},"description":{"en":"Discover how to backup before CCv3 migration with updatekfg. Learn to synchronize KFG changes across devices and get started with the KFG CCv2 installer today!","zh":"了解如何使用 updatekfg 实现 KFG CCv2 的稳定安装和备份，确保在迁移到 CCv3 时数据安全","ja":"updatekfg を使用して KFG CCv2 の安定したインストールとバックアップを行う方法を学びます。CCv3 への移行時のデータのセキュリティを確保します","ko":"updatekfg를 사용하여 KFG CCv2의 안정적인 설치 및 백업을 수행하는 방법을 알아보고 CCv3로의 마이그레이션 시 데이터 보안을 보장합니다","es":"Aprende a actualizar tu entorno KFG con updatekfg y prepara tu migración a CCv3","fr":"Découvrez comment mettre à jour votre environnement KFG avec updatekfg avant la migration vers CCv3","de":"Erfahren Sie, wie Sie Ihre KFG-Umgebung mit updatekfg aktualisieren und auf die Migration zu CCv3 vorbereiten","pt":"Aprenda a configurar o updatekfg para sincronizar alterações KFG em todos os dispositivos com o instalador KFG CCv2 estável","ru":"Узнайте, как настроить updatekfg для синхронизации изменений KFG на все устройства с помощью установщика KFG CCv2 стабильной версии","ar":"تعرف على كيفية 설정 updatekfg لتزامن تغييرات KFG على جميع الأجهزة باستخدام مثبت KFG CCv2 المستقر"},"definition":{"en":"updatekfg is a KFG CCv2 installer skill that backs up environments before CCv3 migration, ensuring seamless synchronization of KFG changes.","zh":"updatekfg 是一种 KFG CCv2 的安装和备份工具","ja":"updatekfg は KFG CCv2 用のインストールとバックアップツールです","ko":"updatekfg는 KFG CCv2용 설치 및 백업 도구입니다","es":"Updatekfg es una herramienta de actualización para KFG que sincroniza reglas y configuraciones","fr":"Updatekfg est un outil de mise à jour pour KFG qui synchronise les règles et les configurations","de":"Updatekfg ist ein Aktualisierungstool für KFG, das Regeln und Konfigurationen synchronisiert","pt":"O updatekfg é um skill de atualização do ambiente KFG","ru":"updatekfg — это навык обновления среды KFG","ar":"updatekfg هو مهارة تحديث بيئة KFG"},"features":{"en":["Synchronizes KFG changes across all devices via the /updatekfg command","Copies installer files from KFG/.claude/ to ~/.claude/","Supports global instructions via CLAUDE.md files","Manages permissions, hooks, and status lines through settings.json","Automates rules using rules/*.md files","Validates changes with hooks/* scripts"],"zh":["支持 KFG CCv2 的安装和备份","自动同步 KFG 更改到所有设备","支持 CLAUDE.md 全局指令","支持 settings.json 配置文件","支持 rules/*.md 自动规则","支持 hooks/* 验证脚本"],"ja":["KFG CCv2 のインストールとバックアップをサポート","KFG の変更をすべてのデバイスに自動同期","CLAUDE.md グローバル指令をサポート","settings.json 構成ファイルをサポート","rules/*.md 自動ルールをサポート","hooks/* 検証スクリプトをサポート"],"ko":["KFG CCv2 설치 및 백업을 지원","KFG 변경 사항을 모든 장치에 자동 동기화","CLAUDE.md 전역 지침을 지원","settings.json 구성 파일을 지원","rules/*.md 자동 규칙을 지원","hooks/* 검증 스크립트를 지원"],"es":["Actualiza el entorno KFG a la versión más reciente","Sincroniza reglas y configuraciones en todos los dispositivos","Soporte para KFG CCv2 y preparación para la migración a CCv3","Compatibilidad con archivos de configuración como settings.json y CLAUDE.md","Integración con hooks y scripts de validación","Sincronización de estado y línea de estado"],"fr":["Mise à jour de l''environnement KFG vers la version la plus récente","Synchronisation des règles et des configurations sur tous les appareils","Prise en charge de KFG CCv2 et préparation pour la migration vers CCv3","Compatibilité avec les fichiers de configuration tels que settings.json et CLAUDE.md","Intégration avec les hooks et les scripts de validation","Synchronisation de l''état et de la ligne d''état"],"de":["Aktualisierung der KFG-Umgebung auf die neueste Version","Synchronisierung von Regeln und Konfigurationen auf allen Geräten","Unterstützung für KFG CCv2 und Vorbereitung auf die Migration zu CCv3","Kompatibilität mit Konfigurationsdateien wie settings.json und CLAUDE.md","Integration mit Hooks und Validierungsskripten","Synchronisierung von Status und Statuszeile"],"pt":["Sincronização de alterações KFG em todos os dispositivos","Instalador KFG CCv2 estável","Suporte a arquivos de configuração como settings.json e CLAUDE.md","Integração com hooks e regras automatizadas","Compatibilidade com statusline e welcome.txt"],"ru":["Синхронизация изменений KFG на все устройства","Установщик KFG CCv2 стабильной версии","Поддержка файлов конфигурации, таких как settings.json и CLAUDE.md","Интеграция с хуками и автоматическими правилами","Совместимость со статусной строкой и welcome.txt"],"ar":["تزامن التغييرات KFG على جميع الأجهزة","مثبت KFG CCv2 المستقر","دعم ملفات التكوين مثل settings.json و CLAUDE.md","التكامل مع Hooks والقواعد التلقائية","التوافق مع سطر الحالة و welcome.txt"]},"keywords":{"en":["how to use updatekfg","what is updatekfg","updatekfg alternative","updatekfg vs KFG CCv3","updatekfg install guide","KFG CCv2 installer setup","synchronizing KFG changes","backup before CCv3 migration"],"zh":["updatekfg","KFG CCv2","安装指南","备份工具","AI工具","KFG 安装","CCv2 升级","数据安全"],"ja":["updatekfg","KFG CCv2","インストールガイド","バックアップツール","AIエージェント","KFG インストール","CCv2 アップグレード","データセキュリティ"],"ko":["updatekfg","KFG CCv2","설치 가이드","백업 도구","AI 에이전트","KFG 설치","CCv2 업그레이드","데이터 보안"],"es":["updatekfg","KFG CCv2","migración a CCv3","herramientas de actualización","sincronización de configuraciones","reglas de automatización","hooks y scripts de validación","CLI y línea de comandos"],"fr":["updatekfg","KFG CCv2","migration vers CCv3","outils de mise à jour","synchronisation de configurations","règles d''automatisation","hooks et scripts de validation","CLI et ligne de commande"],"de":["updatekfg","KFG CCv2","Migration zu CCv3","Aktualisierungstools","Synchronisierung von Konfigurationen","Automatisierungsregeln","Hooks und Validierungsskripte","CLI und Befehlszeile"],"pt":["updatekfg","KFG CCv2","instalador estável","sincronização de alterações","ambiente KFG","settings.json","CLAUDE.md","hooks","regras automatizadas"],"ru":["updatekfg","KFG CCv2","установщик стабильной версии","синхронизация изменений","среда KFG","settings.json","CLAUDE.md","хуки","автоматические правила"],"ar":["updatekfg","KFG CCv2","مثبت المستقر","تزامن التغييرات","بيئة KFG","settings.json","CLAUDE.md","Hooks","القواعد التلقائية"]}},"owner":"kmylpenter","repo":"KFG-CCv2-Installer-Stable","repoPath":"kmylpenter/KFG-CCv2-Installer-Stable","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"updatekfg","description":"Synchronizacja KFG między urządzeniami (Windows/Android). Triggers: sync KFG, updatekfg, zaktualizuj","bodyPreview":"# /updatekfg - Aktualizacja środowiska KFG\n\nSkill do synchronizacji zmian KFG na wszystkie urządzenia.\n\n## Architektura KFG (PRZECZYTAJ!)\n\n```\nKFG/.claude/           →  ~/.claude/ (instalatory kopiują)\n├── CLAUDE.md          →  CLAUDE.md (globalne instrukcje)\n├── settings.json      →  settings.json (permissions + hooks + statusLine)\n├── rules/*.md         →  rules/*.md (reguły automatyczne)\n├── hooks/*            →  hooks/* (skrypty walidacji)\n├── welcome.txt        →  welcome.txt\n├── statusline","body":"# /updatekfg - Aktualizacja środowiska KFG\n\nSkill do synchronizacji zmian KFG na wszystkie urządzenia.\n\n## Architektura KFG (PRZECZYTAJ!)\n\n```\nKFG/.claude/           →  ~/.claude/ (instalatory kopiują)\n├── CLAUDE.md          →  CLAUDE.md (globalne instrukcje)\n├── settings.json      →  settings.json (permissions + hooks + statusLine)\n├── rules/*.md         →  rules/*.md (reguły automatyczne)\n├── hooks/*            →  hooks/* (skrypty walidacji)\n├── welcome.txt        →  welcome.txt\n├── statusline-wrapper.ps1/.sh  →  statusline wrapper\n├── analyze-history.ps1         →  analiza historii (Windows)\n└── export-device-stats.ps1     →  eksport stats (Windows)\n\nKFG/platform/\n├── android/           →  Android-specific overrides (merge przy instalacji)\n└── windows/           →  Windows-specific overrides\n\nKFG/setup/config/\n├── termux/.bashrc     →  ~/.bashrc (Android - append)\n├── termux/.tmux.conf  →  ~/.tmux.conf (Android)\n├── ccstatusline/      →  ~/.config/ccstatusline/ (statusline config)\n└── .templates/        →  ~/.templates/ (szablony walidacji)\n\nKFG/desktop/\n├── install.ps1        →  Jednorazowy instalator Windows (generuje inline)\n├── sync-env.ps1       →  Auto-sync przy każdym `cc` (kopiuje z KFG)\n└── config/            →  Windows-specific configs\n```\n\n## Mechanizmy synchronizacji\n\n| Platforma | Instalacja | Codzienna sync |\n|-----------|------------|----------------|\n| **Windows** | `desktop/install.ps1` | Junction (jak symlink) LUB sync-env.ps1 |\n| **Android** | `install.sh` (symlink) | Automatyczny (symlink) |\n\n**WAŻNE:**\n- Android używa SYMLINK ~/.claude/ → KFG/.claude/ - zmiany w KFG są natychmiast widoczne\n- Windows: install.ps1 tworzy JUNCTION ~/.claude/ → KFG/.claude/ (jak symlink)\n  - Edycja ~/.claude/* = edycja KFG/.claude/* (ten sam plik!)\n  - Git widzi zmiany w KFG/.claude/ automatycznie\n  - Jeśli junction nie działa: sync-env.ps1 kopiuje przy `cc`\n\n**UWAGA dla Claude:** Edytuj ~/.claude/CLAUDE.md LUB KFG/.claude/CLAUDE.md - to ten sam plik (junction)!\n\n## Checklist: Co zaktualizować\n\nPrzed commitem sprawdź które pliki dotyczą zmiany:\n\n### 1. Instrukcje Claude (CLAUDE.md, rules/)\n```\n[ ] KFG/.claude/CLAUDE.md - główne instrukcje\n[ ] KFG/.claude/rules/*.md - reguły automatyczne\n```\n**Sync:** Android=natychmiast, Windows=przy `cc`\n\n### 2. Settings (permissions, hooks, statusLine)\n```\n[ ] KFG/.claude/settings.json - base settings\n[ ] KFG/platform/android/settings-override.json - Android override\n[ ] KFG/platform/windows/settings-override.json - Windows override (jeśli istnieje)\n```\n**Sync:** Android=natychmiast, Windows=sync-env kopiuje tylko jeśli nie istnieje lub -Force\n\n### 3. Hooks (walidacja, pre-compact)\n```\n[ ] KFG/.claude/hooks/*.ps1 - Windows hooks\n[ ] KFG/.claude/hooks/*.sh - Android hooks\n```\n**Sync:** Android=natychmiast, Windows=sync-env\n\n### 4. StatusLine scripts\n```\n[ ] KFG/.claude/statusline-wrapper.ps1 - Windows wrapper\n[ ] KFG/.claude/statusline-wrapper.sh - Android wrapper\n[ ] KFG/.claude/analyze-history.ps1 - analiza historii (Windows only)\n[ ] KFG/.claude/export-device-stats.ps1 - eksport stats (Windows only)\n[ ] KFG/setup/config/ccstatusline/settings.json - ccstatusline config\n```\n**Sync:** Windows=sync-env, Android=symlink (ale .sh tylko!)\n\n### 5. Bashrc / Shell functions\n```\n[ ] KFG/setup/config/termux/.bashrc - funkcje bash (p, np, cc, gs...)\n[ ] KFG/setup/config/bashrc - alternative location\n```\n**Sync:** Android=wymaga `source ~/.bashrc` lub reinstall\n\n### 6. Templates\n```\n[ ] KFG/setup/config/.templates/ - szablony walidacji\n[ ] KFG/.templates/ - alternative location\n```\n**Sync:** Android=install.sh kopiuje, Windows=install.ps1 generuje inline\n\n### 7. Instalatory (jeśli zmiana wymaga)\n```\n[ ] KFG/install.sh - Android/Linux instalator\n[ ] KFG/desktop/install.ps1 - Windows instalator\n[ ] KFG/desktop/sync-env.ps1 - Windows daily sync\n```\n\n## Workflow aktualizacji\n\n### Mała zmiana (reguły, instrukcje)\n```bash\n# 1. Edytuj pliki w KFG/.claude/\n# 2. Commit + push\ngit add -A && git commit -m \"update: [co]\" && git push\n\n# Android: automatycznie (symlink)\n# Windows: przy następnym `cc` (sync-env.ps1)\n```\n\n### Duża zmiana (nowy feature, settings)\n```bash\n# 1. Edytuj pliki źródłowe w KFG/\n# 2. Sprawdź czy sync-env.ps1 obsługuje nowe pliki\n# 3. Commit + push\n# 4. Na innych urządzeniach: git pull (Android) lub cc (Windows)\n```\n\n### Zmiana wymagająca reinstalacji\n```bash\n# Jeśli zmieniłeś:\n# - install.sh / install.ps1\n# - strukturę katalogów\n# - nowe pliki których sync-env nie kopiuje\n\n# Android: ./install.sh --force\n# Windows: .\\desktop\\install.ps1 (lub cc z -Force sync)\n```\n\n## Przykłady\n\n### Dodanie nowej reguły\n```\n1. Utwórz: KFG/.claude/rules/nowa-regula.md\n2. git add && commit && push\n3. Android: automatycznie działa (symlink)\n4. Windows: przy następnym `cc`\n```\n\n### Zmiana statusline\n```\n1. Edytuj: KFG/.claude/statusline-wrapper.ps1 (Windows)\n2. Edytuj: KFG/.claude/statusline-wrapper.sh (Android) - jeśli dotyczy\n3. sync-env.ps1 już kopiuje te pliki\n4. git add && commit && push\n```\n\n### Nowy skrypt do sync\n```\n1. Utwórz skrypt w KFG/.claude/\n2. Dodaj do sync-env.ps1 $statuslineScripts array (jeśli .ps1)\n3. Dla Android: utwórz .sh wersję (symlink = auto)\n4. git add && commit && push\n```\n\n## Weryfikacja\n\nPo aktualizacji sprawdź:\n```powershell\n# Windows - sprawdź czy pliki są aktualne\nls ~/.claude/*.ps1\ncat ~/.claude/CLAUDE.md | head -20\n\n# Porównaj z KFG\ndiff ~/.claude/CLAUDE.md $KFG/.claude/CLAUDE.md\n```\n\n```bash\n# Android - symlink powinien działać\nls -la ~/.claude/  # powinno pokazać -> KFG/.claude/\ncat ~/.claude/CLAUDE.md | head -20\n```\n\n## TODO (brakujące)\n\n- [ ] Android: analyze-history.sh (bash wersja)\n- [ ] Android: export-device-stats.sh (bash wersja)\n- [ ] Cross-device stats agregacja na Androidzie\n"},"lastSynced":"2026-03-08T02:01:29.993Z","agentAnalysis":{"suitability":{"en":"Ideal for KFG CCv2 Developers needing seamless environment synchronization across devices.","zh":"适合需要在设备间实现无缝环境同步的KFG CCv2开发人员。","ja":"KFG CCv2開発者がデバイス間でシームレスな環境同期を必要とする場合に最適です。","ko":"장치 간에 무결점 환경 동기화를 필요로 하는 KFG CCv2 개발자에게 적합합니다.","es":"Ideal para desarrolladores de KFG CCv2 que necesitan una sincronización de entorno sin problemas entre dispositivos.","fr":"Idéal pour les développeurs KFG CCv2 ayant besoin d''une synchronisation d''environnement transparente entre appareils.","de":"Ideal für KFG CCv2-Entwickler, die eine nahtlose Umgebungsynchronisierung zwischen Geräten benötigen.","pt":"Ideal para desenvolvedores do KFG CCv2 que precisam de sincronização de ambiente sem interrupções entre dispositivos.","ru":"Идеально для разработчиков KFG CCv2, которым необходима бесшовная синхронизация среды на всех устройствах.","ar":"مثالي لمطوري KFG CCv2 الذين يحتاجون إلى تنسيق بيئة بدون انقطاع عبر الأجهزة."},"recommendation":{"en":"Empowers agents to synchronize KFG environment changes, ensuring consistency across all devices by updating settings.json, rules/*.md, and hooks/*, thereby streamlining development and validation processes.","zh":"赋予代理人同步KFG环境更改的能力，通过更新settings.json、rules/*.md和hooks/*，确保所有设备的一致性，从而简化开发和验证过程。","ja":"KFG環境の変更を同期するエージェントを可能にし、settings.json、rules/*.md、hooks/*を更新することで、すべてのデバイスでの一貫性を確保し、開発と検証プロセスを簡素化します。","ko":"KFG 환경 변경을 동기화할 수 있는 에이전트를 가능하게 하며, settings.json, rules/*.md 및 hooks/*를 업데이트하여 모든 장치에서 일관성을 보장함으로써 개발 및 검증 과정을 간소화합니다.","es":"Habilita a los agentes a sincronizar los cambios del entorno de KFG, garantizando la coherencia en todos los dispositivos al actualizar settings.json, rules/*.md y hooks/*, lo que simplifica los procesos de desarrollo y validación.","fr":"Permet aux agents de synchroniser les modifications de l''environnement KFG, assurant ainsi la cohérence sur tous les appareils en mettant à jour settings.json, rules/*.md et hooks/*, ce qui simplifie les processus de développement et de validation.","de":"Ermächtigt Agenten, KFG-Umgebungsänderungen zu synchronisieren, um die Konsistenz auf allen Geräten sicherzustellen, indem settings.json, rules/*.md und hooks/* aktualisiert werden, wodurch die Entwicklungs- und Validierungsprozesse gestreamt werden.","pt":"Habilita agentes a sincronizar alterações no ambiente do KFG, garantindo consistência em todos os dispositivos ao atualizar settings.json, rules/*.md e hooks/*, o que simplifica os processos de desenvolvimento e validação.","ru":"Наделяет агентов возможностью синхронизировать изменения среды KFG, обеспечивая согласованность на всех устройствах путем обновления settings.json, rules/*.md и hooks/*, тем самым оптимизируя процессы разработки и проверки.","ar":"تمكين الوكلاء من مزامنة التغييرات في بيئة KFG، مما يضمن الاتساق عبر جميع الأجهزة من خلال تحديث settings.json و rules/*.md و hooks/*، مما يبسط عمليات التطوير والتحقق."},"useCases":{"en":["Synchronizing KFG CCv2 installations","Updating global instructions in CLAUDE.md","Validating environment settings across devices"],"zh":["同步KFG CCv2安装","在CLAUDE.md中更新全局指令","跨设备验证环境设置"],"ja":["KFG CCv2のインストールを同期する","CLAUDE.md内のグローバル指令を更新する","デバイス間で環境設定を検証する"],"ko":["KFG CCv2 설치를 동기화하는 것","CLAUDE.md에서 전역 지침을 업데이트하는 것","장치 간에 환경 설정을 검증하는 것"],"es":["Sincronización de instalaciones de KFG CCv2","Actualización de instrucciones globales en CLAUDE.md","Validación de la configuración del entorno en varios dispositivos"],"fr":["Synchronisation des installations KFG CCv2","Mise à jour des instructions globales dans CLAUDE.md","Validation des paramètres d''environnement sur plusieurs appareils"],"de":["Synchronisierung von KFG CCv2-Installationen","Aktualisierung globaler Anweisungen in CLAUDE.md","Validierung der Umgebungs-Einstellungen auf mehreren Geräten"],"pt":["Sincronização de instalações do KFG CCv2","Atualização de instruções globais em CLAUDE.md","Validação de configurações de ambiente em dispositivos"],"ru":["Синхронизация установок KFG CCv2","Обновление глобальных инструкций в CLAUDE.md","Проверка параметров среды на устройствах"],"ar":["مزامنة تثبيتات KFG CCv2","تحديث الإرشادات العالمية في CLAUDE.md","التحقق من إعدادات البيئة عبر الأجهزة"]},"limitations":{"en":["Requires KFG CCv2 installation","Needs access to ~/.claude/ directory"],"zh":["需要KFG CCv2安装","需要访问~/.claude/目录"],"ja":["KFG CCv2のインストールが必要","~/.claude/ディレクトリへのアクセスが必要"],"ko":["KFG CCv2 설치가 필요합니다","~/.claude/ 디렉토리에 대한 액세스가 필요합니다"],"es":["Requiere instalación de KFG CCv2","Necesita acceso al directorio ~/.claude/"],"fr":["Nécessite une installation KFG CCv2","Nécessite un accès au répertoire ~/.claude/"],"de":["Benötigt KFG CCv2-Installation","Benötigt Zugriff auf das Verzeichnis ~/.claude/"],"pt":["Requer instalação do KFG CCv2","Necessita acesso ao diretório ~/.claude/"],"ru":["Требуется установка KFG CCv2","Требуется доступ к кат