INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryok/claude-beatlab/tech-blog', 'tech-blog', 'ryok', 'claude-beatlab', 'community', 'tech-blog ryok claude-beatlab community The tech-blog skill generates Zenn tech blog articles, including project, tutorial, and til types, to help developers create content efficiently. AIエージェント技术博客创建工具支持项目、教程和TIL文章的创建，提供Zenn Frontmatter模板 AIエージェントによるテックブログ記事作成ツールは、プロジェクト、チュートリアル、TIL記事を作成するためのZenn Frontmatterテンプレートを提供 AI 에이전트 기술 블로그 생성 도구는 프로젝트, 튜토리얼, TIL 게시물 생성을 위한 Zenn Frontmatter 템플릿을 제공합니다 El skill tech-blog de AI Agent permite crear artículos técnicos personalizados con tipos de artículos y plantillas definidos Le skill tech-blog d''AI Agent permet de créer des articles techniques personnalisés avec des types d''articles et des modèles définis Das tech-blog-Skill von AI-Tool ermöglicht die Erstellung von benutzerdefinierten technischen Artikeln mit Artikeltypen und Vorlagen O tech-blog é uma habilidade que permite criar artigos técnicos para o Zenn, incluindo projetos, tutoriais e dicas Тех-блог - это навык, который позволяет создавать технические статьи для Zenn, включая проекты, уроки и советы التقني-مدونة هو مهارة تسمح بإنشاء مقالات تقنية لمنصة Zenn، بما في ذلك المشاريع و الدروس و النصائح how to use tech-blog what is tech-blog tech-blog alternative tech-blog vs zenn tech-blog setup guide tech-blog install zenn tech blog article generation ai agent tech blog skills markdown article generation AIエージェント 技术博客 Zenn Frontmatter 项目 教程 TIL AI技术 技术写作 Determines article type based on user input Collects information from codebases as needed Uses references/templates.md for template-based output Generates articles with Zenn frontmatter Saves articles in Markdown format to articles/<slug>.md Supports project, tutorial, and til article types tech-blog is a skill that generates Zenn tech blog articles using a workflow that includes type determination, information collection, and template-based output.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dupipcom/morpheus/the-linter', 'community', 'dupipcom', 'morpheus', 'dupipcom/morpheus', 'the-linter', 0, 0, 30, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:30.895Z', 'f5519eb08b5266855fcbab0a8a2441b44131d072cdd07f24e7a7340eb0f27447', '{"id":"dupipcom/morpheus/the-linter","name":"the-linter","description":{"en":"The the-linter skill helps code quality engineers maintain clean, consistent, and type-safe code by running ESLint checks and fixing errors. It benefits developers working on Dupip Monorepo projects.","zh":"the-linter 是一个自动检测和修复 TypeScript 错误、ESLint 规则违反和未使用的导入的工具","ja":"the-linter は、ESLint チェックとエラー修復を自動化するツールです","ko":"the-linter는 TypeScript 오류, ESLint 규칙 위반 및 미사용 된 가져오기를 자동으로 감지하고 수정하는 도구입니다","es":"the-linter es una herramienta para mantener un código limpio y consistente, utilizando ESLint para identificar errores y advertencias","fr":"the-linter est un outil pour maintenir un code propre et cohérent, utilisant ESLint pour identifier les erreurs et les avertissements","de":"the-linter ist ein Tool, um einen sauberen und konsistenten Code zu halten, indem ESLint verwendet wird, um Fehler und Warnungen zu identifizieren","pt":"O the-linter é uma ferramenta para melhorar a qualidade do código, executando verificações de ESLint e corrigindo erros de forma sistemática.","ru":"ИИ Агент the-linter - это инструмент для улучшения качества кода, выполняющий проверки ESLint и исправляющий ошибки систематически.","ar":"العامل الذكي the-linter هو أداة لتحسين جودة الكود، يقوم بتنفيذ عمليات فحص ESLint وتصحيح الأخطاء بشكل منهجي."},"seo":{"title":{"en":"the-linter: Automated Code Quality Setup Guide | AI Agent...","zh":"the-linter 设置指南：TypeScript 错误检测和修复","ja":"the-linter のベストプラクティス：ESLint チェックとエラー修復","ko":"the-linter 설정 가이드: TypeScript 오류 감지 및 수정","es":"Guía de Configuración de the-linter para ESLint","fr":"Guide de Configuration de the-linter pour ESLint","de":"Einrichtungsleitfaden für the-linter mit ESLint","pt":"Guia de Configuração do the-linter para Desenvolvedores","ru":"Настройка ИИ Агента the-linter для Разработчиков","ar":"دليل إعداد العامل الذكي the-linter لل مطورين"},"description":{"en":"Discover how to systematically fix ESLint errors with the-linter. Learn to run npm lint commands and prioritize type errors for cleaner code.","zh":"使用 the-linter 自动检测和修复 TypeScript 错误、ESLint 规则违反和未使用的导入","ja":"the-linter を使用して ESLint チェックとエラー修復を自動化する方法","ko":"the-linter를 사용하여 TypeScript 오류, ESLint 규칙 위반 및 미사용 된 가져오기를 자동으로 감지하고 수정하는 방법","es":"Aprende a configurar the-linter para identificar y corregir errores en tu código con ESLint","fr":"Découvrez comment configurer the-linter pour identifier et corriger les erreurs dans votre code avec ESLint","de":"Erfahren Sie, wie Sie the-linter einrichten, um Fehler in Ihrem Code mit ESLint zu identifizieren und zu korrigieren","pt":"Aprenda a configurar e utilizar o the-linter para melhorar a qualidade do código com ESLint e TypeScript","ru":"Узнайте, как настроить и использовать ИИ Агент the-linter для улучшения качества кода с помощью ESLint и TypeScript","ar":"تعرف على كيفية تنظیم و استخدام العامل الذكي the-linter لتحسين جودة الكود باستخدام ESLint و TypeScript"},"definition":{"en":"the-linter is a code quality tool that runs ESLint checks, identifies errors, and systematically fixes them to ensure consistent and type-safe code.","zh":"the-linter 是一个代码质量工程工具，用于检测和修复 TypeScript 错误和 ESLint 规则违反","ja":"the-linter は、コード品質エンジニアリングツールであり、TypeScript エラーと ESLint ルール違反を検出して修復します","ko":"the-linter는 코드 품질 엔지니어링 툴로 TypeScript 오류와 ESLint 규칙 위반을 감지하고 수정합니다","es":"the-linter es una herramienta de código abierto que utiliza ESLint para identificar y corregir errores en el código","fr":"the-linter est un outil open source qui utilise ESLint pour identifier et corriger les erreurs dans le code","de":"the-linter ist ein Open-Source-Tool, das ESLint verwendet, um Fehler im Code zu identifizieren und zu korrigieren","pt":"O the-linter é uma ferramenta de código aberto que executa verificações de ESLint e corrige erros de forma sistemática.","ru":"ИИ Агент the-linter - это открытый инструмент, выполняющий проверки ESLint и исправляющий ошибки систематически.","ar":"العامل الذكي the-linter هو أداة مفتوحة المصدر تقوم بتنفيذ عمليات فحص ESLint وتصحيح الأخطاء بشكل منهجي."},"features":{"en":["Runs ESLint checks using npm run lint command","Identifies and groups TypeScript type errors, ESLint rule violations, and unused imports/variables","Fixes errors in priority order, starting with type errors","Supports systematic fixing of missing dependencies","Executes commands like 2>&1 | head -200 for error analysis"],"zh":["自动运行 ESLint 检查","检测 TypeScript 类型错误","修复 ESLint 规则违反","删除未使用的导入和变量","优先修复类型错误"],"ja":["ESLint チェックの自動実行","TypeScript タイプエラーの検出","ESLint ルール違反の修復","未使用のインポートと変数の削除","タイプエラーの優先修復"],"ko":["ESLint 체크 자동 실행","TypeScript 타입 오류 감지","ESLint 규칙 위반 수정","미사용 된 가져오기 및 변수 삭제","타입 오류의 우선 수정"],"es":["Ejecución de ESLint para identificar errores y advertencias","Análisis de errores por tipo, incluyendo errores de tipo de TypeScript","Corrección sistemática de errores y advertencias","Soporte para la línea de comandos (CLI) con npm","Priorización de correcciones por tipo de error"],"fr":["Exécution d''ESLint pour identifier les erreurs et les avertissements","Analyse des erreurs par type, y compris les erreurs de type de TypeScript","Correction systématique des erreurs et des avertissements","Support de la ligne de commande (CLI) avec npm","Priorisation des corrections par type d''erreur"],"de":["Ausführung von ESLint, um Fehler und Warnungen zu identifizieren","Analyse von Fehlern nach Art, einschließlich TypeScript-Typfehlern","Systematische Korrektur von Fehlern und Warnungen","Unterstützung der Kommandozeile (CLI) mit npm","Priorisierung von Korrekturen nach Fehlerart"],"pt":["Executa verificações de ESLint","Corrige erros de forma sistemática","Suporta TypeScript para verificar erros de tipo","Identifica imports e variáveis não utilizados","Verifica dependências faltantes"],"ru":["Выполняет проверки ESLint","Исправляет ошибки систематически","Поддерживает TypeScript для проверки ошибок типов","Определяет неиспользуемые импорты и переменные","Проверяет отсутствующие зависимости"],"ar":["ينفذ عمليات فحص ESLint","يصحح الأخطاء بشكل منهجي","يدعم TypeScript لفحص الأخطاء النوعية","يحدد الاستيرادات والمتغيرات غير المستخدمة","يفحص الإعتماديات الناقصة"]},"keywords":{"en":["how to use the-linter","the-linter setup guide","the-linter vs ESLint","the-linter install","what is the-linter","the-linter alternative","npm run lint command","TypeScript type errors","ESLint rule violations"],"zh":["the-linter","TypeScript 错误检测","ESLint 检查","代码质量工程","自动化代码修复","AI 工具","代码检查工具"],"ja":["the-linter","TypeScript エラー検出","ESLint チェック","コード品質エンジニアリング","自動コード修復","AI エージェント","コードチェックツール"],"ko":["the-linter","TypeScript 오류 감지","ESLint 체크","코드 품질 엔지니어링","자동 코드 수정","AI 툴","코드 체크 도구"],"es":["the-linter","ESLint","herramientas de código abierto","corrección de errores","análisis de código","TypeScript","npm","CLI","desarrollo de software"],"fr":["the-linter","ESLint","outils open source","correction d''erreurs","analyse de code","TypeScript","npm","CLI","développement de logiciels"],"de":["the-linter","ESLint","Open-Source-Tools","Fehlerkorrektur","Codeanalyse","TypeScript","npm","CLI","Softwareentwicklung"],"pt":["the-linter","ESLint","TypeScript","ferramenta de código aberto","qualidade do código","desenvolvimento de software","programação","correção de erros"],"ru":["ИИ Агент the-linter","ESLint","TypeScript","открытый инструмент","качество кода","разработка программного обеспечения","программирование","исправление ошибок"],"ar":["العامل الذكي the-linter","ESLint","TypeScript","أداة مفتوحة المصدر","جودة الكود","تطوير البرمجيات","البرمجة","تصحيح الأخطاء"]}},"owner":"dupipcom","repo":"morpheus","repoPath":"dupipcom/morpheus","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"the-linter","description":"Identifies and fixes ESLint errors and TypeScript type issues across the codebase.","bodyPreview":"Task: Run ESLint, identify all errors and warnings, and fix them systematically.\n\nRole: You''re a code quality engineer focused on maintaining clean, consistent, and type-safe code.\n\n## Execution Steps\n\n1. **Run ESLint check**\n   ```bash\n   npm run lint 2>&1 | head -200\n   ```\n\n2. **Analyze errors** - Group by:\n   - TypeScript type errors\n   - ESLint rule violations\n   - Unused imports/variables\n   - Missing dependencies\n\n3. **Fix in priority order**:\n   - Type errors (highest priority)\n   - Secu","body":"Task: Run ESLint, identify all errors and warnings, and fix them systematically.\n\nRole: You''re a code quality engineer focused on maintaining clean, consistent, and type-safe code.\n\n## Execution Steps\n\n1. **Run ESLint check**\n   ```bash\n   npm run lint 2>&1 | head -200\n   ```\n\n2. **Analyze errors** - Group by:\n   - TypeScript type errors\n   - ESLint rule violations\n   - Unused imports/variables\n   - Missing dependencies\n\n3. **Fix in priority order**:\n   - Type errors (highest priority)\n   - Security-related warnings\n   - Unused code removal\n   - Style/formatting issues\n\n4. **Verify fixes**\n   ```bash\n   npm run lint\n   ```\n\n## Common Fixes\n\n### TypeScript Errors\n- Add explicit types for function parameters\n- Use `unknown` instead of implicit `any`\n- Add null checks for optional values\n- Fix type mismatches in props\n\n### ESLint Rules\n- `@typescript-eslint/no-explicit-any` → Use proper types\n- `@typescript-eslint/no-unused-vars` → Remove or prefix with `_`\n- `react-hooks/exhaustive-deps` → Add missing dependencies\n- `@next/next/no-img-element` → Use `next/image`\n\n### Import Organization\n```typescript\n// 1. External packages\nimport { useState } from ''react''\nimport { NextResponse } from ''next/server''\n\n// 2. Internal aliases\nimport { Button } from ''@/components/ui/button''\nimport prisma from ''@/lib/prisma''\n\n// 3. Relative imports\nimport { helper } from ''./utils''\n\n// 4. Type imports\nimport type { User } from ''@/lib/types''\n```\n\n## Rules\n- Fix errors without changing functionality\n- Preserve existing code patterns\n- Don''t introduce new dependencies\n- Keep changes minimal and focused\n- Run lint after each batch of fixes to verify\n\n## Do NOT\n- Refactor unrelated code\n- Change business logic\n- Add new features\n- Modify test files unless fixing lint errors in them\n"},"lastSynced":"2026-03-08T02:01:30.895Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Quality Agents needing advanced JavaScript linting and error fixing capabilities with ESLint.","zh":"非常适合需要高级JavaScript linting和错误修复功能的代码质量代理，使用ESLint。","ja":"Code Quality Agentsが高度なJavaScript lintingおよびエラーフィックス機能を必要とする場合に最適です。ESLintを使用します。","ko":"고급 JavaScript linting 및 오류 수정 기능이 필요한 코드 품질 에이전트에게 적합합니다. ESLint를 사용합니다.","es":"Ideal para agentes de calidad de código que necesitan capacidades de análisis y corrección de errores de JavaScript avanzadas con ESLint.","fr":"Parfait pour les agents de qualité de code ayant besoin de capacités de linting et de correction d''erreurs JavaScript avancées avec ESLint.","de":"Perfekt für Code-Qualitäts-Agents, die erweiterte JavaScript-Linting- und Fehlerbehebungsfunktionen mit ESLint benötigen.","pt":"Perfeito para Agentes de Qualidade de Código que precisam de capacidades avançadas de linting JavaScript e correção de erros com ESLint.","ru":"Идеально подходит для агентов контроля качества кода, требующих продвинутых возможностей проверки и исправления ошибок JavaScript с помощью ESLint.","ar":"مثالي لعميل جودة الشفرة الذي يحتاج إلى إمكانيات متقدمة لتنسيق JavaScript وتصحيح الأخطاء مع ESLint."},"recommendation":{"en":"Empowers agents to systematically identify and fix TypeScript type errors, ESLint rule violations, and unused imports using npm and ESLint, ensuring clean, consistent, and type-safe code.","zh":"赋予代理系统地识别和修复TypeScript类型错误、ESLint规则违规以及未使用的导入，使用npm和ESLint，确保代码干净、一致且类型安全。","ja":"エージェントにTypeScriptのタイプエラー、ESLintルール違反、および未使用のインポートを体系的に識別して修復する能力を与え、npmとESLintを使用してクリーンで一貫性のあるタイプセーフなコードを保証します。","ko":"에이전트가 TypeScript 유형 오류, ESLint 규칙 위반 및 사용되지 않은 가져오기를 체계적으로 식별하고 수정할 수 있는 능력을 부여하여 npm 및 ESLint를 사용하여 깨끗하고 일관성 있는 유형 안전 코드를 보장합니다.","es":"Habilita a los agentes a identificar y corregir sistemáticamente errores de tipo TypeScript, violaciones de reglas de ESLint y importaciones no utilizadas utilizando npm y ESLint, garantizando un código limpio, consistente y seguro en cuanto a tipos.","fr":"Permet aux agents d''identifier et de corriger systématiquement les erreurs de type TypeScript, les violations de règles ESLint et les imports non utilisés en utilisant npm et ESLint, garantissant un code propre, cohérent et sécurisé en termes de types.","de":"Ermächtigt die Agents, systematisch TypeScript-Typfehler, ESLint-Regelverletzungen und nicht verwendete Importe mit npm und ESLint zu identifizieren und zu beheben, um sauberen, konsistenten und typsicheren Code sicherzustellen.","pt":"Habilita os agentes a identificar e corrigir sistematicamente erros de tipo TypeScript, violações de regras ESLint e imports não utilizados usando npm e ESLint, garantindo um código limpo, consistente e seguro em termos de tipo.","ru":"Позволяет агентам систематически выявлять и исправлять ошибки типов TypeScript, нарушения правил ESLint и неиспользуемые импорты с помощью npm и ESLint, обеспечивая чистый, последовательный и типобезопасный код.","ar":"تمكّن الوكيل من تحديد وتصحيح أخطاء نوع TypeScript وإخفاقات قواعد ESLint والاستيرادات غير المستخدمة باستخدام npm وESLint بشكل منهجي، مما يضمن 코드ًا نظيفًا ومتسقًا وأمنًا من النوع."},"useCases":{"en":["Automating ESLint checks for Dupip Monorepo projects","Debugging TypeScript type errors and fixing them systematically","Optimizing code quality by identifying and removing unused imports and variables"],"zh":["为Dupip Monorepo项目自动执行ESLint检查","系统地调试TypeScript类型错误并进行系统修复","通过识别和删除未使用的导入和变量来优化代码质量"],"ja":["Dupip MonorepoプロジェクトのESLintチェックを自動化する","TypeScriptのタイプエラーを体系的にデバッグして修復する","未使用のインポートおよび変数を識別して削除することでコード品質を最適化する"],"ko":["Dupip Monorepo 프로젝트의 ESLint 확인 자동화","TypeScript 유형 오류를 체계적으로 디버깅하고 수정","사용되지 않은 가져오기 및 변수를 식별하고 제거하여 코드 품질 최적화"],"es":["Automatizar las comprobaciones de ESLint para proyectos de Monorepo de Dupip","Depurar errores de tipo TypeScript y corregirlos sistemáticamente","Optimizar la calidad del código identificando y eliminando importaciones y variables no utilizadas"],"fr":["Automatiser les vérifications ESLint pour les projets Monorepo de Dupip","Déboguer les erreurs de type TypeScript et les corriger systématiquement","Optimiser la qualité du code en identifiant et en supprimant les imports et les variables non utilisés"],"de":["Automatisieren von ESLint-Prüfungen für Dupip-Monorepo-Projekte","Systematische Fehlersuche und -behebung von TypeScript-Typfehlern","Optimieren der Code-Qualität durch Identifizierung und Entfernung nicht verwendeter Importe und Variablen"],"pt":["Automatizar verificações ESLint para projetos Monorepo Dupip","Depurar erros de tipo TypeScript e corrigi-los sistematicamente","Otimizar a qualidade do código identificando e removendo imports e variáveis não utilizados"],"ru":["Автоматизация проверок ESLint для проектов Monorepo Dupip","Отладка ошибок типов TypeScript и систематическое их исправление","Оптимизация качества кода путем выявления и удаления неиспользуемых импортов и переменных"],"ar":["تحسين التحقق من ESLint لمشاريع Monorepo Dupip","تصحيح أخطاء نوع TypeScript بشكل منهجي","تحسين جودة الشفرة من خلال تحديد وإزالة الاستيرادات والمتغيرات غير المستخدمة"]},"limitations":{"en":["Requires npm and ESLint installation","Limited to JavaScript and TypeScript projects","Dependent on npm run lint command"],"zh":["需要安装npm和ESLint","仅限于JavaScript和TypeScript项目","依赖于npm run lint命令"],"ja":["npmとESLintのインストールが必要","JavaScriptとTypeScriptプロジェクトのみに限定","npm run lintコマンドに依存"],"ko":["npm 및 ESLint 설치가 필요","JavaScript 및 TypeScript 프로젝트만 해당","npm run lint 명령어에 의존"],"es":["Requiere la instalación de npm y ESLint","Limitado a proyectos de JavaScript y TypeScript","Dependiente del comando npm run lint"],"fr":["Nécessite l''installation de npm et ESLint","Limité aux projets JavaScript et TypeScript","Dépend de la commande npm run lint"],"de":["Benötigt die Installation von npm und ESLint","Begrenzt auf JavaScript- und TypeScript-Projekte","Abhängig vom Befehl npm run lint"],"pt":["Exige instalação do npm e ESLint","Limitado a projetos JavaScript e TypeScript","Dependente do comando npm run lint"],"ru":["Требует установки npm и ESLint","Ограничен проектами JavaScript и TypeScript","Зависит от команды npm run lint"],"ar":["يتطلب تثبيت npm وESLint","محدود لمشاريع JavaScript وTypeScript","يعتمد على الأمر npm run lint"]},"version":4},"contentHash":"f5519eb08b5266855fcbab0a8a2441b44131d072cdd07f24e7a7340eb0f27447","qualityScore":30}');
