INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ncukondo/reference-manager/code-with-task-local', 'code-with-task-local', 'ncukondo', 'reference-manager', 'community', 'code-with-task-local ncukondo reference-manager community code-with-task-local is a local reference management tool that utilizes CSL-JSON as the single source of truth, benefiting developers by streamlining task implementation. It facilitates workflow by managing tasks and reporting IPC status code-with-task-local是一个使用CSL-JSON作为单一事实来源的本地引用管理工具，用于简化代码管理 code-with-task-localは、CSL-JSONを使用したローカル参照管理ツールで、コード管理を簡素化 code-with-task-local는 CSL-JSON를 사용한 로컬 참조 관리 도구로 코드 관리를 단순화 Code-with-task-local es una herramienta de gestión de referencias locales que utiliza CSL-JSON como fuente de verdad única, permitiendo la gestión de tareas y el reporting de estado Code-with-task-local est un outil de gestion de références locales utilisant CSL-JSON comme source de vérité unique, permettant la gestion de tâches et le reporting d''état Code-with-task-local ist ein lokales Referenzmanagement-Tool, das CSL-JSON als einzige Quelle der Wahrheit verwendet, um die Aufgabenverwaltung und den Statusbericht zu ermöglichen O code-with-task-local é uma ferramenta de gerenciamento de referências locais que utiliza CSL-JSON como fonte de verdade. Ele permite a gestão de tarefas e referências de forma eficiente Code-with-task-local - это местный инструмент управления ссылками, использующий CSL-JSON как источник правды. Он позволяет эффективно управлять задачами и ссылками code-with-task-local هي أداة إدارة المراجع المحلية التي تستخدم CSL-JSON كمصدر وحيد للtruth. وهي تسمح بإدارة المهام والمراجع بفعالية how to use code-with-task-local code-with-task-local setup guide CSL-JSON task implementation IPC status reporting tools code-with-task-local alternative code-with-task-local vs other reference management tools code-with-task-local install local reference management best practices 代码管理工具 CSL-JSON 本地引用管理 IPC状态报告 自动分支管理 AIエージェント 代码开发工具 Utilizes CSL-JSON as the single source of truth for task implementation Implements tasks based on spec/_index.md and spec/tasks/ directory Reports IPC status to .worker-status.json file Manages tasks using Git branches Supports dynamic task file path and status updates code-with-task-local is a local reference management tool using CSL-JSON for task implementation and IPC status reporting');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Deng-GuiFeng/Paper2PPT/literature-review-ppt-generator', 'community', 'Deng-GuiFeng', 'Paper2PPT', 'Deng-GuiFeng/Paper2PPT', 'literature-review-ppt-generator', 0, 0, 30, '2026-03-08T01:57:15.304Z', '2026-03-08T02:01:54.796Z', '9a31f5b669282fe407716c5cf35a122eaa8d483fadae53f8e3992ab857cfc7cd', '{"id":"Deng-GuiFeng/Paper2PPT/literature-review-ppt-generator","name":"literature-review-ppt-generator","description":{"en":"The literature-review-ppt-generator skill automatically converts academic paper PDFs into 2-3 page PPTs, ideal for 5-minute shares, benefiting researchers and academics","zh":"文献综述PPT生成器可以自动将学术论文 PDF 转换为组会汇报 PPT，聚焦方法创新，适合 5 分钟快速分享","ja":"文献レビューPPTジェネレーターは、学術論文の PDF を自動的にプレゼンテーション PPT に変換します。方法の革新に焦点を当て、5 分間のクイックシェアに適しています","ko":"문헌 리뷰 PPT 생성기는 학술 논문의 PDF를 자동으로 발표 PPT로 변환합니다. 방법의 혁신에 초점을 맞추고 5분간의快速 공유에 적합합니다","es":"El generador de PPT de revisión de literatura convierte PDF en presentaciones de 2-3 páginas, enfocándose en la innovación metodológica","fr":"Le générateur de PPT de revue de littérature convertit des PDF en présentations de 2-3 pages, axées sur l''innovation méthodologique","de":"Der Literaturübersichts-PPT-Generator wandelt PDF in Präsentationen von 2-3 Seiten um, mit Fokus auf methodologische Innovationen","pt":"O gerador de PPT de revisão de literatura cria apresentações de 2-3 páginas para compartilhamento rápido","ru":"ИИ Агент для генерации PPT обзора литературы создает презентации для быстрого обмена","ar":"جهاز العرض للمراجعة الأدبية يقوم بإنشاء عروض تقديمية للاستخدام السريع"},"seo":{"title":{"en":"Literature-Review-PPT-Generator: Automated PPT Creation f...","zh":"文献综述PPT生成器 Setup Guide","ja":"文献レビューPPTジェネレーター ベストプラクティス","ko":"문헌 리뷰 PPT 생성기 사용법","es":"Generador de PPT de Revisión de Literatura: Guía de Confi...","fr":"Générateur de PPT de Revue de Littérature: Meilleures Pr