INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Deng-GuiFeng/Paper2PPT/literature-review-ppt-generator', 'literature-review-ppt-generator', 'Deng-GuiFeng', 'Paper2PPT', 'community', 'literature-review-ppt-generator Deng-GuiFeng Paper2PPT community The literature-review-ppt-generator skill automatically converts academic paper PDFs into 2-3 page PPTs, ideal for 5-minute shares, benefiting researchers and academics 文献综述PPT生成器可以自动将学术论文 PDF 转换为组会汇报 PPT，聚焦方法创新，适合 5 分钟快速分享 文献レビューPPTジェネレーターは、学術論文の PDF を自動的にプレゼンテーション PPT に変換します。方法の革新に焦点を当て、5 分間のクイックシェアに適しています 문헌 리뷰 PPT 생성기는 학술 논문의 PDF를 자동으로 발표 PPT로 변환합니다. 방법의 혁신에 초점을 맞추고 5분간의快速 공유에 적합합니다 El generador de PPT de revisión de literatura convierte PDF en presentaciones de 2-3 páginas, enfocándose en la innovación metodológica Le générateur de PPT de revue de littérature convertit des PDF en présentations de 2-3 pages, axées sur l''innovation méthodologique Der Literaturübersichts-PPT-Generator wandelt PDF in Präsentationen von 2-3 Seiten um, mit Fokus auf methodologische Innovationen O gerador de PPT de revisão de literatura cria apresentações de 2-3 páginas para compartilhamento rápido ИИ Агент для генерации PPT обзора литературы создает презентации для быстрого обмена جهاز العرض للمراجعة الأدبية يقوم بإنشاء عروض تقديمية للاستخدام السريع how to use literature-review-ppt-generator what is literature-review-ppt-generator literature-review-ppt-generator alternative literature-review-ppt-generator setup guide automated PPT generation for academic papers literature-review-ppt-generator vs manual PPT creation install literature-review-ppt-generator literature-review-ppt-generator for researchers AI agent skills for academic paper summarization 文献综述PPT生成器 学术论文 PDF 转换 组会汇报 PPT 方法创新 AI 工具 自动转换 结构灵活 2 页限制 Automatically generates 2-3 page PPTs from academic paper PDFs Applies core principles like paper abstracts and method innovation Supports flexible structure adjustment based on paper characteristics Enforces strict formatting guidelines, including page limits and title requirements Utilizes specific outline symbols, such as ▶ and ▢, for organization literature-review-ppt-generator is an AI agent skill that generates concise PPT content from academic papers, focusing on method innovation and flexible structure');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Youngger9765/young-personal-site/design-improvement', 'community', 'Youngger9765', 'young-personal-site', 'Youngger9765/young-personal-site', 'design-improvement', 0, 0, 30, '2026-03-08T01:57:15.309Z', '2026-03-08T02:02:24.518Z', 'e9e6f3bd4ce547313affded842657ac1d2eca61bacdf36a4a6cdec22a134689f', '{"id":"Youngger9765/young-personal-site/design-improvement","name":"design-improvement","description":{"en":"The design-improvement skill streamlines design optimization by following project design principles, preventing inconsistent design and ensuring a professional appearance for developers and designers.","zh":"设计改进技能通过系统化的设计优化提高项目质量，确保色彩一致性和响应式布局","ja":"デザイン改善スキルは、体系的なデザイン最適化によってプロジェクトの品質を向上させ、色彩の一貫性とレスポンシブレイアウトを確保","ko":"디자인 개선 스킬은 체계적인 디자인 최적화를 통해 프로젝트 품질을 향상시키고, 색상 일관성과 반응형 레이아웃을 보장","es":"La habilidad de mejora de diseño optimiza la experiencia del usuario con paletas de colores coherentes y diseños responsivos","fr":"La compétence d''amélioration de la conception optimise l''expérience utilisateur avec des palettes de couleurs cohérentes et des conceptions responsives","de":"Die Fähigkeit zur Design-Verbesserung optimiert die Benutzererfahrung mit konsistenten Farbpaletten und responsivem Design","pt":"A habilidade de melhoria de design ajuda a otimizar layouts e garantir a consistência do design, seguindo princípios de design de projeto","ru":"Навык улучшения дизайна помогает оптимизировать макеты и обеспечить последовательность дизайна, следуя принципам дизайна проекта","ar":"أداة تحسين التصميم تساعد على تحسين التصميم وتضمن συνέافيه التصميم، متبعة مبادئ تصميم المشروع"},"seo":{"title":{"en":"design-improvement: Streamlined Design Optimization Setup...","zh":"设计改进设置指南 - AI智能工具","ja":"デザイン改善ベストプラクティス - AIエージェント","ko":"디자인 개선 가이드 - AI 에이전트","es":"Mejora de Diseño: Guía de Configuración para Agentes de IA","fr":"Amélioration de la Conception: Guide de Mise en Place pou...","de":"Design-Verbesserung: Einrichtungsleitfaden für KI-Agents","pt":"Guia de Melhoria de Design: Otimização de Layouts","ru":"ИИ Агенты для Улучшения Дизайна: Настройка Руководство","ar":"أداة تحسين التصميم: دليل إعداد أفضل الممارسات"},"description":{"en":"Discover how design-improvement skill ensures color palette consistency, mobile-first responsive design, and professional appearance. Learn how to implement ...","zh":"通过系统化的设计优化提高项目质量，确保色彩一致性和响应式布局","ja":"プロジェクトの品質を向上させるための体系的なデザイン最適化、色彩の一貫性とレスポンシブレイアウトを確保","ko":"프로젝트 품질 향상을 위한 체계적인 디자인 최적화, 색상 일관성과 반응형 레이아웃 보장","es":"Optimice su diseño con la habilidad de mejora de diseño, que garantiza paletas de colores coherentes y diseños responsivos para una apariencia profesional","fr":"Optimisez votre conception avec la compétence d''amélioration de la conception, qui assure des palettes de couleurs cohérentes et des conceptions responsives ...","de":"Optimieren Sie Ihr Design mit der Fähigkeit zur Design-Verbesserung, die konsistente Farbpaletten und responsives Design für ein professionelles Aussehen gew...","pt":"Aprenda a melhorar a consistência do design com a habilidade de melhoria de design, garantindo paletas de cores coerentes e layouts responsivos","ru":"Улучшите последовательность дизайна с помощью навыка улучшения дизайна, обеспечивая согласованность цветовой палитры и адаптивного дизайна","ar":"تعرف على كيفية تحسين تصميمك مع أداة تحسين التصميم، مما يضمن تناسقًا في الألوان وتصميم الاستجابة"},"definition":{"en":"design-improvement is a systematic approach to optimizing design, focusing on color palette consistency, mobile-first responsive design, and adherence to brand principles.","zh":"设计改进是一种通过系统化的设计优化提高项目质量的技能","ja":"デザイン改善は、体系的なデザイン最適化によってプロジェクトの品質を向上させるスキル","ko":"디자인 개선은 체계적인 디자인 최적화를 통해 프로젝트 품질을 향상시키는 스킬","es":"La mejora de diseño es una habilidad que aplica principios de diseño para garantizar una apariencia profesional y coherente","fr":"L''amélioration de la conception est une compétence qui applique des principes de conception pour assurer une apparence professionnelle et cohérente","de":"Die Design-Verbesserung ist eine Fähigkeit, die Designprinzipien anwendet, um ein professionelles und konsistentes Aussehen zu gewährleisten","pt":"Melhoria de design é uma habilidade que visa otimizar a consistência do design, seguindo princípios de design de projeto","ru":"Улучшение дизайна - это навык, направленный на оптимизацию последовательности дизайна, следуя принципам дизайна проекта","ar":"تحسين التصميم هو أداة تهدف إلى تحسين تصميم متسق، متبعة مبادئ تصميم المشروع"},"features":{"en":["Ensures color palette consistency using primary slate-blue (#475569, #64748b) and accent coral-orange (#fb923c, #f97316) colors","Implements mobile-first responsive design for seamless user experience","Maintains professional appearance by adhering to brand design principles","Prevents broken responsive layouts and brand violations","Utilizes warm-cream (#fef3c7, #fef9c3) background for visually appealing designs","Applies gradient effects for enhanced visual hierarchy"],"zh":["色彩一致性：slate-blue (#475569, #64748b) 和 coral-orange (#fb923c, #f97316)","响应式布局：mobile-first 设计","专业外观：warm-cream (#fef3c7, #fef9c3) 背景","CSS 渐变支持","品牌违规防止"],"ja":["色彩の一貫性：slate-blue (#475569, #64748b) と coral-orange (#fb923c, #f97316)","レスポンシブレイアウト：mobile-first デザイン","プロフェッショナルな外観：warm-cream (#fef3c7, #fef9c3) 背景","CSS グラデーション対応","ブランド違反防止"],"ko":["색상 일관성：slate-blue (#475569, #64748b)와 coral-orange (#fb923c, #f97316)","반응형 레이아웃：mobile-first 디자인","전문적인 외관：warm-cream (#fef3c7, #fef9c3) 배경","CSS 그라데이션 지원","브랜드 위반 방지"],"es":["Paletas de colores coherentes con azul pizarra y naranja coral","Diseño responsivo para una experiencia de usuario óptima","Gradientes de colores personalizados para una apariencia única","Diseño móvil primero para una experiencia de usuario fluida","Evita violaciones de marca y diseños inconsistentes"],"fr":["Palettes de couleu